insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('gn',1,1,'crampon1923','Au commencement Dieu créa le ciel et la terre.'),
('gn',1,2,'crampon1923','La terre était informe et vide; les ténèbres couvraient l''abîme, et l''Esprit de Dieu se mouvait au-dessus des eaux.'),
('gn',1,3,'crampon1923','Dieu dit: " Que la lumière soit! " et la lumière fut.'),
('gn',1,4,'crampon1923','Et Dieu vit que la lumière était bonne; et Dieu sépara la lumière et les ténèbres.'),
('gn',1,5,'crampon1923','Dieu appela la lumière jour, et les ténèbres Nuit. Et il y eut un soir, et il y eut un matin; ce fut le premier jour.'),
('gn',1,6,'crampon1923','Dieu dit: " Qu''il y ait un firmament entre les eaux, et qu''il sépare les eaux d''avec les eaux. "'),
('gn',1,7,'crampon1923','Et Dieu fit le firmament, et il sépara les eaux qui sont au-dessous du firmament d''avec les eaux qui sont au-dessus du firmament. Et cela fut ainsi.'),
('gn',1,8,'crampon1923','Dieu appela le firmament Ciel. Et il y eut un soir et il y eut un matin; ce fut le second jour.'),
('gn',1,9,'crampon1923','Dieu dit: " Que les eaux qui sont au-dessous du ciel se rassemblent en un seul lieu, et que le sec paraisse. " Et cela fut ainsi.'),
('gn',1,10,'crampon1923','Dieu appela le sec Terre, et il appela Mer l''amas des eaux. Et Dieu vit que cela était bon.'),
('gn',1,11,'crampon1923','Puis Dieu dit: " Que la terre fasse pousser du gazon, des herbes portant semence, des arbres à fruit produisant, selon leur espèce, du fruit ayant en soi sa semence, sur la terre. " Et cela fut ainsi.'),
('gn',1,12,'crampon1923','Et la terre fit sortir du gazon, des herbes portant semence selon leur espèce, et des arbres produisant, selon leur espèce, du fruit ayant en soi sa semence. Et Dieu vit que cela était bon.'),
('gn',1,13,'crampon1923','Et il y eut un soir, et il y eut un matin; ce fut le troisième jour.'),
('gn',1,14,'crampon1923','Dieu dit: " Qu''il y ait des luminaires dans le firmament du ciel pour séparer le jour et la nuit; qu''ils soient des signes, qu''ils marquent les époques, les jours et les années,'),
('gn',1,15,'crampon1923','et qu''ils servent de luminaires dans le firmament du ciel pour éclairer la terre. " Et cela fut ainsi.'),
('gn',1,16,'crampon1923','Dieu fit les deux grands luminaires, le plus grand luminaire pour présider au jour, le plus petit luminaire pour présider à la nuit; il fit aussi les étoiles.'),
('gn',1,17,'crampon1923','Dieu les plaça dans le firmament du ciel pour éclairer la terre,'),
('gn',1,18,'crampon1923','pour présider au jour et à la nuit, et pour séparer la lumière et les ténèbres. Et Dieu vit que cela était bon.'),
('gn',1,19,'crampon1923','Et il y eut un soir, et il y eut un matin: ce fut le quatrième jour.'),
('gn',1,20,'crampon1923','Dieu dit: " Que les eaux foisonnent d''une multitude d''êtres vivants, et que les oiseaux volent sur la terre, sur la face du firmament du ciel. "'),
('gn',1,21,'crampon1923','Et Dieu créa les grands animaux aquatiques, et tout être vivant qui se meut, foisonnant dans les eaux, selon leur espèce, et tout volatile ailé selon son espèce. Et Dieu vit que cela était bon.'),
('gn',1,22,'crampon1923','Et Dieu les bénit, en disant: " Soyez féconds et multipliez, et remplissez les eaux de la mer, et que les oiseaux multiplient sur la terre. "'),
('gn',1,23,'crampon1923','Et il y eut un soir, et il y eut un matin: ce fut le cinquième jour.'),
('gn',1,24,'crampon1923','Dieu dit: " Que la terre fasse sortir des êtres animés selon leur espèce, des animaux domestiques, des reptiles et des bêtes de la terre selon leur espèce. " Et cela fut ainsi.'),
('gn',1,25,'crampon1923','Dieu fit les bêtes de la terre selon leur espèce, les animaux domestiques selon leur espèce, et tout ce qui rampe sur la terre selon son espèce. Et Dieu vit que cela était bon.'),
('gn',1,26,'crampon1923','Puis Dieu dit: " Faisons l''homme à notre image, selon notre ressemblance, et qu''il domine sur les poissons de la mer, sur les oiseaux du ciel, sur les animaux domestiques et sur toute la terre, et sur les reptiles qui rampent sur la terre. "'),
('gn',1,27,'crampon1923','Et Dieu créa l''homme à son image; il le créa à l''image de Dieu: il les créa mâle et femelle.'),
('gn',1,28,'crampon1923','Et Dieu les bénit, et il leur dit: " Soyez féconds, multipliez, remplissez la terre et soumettez-la, et dominez sur les poissons de la mer, sur les oiseaux du ciel et sur tout animal qui se meut sur la terre. "'),
('gn',1,29,'crampon1923','Et Dieu dit: " Voici que je vous donne toute herbe portant semence à la surface de toute la terre, et tout arbre qui porte un fruit d''arbre ayant semence; ce sera pour votre nourriture.'),
('gn',1,30,'crampon1923','Et à tout animal de la terre, et à tout oiseau du ciel, et à tout ce qui se meut sur la terre, ayant en soi un souffle de vie, je donne toute herbe verte pour nourriture. " Et cela fut ainsi.'),
('gn',1,31,'crampon1923','Et Dieu vit tout ce qu''il avait fait, et voici cela était très bon. Et il y eut un soir, et il y eut un matin: ce fut le sixième jour.'),
('gn',2,1,'crampon1923','Ainsi furent achevés le ciel et la terre, et toute leur armée.'),
('gn',2,2,'crampon1923','Et Dieu eut achevé le septième jour son œuvre qu''il avait faite, et il se reposa le septième jour de toute son œuvre qu''il avait faite.'),
('gn',2,3,'crampon1923','Et Dieu bénit le septième jour et le sanctifia, parce qu''en ce jour-là il s''était reposé de toute l''œuvre qu''il avait créée en la faisant.'),
('gn',2,4,'crampon1923','Voici l''histoire du ciel et de la terre quand ils furent créés, lorsque Yahweh Dieu eut fait une terre et un ciel.'),
('gn',2,5,'crampon1923','Il n''y avait encore sur la terre aucun arbrisseau des champs, et aucune herbe des champs n''avait encore germé; car Yahweh Dieu n''avait pas fait pleuvoir sur la terre, et il n''y avait pas d''homme pour cultiver le sol.'),
('gn',2,6,'crampon1923','Mais une vapeur montait de la terre et arrosait toute la surface du sol.'),
('gn',2,7,'crampon1923','Yahweh Dieu forma l''homme de la poussière du sol, et il souffla dans ses narines un souffle de vie, et l''homme devint un être vivant.'),
('gn',2,8,'crampon1923','Puis Yahweh Dieu planta un jardin en Eden du côté de l''Orient, et il y mit l''homme qu''il avait formé.'),
('gn',2,9,'crampon1923','Et Yahweh Dieu fit pousser du sol toute espèce d''arbres agréables à voir et bons à manger, et l''arbre de la vie au milieu du jardin, et l''arbre de la connaissance du bien et du mal.'),
('gn',2,10,'crampon1923','Un fleuve sortait d''Eden pour arroser le jardin, et de là il se partageait en quatre bras.'),
('gn',2,11,'crampon1923','Le nom du premier est Phison; c''est celui qui entoure tout le pays d''Hévilath, où se trouve l''or.'),
('gn',2,12,'crampon1923','Et l''or de ce pays est bon; là aussi se trouvent le bdellium et la pierre d''onyx.'),
('gn',2,13,'crampon1923','Le nom du second fleuve est Géhon; c''est celui qui entoure toute la terre de Cousch.'),
('gn',2,14,'crampon1923','Le nom du troisième est le Tigre; c''est celui qui coule à l''orient d''Assur. Le quatrième fleuve est l''Euphrate.'),
('gn',2,15,'crampon1923','Yahweh Dieu prit l''homme et le plaça dans le jardin d''Eden pour le cultiver et pour le garder.'),
('gn',2,16,'crampon1923','Et Yahweh Dieu donna à l''homme cet ordre: " Tu peux manger de tous les arbres du jardin;'),
('gn',2,17,'crampon1923','mais tu ne mangeras pas de l''arbre de la connaissance du bien et du mal, car le jour où tu en mangeras, tu mourras certainement. "'),
('gn',2,18,'crampon1923','Yahweh Dieu dit: " Il n''est pas bon que l''homme soit seul; je lui ferai une aide semblable à lui. "'),
('gn',2,19,'crampon1923','Et Yahweh Dieu, qui avait formé du sol tous les animaux des champs et tous les oiseaux du ciel, les fit venir vers l''homme pour voir comment il les appellerait, et pour que tout être vivant portât le nom que lui donnerait l''homme.'),
('gn',2,20,'crampon1923','Et l''homme donna des noms à tous les animaux domestiques, aux oiseaux du ciel et à tous les animaux des champs; mais il ne trouva pas pour l''homme une aide semblable à lui.'),
('gn',2,21,'crampon1923','Alors Yahweh Dieu fit tomber un profond sommeil sur l''homme, qui s''endormit, et il prit une de ses côtes et referma la chair à sa place.'),
('gn',2,22,'crampon1923','De la côte qu''il avait prise de l''homme, Yahweh Dieu forma une femme, et il l''amena à l''homme.'),
('gn',2,23,'crampon1923','Et l''homme dit: " Celle-ci cette fois est os de mes os et chair de ma chair! Celle-ci sera appelée femme, parce qu''elle a été prise de l''homme. "'),
('gn',2,24,'crampon1923','C''est pourquoi l''homme quittera son père et sa mère, et s''attachera à sa femme, et ils deviendront une seule chair.'),
('gn',2,25,'crampon1923','Ils étaient nus tous deux, l''homme et sa femme, sans en avoir honte.'),
('gn',3,1,'crampon1923','Le serpent était le plus rusé de tous les animaux des champs que Yahweh Dieu ait faits. Il dit à la femme: " Est-ce que Dieu aurait dit: " Vous ne mangerez pas de tout arbre du jardin? "'),
('gn',3,2,'crampon1923','La femme répondit au serpent: " Nous mangeons du fruit des arbres du jardin.'),
('gn',3,3,'crampon1923','Mais du fruit de l''arbre qui est au milieu du jardin, Dieu a dit: Vous n''en mangerez point et vous n''y toucherez point, de peur que vous ne mouriez. "'),
('gn',3,4,'crampon1923','Le serpent dit à la femme: " Non, vous ne mourrez point;'),
('gn',3,5,'crampon1923','mais Dieu sait que, le jour où vous en mangerez, vos yeux s''ouvriront et vous serez comme Dieu, connaissant le bien et le mal. "'),
('gn',3,6,'crampon1923','La femme vit que le fruit de l''arbre était bon à manger, agréable à la vue et désirable pour acquérir l''intelligence; elle prit de son fruit et en mangea; elle en donna aussi à son mari qui était avec elle, et il en mangea.'),
('gn',3,7,'crampon1923','Leurs yeux à tous deux s''ouvrirent et ils connurent qu''ils étaient nus; et, ayant cousu des feuilles de figuier, ils s''en firent des ceintures.'),
('gn',3,8,'crampon1923','Alors ils entendirent la voix de Yahweh Dieu passant dans le jardin à la brise du jour, et l''homme et sa femme se cachèrent de devant Yahweh Dieu au milieu des arbres du jardin.'),
('gn',3,9,'crampon1923','Mais Yahweh Dieu appela l''homme et lui dit: " Où es-tu? "'),
('gn',3,10,'crampon1923','Il répondit: " J''ai entendu ta voix, dans le jardin, et j''ai eu peur, car je suis nu; et je me suis caché. "'),
('gn',3,11,'crampon1923','Et Yahweh Dieu dit: " Qui t''a appris que tu es nu? Est-ce que tu as mangé de l''arbre dont je t''avais défendu de manger? "'),
('gn',3,12,'crampon1923','L''homme répondit: " La femme que vous avez mise avec moi m''a donné du fruit de l''arbre, et j''en ai mangé. "'),
('gn',3,13,'crampon1923','Yahweh Dieu dit à la femme: " Pourquoi as-tu fait cela? " La femme répondit: " Le serpent m''a trompée, et j''en ai mangé. "'),
('gn',3,14,'crampon1923','Yahweh Dieu dit au serpent: " Parce que tu as fait cela, tu es maudit entre tous les animaux domestiques et toutes les bêtes des champs; tu marcheras sur ton ventre, et tu mangeras la poussière tous les jours de ta vie.'),
('gn',3,15,'crampon1923','Et je mettrai une inimitié entre toi et la femme, entre ta postérité et sa postérité; celle-ci te meurtrira à la tête, et tu la meurtriras au talon. "'),
('gn',3,16,'crampon1923','A la femme il dit: " je multiplierai tes souffrances, et spécialement celles de ta grossesse; tu enfanteras des fils dans la douleur; ton désir se portera vers ton mari, et il dominera sur toi. "'),
('gn',3,17,'crampon1923','Il dit à l''homme: " Parce que tu as écouté la voix de ta femme, et que tu as mangé de l''arbre au sujet duquel je t''avais donné cet ordre: Tu n''en mangeras pas, le sol est maudit à cause de toi. C''est par un travail pénible que tu en tireras ta nourriture, tous les jours de ta vie;'),
('gn',3,18,'crampon1923','il te produira des épines et des chardons, et tu mangeras l''herbe des champs.'),
('gn',3,19,'crampon1923','C''est à la sueur de ton visage que tu mangeras du pain, jusqu''à ce que tu retournes à la terre, parce que c''est d''elle que tu as été pris; car tu es poussière et tu retourneras en poussière. "'),
('gn',3,20,'crampon1923','Adam donna à sa femme le nom d''Eve, parce qu''elle a été la mère de tous les vivants.'),
('gn',3,21,'crampon1923','Yahweh Dieu fit à Adam et à sa femme des tuniques de peau et les en revêtit.'),
('gn',3,22,'crampon1923','Et Yahweh Dieu dit: " Voici que l''homme est devenu comme l''un de nous, pour la connaissance du bien et du mal. Maintenant, qu''il n''avance pas sa main, qu''il ne prenne pas aussi de l''arbre de vie, pour en manger et vivre éternellement. "'),
('gn',3,23,'crampon1923','Et Yahweh Dieu le fit sortir du jardin d''Eden, pour qu''il cultivât la terre d''où il avait été pris.'),
('gn',3,24,'crampon1923','Et il chassa l''homme, et il mit à l''orient du jardin d''Eden les Chérubins et la flamme de l''épée tournoyante, pour garder le chemin de l''arbre de vie.'),
('gn',4,1,'crampon1923','Adam connut Eve, sa femme; elle conçut et enfanta Caïn, et elle dit: " J''ai acquis un homme avec le secours de Yahweh! "'),
('gn',4,2,'crampon1923','Elle enfanta encore Abel, son frère. Abel fut pasteur de brebis, et Caïn était laboureur.'),
('gn',4,3,'crampon1923','Au bout de quelque temps, Caïn offrit des produits de la terre en oblation à Yahweh;'),
('gn',4,4,'crampon1923','Abel, de son côté, offrit des premiers-nés de son troupeau et de leur graisse. Yahweh regarda Abel et son offrande;'),
('gn',4,5,'crampon1923','mais il ne regarda pas Caïn et son offrande. Caïn en fut très irrité et son visage fut abattu.'),
('gn',4,6,'crampon1923','Yahweh dit à Caïn: " Pourquoi es-tu irrité, et pourquoi ton visage est-il abattu?'),
('gn',4,7,'crampon1923','Si tu fais bien, ne seras-tu pas agréé? Et si tu ne fais pas bien, le péché ne se couche-t-il pas à ta porte? Son désir se tourne vers toi; mais toi, tu dois dominer sur lui. "'),
('gn',4,8,'crampon1923','Caïn dit à Abel, son frère: " Allons aux champs. " Et, comme ils étaient dans les champs, Caïn s''éleva contre Abel, son frère, et le tua.'),
('gn',4,9,'crampon1923','Et Yahweh dit à Caïn: " Où est Abel, ton frère? " Il répondit: " Je ne sais pas; suis-je le gardien de mon frère? "'),
('gn',4,10,'crampon1923','Yahweh dit: " Qu''as-tu fait? La voix du sang de ton frère crie de la terre jusqu''à moi.'),
('gn',4,11,'crampon1923','Maintenant tu es maudit de la terre, qui a ouvert sa bouche pour recevoir de ta main le sang de ton frère.'),
('gn',4,12,'crampon1923','Quand tu cultiveras la terre, elle ne donnera plus ses fruits; tu seras errant et fugitif sur la terre. "'),
('gn',4,13,'crampon1923','Caïn dit à Yahweh: " Ma peine est trop grande pour que je la puisse supporter.'),
('gn',4,14,'crampon1923','Voici que vous me chassez aujourd''hui de cette terre, et je serai caché loin de votre face; je serai errant et fugitif sur la terre, et quiconque me trouvera me tuera. "'),
('gn',4,15,'crampon1923','Yahweh lui dit: " Eh bien, si quelqu''un tue Caïn, Caïn sera vengé sept fois. " Et Yahweh mit un signe sur Caïn, afin que quiconque le rencontrerait ne le tuât pas.'),
('gn',4,16,'crampon1923','Puis Caïn s''éloigna de devant Yahweh, et il habita dans le pays de Nod, à l''orient d''Eden.'),
('gn',4,17,'crampon1923','Caïn connut sa femme; elle conçut et enfanta Hénoch. Et il se mit à bâtir une ville qu''il appela Hénoch, du nom de son fils.'),
('gn',4,18,'crampon1923','Irad naquit à Hénoch, et il engendra Maviaël; Maviaël engendra Mathusaël, et Mathusaël engendra Lamech.'),
('gn',4,19,'crampon1923','Lamech prit deux femmes; le nom de l''une était Ada, et celui de la seconde Sella.'),
('gn',4,20,'crampon1923','Ada enfanta Jabel: il a été le père de ceux qui habitent sous des tentes et au milieu de troupeaux.'),
('gn',4,21,'crampon1923','Le nom de son frère était Jubal: il a été le père de tous ceux qui jouent de la harpe et du chalumeau.'),
('gn',4,22,'crampon1923','Sella, de son côté, enfanta Tubal-Caïn, qui forgeait toute espèce d''instruments tranchants d''airain et de fer. La sœur de Tubal-Caïn était Noéma.'),
('gn',4,23,'crampon1923','Lamech dit à ses femmes: Ada et Sella, entendez ma voix, femmes de Lamech, écoutez ma parole: J''ai tué un homme pour ma blessure, et un jeune homme pour ma meurtrissure.'),
('gn',4,24,'crampon1923','Caïn sera vengé sept fois, et Lamech soixante-dix-sept fois.'),
('gn',4,25,'crampon1923','Adam connut encore sa femme; elle enfanta un fils et l''appela Seth, car, dit-elle, " Dieu m''a donné une postérité à la place d''Abel, que Caïn a tué. "'),
('gn',4,26,'crampon1923','Seth eut aussi un fils, qu''il appela Enos. Ce fut alors que l''on commença à invoquer le nom de Yahweh.'),
('gn',5,1,'crampon1923','Voici le livre de l''histoire d''Adam. Lorsque Dieu créa Adam, il le fit à la ressemblance de Dieu.'),
('gn',5,2,'crampon1923','Il les créa mâle et femelle, et il les bénit, et il leur donna le nom d''Homme, lorsqu''ils furent créés.'),
('gn',5,3,'crampon1923','Adam vécut cent trente ans, et il engendra un fils à sa ressemblance, selon son image, et il lui donna le nom de Seth.'),
('gn',5,4,'crampon1923','Les jours d''Adam, après qu''il eut engendré Seth, furent de huit cents ans, et il engendra des fils et des filles.'),
('gn',5,5,'crampon1923','Tout le temps qu''Adam vécut fut de neuf cent trente ans, et il mourut.'),
('gn',5,6,'crampon1923','Seth vécut cent cinq ans, et il engendra Enos.'),
('gn',5,7,'crampon1923','Après qu''il eut engendré Enos, Seth vécut huit cent sept ans, et il engendra des fils et des filles.'),
('gn',5,8,'crampon1923','Tout le temps que Seth vécut fut de neuf cent douze ans, et il mourut.'),
('gn',5,9,'crampon1923','Enos vécut quatre-vingt-dix ans, et il engendra Caïnan.'),
('gn',5,10,'crampon1923','Après qu''il eut engendré Caïnan, Enos vécut huit cent quinze ans, et il engendra des fils et des filles.'),
('gn',5,11,'crampon1923','Tout le temps qu''Enos vécut fut de neuf cent cinq ans, et il mourut.'),
('gn',5,12,'crampon1923','Caïnan vécut soixante-dix ans, et il engendra Malaléel.'),
('gn',5,13,'crampon1923','Après qu''il eut engendré Malaléel, Caïnan vécut huit cent quarante ans, et il engendra des fils et des filles.'),
('gn',5,14,'crampon1923','Tout le temps que Caïnan vécut fut de neuf cent dix ans, et il mourut.'),
('gn',5,15,'crampon1923','Malaléel vécut soixante-cinq ans, et il engendra Jared.'),
('gn',5,16,'crampon1923','Après qu''il eut engendré Jared, Malaléel vécut huit cent trente ans, et il engendra des fils et des filles.'),
('gn',5,17,'crampon1923','Tout le temps que Malaléel vécut fut de huit cent quatre-vingt-quinze ans, et il mourut.'),
('gn',5,18,'crampon1923','Jared vécut cent soixante-deux ans, et il engendra Hénoch.'),
('gn',5,19,'crampon1923','Après qu''il eut engendré Hénoch, Jared vécut huit cents ans, et il engendra des fils et des filles.'),
('gn',5,20,'crampon1923','Tout le temps que Jared vécut fut de neuf cent soixante-deux ans, et il mourut.'),
('gn',5,21,'crampon1923','Hénoch vécut soixante-cinq ans, et il engendra Mathusalem.'),
('gn',5,22,'crampon1923','Après qu''il eut engendré Mathusalem, Hénoch marcha avec Dieu trois cents ans, et il engendra des fils et des filles.'),
('gn',5,23,'crampon1923','Tout le temps qu''Hénoch vécut fut de trois cent soixante-cinq ans.'),
('gn',5,24,'crampon1923','Hénoch marcha avec Dieu, et on ne le vit plus, car Dieu l''avait pris.'),
('gn',5,25,'crampon1923','Mathusalem vécut cent quatre-vingt-sept ans, et il engendra Lamech.'),
('gn',5,26,'crampon1923','Après qu''il eut engendré Lamech, Mathusalem vécut sept cent quatre-vingt-deux ans, et il engendra des fils et des filles.'),
('gn',5,27,'crampon1923','Tout le temps que Mathusalem vécut fut de neuf cent soixante-neuf ans, et il mourut.'),
('gn',5,28,'crampon1923','Lamech vécut cent quatre-vingt-deux ans, et il engendra un fils.'),
('gn',5,29,'crampon1923','Il lui donna le nom de Noé, en disant: " Celui-ci nous soulagera de nos fatigues et du travail pénible de nos mains, provenant de ce sol qu''a maudit Yahweh. "'),
('gn',5,30,'crampon1923','Après qu''il eut engendré Noé, Lamech vécut cinq cent quatre-vingt-quinze ans, et il engendra des fils et des filles.'),
('gn',5,31,'crampon1923','Tout le temps que Lamech vécut fut de sept cent soixante-dix-sept ans, et il mourut.'),
('gn',5,32,'crampon1923','Noé, âgé de cinq cents ans, engendra Sem, Cham et Japheth.'),
('gn',6,1,'crampon1923','Lorsque les hommes eurent commencé à être nombreux sur la surface de la terre, et qu''il leur fut né des filles,'),
('gn',6,2,'crampon1923','les fils de Dieu virent que les filles des hommes étaient belles, et ils en prirent pour femmes parmi toutes celles qui leur plurent.'),
('gn',6,3,'crampon1923','Et Yahweh dit: " Mon esprit ne demeurera pas toujours dans l''homme, car l''homme n''est que chair, et ses jours seront de cent vingt ans. "'),
('gn',6,4,'crampon1923','Or, les géants étaient sur la terre en ces jours-là, et cela après que les fils de Dieu furent venus vers les filles des hommes, et qu''elles leur eurent donné des enfants: ce sont là les héros renommés dès les temps anciens.'),
('gn',6,5,'crampon1923','Yahweh vit que la méchanceté des hommes était grande sur la terre, et que toutes les pensées de leur cœur se portaient chaque jour uniquement vers le mal.'),
('gn',6,6,'crampon1923','Et Yahweh se repentit d''avoir fait l''homme sur la terre, et il fut affligé dans son cœur,'),
('gn',6,7,'crampon1923','et il dit: " J''exterminerai de dessus la terre l''homme que j''ai créé, depuis l''homme jusqu''aux animaux domestiques, aux reptiles et aux oiseaux du ciel, car je me repens de les avoir faits. "'),
('gn',6,8,'crampon1923','Mais Noé trouva grâce aux yeux de Yahweh.'),
('gn',6,9,'crampon1923','Voici l''histoire de Noé. Noé était un homme juste, intègre parmi les hommes de son temps; Noé marchait avec Dieu.'),
('gn',6,10,'crampon1923','Noé engendra trois fils, Sem, Cham et Japheth.'),
('gn',6,11,'crampon1923','Or la terre se corrompit devant Dieu et se remplit de violence.'),
('gn',6,12,'crampon1923','Dieu regarda la terre, et voici qu''elle était corrompue, car toute chair avait corrompu sa voie sur la terre.'),
('gn',6,13,'crampon1923','Alors Dieu dit à Noé: " La fin de toute chair est venue devant moi, car la terre est pleine de violence à cause d''eux; je vais les détruire, ainsi que la terre.'),
('gn',6,14,'crampon1923','Fais-toi une arche de bois résineux; tu la feras composée de cellules et tu l''enduiras de bitume en dedans et en dehors.'),
('gn',6,15,'crampon1923','Voici comment tu la feras: la longueur de l''arche sera de trois cents coudées, sa largeur de cinquante coudées et sa hauteur de trente.'),
('gn',6,16,'crampon1923','Tu feras à l''arche une ouverture, à laquelle tu donneras une coudée depuis le toit; tu établiras une porte sur le côté de l''arche, et tu feras un premier, un second et un troisième étage de cellules.'),
('gn',6,17,'crampon1923','Et moi, je vais faire venir le déluge, une inondation de la terre, pour détruire de dessous le ciel toute chair ayant en soi souffle de vie; tout ce qui est sur la terre périra.'),
('gn',6,18,'crampon1923','Mais j''établirai mon alliance avec toi; et tu entreras dans l''arche, toi et tes fils, ta femme et les femmes de tes fils avec toi.'),
('gn',6,19,'crampon1923','De tout ce qui vit, de toute chair, tu feras entrer dans l''arche deux de chaque espèce, pour les conserver en vie avec toi; ce sera un mâle et une femelle.'),
('gn',6,20,'crampon1923','Des oiseaux des diverses espèces, des animaux domestiques des diverses espèces, et de toutes les espèces d''animaux qui rampent sur le sol, deux de toute espèce viendront vers toi, pour que tu leur conserves la vie.'),
('gn',6,21,'crampon1923','Et toi, prends de tous les aliments que l''on mange et fais-en provision près de toi, afin qu''ils te servent de nourriture, ainsi qu''à eux. "'),
('gn',6,22,'crampon1923','Noé se mit à l''œuvre; il fit tout ce que Dieu lui avait ordonné.'),
('gn',7,1,'crampon1923','Yahweh dit à Noé: " Entre dans l''arche, toi et toute ta maison, car je t''ai vu juste devant moi au milieu de cette génération.'),
('gn',7,2,'crampon1923','De tous les animaux purs, tu en prendras avec toi sept paires, des mâles et leurs femelles, et de tous les animaux qui ne sont pas purs, tu en prendras deux, un mâle et sa femelle;'),
('gn',7,3,'crampon1923','sept paires aussi des oiseaux du ciel, des mâles et leurs femelles, pour conserver en vie leur race sur la face de toute la terre.'),
('gn',7,4,'crampon1923','Car, encore sept jours et je ferai pleuvoir sur la terre pendant quarante jours et quarante nuits, et j''exterminerai de la face de la terre tous les êtres que j''ai faits. "'),
('gn',7,5,'crampon1923','Noé fit tout ce que Yahweh lui avait ordonné.'),
('gn',7,6,'crampon1923','Il avait six cents ans quand eut lieu le déluge, une inondation de la terre.'),
('gn',7,7,'crampon1923','Noé entra dans l''arche avec ses fils, sa femme et les femmes de ses fils pour échapper aux eaux du déluge.'),
('gn',7,8,'crampon1923','Des animaux purs et de ceux qui ne sont pas purs, des oiseaux et de tout ce qui rampe sur le sol,'),
('gn',7,9,'crampon1923','chaque paire, mâle et femelle, vint vers Noé dans l''arche, comme Dieu l''avait ordonné à Noé.'),
('gn',7,10,'crampon1923','Et, au bout de sept jours, les eaux du déluge se répandirent sur la terre.'),
('gn',7,11,'crampon1923','L''an six cent de la vie de Noé, au deuxième mois, le dix-septième jour du mois, en ce jour-là, toutes les sources du grand abîme jaillirent et les écluses du ciel s''ouvrirent,'),
('gn',7,12,'crampon1923','et la pluie tomba sur la terre durant quarante jours et quarante nuits.'),
('gn',7,13,'crampon1923','Ce même jour, Noé entra dans l''arche, avec Sem, Cham et Japhet, fils de Noé, la femme de Noé et les trois femmes de ses fils avec eux,'),
('gn',7,14,'crampon1923','eux et toutes les bêtes des diverses espèces, tous les animaux domestiques des diverses espèces, tous les reptiles des diverses espèces qui rampent sur la terre, et tous les oiseaux des diverses espèces, tous les petits oiseaux, tout ce qui a des ailes.'),
('gn',7,15,'crampon1923','Ils vinrent vers Noé dans l''arche, deux à deux, de toute chair ayant souffle de vie.'),
('gn',7,16,'crampon1923','Ils arrivaient mâle et femelle, de toute chair, comme Dieu l''avait ordonné à Noé. Et Yahweh ferma la porte sur lui.'),
('gn',7,17,'crampon1923','Le déluge fut quarante jours sur la terre; les eaux grossirent et soulevèrent l''arche, et elle s''éleva au-dessus de la terre.'),
('gn',7,18,'crampon1923','Les eaux crûrent et devinrent extrêmement grosses sur la terre, et l''arche flotta sur les eaux.'),
('gn',7,19,'crampon1923','Les eaux, ayant grossi de plus en plus, couvrirent toutes les hautes montagnes qui sont sous le ciel tout entier.'),
('gn',7,20,'crampon1923','Les eaux s''élevèrent de quinze coudées au-dessus des montagnes qu''elles recouvraient.'),
('gn',7,21,'crampon1923','Toute chair qui se meut sur la terre périt: oiseaux, animaux domestiques, bêtes sauvages, tout ce qui rampe sur la terre, ainsi que tous les hommes.'),
('gn',7,22,'crampon1923','De tout ce qui existe sur la terre sèche, tout ce qui a souffle de vie dans les narines mourut.'),
('gn',7,23,'crampon1923','Tout être qui se trouve sur la face du sol fut détruit, depuis l''homme jusqu''à l''animal domestique, jusqu''aux reptiles et jusqu''aux oiseaux du ciel; ils furent exterminés de la terre, et il ne resta que Noé et ce qui était avec lui dans l''arche.'),
('gn',7,24,'crampon1923','Les eaux furent hautes sur la terre pendant cent cinquante jours.'),
('gn',8,1,'crampon1923','Dieu se souvint de Noé, de toutes les bêtes et de tous les animaux domestiques qui étaient avec lui dans l''arche, et Dieu fit passer un vent sur la terre, et les eaux baissèrent;'),
('gn',8,2,'crampon1923','les sources de l''abîme et les écluses du ciel se fermèrent, et la pluie cessa de tomber du ciel.'),
('gn',8,3,'crampon1923','Les eaux se retirèrent de dessus la terre, allant et revenant, et elles s''abaissèrent au bout de cent cinquante jours.'),
('gn',8,4,'crampon1923','Au septième mois, le dix-septième jour du mois, l''arche s''arrêta sur les montagnes d''Ararat.'),
('gn',8,5,'crampon1923','Les eaux allèrent se retirant jusqu''au dixième mois; et, au dixième mois, le premier jour du mois, apparurent les sommets des montagnes.'),
('gn',8,6,'crampon1923','Au bout de quarante jours, Noé ouvrit la fenêtre qu''il avait faite à l''arche,'),
('gn',8,7,'crampon1923','et lâcha le corbeau, qui sortit, allant et revenant, jusqu''à ce que les eaux fussent séchées au-dessus de la terre.'),
('gn',8,8,'crampon1923','Il lâcha ensuite la colombe d''auprès de lui, pour voir si les eaux avaient diminué de la surface de la terre.'),
('gn',8,9,'crampon1923','Mais la colombe, n''ayant pas trouvé où poser la plante de son pied, revint vers lui dans l''arche; parce qu''il y avait encore des eaux à la surface de toute la terre. Il étendit la main et, l''ayant prise, il la fit rentrer auprès de lui dans l''arche.'),
('gn',8,10,'crampon1923','Il attendit encore sept autres jours, et il lâcha de nouveau la colombe hors de l''arche,'),
('gn',8,11,'crampon1923','et la colombe revint vers lui sur le soir, et voici, une feuille d''olivier toute fraîche était dans son bec; et Noé reconnut que les eaux ne couvraient plus la terre.'),
('gn',8,12,'crampon1923','Il attendit encore sept autres jours, et il lâcha la colombe; et elle ne revint plus vers lui.'),
('gn',8,13,'crampon1923','L''an six cent un, au premier mois, le premier jour du mois, les eaux avaient séché sur la terre. Noé ôta la couverture de l''arche et regarda, et voici, la surface du sol avait séché.'),
('gn',8,14,'crampon1923','Au second mois, le vingt-septième jour du mois, la terre fut sèche.'),
('gn',8,15,'crampon1923','Alors Dieu parla à Noé, en disant:'),
('gn',8,16,'crampon1923','" Sors de l''arche, toi et ta femme, tes fils et les femmes de tes fils avec toi.'),
('gn',8,17,'crampon1923','Toutes les bêtes de toute chair, qui sont avec toi, oiseaux, animaux domestiques, et tous les reptiles qui rampent sur la terre, fais-les sortir avec toi; qu''ils se répandent sur la terre, qu''ils soient féconds et multiplient sur la terre. "'),
('gn',8,18,'crampon1923','Noé sortit, lui et ses fils, sa femme et les femmes de ses fils.'),
('gn',8,19,'crampon1923','Toutes les bêtes, tous les reptiles et tous les oiseaux, tous les êtres qui se meuvent sur la terre, selon leurs espèces, sortirent de l''arche.'),
('gn',8,20,'crampon1923','Noé construisit un autel à Yahweh et, ayant pris de tous les animaux purs et de tous les oiseaux purs, il offrit des holocaustes sur l''autel.'),
('gn',8,21,'crampon1923','Yahweh sentit une odeur agréable, et Yahweh dit en son cœur: " Je ne maudirai plus désormais la terre à cause de l''homme, parce que les pensées du cœur de l''homme sont mauvaises dès sa jeunesse, et je ne frapperai plus tout être vivant, comme je l''ai fait.'),
('gn',8,22,'crampon1923','Désormais, tant que la terre durera, les semailles et la moisson, le froid et le chaud, l''été et l''hiver, le jour et la nuit ne cesseront point. "'),
('gn',9,1,'crampon1923','Dieu bénit Noé et ses fils et leur dit: " Soyez féconds, multipliez et remplissez la terre.'),
('gn',9,2,'crampon1923','Vous serez craints et redoutés de toute bête de la terre, de tout oiseau du ciel, de tout ce qui se meut sur la terre et de tous les poissons de la mer: ils sont livrés entre vos mains.'),
('gn',9,3,'crampon1923','Tout ce qui se meut et qui a vie vous servira de nourriture; je vous donne tout cela, comme je vous avais donné l''herbe verte.'),
('gn',9,4,'crampon1923','Seulement vous ne mangerez point de chair avec son âme, c''est-à-dire avec son sang.'),
('gn',9,5,'crampon1923','Et votre sang à vous, j''en demanderai compte à cause de vos âmes, j''en demanderai compte à toute bête; de la main de l''homme, de la main de l''homme qui est son frère, je redemanderai l''âme de l''homme.'),
('gn',9,6,'crampon1923','Quiconque aura versé le sang de l''homme, par l''homme son sang sera versé, car Dieu a fait l''homme à son image.'),
('gn',9,7,'crampon1923','Vous, soyez féconds et multipliez; répandez-vous sur la terre et vous y multipliez. "'),
('gn',9,8,'crampon1923','Dieu dit encore à Noé et à ses fils avec lui:'),
('gn',9,9,'crampon1923','" Et moi, je vais établir mon alliance avec vous et avec votre postérité après vous,'),
('gn',9,10,'crampon1923','avec tous les êtres vivants qui sont avec vous, oiseaux, animaux domestiques et toutes les bêtes de la terre avec vous, depuis tous ceux qui sont sortis de l''arche jusqu''à toute bête de la terre.'),
('gn',9,11,'crampon1923','J''établis mon alliance avec vous: aucune chair ne sera plus détruite par les eaux du déluge, et il n''y aura plus de déluge pour ravager la terre. "'),
('gn',9,12,'crampon1923','Et Dieu dit: " Voici le signe de l''alliance que je mets entre moi et vous, et tous les êtres vivants qui sont avec vous, pour toutes les générations à venir.'),
('gn',9,13,'crampon1923','J''ai mis mon arc dans la nue, et il deviendra signe d''alliance entre moi et la terre.'),
('gn',9,14,'crampon1923','Quand j''assemblerai des nuées au-dessus de la terre, l''arc apparaîtra dans la nue,'),
('gn',9,15,'crampon1923','et je me souviendrai de mon alliance entre moi et vous et tout être vivant, de toute chair, et les eaux ne deviendront plus un déluge détruisant toute chair.'),
('gn',9,16,'crampon1923','L''arc sera dans la nue et, en le regardant, je me souviendrai de l''alliance éternelle qui existe entre Dieu et tous les êtres vivants, de toute chair, qui sont sur la terre. "'),
('gn',9,17,'crampon1923','Et Dieu dit à Noé: " Tel est le signe de l''alliance que j''ai établie entre moi et toute chair qui est sur la terre. "'),
('gn',9,18,'crampon1923','Les fils de Noé qui sortirent de l''arche étaient Sem, Cham et Japheth; et Cham était père de Chanaan.'),
('gn',9,19,'crampon1923','Ces trois sont les fils de Noé, et c''est par eux que fut peuplée toute la terre.'),
('gn',9,20,'crampon1923','Noé, qui était cultivateur, commença à planter de la vigne.'),
('gn',9,21,'crampon1923','Ayant bu du vin, il s''enivra, et il se découvrit au milieu de sa tente.'),
('gn',9,22,'crampon1923','Cham, père de Chanaan, vit la nudité de son père, et il alla le rapporter dehors à ses deux frères.'),
('gn',9,23,'crampon1923','Alors Sem avec Japheth prit le manteau de Noé et, l''ayant mis sur leurs épaules, ils marchèrent à reculons et couvrirent la nudité de leur père.'),
('gn',9,24,'crampon1923','Comme leur visage était tourné en arrière, ils ne virent pas la nudité de leur père. Lorsque Noé se réveilla de son ivresse, il apprit ce que lui avait fait son plus jeune fils,'),
('gn',9,25,'crampon1923','et il dit: Maudit soit Chanaan! Il sera pour ses frères le serviteur des serviteurs!'),
('gn',9,26,'crampon1923','Puis il dit: Béni soit Yahweh, Dieu de Sem, et que Chanaan soit son serviteur!'),
('gn',9,27,'crampon1923','Que Dieu donne de l''espace à Japheth, qu''il habite dans les tentes de Sem, et que Chanaan soit son serviteur!'),
('gn',9,28,'crampon1923','Noé vécut après le déluge trois cent cinquante ans.'),
('gn',9,29,'crampon1923','Tous les jours de Noé furent de neuf cent cinquante ans, et il mourut.'),
('gn',10,1,'crampon1923','Voici la postérité des fils de Noé, Sem, Cham et Japheth. Il leur naquit des fils après le déluge.'),
('gn',10,2,'crampon1923','Fils de Japheth: Gomer, Magog, Madaï, Javan, Thubal, Mosoch et Tiras.'),
('gn',10,3,'crampon1923','Fils de Gomer: Ascénez, Riphath et Thogorma. —'),
('gn',10,4,'crampon1923','Fils de Javan: Elisa et Tharsis, Cetthim et Dodanim.'),
('gn',10,5,'crampon1923','C''est d''eux que viennent les peuples dispersés dans les îles des nations, dans leurs divers pays, chacun selon sa langue, selon leurs familles, selon leurs nations.'),
('gn',10,6,'crampon1923','Fils de Cham: Chus, Mesraïm, Phuth et Chanaan. —'),
('gn',10,7,'crampon1923','Fils de Chus: Saba, Hévila, Sabatha, Regma et Sabathaca. Fils de Regma: Saba et Dadan.'),
('gn',10,8,'crampon1923','Chus engendra Nemrod: celui-ci fut le premier un homme puissant sur la terre.'),
('gn',10,9,'crampon1923','Ce fut un vaillant chasseur devant Yahweh; c''est pourquoi l''on dit: " Comme Nemrod, vaillant chasseur devant Yahweh. "'),
('gn',10,10,'crampon1923','Le commencement de son empire fut Babel, Arach, Achad et Chalanné au pays de Sennaar.'),
('gn',10,11,'crampon1923','De ce pays il alla en Assur, et bâtit Ninive, Rechoboth-Ir, Chalé,'),
('gn',10,12,'crampon1923','et Résen, entre Ninive et Chalé; c''est la grande ville. —'),
('gn',10,13,'crampon1923','Mesraïm engendra les Ludim, les Anamim, les Laabim, les Nephthuim,'),
('gn',10,14,'crampon1923','les Phétrusim, les Chasluim, d''où sont sortis les Philistins, et les Caphtorim. —'),
('gn',10,15,'crampon1923','Chanaan engendra Sidon, son premier-né, et Heth,'),
('gn',10,16,'crampon1923','ainsi que les Jébuséens, les Amorrhéens, les Gergéséens,'),
('gn',10,17,'crampon1923','les Hévéens, les Aracéens, les Sinéens,'),
('gn',10,18,'crampon1923','les Aradiens, les Samaréens et les Hamathéens. Ensuite les familles des Chananéens se répandirent dans le pays,'),
('gn',10,19,'crampon1923','et le territoire des Chananéens alla depuis Sidon, dans la direction de Gérare, jusqu''à Gaza; et, dans la direction de Sodome, Gomorrhe, Adama, et Séboïm, jusqu''à Lésa. —'),
('gn',10,20,'crampon1923','Tels sont les fils de Cham selon leurs familles, selon leurs langues, dans leurs divers pays, dans leurs nations.'),
('gn',10,21,'crampon1923','Des fils naquirent aussi à Sem, qui est le père de tous les fils d''Héber et le frère aîné de Japheth.'),
('gn',10,22,'crampon1923','Fils de Sem: Elam, Assur, Arphaxad, Lud et Aram. —'),
('gn',10,23,'crampon1923','Fils d''Aram: Us, Hul, Géther et Mes. —'),
('gn',10,24,'crampon1923','Arphaxad engendra Salé, et Salé engendra Héber.'),
('gn',10,25,'crampon1923','Et il naquit à Héber deux fils: le nom de l''un était Phaleg, parce que de son temps la terre était partagée, et le nom de son frère était Jectan.'),
('gn',10,26,'crampon1923','Jectan engendra Elmodad, Saleph, Asarmoth, Jaré,'),
('gn',10,27,'crampon1923','Aduram, Uzal, Décla,'),
('gn',10,28,'crampon1923','Ebal, Abimaël, Saba,'),
('gn',10,29,'crampon1923','Ophir, Hévila et Jobab. Tous ceux-là sont fils de Jectan.'),
('gn',10,30,'crampon1923','Le pays qu''ils habitèrent fut la montagne d''Orient, à partir de Mésa, dans la direction de Séphar. —'),
('gn',10,31,'crampon1923','Tels sont les fils de Sem, selon leurs familles, selon leurs langues, dans leurs divers pays, selon leurs nations.'),
('gn',10,32,'crampon1923','Telles sont les familles des fils de Noé selon leurs générations, dans leurs nations. C''est d''eux que sont sorties les nations qui se sont répandues sur la terre après le déluge.'),
('gn',11,1,'crampon1923','Toute la terre avait une seule langue et les mêmes mots.'),
('gn',11,2,'crampon1923','Etant partis de l''Orient, les hommes trouvèrent une plaine dans le pays de Sennaar, et ils s''y établirent.'),
('gn',11,3,'crampon1923','Ils se dirent entre eux: " Allons, faisons des briques, et cuisons-les au feu. " Et ils se servirent de briques au lieu de pierres, et de bitume au lieu de ciment.'),
('gn',11,4,'crampon1923','Ils dirent encore: " Allons, bâtissons-nous une ville et une tour dont le sommet soit dans le ciel, et faisons-nous un monument, de peur que nous ne soyons dispersés sur la face de toute la terre. "'),
('gn',11,5,'crampon1923','Mais Yahweh descendit pour voir la ville et la tour que bâtissaient les fils des hommes.'),
('gn',11,6,'crampon1923','Et Yahweh dit: " Voici, ils sont un seul peuple et ils ont pour eux tous une même langue; et cet ouvrage est le commencement de leurs entreprises; maintenant rien ne les empêchera d''accomplir leurs projets.'),
('gn',11,7,'crampon1923','Allons, descendons, et là même confondons leur langage, de sorte qu''ils n''entendent plus le langage les uns des autres. "'),
('gn',11,8,'crampon1923','C''est ainsi que Yahweh les dispersa de là sur la face de toute la terre, et ils cessèrent de bâtir la ville.'),
('gn',11,9,'crampon1923','C''est pourquoi on lui donna le nom de Babel, car c''est là que Yahweh confondit le langage de toute la terre, et c''est de là que Yahweh les a dispersés sur la face de toute la terre.'),
('gn',11,10,'crampon1923','Voici l''histoire de Sem: Sem, âgé de cent ans, engendra Arphaxad, deux ans après le déluge.'),
('gn',11,11,'crampon1923','Après qu''il eut engendré Arphaxad, Sem vécut cinq cents ans, et il engendra des fils et des filles.'),
('gn',11,12,'crampon1923','Arphaxad vécut trente-cinq ans, et il engendra Salé.'),
('gn',11,13,'crampon1923','Après qu''il eut engendré Salé, Arphaxad vécut quatre cent trois ans, et il engendra des fils et des filles.'),
('gn',11,14,'crampon1923','Salé vécut trente ans, et il engendra Héber.'),
('gn',11,15,'crampon1923','Après qu''il eut engendré Héber, Salé vécut quatre cent trois ans, et il engendra des fils et des filles.'),
('gn',11,16,'crampon1923','Héber vécut trente-quatre ans, et il engendra Phaleg.'),
('gn',11,17,'crampon1923','Après qu''il eut engendré Phaleg, Héber vécut quatre cent trente ans, et il engendra des fils et des filles.'),
('gn',11,18,'crampon1923','Phaleg vécut trente ans, et il engendra Réü.'),
('gn',11,19,'crampon1923','Après qu''il eut engendré Réü, Phaleg vécut deux cent neuf ans, et il engendra des fils et des filles.'),
('gn',11,20,'crampon1923','Réü vécut trente-deux ans, et il engendra Sarug.'),
('gn',11,21,'crampon1923','Après qu''il eut engendré Sarug, Réü vécut deux cent sept ans, et il engendra des fils et des filles.'),
('gn',11,22,'crampon1923','Sarug vécut trente ans, et il engendra Nachor.'),
('gn',11,23,'crampon1923','Après qu''il eut engendré Nachor, Sarug vécut deux cents ans, et il engendra des fils et des filles.'),
('gn',11,24,'crampon1923','Nachor vécut vingt-neuf ans, et il engendra Tharé.'),
('gn',11,25,'crampon1923','Après qu''il eut engendré Tharé, Nachor vécut cent dix-neuf ans, et il engendra des fils et des filles.'),
('gn',11,26,'crampon1923','Tharé vécut soixante-dix ans, et il engendra Abram, Nachor et Aran.'),
('gn',11,27,'crampon1923','Voici l''histoire de Tharé. Tharé engendra Abram, Nachor et Aran. Aran engendra Lot.'),
('gn',11,28,'crampon1923','Et Aran mourut en présence de Tharé, son père, au pays de sa naissance, à Ur en Chaldée.'),
('gn',11,29,'crampon1923','Abram et Nachor prirent des femmes: le nom de la femme d''Abram était Saraï, et le nom de la femme de Nachor était Melcha, fille d''Aran, père de Melcha et père de Jesca.'),
('gn',11,30,'crampon1923','Or Saraï fut stérile: elle n''avait point d''enfants.'),
('gn',11,31,'crampon1923','Tharé prit Abram, son fils, et Lot, fils d''Aran, son petit-fils, et Saraï, sa belle-fille, femme d''Abram, son fils, et ils sortirent ensemble d''Ur des Chaldéens, pour aller au pays de Chanaan; mais, arrivés à Haran, ils s''y établirent.'),
('gn',11,32,'crampon1923','Les jours de Tharé furent de deux cent cinq ans, et Tharé mourut à Haran.'),
('gn',12,1,'crampon1923','Yahweh dit à Abram: " Va-t-en de ton pays, de ta famille et de la maison de ton père, dans le pays que je te montrerai.'),
('gn',12,2,'crampon1923','Je ferai de toi une grande nation, je te bénirai et je rendrai grand ton nom. Tu seras une bénédiction:'),
('gn',12,3,'crampon1923','Je bénirai ceux qui te béniront, et celui qui te maudira, je le maudirai, et toutes les familles de la terre seront bénies en toi. "'),
('gn',12,4,'crampon1923','Abram partit, comme Yahweh le lui avait dit, et Lot s''en alla avec lui. Abram avait soixante-quinze ans quand il sortit de Haran.'),
('gn',12,5,'crampon1923','Abram prit Saraï, sa femme, et Lot, fils de son frère, ainsi que tous les biens qu''ils possédaient et les serviteurs qu''ils avaient acquis à Haran, et ils partirent pour aller au pays de Chanaan. Et ils arrivèrent au pays de Chanaan.'),
('gn',12,6,'crampon1923','Abram traversa le pays jusqu''au lieu nommé Sichem, jusqu''au chêne de Moré. — Les Chananéens étaient alors dans le pays. —'),
('gn',12,7,'crampon1923','Yahweh apparut à Abram et lui dit: " je donnerai ce pays à ta postérité. " Et Abram bâtit là un autel à Yahweh qui lui était apparu.'),
('gn',12,8,'crampon1923','Il passa de là à la montagne, à l''orient de Béthel, et il dressa sa tente, ayant Béthel au couchant et Haï à l''orient. Là encore il bâtit un autel à Yahweh, et il invoqua le nom de Yahweh.'),
('gn',12,9,'crampon1923','Puis Abram s''avança, de campement en campement, vers le Midi.'),
('gn',12,10,'crampon1923','Il y eut une famine dans le pays, et Abram descendit en Egypte pour y séjourner; car la famine était grande dans le pays.'),
('gn',12,11,'crampon1923','Comme il était près d''entrer en Egypte, il dit à Saraï, sa femme: " Voici, je sais que tu es une belle femme;'),
('gn',12,12,'crampon1923','quand les Egyptiens te verront, ils diront: C''est sa femme, et ils me tueront et te laisseront vivre.'),
('gn',12,13,'crampon1923','Dis donc que tu es ma sœur, afin que je sois bien traité à cause de toi, et qu''on me laisse la vie par égard pour toi. "'),
('gn',12,14,'crampon1923','Lorsque Abram fut arrivé en Egypte, les Egyptiens virent que sa femme était fort belle.'),
('gn',12,15,'crampon1923','Les grands de Pharaon, l''ayant vue, la vantèrent à Pharaon, et cette femme fut prise et emmenée dans la maison de Pharaon.'),
('gn',12,16,'crampon1923','Il traita bien Abram à cause d''elle, et Abram reçut des brebis, des bœufs, des ânes, des serviteurs et des servantes, des ânesses et des chameaux.'),
('gn',12,17,'crampon1923','Mais Yahweh frappa de grandes plaies Pharaon et sa maison, à cause de Saraï, femme d''Abram.'),
('gn',12,18,'crampon1923','Pharaon appela alors Abram et lui dit: " Qu''est-ce que tu m''as fait? Pourquoi ne m''as-tu pas déclaré qu''elle était ta femme?'),
('gn',12,19,'crampon1923','Pourquoi as-tu dit: C''est ma sœur; de sorte que je l''ai prise pour femme? Maintenant, voici ta femme; prends-la et va-t''en! "'),
('gn',12,20,'crampon1923','Et Pharaon, ayant donné des ordres à ses gens au sujet d''Abram, ils le renvoyèrent, lui et sa femme, et tout ce qui lui appartenait.'),
('gn',13,1,'crampon1923','Abram remonta d''Egypte vers le Midi, lui, sa femme et tout ce qui lui appartenait, et Lot avec lui.'),
('gn',13,2,'crampon1923','Or Abram était fort riche en troupeaux, en argent et en or.'),
('gn',13,3,'crampon1923','Puis il alla, de campement en campement, du Midi jusqu''à Béthel, jusqu''au lieu où il avait la première fois dressé sa tente, entre Béthel et Haï,'),
('gn',13,4,'crampon1923','à l''endroit où était l''autel qu''il avait précédemment élevé. Et là Abram invoqua le nom de Yahweh.'),
('gn',13,5,'crampon1923','Lot, qui voyageait avec Abram, avait aussi des brebis, des bœufs et des tentes,'),
('gn',13,6,'crampon1923','et la contrée ne leur suffisait pas pour habiter ensemble; car leurs biens étaient trop considérables pour qu''ils pussent demeurer ensemble.'),
('gn',13,7,'crampon1923','Il y eut une querelle entre les bergers des troupeaux d''Abram et les bergers des troupeaux de Lot. — Les Chananéens et les Phérézéens étaient alors établis dans le pays. —'),
('gn',13,8,'crampon1923','Abram dit à Lot: " Qu''il n''y ait pas, je te prie, de débat entre moi et toi, ni entre mes bergers et tes bergers; car nous sommes des frères.'),
('gn',13,9,'crampon1923','Tout le pays n''est-il pas devant toi? Sépare-toi donc de moi. Si tu vas à gauche, je prendrai la droite; et si tu vas à droite, je prendrai la gauche. "'),
('gn',13,10,'crampon1923','Lot, levant les yeux, vit toute la plaine du Jourdain qui était entièrement arrosée: c''était, avant que Yahweh eût détruit Sodome et Gomorrhe, comme le jardin de Yahweh, comme la terre d''Egypte du côté de Tsoar.'),
('gn',13,11,'crampon1923','Lot choisit pour lui toute la plaine du Jourdain, et il s''avança vers l''orient; c''est ainsi qu''ils se séparèrent l''un de l''autre.'),
('gn',13,12,'crampon1923','Abram habitait dans le pays de Chanaan, et Lot habitait dans les villes de la plaine, et il dressa ses tentes jusqu''à Sodome.'),
('gn',13,13,'crampon1923','Or les gens de Sodome étaient fort mauvais et grands pécheurs contre Yahweh.'),
('gn',13,14,'crampon1923','Yahweh dit à Abram, après que Lot se fut séparé de lui: " Lève les yeux et, du lieu où tu es, regarde vers le septentrion et vers le midi, vers l''orient, et vers le couchant:'),
('gn',13,15,'crampon1923','tout le pays que tu vois, je le donnerai à toi et à ta postérité pour toujours.'),
('gn',13,16,'crampon1923','Je rendrai ta postérité nombreuse comme la poussière de la terre; si l''on peut compter la poussière de la terre, on comptera aussi ta postérité.'),
('gn',13,17,'crampon1923','Lève-toi, parcours le pays en long et en large, car, je te le donnerai. "'),
('gn',13,18,'crampon1923','Abram leva ses tentes et vint habiter aux chênes de Mambré, qui sont en Hébron; et il bâtit là un autel à Yahweh.'),
('gn',14,1,'crampon1923','Au temps d''Amraphel, roi de Sennaar, d''Arioch, roi d''Ellasar, de Chodorlahomor, roi d''Elam, et de Thadal, roi de Goïm, il arriva'),
('gn',14,2,'crampon1923','qu''ils firent la guerre à Bara, roi de Sodome, à Bersa, roi de Gomorrhe, à Sennaab, roi d''Adama, à Séméber, roi de Séboïm, et au roi de Bala qui est Ségor.'),
('gn',14,3,'crampon1923','Ces derniers s''assemblèrent tous dans la vallée de Siddim, qui est la mer Salée.'),
('gn',14,4,'crampon1923','Car, pendant douze ans, ils avaient été soumis à Chodorlahomor, et la treizième année ils s''étaient révoltés.'),
('gn',14,5,'crampon1923','Mais, la quatorzième année, Chodorlahomor se mit en marche avec les rois qui étaient avec lui, et ils battirent les Réphaïm à Astaroth-Carnaïm, les Zusim à Ham, les Emim dans la plaine de Cariathaïm'),
('gn',14,6,'crampon1923','et les Horréens dans leur montagne de Séir, jusqu''à El-Pharan, qui est près du désert.'),
('gn',14,7,'crampon1923','Puis, s''en retournant, ils arrivèrent à la fontaine du Jugement, qui est Cadès, et ils battirent tout le pays des Amalécites, ainsi que les Amorrhéens qui habitaient à Asason-Thamar.'),
('gn',14,8,'crampon1923','Alors le roi de Sodome s''avança avec le roi de Gomorrhe, le roi d''Adama, le roi de Séboïm et le roi de Bala, qui est Ségor, et ils se rangèrent en bataille contre eux dans la vallée de Siddim,'),
('gn',14,9,'crampon1923','contre Chodorlahomor, roi d''Elam, Thadal, roi de Goïm, Amraphel, roi de Sennaar, et Arioch, roi d''Ellasar, quatre rois contre les cinq.'),
('gn',14,10,'crampon1923','Il y avait dans la vallée de Siddim de nombreux puits de bitume; le roi de Sodome et celui de Gomorrhe prirent la fuite, et ils y tombèrent; le reste s''enfuit dans la montagne.'),
('gn',14,11,'crampon1923','Les vainqueurs enlevèrent tous les biens de Sodome et de Gomorrhe et tous leurs vivres, et ils s''en allèrent.'),
('gn',14,12,'crampon1923','Ils prirent aussi Lot, fils du frère d''Abram, et ses biens, et ils s''en allèrent; or, il demeurait à Sodome.'),
('gn',14,13,'crampon1923','Un des fugitifs vint l''annoncer à Abram l''Hébreu, qui habitait aux chênes de Mambré, l''Amorrhéen, frère d''Eschol et frère d''Aner; ils étaient des alliés d''Abram.'),
('gn',14,14,'crampon1923','Dès qu''Abram apprit que son frère avait été emmené captif, il mit sur pied ses gens les mieux éprouvés, nés dans sa maison, au nombre de trois cent dix-huit, et il poursuivit les rois jusqu''à Dan.'),
('gn',14,15,'crampon1923','Là, ayant partagé sa troupe pour les attaquer de nuit, lui et ses serviteurs, il les battit et les poursuivit jusqu''à Hoba, qui est à gauche de Damas.'),
('gn',14,16,'crampon1923','Il ramena tous les biens; il ramena aussi Lot, son frère, et ses biens, ainsi que les femmes et les gens.'),
('gn',14,17,'crampon1923','Comme Abram revenait vainqueur de Chodorlahomor et des rois qui étaient avec lui, le roi de Sodome sortit à sa rencontre, dans la vallée de Savé; c''est la vallée du Roi.'),
('gn',14,18,'crampon1923','Melchisédech, roi de Salem, apporta du pain et du vin; il était prêtre du Dieu Très-Haut.'),
('gn',14,19,'crampon1923','Il bénit Abram et dit: Béni soit Abram par le Dieu Très-Haut, qui a créé le ciel et la terre!'),
('gn',14,20,'crampon1923','Béni soit le Dieu Très-Haut, qui a livré tes ennemis entre tes mains! " Et Abram lui donna la dîme de tout.'),
('gn',14,21,'crampon1923','Le roi de Sodome dit à Abram: " Donne-moi les personnes et prends pour toi les biens. "'),
('gn',14,22,'crampon1923','Abram répondit au roi de Sodome: " J''ai levé la main vers Yahweh, le Dieu Très-Haut, qui a créé le ciel et la terre:'),
('gn',14,23,'crampon1923','D''un fil à une courroie de sandale, je ne prendrai quoi que ce soit qui t''appartienne! afin que tu ne dises pas: J''ai enrichi Abram.'),
('gn',14,24,'crampon1923','Rien pour moi! Ce qu''ont mangé les jeunes gens et la part des hommes qui sont venus avec moi, Aner, Eschol et Mambré, eux, ils prendront leur part. "'),
('gn',15,1,'crampon1923','Après ces événements, la parole de Yahweh fut adressée à Abram en vision: " Ne crains point, Abram; je suis ton bouclier; ta récompense sera très grande. "'),
('gn',15,2,'crampon1923','Abram répondit: " Seigneur Yahweh, que me donnerez-vous? Je m''en vais sans enfants, et l''héritier de ma maison, c''est Eliézer de Damas. "'),
('gn',15,3,'crampon1923','Et Abram dit: " Voici, vous ne m''avez pas donné de postérité, et un homme attaché à ma maison sera mon héritier. "'),
('gn',15,4,'crampon1923','Alors la parole de Yahweh lui fut adressée en ces termes: " Ce n''est pas lui qui sera ton héritier, mais celui qui sortira de tes entrailles sera ton héritier. "'),
('gn',15,5,'crampon1923','Et, l''ayant conduit dehors, il dit: " Lève ton regard vers le ciel et compte les étoiles, si tu peux les compter. " Et il lui dit: " Telle sera ta postérité. "'),
('gn',15,6,'crampon1923','Abram eut foi à Yahweh, et Yahweh le lui imputa à justice.'),
('gn',15,7,'crampon1923','Et il lui dit: " Je suis Yahweh, qui t''ai fait sortir d''Ur des Chaldéens, afin de te donner ce pays pour le posséder. "'),
('gn',15,8,'crampon1923','Abram répondit: " Seigneur Yahweh, à quoi connaîtrai-je que je le posséderai? "'),
('gn',15,9,'crampon1923','Et Yahweh lui dit: " Prends une génisse de trois ans, une chèvre de trois ans, un bélier de trois ans, une tourterelle et un jeune pigeon. "'),
('gn',15,10,'crampon1923','Abram lui amena tous ces animaux et, les ayant partagés par le milieu, il mit chaque moitié vis-à-vis de l''autre; mais il ne partagea pas les oiseaux.'),
('gn',15,11,'crampon1923','Les oiseaux de proie s''abattirent sur les cadavres, et Abram les chassa.'),
('gn',15,12,'crampon1923','Comme le soleil se couchait, un profond sommeil tomba sur Abram; une terreur, une obscurité profonde tombèrent sur lui.'),
('gn',15,13,'crampon1923','Yahweh dit à Abram: " Sache bien que tes descendants seront étrangers dans un pays qui ne sera pas à eux; ils y seront en servitude et on les opprimera pendant quatre cents ans.'),
('gn',15,14,'crampon1923','Mais je jugerai la nation à laquelle ils auront été asservis, et ensuite ils sortiront avec de grands biens.'),
('gn',15,15,'crampon1923','Toi, tu t''en iras en paix vers tes pères; tu seras mis en terre dans une heureuse vieillesse.'),
('gn',15,16,'crampon1923','A la quatrième génération ils reviendront ici; car jusqu''à présent l''iniquité de l''Amorrhéen n''est pas à son comble. "'),
('gn',15,17,'crampon1923','Lorsque le soleil fut couché et qu''une profonde obscurité fut venue, voici qu''un four fumant et un brandon de feu passaient entre les animaux partagés.'),
('gn',15,18,'crampon1923','En ce jour-là, Yahweh fit alliance avec Abram, en disant: " Je donne à ta postérité ce pays, depuis le fleuve d''Egypte jusqu''au grand fleuve, au fleuve de l''Euphrate:'),
('gn',15,19,'crampon1923','le pays des Cinéens, des Cénézéens, des Cadmonéens,'),
('gn',15,20,'crampon1923','des Héthéens, des Phéréséens, des Rephaïm,'),
('gn',15,21,'crampon1923','des Amorrhéens, des Chananéens, des Gergéséens et des Jébuséens.'),
('gn',16,1,'crampon1923','Saraï, femme d''Abram, ne lui avait pas donné d''enfants; et elle avait une servante égyptienne, nommée Agar.'),
('gn',16,2,'crampon1923','Saraï dit à Abram: " Voici que Yahweh m''a rendue stérile; viens, je te prie, vers ma servante; peut-être aurai-je d''elle des fils. " Abram écouta la voix de Saraï.'),
('gn',16,3,'crampon1923','Saraï, femme d''Abram, prit donc Agar l''Egyptienne, sa servante, après qu''Abram eut habité dix années dans le pays de Chanaan, et elle la donna à Abram, son mari, pour être sa femme.'),
('gn',16,4,'crampon1923','Il alla vers Agar, et elle conçut; et quand elle vit qu''elle avait conçu, elle regarda sa maîtresse avec mépris.'),
('gn',16,5,'crampon1923','Saraï dit à Abram: " L''outrage qui m''est fait tombe sur toi. J''ai mis ma servante dans ton sein et, quand elle a vu qu''elle avait conçu, elle m''a regardée avec mépris. Que Yahweh juge entre moi et toi! "'),
('gn',16,6,'crampon1923','Abram répondit à Saraï: " Voici, ta servante est sous ta puissance; agis à son égard comme bon te semblera. " Alors Saraï la maltraita, et Agar s''enfuit de devant elle.'),
('gn',16,7,'crampon1923','L''ange de Yahweh la trouva près d''une source d''eau dans le désert, près de la source qui est sur le chemin de Sur.'),
('gn',16,8,'crampon1923','Il dit: " Agar, servante de Saraï, d''où viens-tu et où vas-tu? " Elle répondit: " Je fuis loin de Saraï, ma maîtresse. "'),
('gn',16,9,'crampon1923','L''ange de Yahweh lui dit: " Retourne vers ta maîtresse et humilie-toi sous sa main. "'),
('gn',16,10,'crampon1923','L''ange de Yahweh ajouta: " Je multiplierai extrêmement ta postérité; on ne pourra la compter, tant elle sera nombreuse. "'),
('gn',16,11,'crampon1923','L''ange de Yahweh lui dit encore: " Voici que tu es enceinte, et tu enfanteras un fils, et tu lui donneras le nom d''Ismaël, parce que Yahweh a entendu ton affliction.'),
('gn',16,12,'crampon1923','Ce sera un âne sauvage que cet homme; sa main sera contre tous, et la main de tous sera contre lui, et il habitera en face de tous ses frères. "'),
('gn',16,13,'crampon1923','Agar donna à Yahweh qui lui avait parlé le nom de Atta-El-Roï car elle avait dit: " Ai-je donc ici même vu le Dieu qui me voyait? "'),
('gn',16,14,'crampon1923','C''est pourquoi on a appelé ce puits le puits Lachaï-Roï. Il est situé entre Cadès et Barad.'),
('gn',16,15,'crampon1923','Agar enfanta un fils à Abram, et Abram donna le nom d''Ismaël au fils qu''Agar avait mis au monde.'),
('gn',16,16,'crampon1923','Abram était âgé de quatre-vingt-six ans lorsqu''Agar enfanta Ismaël à Abram.'),
('gn',17,1,'crampon1923','Lorsque Abram fut arrivé à l''âge de quatre-vingt-dix-neuf ans, Yahweh lui apparut et lui dit: " Je suis le Dieu tout-puissant; marche devant ma face et sois irréprochable:'),
('gn',17,2,'crampon1923','j''établirai mon alliance entre moi et toi, et je te multiplierai à l''infini. "'),
('gn',17,3,'crampon1923','Abram tomba la face contre terre, et Dieu lui parla ainsi:'),
('gn',17,4,'crampon1923','" Moi, voici mon alliance avec toi: tu deviendras père d''une multitude de nations.'),
('gn',17,5,'crampon1923','On ne te nommera plus Abram, mais ton nom sera Abraham, car je te fais père d''une multitude de nations.'),
('gn',17,6,'crampon1923','Je te ferai croître extraordinairement, je ferai de toi des nations, et des rois sortiront de toi.'),
('gn',17,7,'crampon1923','J''établis mon alliance, entre moi et toi et tes descendants après toi, d''âge en âge, en une alliance perpétuelle, pour être ton Dieu et le Dieu de tes descendants après toi.'),
('gn',17,8,'crampon1923','Je te donnerai, à toi et à tes descendants après toi, le pays où tu séjournes comme étranger, tout le pays de Chanaan, en possession perpétuelle, et je serai leur Dieu ".'),
('gn',17,9,'crampon1923','Dieu dit à Abraham: " Et toi, tu garderas mon alliance, toi et tes descendants après toi, d''âge en âge.'),
('gn',17,10,'crampon1923','Voici l''alliance que vous avez à garder, l''alliance entre moi et vous, et tes descendants après toi: tout mâle parmi vous sera circoncis.'),
('gn',17,11,'crampon1923','Vous vous circoncirez dans votre chair, et ce sera le signe de l''alliance entre moi et vous.'),
('gn',17,12,'crampon1923','Quand il aura huit jours, tout mâle parmi vous, d''âge en âge, sera circoncis, qu''il soit né dans la maison, ou qu''il ait été acquis à prix d''argent d''un étranger quelconque, qui n''est pas de ta race.'),
('gn',17,13,'crampon1923','On devra circoncire le mâle né dans la maison ou acquis à prix d''argent, et mon alliance sera dans votre chair comme alliance perpétuelle.'),
('gn',17,14,'crampon1923','Un mâle incirconcis, qui n''aura pas été circoncis dans sa chair, sera retranché de son peuple: il aura violé mon alliance. "'),
('gn',17,15,'crampon1923','Dieu dit à Abraham: " Tu ne donneras plus à Saraï, ta femme, le nom de Saraï, car son nom est Sara.'),
('gn',17,16,'crampon1923','Je la bénirai, et je te donnerai aussi d''elle un fils; je la bénirai, et elle deviendra des nations; des rois de peuples sortiront d''elle. "'),
('gn',17,17,'crampon1923','Abraham tomba la face contre terre, et il rit, disant dans son cœur: " Naîtra-t-il un fils à un homme de cent ans? Et Sara, une femme de quatre-vingt-dix ans, enfantera-t-elle? "'),
('gn',17,18,'crampon1923','Et Abraham dit à Dieu: " Oh! qu'' Ismaël vive devant votre face! "'),
('gn',17,19,'crampon1923','Dieu dit: " Oui, Sara, ta femme, t''enfantera un fils; tu le nommeras Isaac, et j''établirai mon alliance avec lui comme une alliance perpétuelle pour ses descendants après lui.'),
('gn',17,20,'crampon1923','Quant à Ismaël, je t''ai entendu. Voici, je l''ai béni, je le rendrai fécond et je le multiplierai extrêmement; il engendrera douze princes, et je ferai de lui une grande nation.'),
('gn',17,21,'crampon1923','Mais mon alliance, je l''établirai avec Isaac, que Sara t''enfantera l''année prochaine, à cette époque. "'),
('gn',17,22,'crampon1923','Et ayant achevé de parler avec lui, Dieu remonta d''auprès d''Abraham.'),
('gn',17,23,'crampon1923','Abraham prit Ismaël, son fils, ainsi que tous les serviteurs nés dans sa maison et tous ceux qu''il avait acquis à prix d''argent, tous les mâles parmi les gens de sa maison, et il les circoncit en ce jour même, comme Dieu le lui avait commandé.'),
('gn',17,24,'crampon1923','Abraham était âgé de quatre-vingt-dix-neuf ans lorsqu''il fut circoncis;'),
('gn',17,25,'crampon1923','et Ismaël, son fils, avait treize ans lorsqu''il fut circoncis.'),
('gn',17,26,'crampon1923','Ce même jour, Abraham fut circoncis, ainsi qu''Ismaël, son fils;'),
('gn',17,27,'crampon1923','et tous les hommes de sa maison, ceux qui étaient nés chez lui et ceux qui avaient été acquis des étrangers à prix d''argent, furent circoncis avec lui.'),
('gn',18,1,'crampon1923','Yahweh lui apparut aux chênes de Mambré, comme il était assis à l''entrée de la tente pendant la chaleur du jour.'),
('gn',18,2,'crampon1923','Il leva les yeux et il regarda, et voici que trois hommes se tenaient debout devant lui. Dès qu''il les vit, il courut de l''entrée de la tente au-devant d''eux et, s''étant prosterné en terre,'),
('gn',18,3,'crampon1923','il dit: " Seigneur, si j''ai trouvé grâce à tes yeux, ne passe pas, je te prie, loin de ton serviteur.'),
('gn',18,4,'crampon1923','Permettez qu''on apporte un peu d''eau pour vous laver les pieds. Reposez-vous sous cet arbre;'),
('gn',18,5,'crampon1923','je vais prendre un morceau de pain, vous fortifierez votre cœur et vous continuerez votre chemin; car c''est pour cela que vous avez passé devant votre serviteur. " Ils répondirent: " Fais comme tu l''as dit. "'),
('gn',18,6,'crampon1923','Abraham s''empressa de revenir dans la tente vers Sara, et il dit: " Vite, trois mesures de farine; pétris et fais des gâteaux. "'),
('gn',18,7,'crampon1923','Puis Abraham courut au troupeau et, ayant pris un veau tendre et bon, il le donna au serviteur qui se hâta de l''apprêter.'),
('gn',18,8,'crampon1923','Il prit aussi du beurre et du lait, avec le veau qu''on avait apprêté, et il les mit devant eux; lui se tenait debout près d''eux sous l''arbre. Et ils mangèrent.'),
('gn',18,9,'crampon1923','Alors ils lui dirent: " Où est Sara, ta femme? " Il répondit: " Elle est là, dans la tente. "'),
('gn',18,10,'crampon1923','Et il dit: " Je reviendrai chez toi à cette époque même, et voici, Sara, ta femme, aura un fils. " Sara entendait ces paroles à l''entrée de la tente, derrière lui.'),
('gn',18,11,'crampon1923','— Or Abraham et Sara étaient vieux, avancés en jours; Sara était hors d''âge. —'),
('gn',18,12,'crampon1923','Sara rit en elle-même, en se disant: " Vieille comme je suis, connaîtrais-je encore le plaisir? Et mon seigneur aussi est vieux. "'),
('gn',18,13,'crampon1923','Yahweh dit à Abraham: " Pourquoi Sara a-t-elle ri en disant: Est-ce que vraiment j''aurais un enfant, vieille comme je suis?'),
('gn',18,14,'crampon1923','Y a-t-il rien qui soit étonnant de la part de Yahweh? Au temps fixé, je reviendrai vers toi, à cette même saison, et Sara aura un fils. "'),
('gn',18,15,'crampon1923','Sara nia, en disant: " Je n''ai pas ri "; car elle eut peur. Mais il lui dit: " Non, tu as ri. "'),
('gn',18,16,'crampon1923','Ces hommes se levèrent pour partir et se tournèrent du côté de Sodome; Abraham allait avec eux pour les accompagner.'),
('gn',18,17,'crampon1923','Alors Yahweh dit: " Cacherai-je à Abraham ce que je vais faire?'),
('gn',18,18,'crampon1923','Car Abraham doit devenir une nation grande et forte, et toutes les nations de la terre seront bénies en lui.'),
('gn',18,19,'crampon1923','Je l''ai choisi, en effet, afin qu''il ordonne à ses fils et à sa maison après lui de garder la voie de Yahweh, en pratiquant l''équité et la justice, et qu''ainsi Yahweh accomplisse en faveur d''Abraham les promesses qu''il lui a faites. "'),
('gn',18,20,'crampon1923','Et Yahweh dit: " Le cri qui s''élève de Sodome et de Gomorrhe est bien fort, et leur péché bien énorme.'),
('gn',18,21,'crampon1923','Je veux descendre et voir si, selon le cri qui est venu jusqu''à moi, leur crime est arrivé au comble; et s''il n''en est pas ainsi, je le saurai. "'),
('gn',18,22,'crampon1923','Les hommes partirent et s''en allèrent vers Sodome; et Abraham se tenait encore devant Yahweh.'),
('gn',18,23,'crampon1923','Abraham s''approcha et dit: " Est-ce que vous feriez périr aussi le juste avec le coupable?'),
('gn',18,24,'crampon1923','Peut-être y a-t-il cinquante justes dans la ville: les feriez-vous périr aussi, et ne pardonnerez-vous pas à cette ville à cause des cinquante justes qui s''y trouveraient?'),
('gn',18,25,'crampon1923','Loin de vous d''agir de la sorte, de faire mourir le juste avec le coupable! Ainsi il en serait du juste comme du coupable! Loin de vous! Celui qui juge toute la terre ne rendrait-il pas justice? "'),
('gn',18,26,'crampon1923','Yahweh dit: " Si je trouve à Sodome cinquante justes dans la ville, je pardonnerai à toute la ville à cause d''eux. "'),
('gn',18,27,'crampon1923','Abraham reprit et dit: " Voilà que j''ai osé parler au Seigneur, moi qui suis poussière et cendre.'),
('gn',18,28,'crampon1923','Peut-être que des cinquante justes il en manquera cinq; pour cinq hommes détruirez-vous toute la ville? " Il dit: " Je ne la détruirai pas, si j''en trouve quarante-cinq. "'),
('gn',18,29,'crampon1923','Abraham continua encore à lui parler et dit: " Peut-être s''y trouvera-t-il quarante justes. " Et il dit: " Je ne le ferai pas, à cause de ces quarante. "'),
('gn',18,30,'crampon1923','Abraham dit: " Que le Seigneur veuille ne pas s''irriter, si je parle! Peut-être s''en trouvera-t-il trente. " Et il dit: " Je ne le ferai pas, si j''en trouve trente. "'),
('gn',18,31,'crampon1923','Abraham dit: " Voilà que j''ai osé parler au Seigneur. Peut-être s''en trouvera-t-il vingt. " Et il dit: " A cause de ces vingt, je ne la détruirai pas. "'),
('gn',18,32,'crampon1923','Abraham dit: " Que le Seigneur veuille ne pas s''irriter, et je ne parlerai plus que cette fois: Peut-être s''en trouvera-t-il dix. " Et il dit: " A cause de ces dix, je ne la détruirai point. "'),
('gn',18,33,'crampon1923','Yahweh s''en alla, lorsqu''il eut achevé de parler à Abraham, et Abraham retourna chez lui.'),
('gn',19,1,'crampon1923','Les deux anges arrivèrent à Sodome le soir, et Lot était assis à la porte de Sodome. En les voyant, Lot se leva pour aller au-devant d''eux et il se prosterna le visage contre terre,'),
('gn',19,2,'crampon1923','et il dit: " Voici, mes seigneurs, entrez, je vous prie, chez votre serviteur pour y passer la nuit; lavez vos pieds; vous vous lèverez de bon matin et vous poursuivrez votre route. " Ils répondirent: " Non, nous passerons la nuit sur la place. "'),
('gn',19,3,'crampon1923','Mais Lot leur fit tant d''instances qu''ils vinrent chez lui et entrèrent dans sa maison. Il leur prépara un festin et fit cuire des pains sans levain; et ils mangèrent.'),
('gn',19,4,'crampon1923','Ils n''étaient pas encore couchés que les hommes de la ville, les hommes de Sodome, entourèrent la maison, depuis les enfants jusqu''aux vieillards, le peuple entier, de tous les bouts de la ville.'),
('gn',19,5,'crampon1923','Ils appelèrent Lot et lui dirent: " Où sont les hommes qui sont entrés chez toi cette nuit? Fais-les sortir vers nous, pour que nous les connaissions. "'),
('gn',19,6,'crampon1923','Lot s''avança vers eux à l''entrée de la maison et, ayant fermé la porte derrière lui,'),
('gn',19,7,'crampon1923','il dit: " Non, mes frères, je vous en prie, ne faites pas le mal!'),
('gn',19,8,'crampon1923','Voici, j''ai deux filles qui n''ont pas connu d''homme; laissez-moi vous les amener, et vous leur ferez ce qu''il vous plaira. Mais ne faites rien à ces hommes, car c''est pour cela qu''ils sont venus s''abriter sous mon toit. "'),
('gn',19,9,'crampon1923','Ils répondirent: " Ote-toi de là! " Et ils ajoutèrent: " Cet individu est venu comme étranger, et il fait le juge! Eh bien, nous te ferons plus de mal qu''à eux. " Et, repoussant Lot avec violence, ils s''avancèrent pour briser la porte.'),
('gn',19,10,'crampon1923','Les deux hommes étendirent la main et, ayant retiré Lot vers eux dans la maison, ils fermèrent la porte.'),
('gn',19,11,'crampon1923','Et ils frappèrent d''aveuglement les gens qui étaient à l''entrée de la maison, depuis le plus petit jusqu''au plus grand, et ceux-ci se fatiguèrent inutilement à chercher la porte.'),
('gn',19,12,'crampon1923','Les deux hommes dirent à Lot: " Qui as-tu encore ici? Gendres, fils et filles, et qui que ce soit que tu aies dans la ville, fais-les sortir de ce lieu.'),
('gn',19,13,'crampon1923','Car nous allons détruire ce lieu, parce qu''un grand cri s''est élevé de ses habitants devant Yahweh, et que Yahweh nous a envoyés pour le détruire. "'),
('gn',19,14,'crampon1923','Lot sortit et parla à ses gendres, qui avaient pris ses filles: " Levez-vous, leur dit-il, sortez de ce lieu, car Yahweh va détruire la ville. " Mais, aux yeux de ses gendres, il parut plaisanter.'),
('gn',19,15,'crampon1923','Dès l''aube du jour, les anges pressèrent Lot, en disant: " Lève-toi, prends ta femme et tes deux filles qui sont ici, afin que tu ne périsses pas dans le châtiment de la ville. "'),
('gn',19,16,'crampon1923','Comme il tardait, ces hommes le prirent par la main, lui, sa femme et ses deux filles, car Yahweh voulait l''épargner; ils l''emmenèrent et le mirent hors de la ville.'),
('gn',19,17,'crampon1923','Lorsqu''ils les eurent fait sortir, l''un des anges dit: " Sauve-toi, sur ta vie. Ne regarde pas derrière toi, et ne t''arrête nulle part dans la Plaine; sauve-toi à la montagne, de peur que tu ne périsses. "'),
('gn',19,18,'crampon1923','Lot leur dit: " Non, Seigneur.'),
('gn',19,19,'crampon1923','Voici votre serviteur a trouvé grâce à vos yeux, et vous avez fait un grand acte de bonté à mon égard en me conservant la vie; mais je ne puis me sauver à la montagne, sans risquer d''être atteint par la destruction et de périr.'),
('gn',19,20,'crampon1923','Voyez, cette ville est assez proche pour m''y réfugier, et elle est peu de chose; permettez que je m''y sauve, — n''est-elle pas petite? — et que je vive. "'),
('gn',19,21,'crampon1923','Il lui dit: " Voici, je t''accorde encore cette grâce, de ne pas détruire la ville dont tu parles.'),
('gn',19,22,'crampon1923','Hâte-toi de t''y sauver, car je ne puis rien faire que tu n''y sois arrivé. " C''est pour cela qu''on a donné à cette ville le nom de Ségor.'),
('gn',19,23,'crampon1923','Le soleil se leva sur la terre, et Lot arriva à Ségor.'),
('gn',19,24,'crampon1923','Alors Yahweh fit pleuvoir sur Sodome et sur Gomorrhe du soufre et du feu d''auprès de Yahweh, du ciel.'),
('gn',19,25,'crampon1923','Il détruisit ces villes et toute la Plaine, et tous les habitants des villes et les plantes de la terre.'),
('gn',19,26,'crampon1923','La femme de Lot regarda en arrière et devint une colonne de sel.'),
('gn',19,27,'crampon1923','Abraham se leva de bon matin et se rendit au lieu où il s''était tenu devant Yahweh.'),
('gn',19,28,'crampon1923','Il regarda du côté de Sodome et de Gomorrhe, et sur toute l''étendue de la Plaine, et il vit monter de la terre une fumée, comme la fumée d''une fournaise.'),
('gn',19,29,'crampon1923','Lorsque Dieu détruisit les villes de la Plaine, il se souvint d''Abraham, et il fit échapper Lot au bouleversement, lorsqu''il bouleversa les villes où Lot habitait.'),
('gn',19,30,'crampon1923','Lot monta de Ségor et s''établit à la montagne, ayant avec lui ses deux filles, car il craignait de rester à Ségor; et il habitait dans une caverne avec ses deux filles.'),
('gn',19,31,'crampon1923','L''aînée dit à la plus jeune: " Notre père est vieux, et il n''y a pas d''homme dans le pays pour venir vers nous, selon l''usage de tous les pays.'),
('gn',19,32,'crampon1923','Viens, faisons boire du vin à notre père et couchons avec lui, afin que nous conservions de notre père une postérité. "'),
('gn',19,33,'crampon1923','Elles firent donc boire du vin à leur père cette nuit-là, et l''aînée alla coucher avec son père, et il ne s''aperçut ni du coucher de sa fille ni de son lever.'),
('gn',19,34,'crampon1923','Le lendemain, l''aînée dit à la plus jeune: " Voici, j''ai couché la nuit dernière avec mon père; faisons-lui boire du vin encore cette nuit, et va coucher avec lui afin que nous conservions de notre père une postérité ".'),
('gn',19,35,'crampon1923','Cette nuit-là encore elles firent boire du vin à leur père, et la cadette alla se coucher auprès de lui, et il ne s''aperçut ni de son coucher ni de son lever.'),
('gn',19,36,'crampon1923','Les deux filles de Lot devinrent enceintes de leur père.'),
('gn',19,37,'crampon1923','L''aînée mit au monde un fils, qu''elle nomma Moab: c''est le père des Moabites, qui existent jusqu''à ce jour.'),
('gn',19,38,'crampon1923','La cadette eut aussi un fils, qu''elle nomma Ben-Ammi: c''est le père des fils d''Ammon, qui existent jusqu''à ce jour.'),
('gn',20,1,'crampon1923','Abraham partit de là pour la contrée du Midi; il s''établit entre Cadès et Sur, et fit un séjour à Gérare.'),
('gn',20,2,'crampon1923','Abraham disait de Sara, sa femme: " C''est ma sœur. " Abimélech, roi de Gérare, envoya prendre Sara.'),
('gn',20,3,'crampon1923','Mais Dieu vint à Abimélech en songe pendant la nuit, et lui dit: " Voici, tu vas mourir à cause de la femme que tu as prise: car elle a un mari. "'),
('gn',20,4,'crampon1923','Or Abimélech ne s''était pas approché d''elle; il répondit: " Seigneur, ferez-vous mourir des gens même innocents?')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('gn',20,5,'crampon1923','Ne m''a-t-il pas dit: C''est ma sœur? Et elle-même m''a dit aussi: C''est mon frère. C''est avec un cœur intègre et des mains pures que j''ai fait cela. "'),
('gn',20,6,'crampon1923','Dieu lui dit en songe: " Moi aussi, je sais que c''est avec un cœur intègre que tu as agi; aussi t''ai-je retenu de pécher contre moi. C''est pourquoi je n''ai pas permis que tu la touches.'),
('gn',20,7,'crampon1923','Maintenant, rends la femme de cet homme, car il est prophète; il priera pour toi, et tu vivras. Si tu ne la rends pas, sache que tu mourras certainement, toi et tous ceux qui t''appartiennent. "'),
('gn',20,8,'crampon1923','Abimélech se leva de bon matin, appela tous ses serviteurs et leur rapporta toutes ces choses; et ces gens furent saisis d''une grande frayeur.'),
('gn',20,9,'crampon1923','Puis Abimélech appela Abraham et lui dit: " Qu''est-ce que tu nous as fait? En quoi ai-je manqué à ton égard, que tu aies fait venir sur moi et sur mon royaume un si grand péché? Tu as fait avec moi des choses qui ne se font pas. "'),
('gn',20,10,'crampon1923','Abimélech dit encore à Abraham: " A quoi as-tu pensé en agissant de la sorte? "'),
('gn',20,11,'crampon1923','Abraham répondit: " Je me disais: Il n''y a sans doute aucune crainte de Dieu dans ce pays, et l''on me tuera à cause de ma femme.'),
('gn',20,12,'crampon1923','Et d''ailleurs elle est vraiment ma sœur; elle est fille de mon père, quoiqu''elle ne soit pas fille de ma mère, et elle est devenue ma femme.'),
('gn',20,13,'crampon1923','Lorsque Dieu me fit errer loin de la maison de mon père, je dis à Sara: Voici la grâce que tu me feras: dans tous les lieux où nous arriverons, dis de moi: C''est mon frère. "'),
('gn',20,14,'crampon1923','Alors Abimélech prit des brebis et des bœufs, des serviteurs et des servantes, et les donna à Abraham; et il lui rendit Sara, sa femme.'),
('gn',20,15,'crampon1923','Abimélech dit: " Voici, mon pays est devant toi; habite où il te plaira. "'),
('gn',20,16,'crampon1923','Et il dit à Sara: " Je donne à ton frère mille pièces d''argent; cela te sera un voile sur les yeux pour tous ceux qui sont avec toi et pour tous; te voilà justifiée. "'),
('gn',20,17,'crampon1923','Abraham intercéda auprès de Dieu, et Dieu guérit Abimélech, sa femme et ses servantes, et ils eurent des enfants.'),
('gn',20,18,'crampon1923','Car Yahweh avait rendu tout sein stérile dans la maison d''Abimélech, à cause de Sara, femme d''Abraham.'),
('gn',21,1,'crampon1923','Yahweh visita Sara, comme il l''avait dit; Yahweh accomplit pour Sara ce qu''il avait promis.'),
('gn',21,2,'crampon1923','Sara conçut et enfanta à Abraham un fils dans sa vieillesse, au terme que Dieu lui avait marqué.'),
('gn',21,3,'crampon1923','Abraham donna au fils qui lui était né, que Sara lui avait enfanté, le nom d''Isaac.'),
('gn',21,4,'crampon1923','Et Abraham circoncit Isaac, son fils, à l''âge de huit jours, comme Dieu le lui avait ordonné.'),
('gn',21,5,'crampon1923','Abraham avait cent ans à la naissance d''Isaac, son fils.'),
('gn',21,6,'crampon1923','Et Sara dit: " Dieu m''a donné de quoi rire; quiconque l''apprendra rira à mon sujet. "'),
('gn',21,7,'crampon1923','Elle ajouta: " Qui eût dit à Abraham: Sara allaitera des enfants? Car j''ai donné un fils à sa vieillesse. "'),
('gn',21,8,'crampon1923','L''enfant grandit, et on le sevra. Abraham fit un grand festin le jour où Isaac fut sevré.'),
('gn',21,9,'crampon1923','Sara vit le fils d''Agar, l''Egyptienne, qu''elle avait enfanté à Abraham, qui riait,'),
('gn',21,10,'crampon1923','et elle dit à Abraham: " Chasse cette servante et son fils; car le fils de cette servante ne doit pas hériter avec mon fils, avec Isaac. "'),
('gn',21,11,'crampon1923','Cette parole déplut beaucoup aux yeux d''Abraham, à cause de son fils Ismaël.'),
('gn',21,12,'crampon1923','Mais Dieu dit à Abraham: " Que cela ne déplaise pas à tes yeux, à cause de l''enfant et de ta servante; quoi que Sara te demande, consens-y, car c''est d''Isaac que naîtra la postérité qui portera ton nom.'),
('gn',21,13,'crampon1923','Néanmoins du fils de la servante je ferai aussi une nation, parce qu''il est né de toi. "'),
('gn',21,14,'crampon1923','Abraham s''étant levé de bon matin, prit du pain et une outre d''eau, les donna à Agar et les mit sur son épaule; il lui remit aussi l''enfant, et il la renvoya. Elle s''en alla, errant dans le désert de Bersabée.'),
('gn',21,15,'crampon1923','Quand l''eau qui était dans l''outre fut épuisée, elle jeta l''enfant sous l''un des arbrisseaux,'),
('gn',21,16,'crampon1923','et elle s''en alla s''asseoir vis-à-vis, à une portée d''arc; car elle disait: " Je ne veux pas voir mourir l''enfant. " Elle s''assit donc vis-à-vis, éleva la voix et pleura.'),
('gn',21,17,'crampon1923','Dieu entendit la voix de l''enfant, et l''ange de Dieu appela du ciel Agar, en disant: " Qu''as-tu Agar? Ne crains point, car Dieu a entendu la voix de l''enfant, dans le lieu où il est.'),
('gn',21,18,'crampon1923','Lève-toi, relève l''enfant, prends-le par la main, car je ferai de lui une grande nation. "'),
('gn',21,19,'crampon1923','Et Dieu lui ouvrit les yeux, et elle vit un puits d''eau; elle alla remplir l''outre d''eau et donna à boire à l''enfant.'),
('gn',21,20,'crampon1923','Dieu fut avec l''enfant, et il grandit; il habita dans le désert et devint un tireur d''arc.'),
('gn',21,21,'crampon1923','Il habitait dans le désert de Pharan, et sa mère prit pour lui une femme du pays d''Egypte.'),
('gn',21,22,'crampon1923','En ce temps-là, Abimélech, accompagné de Phicol, chef de son armée, parla ainsi à Abraham: " Dieu est avec toi dans tout ce que tu fais.'),
('gn',21,23,'crampon1923','Jure-moi donc ici, par le nom de Dieu, que tu ne tromperas ni moi, ni mes enfants, ni mes petits-enfants, mais que tu auras pour moi et pour ce pays où tu séjournes la même bienveillance dont j''ai usé envers toi. "'),
('gn',21,24,'crampon1923','Abraham dit: " Je le jurerai. "'),
('gn',21,25,'crampon1923','Mais Abraham fit des reproches à Abimélech au sujet d''un puits d''eau dont les serviteurs d''Abimélech s''étaient emparés de force.'),
('gn',21,26,'crampon1923','Abimélech répondit: " J''ignore qui a fait cela; toi-même tu ne m''en as pas informé, et je n''en ai entendu parler qu''aujourd''hui. "'),
('gn',21,27,'crampon1923','Et Abraham prit des brebis et des bœufs, et les donna à Abimélech, et ils firent alliance tous deux.'),
('gn',21,28,'crampon1923','Abraham mit à part sept jeunes brebis du troupeau,'),
('gn',21,29,'crampon1923','et Abimélech dit à Abraham: " Qu''est-ce que ces sept jeunes brebis, que tu as mises à part? "'),
('gn',21,30,'crampon1923','Il répondit: " Tu accepteras de ma main ces sept jeunes brebis, afin que ce soit pour moi un témoignage que j''ai creusé ce puits. "'),
('gn',21,31,'crampon1923','C''est pourquoi on a appelé ce lieu Bersabée, parce que c''est là qu''ils ont tous deux prêté serment.'),
('gn',21,32,'crampon1923','C''est ainsi qu''ils firent alliance à Bersabée. Après quoi Abimélech se leva, avec Phicol, chef de son armée, et ils retournèrent au pays des Philistins.'),
('gn',21,33,'crampon1923','Abraham planta un tamaris à Bersabée, et il invoqua là le nom de Yahweh, Dieu éternel;'),
('gn',21,34,'crampon1923','et Abraham séjourna longtemps dans le pays des Philistins.'),
('gn',22,1,'crampon1923','Après cela, Dieu mit Abraham à l''épreuve et lui dit: " Abraham! " Il répondit: " Me voici. "'),
('gn',22,2,'crampon1923','Et Dieu dit: " Prends ton fils, ton unique, celui que tu aimes, Isaac, et va-t''en au pays de Moria, et là offre-le en holocauste sur l''une des montagnes que je t''indiquerai. "'),
('gn',22,3,'crampon1923','Abraham se leva de bon matin et, ayant sellé son âne, il prit avec lui deux de ses serviteurs et son fils Isaac; il fendit le bois de l''holocauste et partit pour aller au lieu que Dieu lui avait dit.'),
('gn',22,4,'crampon1923','Le troisième jour, Abraham, levant les yeux, aperçut le lieu de loin;'),
('gn',22,5,'crampon1923','et Abraham dit à ses serviteurs: " Restez ici avec l''âne; moi et l''enfant, nous voulons aller jusque-là et adorer, puis nous reviendrons vers vous. "'),
('gn',22,6,'crampon1923','Et Abraham prit le bois de l''holocauste, et le mit sur Isaac, son fils, lui-même portait dans sa main le feu et le couteau, et ils s''en allèrent tous deux ensemble.'),
('gn',22,7,'crampon1923','Isaac parla à Abraham, son père, et dit: " Mon père! " Il répondit: " Me voici, mon fils. " Et Isaac dit: " Voici le feu et le bois; mais où est l''agneau pour l''holocauste? "'),
('gn',22,8,'crampon1923','Abraham répondit: " Dieu verra à trouver l''agneau pour l''holocauste, mon fils. " Et ils allaient tous deux ensemble.'),
('gn',22,9,'crampon1923','Lorsqu''ils furent arrivés au lieu que Dieu lui avait désigné, Abraham y éleva l''autel et arrangea le bois; puis il lia Isaac, son fils, et le mit sur l''autel, au-dessus du bois.'),
('gn',22,10,'crampon1923','Et Abraham étendit la main et prit le couteau pour égorger son fils.'),
('gn',22,11,'crampon1923','Alors l''ange de Yahweh lui cria du ciel et dit: " Abraham! Abraham! " Il répondit: " Me voici. "'),
('gn',22,12,'crampon1923','Et l''ange dit: " Ne porte pas la main sur l''enfant et ne lui fais rien; car je sais maintenant que tu crains Dieu et que tu ne m''as pas refusé ton fils, ton unique. "'),
('gn',22,13,'crampon1923','Abraham, ayant levé les yeux, vit derrière lui un bélier pris dans un buisson par les cornes; et Abraham alla prendre le bélier et l''offrit en holocauste à la place de son fils.'),
('gn',22,14,'crampon1923','Et Abraham nomma ce lieu: " Yahweh-Yiréh ", d''où l''on dit aujourd''hui: " Sur la montagne de Yahweh, il sera vu. "'),
('gn',22,15,'crampon1923','L''ange de Yahweh appela du ciel Abraham une seconde fois, en disant:'),
('gn',22,16,'crampon1923','" Je l''ai juré par moi-même, dit Yahweh: parce que tu as fait cela, et que tu ne m''as pas refusé ton fils, ton unique,'),
('gn',22,17,'crampon1923','je te bénirai; je multiplierai ta postérité comme les étoiles du ciel et comme le sable qui est au bord de la mer, et ta postérité possédera la porte de ses ennemis.'),
('gn',22,18,'crampon1923','En ta postérité seront bénies toutes les nations de la terre, parce que tu as obéi à ma voix. "'),
('gn',22,19,'crampon1923','Abraham retourna vers ses serviteurs et, s''étant levés, ils s''en allèrent ensemble à Bersabée. Et Abraham habita à Bersabée.'),
('gn',22,20,'crampon1923','Après ces événements, on apporta à Abraham cette nouvelle: " Voici, Melcha a aussi enfanté des fils à Nachor, ton frère:'),
('gn',22,21,'crampon1923','Hus, son premier-né, Buz, son frère, Camuel, père d''Aram,'),
('gn',22,22,'crampon1923','Cased, Azau, Pheldas, Jedlaph et Bathuel. "'),
('gn',22,23,'crampon1923','Bathuel fut père de Rébecca. Ce sont là les huit fils que Melcha enfanta à Nachor, frère d''Abraham.'),
('gn',22,24,'crampon1923','Sa concubine, nommée Roma, eut aussi des enfants: Tabée, Gaham, Taas et Maacha.'),
('gn',23,1,'crampon1923','Sara vécut cent vingt-sept ans: telles sont les années de sa vie.'),
('gn',23,2,'crampon1923','Sara mourut à Qiriath-Arbé, qui est Hébron, dans le pays de Chanaan; et Abraham vint pour faire le deuil de Sara et pour la pleurer.'),
('gn',23,3,'crampon1923','Puis Abraham se leva de devant son mort, et parla ainsi aux fils de Heth:'),
('gn',23,4,'crampon1923','" Je suis un étranger et un hôte parmi vous; accordez-moi de posséder un sépulcre, afin que je puisse ôter de devant moi mon mort et l''enterrer. "'),
('gn',23,5,'crampon1923','Les fils de Heth répondirent à Abraham en lui disant:'),
('gn',23,6,'crampon1923','" Ecoute-nous, mon seigneur; tu es un prince de Dieu au milieu de nous; enterre ton mort dans le plus beau de nos sépulcres; aucun de nous ne te refusera son sépulcre pour y déposer ton mort. "'),
('gn',23,7,'crampon1923','Alors Abraham se leva et, se prosternant devant le peuple du pays, devant les fils de Heth,'),
('gn',23,8,'crampon1923','il leur parla en ces termes: " Si vous voulez que j''ôte mon mort de devant moi pour l''enterrer, écoutez-moi et priez pour moi Ephron, fils de Séor,'),
('gn',23,9,'crampon1923','de me céder la caverne de Macpéla, qui lui appartient et qui est au bout de son champ, de me la céder en votre présence pour l''argent qu''elle vaut, comme un lieu de sépulture qui soit à moi. "'),
('gn',23,10,'crampon1923','Or Ephron était assis au milieu des fils de Heth. Ephron le Héthéen répondit à Abraham en présence des fils de Heth, de tous ceux qui entraient par la porte de sa ville; il lui dit:'),
('gn',23,11,'crampon1923','" Non, mon seigneur, écoute-moi: je te donne le champ et je te donne la caverne qui s''y trouve; je te la donne aux yeux des fils de mon peuple; enterre ton mort. "'),
('gn',23,12,'crampon1923','Abraham se prosterna devant le peuple du pays,'),
('gn',23,13,'crampon1923','et il parla ainsi à Ephron en présence du peuple du pays: " Qu''il te plaise seulement de m''écouter: je donne le prix du champ; reçois-le de moi, et j''enterrerai là mon mort. "'),
('gn',23,14,'crampon1923','Ephron répondit à Abraham en lui disant:'),
('gn',23,15,'crampon1923','" Mon seigneur, écoute-moi: une terre de quatre cents sicles d''argent, entre moi et toi, qu''est-ce que cela? Enterre ton mort. "'),
('gn',23,16,'crampon1923','Abraham écouta Ephron, et Abraham pesa à Ephron l''argent qu''il avait dit en présence des fils de Heth, savoir quatre cents sicles d''argent ayant cours chez le marchand.'),
('gn',23,17,'crampon1923','Ainsi le champ d''Ephron, qui est à Macpéla, vis-à-vis de Mambré, le champ et la caverne qui s''y trouve, ainsi que tous les arbres qui sont dans le champ et dans ses confins tout autour,'),
('gn',23,18,'crampon1923','devinrent la propriété d''Abraham, aux yeux des fils de Heth, de tous ceux qui entraient par la porte de la ville.'),
('gn',23,19,'crampon1923','Après cela, Abraham enterra Sara, sa femme, dans la caverne de Macpéla, vis-à-vis de Mambré, qui est Hébron, dans le pays de Chanaan.'),
('gn',23,20,'crampon1923','Le champ, avec la caverne qui s''y trouve, demeura à Abraham en toute propriété comme lieu de sépulture, provenant des fils de Heth.'),
('gn',24,1,'crampon1923','Abraham était vieux, avancé en âge, et Yahweh avait béni Abraham en toutes choses.'),
('gn',24,2,'crampon1923','Et Abraham dit à son serviteur, le plus ancien de sa maison, qui administrait tous ses biens: " Mets donc ta main sous ma cuisse,'),
('gn',24,3,'crampon1923','et je te ferai jurer par Yahweh, Dieu du ciel et Dieu de la terre, que tu ne prendras pas pour mon fils une femme parmi les filles des Chananéens, au milieu desquels j''habite;'),
('gn',24,4,'crampon1923','mais ce sera dans mon pays et dans ma patrie que tu iras prendre une femme pour mon fils, pour Isaac. "'),
('gn',24,5,'crampon1923','Le serviteur lui répondit: " Peut-être la femme ne voudra-t-elle pas me suivre dans ce pays; devrai-je ramener ton fils dans le pays d''où tu es sorti? "'),
('gn',24,6,'crampon1923','Abraham lui dit: " Garde-toi d''y ramener mon fils!'),
('gn',24,7,'crampon1923','Yahweh, le Dieu du ciel, qui m''a pris de la maison de mon père et du pays de ma naissance, qui m''a parlé et qui m''a fait serment en disant: Je donnerai ce pays à ta postérité, lui-même enverra son ange devant toi, et tu prendras de là une femme pour mon fils.'),
('gn',24,8,'crampon1923','Si la femme ne veut pas te suivre, tu seras dégagé de ce serment que je te demande; mais tu ne ramèneras pas là mon fils. "'),
('gn',24,9,'crampon1923','Alors le serviteur mit sa main sous la cuisse d''Abraham, son maître, et lui prêta serment à ce sujet.'),
('gn',24,10,'crampon1923','Le serviteur prit dix des chameaux de son maître, et il se mit en route; or il avait à sa disposition tous les biens de son maître. S''étant levé, il alla en Mésopotamie, à la ville de Nachor.'),
('gn',24,11,'crampon1923','Il fit ployer les genoux aux chameaux hors de la ville, près d''un puits, vers le soir, à l''heure où les femmes sortent pour puiser de l''eau.'),
('gn',24,12,'crampon1923','Et il dit: " Yahweh, Dieu d''Abraham, mon maître, veuillez me faire rencontrer aujourd''hui ce que je désire, et usez de bonté envers mon maître Abraham.'),
('gn',24,13,'crampon1923','Voici que je me tiens près de la source d''eau, et les filles des habitants de la ville vont sortir pour puiser de l''eau.'),
('gn',24,14,'crampon1923','Que la jeune fille à laquelle je dirai: Penche ta cruche, je te prie, pour que je boive, — et qui répondra: Bois, et je donnerai aussi à boire à tes chameaux, — soit celle que vous avez destinée à votre serviteur Isaac! Et par là je connaîtrai que vous avez usé de bonté envers mon maître. "'),
('gn',24,15,'crampon1923','Il n''avait pas encore fini de parler, et voici que sortit, sa cruche sur l''épaule, Rebecca, fille de Bathuel, fils de Melcha, femme de Nachor, frère d''Abraham.'),
('gn',24,16,'crampon1923','La jeune fille était fort belle de figure; elle était vierge, et nul homme ne l''avait connue. Elle descendit à la source, remplit sa cruche et remonta.'),
('gn',24,17,'crampon1923','Le serviteur courut au-devant d''elle et dit: " Permets que je boive un peu d''eau de ta cruche. "'),
('gn',24,18,'crampon1923','Elle répondit: " Bois, mon seigneur "; et, s''empressant d''abaisser sa cruche sur sa main, elle lui donna à boire.'),
('gn',24,19,'crampon1923','Quand elle eut achevé de lui donner à boire, elle dit: " Je puiserai aussi de l''eau pour les chameaux, jusqu''à ce qu''ils aient bu assez. "'),
('gn',24,20,'crampon1923','Et elle se hâta de vider sa cruche dans l''abreuvoir, et courut encore au puits pour puiser, et elle puisa pour tous les chameaux.'),
('gn',24,21,'crampon1923','L''homme la considérait en silence, pour savoir si Yahweh avait fait réussir son voyage, ou non.'),
('gn',24,22,'crampon1923','Quand les chameaux eurent fini de boire, l''homme prit un anneau d''or du poids d''un demi-sicle, et deux bracelets du poids de dix sicles d''or,'),
('gn',24,23,'crampon1923','et il dit: " De qui es-tu fille? Dis-le-moi donc. Y a-t-il dans la maison de ton père une place où nous puissions passer la nuit? "'),
('gn',24,24,'crampon1923','Elle répondit: " Je suis fille de Bathuel, le fils de Melcha, qu''elle enfanta à Nachor. "'),
('gn',24,25,'crampon1923','Elle ajouta: Il y a chez nous de la paille et du fourrage en abondance, et aussi de la place pour y passer la nuit. "'),
('gn',24,26,'crampon1923','Alors cet homme s''inclina et se prosterna devant Yahweh,'),
('gn',24,27,'crampon1923','et il dit: " Béni soit Yahweh, le Dieu d''Abraham, mon maître, qui n''a pas manqué à sa bonté et à sa fidélité envers mon maître. Moi-même, Yahweh m''a conduit par le chemin chez les frères de mon maître. "'),
('gn',24,28,'crampon1923','La jeune fille courut raconter chez sa mère ce qui s''était passé.'),
('gn',24,29,'crampon1923','Rebecca avait un frère, nommé Laban. Laban courut dehors vers cet homme, près de la source.'),
('gn',24,30,'crampon1923','Il avait vu l''anneau et les bracelets aux mains de sa sœur, et il avait entendu les paroles de Rebecca, sa sœur, disant: " L''homme m''a parlé ainsi. " Il vint donc à cet homme, qui se tenait auprès des chameaux, à la source,'),
('gn',24,31,'crampon1923','et il dit: " Viens, béni de Yahweh; pourquoi restes-tu dehors? J''ai préparé la maison et une place pour les chameaux. "'),
('gn',24,32,'crampon1923','Et l''homme entra à la maison. Laban débâta les chameaux, et il donna de la paille et du fourrage aux chameaux, et de l''eau pour laver les pieds de l''homme et les pieds des gens qui étaient avec lui.'),
('gn',24,33,'crampon1923','Puis il lui servit à manger; mais l''homme dit: " Je ne mangerai point que je n''aie dit ce que j''ai à dire. " — " Parle, " dit Laban.'),
('gn',24,34,'crampon1923','Il dit: Je suis serviteur d''Abraham.'),
('gn',24,35,'crampon1923','Yahweh a comblé de bénédictions mon maître, et il est devenu puissant. Il lui a donné des brebis et des bœufs, des serviteurs et des servantes, des chameaux et des ânes.'),
('gn',24,36,'crampon1923','Sara, femme de mon maître, a enfanté dans sa vieillesse un fils à mon maître, et il lui a donné tous ses biens.'),
('gn',24,37,'crampon1923','Mon maître m''a fait jurer, en disant: Tu ne prendras pas pour mon fils une femme parmi les filles des Chananéens, dans le pays desquels j''habite.'),
('gn',24,38,'crampon1923','Mais tu iras dans la maison de mon père et dans ma parenté, et tu prendras là une femme pour mon fils.'),
('gn',24,39,'crampon1923','— Je dis à mon maître: Peut-être la femme ne voudra-t-elle pas me suivre.'),
('gn',24,40,'crampon1923','Et il m''a répondu: Yahweh, devant qui je marche, enverra son ange avec toi et fera réussir ton voyage, et tu prendras pour mon fils une femme de ma parenté et de la maison de mon père.'),
('gn',24,41,'crampon1923','Tu seras dégagé du serment que tu me fais, une fois que tu te seras rendu dans ma parenté; si on ne te l''accorde pas, tu seras dégagé du serment que je te demande. —'),
('gn',24,42,'crampon1923','En arrivant aujourd''hui à la source, j''ai dit: Yahweh, Dieu de mon maître Abraham, si vous daignez faire réussir le voyage que je fais,'),
('gn',24,43,'crampon1923','voici que je me tiens près de la source d''eau; que la jeune fille qui sortira pour puiser et à qui je dirai: Laisse-moi boire, je te prie, un peu d''eau de ta cruche,'),
('gn',24,44,'crampon1923','et qui me répondra: Bois toi-même, et je puiserai aussi pour tes chameaux, — qu''elle soit la femme que Yahweh a destinée au fils de mon maître.'),
('gn',24,45,'crampon1923','Je n''avais pas encore fini de parler en mon cœur, voici que Rebecca sortait, sa cruche sur l''épaule; elle est descendue à la source et a puisé; et je lui ai dit: Donne-moi à boire, je te prie. —'),
('gn',24,46,'crampon1923','Abaissant aussitôt sa cruche de dessus son épaule, elle me dit: Bois, et je donnerai aussi à boire à tes chameaux. J''ai donc bu, et elle a aussi donné à boire aux chameaux.'),
('gn',24,47,'crampon1923','Et je l''ai interrogée, en disant: De qui es-tu fille? Elle a répondu: Je suis fille de Bathuel, le fils de Nachor, que Melcha lui a enfanté. Alors j''ai mis l''anneau à ses narines et les bracelets à ses mains.'),
('gn',24,48,'crampon1923','Puis je me suis incliné et prosterné devant Yahweh, et j''ai béni Yahweh, le Dieu de mon maître Abraham, qui m''a conduit dans le vrai chemin pour prendre la fille du frère de mon maître pour son fils.'),
('gn',24,49,'crampon1923','Maintenant, si vous voulez user de bonté et de fidélité envers mon maître, déclarez-le-moi; sinon, déclarez-le-moi encore, et je me tournerai à droite ou à gauche. "'),
('gn',24,50,'crampon1923','Laban et Bathuel répondirent, en disant: " La chose vient de Yahweh, nous ne pouvons te dire ni mal ni bien.'),
('gn',24,51,'crampon1923','Voici Rebecca devant toi; prends-la et t''en va; qu''elle soit la femme du fils de ton maître, comme Yahweh l''a dit. "'),
('gn',24,52,'crampon1923','Lorsque le serviteur d''Abraham eut entendu ces paroles, il se prosterna à terre devant Yahweh.'),
('gn',24,53,'crampon1923','Et le serviteur tira des objets d''argent, des objets d''or et des vêtements, qu''il donna à Rebecca; il fit aussi de riches présents à son frère et à sa mère.'),
('gn',24,54,'crampon1923','Ensuite ils mangèrent et burent, lui et les gens qui étaient avec lui, et ils passèrent là la nuit. Le matin, quand ils furent levés, le serviteur dit: " Laissez-moi retourner vers mon maître. "'),
('gn',24,55,'crampon1923','Le frère et la mère de Rebecca dirent: " Que la jeune fille demeure avec nous quelques jours encore, une dizaine; après quoi elle partira. "'),
('gn',24,56,'crampon1923','Il leur répondit: " Ne me retardez pas, puisque Yahweh a fait réussir mon voyage; laissez-moi partir, pour que je retourne vers mon maître. "'),
('gn',24,57,'crampon1923','Ils dirent: " Appelons la jeune fille, et demandons-lui ce qu''elle désire. "'),
('gn',24,58,'crampon1923','Ils appelèrent donc Rebecca et lui dirent: " Veux-tu partir avec cet homme? " Elle répondit: " Je partirai. "'),
('gn',24,59,'crampon1923','Alors ils congédièrent Rebecca, leur sœur, et sa nourrice, avec le serviteur d''Abraham et ses gens.'),
('gn',24,60,'crampon1923','Ils bénirent Rebecca et lui dirent: " O notre sœur, puisses-tu devenir des milliers de myriades! Puisse ta postérité posséder la porte de ses ennemis! "'),
('gn',24,61,'crampon1923','Alors Rebecca et ses servantes, s''étant levées, montèrent sur les chameaux, et suivirent cet homme. Et le serviteur emmena Rebecca et se mit en route.'),
('gn',24,62,'crampon1923','Cependant Isaac était revenu du puits de Chai-Roï, et il habitait dans le pays du Midi.'),
('gn',24,63,'crampon1923','Un soir qu'' Isaac était sorti dans les champs pour méditer, levant les yeux, il vit des chameaux qui arrivaient.'),
('gn',24,64,'crampon1923','Rebecca leva aussi les yeux et, ayant aperçu Isaac, elle sauta à bas de son chameau.'),
('gn',24,65,'crampon1923','Elle dit au serviteur: " Qui est cet homme qui vient dans les champs à notre rencontre? " Le serviteur répondit: " C''est mon maître. " Et elle prit son voile et se couvrit.'),
('gn',24,66,'crampon1923','Le serviteur raconta à Isaac toutes les choses qu''il avait faites.'),
('gn',24,67,'crampon1923','Et Isaac conduisit Rebecca dans la tente de Sara, sa mère. Il prit Rebecca, qui devint sa femme, et il l''aima; et Isaac se consola de la mort de sa mère.'),
('gn',25,1,'crampon1923','Abraham prit encore une femme, nommée Cétura.'),
('gn',25,2,'crampon1923','Et elle lui enfanta Zamran, Jecsan, Madan, Madian, Jesboc et Sué. —'),
('gn',25,3,'crampon1923','Jecsan engendra Saba et Dadan; les fils de Dadan furent les Assurim, les Latusim et les Laomim. —'),
('gn',25,4,'crampon1923','Les fils de Madian furent Epha, Opher, Hénoch, Abida et Eldaa. — Ce sont là tous les fils de Cétura.'),
('gn',25,5,'crampon1923','Abraham donna tous ses biens à Isaac:'),
('gn',25,6,'crampon1923','Quant aux fils de ses concubines, il leur donna des présents, et il les envoya de son vivant loin de son fils Isaac, à l''orient, au pays d''Orient.'),
('gn',25,7,'crampon1923','Voici les jours des années de la vie d''Abraham: il vécut cent soixante-quinze ans.'),
('gn',25,8,'crampon1923','Abraham expira et mourut dans une heureuse vieillesse, âgé et rassasié de jours, et il fut réuni à son peuple.'),
('gn',25,9,'crampon1923','Isaac et Ismaël, ses fils, l''enterrèrent dans la caverne de Macpéla, dans le champ d''Ephron, fils de Séor le Héthéen, qui est vis-à-vis de Mambré:'),
('gn',25,10,'crampon1923','c''est le champ qu''Abraham avait acheté des fils de Heth. Là fut enterré Abraham, avec Sara, sa femme.'),
('gn',25,11,'crampon1923','Après la mort d''Abraham, Dieu bénit Isaac son fils; et Isaac habitait près du puits de Lachaï-Roï.'),
('gn',25,12,'crampon1923','Voici l''histoire d''Ismaël, fils d''Abraham, qu''avait enfanté à Abraham Agar l''Egyptienne, servante de Sara.'),
('gn',25,13,'crampon1923','Voici les noms des fils d''Ismaël, selon les noms de leurs postérités: premier-né d''Ismaël, Nebaïoth; puis Cédar, Adbéel, Mabsam,'),
('gn',25,14,'crampon1923','Masma, Duma, Massa,'),
('gn',25,15,'crampon1923','Hadad, Théma, Jéthur, Naphis et Cedma.'),
('gn',25,16,'crampon1923','Ce sont là les fils d''Ismaël, ce sont là leurs noms, selon leurs villages et leurs campements: ce furent les douze chefs de leurs tribus.'),
('gn',25,17,'crampon1923','Voici les années de la vie d''Ismaël: cent trente-sept ans; puis il expira et mourut et il fut réuni à son peuple.'),
('gn',25,18,'crampon1923','Ses fils habitèrent depuis Hévila jusqu''à Sur qui est en face de l''Egypte, dans la direction de l''Assyrie. Il s''étendit en face de tous ses frères.'),
('gn',25,19,'crampon1923','Voici l''histoire d''Isaac, fils d''Abraham. Abraham engendra Isaac.'),
('gn',25,20,'crampon1923','Isaac était âgé de quarante ans quand il prit pour femme Rebecca, fille de Bathuel l''Araméen, de Paddan-Aram, et sœur de Laban, l''Araméen.'),
('gn',25,21,'crampon1923','Isaac implora Yahweh au sujet de sa femme, car elle était stérile; Yahweh l''exauça et Rebecca, sa femme, conçut.'),
('gn',25,22,'crampon1923','Les enfants se heurtaient dans son sein, et elle dit: " S''il en est ainsi, pourquoi suis-je enceinte? " Elle alla consulter Yahweh;'),
('gn',25,23,'crampon1923','et Yahweh lui dit: " Deux nations sont dans ton sein; deux peuples, au sortir de tes entrailles, se sépareront; un peuple l''emportera sur l''autre, et le plus grand servira le plus petit. "'),
('gn',25,24,'crampon1923','Le temps où elle devait enfanter arriva, et voici, il y avait deux jumeaux dans son sein.'),
('gn',25,25,'crampon1923','Celui qui sortit le premier était roux, tout entier comme un manteau de poil, et ils l''appelèrent Esaü; ensuite sortit son frère, tenant dans sa main le talon d''Esaü, et on le nomma Jacob.'),
('gn',25,26,'crampon1923','Isaac était âgé de soixante ans quand ils naquirent.'),
('gn',25,27,'crampon1923','Ces enfants grandirent. Esaü devint un habile chasseur, un homme des champs; mais Jacob était un homme paisible, demeurant sous la tente.'),
('gn',25,28,'crampon1923','Isaac prit en affection Esaü, parce qu''il aimait la venaison, et l''affection de Rebecca était pour Jacob.'),
('gn',25,29,'crampon1923','Comme Jacob faisait un potage, Esaü arriva des champs, accablé de fatigue.'),
('gn',25,30,'crampon1923','Esaü dit à Jacob: " Laisse-moi donc manger de ce roux, de ce roux-là, car je suis fatigué. " — C''est pour cela qu''on a donné à Esaü le nom d''Edom. —'),
('gn',25,31,'crampon1923','Jacob dit: " Vends-moi d''abord ton droit d''aînesse. "'),
('gn',25,32,'crampon1923','Esaü répondit: " Voici je m''en vais mourir; que me servira mon droit d''aînesse? "'),
('gn',25,33,'crampon1923','Et Jacob dit: " Jure-le-moi d''abord. " Il jura et vendit son droit d''aînesse à Jacob.'),
('gn',25,34,'crampon1923','Alors Jacob donna à Esaü du pain et du potage de lentilles; celui-ci mangea et but; puis il se leva et s''en alla. C''est ainsi qu''Esaü méprisa le droit d''aînesse.'),
('gn',26,1,'crampon1923','Il y eut une famine dans le pays, outre la première famine qui avait eu lieu du temps d''Abraham; et Isaac alla à Gérare, vers Abimélech, roi des Philistins.'),
('gn',26,2,'crampon1923','Yahweh lui apparut et dit: " Ne descends point en Egypte, mais demeure dans le pays que je te dirai.'),
('gn',26,3,'crampon1923','Séjourne dans ce pays-ci; je serai avec toi et je te bénirai, car je donnerai toutes ces contrées à toi et à ta postérité, et je tiendrai le serment que j''ai fait à Abraham, ton père.'),
('gn',26,4,'crampon1923','Je multiplierai ta postérité comme les étoiles du ciel, et je donnerai à ta postérité toutes ces contrées, et en ta postérité seront bénies toutes les nations de la terre,'),
('gn',26,5,'crampon1923','parce qu''Abraham a obéi à ma voix et a gardé mon ordre, mes commandements, mes statuts et mes lois. "'),
('gn',26,6,'crampon1923','Isaac demeura donc à Gérare.'),
('gn',26,7,'crampon1923','Les gens du lieu le questionnaient sur sa femme, il disait: " C''est ma sœur "; car il craignait de dire: " Ma femme ", de peur, pensait-il, que les gens du lieu ne me tuent à cause de Rebecca ", car elle était belle de figure.'),
('gn',26,8,'crampon1923','Comme son séjour à Gérare se prolongeait, il arriva qu''Abimélech, roi des Philistins, regardant par la fenêtre, aperçut Isaac qui faisait des caresses à Rebecca, sa femme.'),
('gn',26,9,'crampon1923','Abimélech appela Isaac et dit: " Elle ne peut être que ta femme; comment as-tu dit: C''est ma sœur? " Isaac lui répondit: " C''est que je me disais: Je crains de mourir à cause d''elle. "'),
('gn',26,10,'crampon1923','Et Abimélech dit: " Qu''est-ce que tu nous as fait? Car peu s''en est fallu qu''un homme du peuple couche avec ta femme, et tu aurais fait venir sur nous un péché. "'),
('gn',26,11,'crampon1923','Alors Abimélech donna cet ordre à tout le peuple: " Celui qui touchera cet homme ou sa femme sera mis à mort. "'),
('gn',26,12,'crampon1923','Isaac fit des semailles dans ce pays, et il recueillit cette année-là le centuple. Yahweh le bénit;'),
('gn',26,13,'crampon1923','et cet homme devint riche, et il alla s''enrichissant de plus en plus, jusqu''à devenir très riche.'),
('gn',26,14,'crampon1923','Il avait des troupeaux de menu bétail et des troupeaux de gros bétail et beaucoup de serviteurs, et les Philistins lui portèrent envie.'),
('gn',26,15,'crampon1923','Tous les puits qu''avaient creusés les serviteurs de son père, du temps de son père Abraham, les Philistins les bouchèrent, en les remplissant de terre.'),
('gn',26,16,'crampon1923','Et Abimélech dit à Isaac: " Va-t''en de chez nous, car tu es devenu beaucoup plus puissant que nous. "'),
('gn',26,17,'crampon1923','Isaac s''en alla et, ayant établi son campement dans la vallée de Gérare, il y demeura.'),
('gn',26,18,'crampon1923','Isaac creusa de nouveau les puits d''eau qu''on avait creusés du temps d''Abraham, son père, et que les Philistins avaient bouchés après la mort d''Abraham, et il leur donna les mêmes noms que son père leur avait donnés.'),
('gn',26,19,'crampon1923','Les serviteurs d''Isaac creusèrent encore dans la vallée et y trouvèrent un puits d''eau vive.'),
('gn',26,20,'crampon1923','Et les bergers de Gérare se querellèrent avec les bergers d''Isaac, en disant: " L''eau est à nous. " Et il nomma le puits Eseq, parce qu''ils avaient eu un débat avec lui.'),
('gn',26,21,'crampon1923','Ses serviteurs creusèrent un autre puits, au sujet duquel il y eut encore une querelle, et il le nomma Sitna.'),
('gn',26,22,'crampon1923','Étant parti de là, il creusa un autre puits, pour lequel il n''y eut plus de querelle, et il le nomma Rechoboth: " Car maintenant, dit-il, Yahweh nous a mis au large, et nous prospérerons dans le pays. "'),
('gn',26,23,'crampon1923','De là, il remonta à Bersabée.'),
('gn',26,24,'crampon1923','Yahweh lui apparut cette nuit-là et dit: " Je suis le Dieu d''Abraham, ton père; ne crains point, car je suis avec toi; je te bénirai et je multiplierai ta postérité, à cause d''Abraham, mon serviteur. "'),
('gn',26,25,'crampon1923','Il éleva là un autel et invoqua le nom de Yahweh, puis il y dressa sa tente; et les serviteurs d''Isaac y creusèrent un puits.'),
('gn',26,26,'crampon1923','Abimélech vint vers lui, de Gérare, avec Ochozath, son ami, et Phicol, chef de son armée.'),
('gn',26,27,'crampon1923','Isaac leur dit: " Pourquoi êtes-vous venus vers moi, vous qui me haïssez et qui m''avez renvoyé de chez vous? "'),
('gn',26,28,'crampon1923','Ils répondirent: " Nous avons vu clairement que Yahweh est avec toi, et nous avons dit: Qu''il y ait un serment entre nous, entre nous et toi, et que nous fassions une alliance avec toi.'),
('gn',26,29,'crampon1923','Jure de ne pas nous faire de mal, de même que nous ne t''avons pas touché, et que nous ne t''avons fait que du bien, et t''avons laissé partir en paix. Tu es maintenant le béni de Yahweh. "'),
('gn',26,30,'crampon1923','Isaac leur fit un festin, et ils mangèrent et burent.'),
('gn',26,31,'crampon1923','Et, s''étant levés de bon matin, ils se prêtèrent serment l''un à l''autre; puis Isaac les congédia et ils s''en allèrent de chez lui en paix.'),
('gn',26,32,'crampon1923','Ce même jour, les serviteurs d''Isaac vinrent lui apporter des nouvelles du puits qu''ils creusaient; ils lui dirent: " Nous avons trouvé de l''eau. "'),
('gn',26,33,'crampon1923','Et il appela le puits Schibéa. C''est pour cela que la ville se nomme Bersabée jusqu''à ce jour.'),
('gn',26,34,'crampon1923','Esaü, âgé de quarante ans, prit pour femmes Judith, fille de Bééri, le Héthéen, et Basemath, fille d''Elon, le Héthéen.'),
('gn',26,35,'crampon1923','Elles furent un sujet d''amertume pour Isaac et Rebecca.'),
('gn',27,1,'crampon1923','Isaac était devenu vieux, et ses yeux s''étaient obscurcis au point de ne plus voir. Il appela Esaü, son fils aîné, et lui dit: " Mon fils! " Celui-ci lui–répondit: " Me voici. "'),
('gn',27,2,'crampon1923','Isaac dit: " Voici donc, je suis vieux; je ne connais pas le jour de ma mort.'),
('gn',27,3,'crampon1923','Maintenant donc, prends tes armes, ton carquois et ton arc, va dans la campagne et tue-moi du gibier.'),
('gn',27,4,'crampon1923','Fais-m''en un bon plat, selon mon goût, et apporte-le-moi, que je le mange, afin que mon âme te bénisse avant que je meure. "'),
('gn',27,5,'crampon1923','— Rebecca entendait pendant qu''Isaac parlait à Esaü, son fils. — Et Esaü s''en alla dans la campagne pour tuer du gibier et l''apporter.'),
('gn',27,6,'crampon1923','Alors Rebecca parla ainsi à Jacob, son fils: " Voici, j''ai entendu ton père qui parlait ainsi à ton frère Esaü:'),
('gn',27,7,'crampon1923','Apporte-moi du gibier et fais-m''en un bon plat, afin que je le mange et que je te bénisse devant Yahweh avant de mourir.'),
('gn',27,8,'crampon1923','Maintenant, mon fils, écoute ma voix dans ce que je vais te commander.'),
('gn',27,9,'crampon1923','Va au troupeau et prends-moi deux beaux chevreaux; j''en ferai pour ton père un bon plat, selon son goût,'),
('gn',27,10,'crampon1923','et tu le porteras à ton père, et il en mangera, afin qu''il te bénisse avant de mourir. "'),
('gn',27,11,'crampon1923','Jacob répondit à Rebecca, sa mère: " Voici, Esaü, mon frère, est velu, et moi j''ai la peau lisse.'),
('gn',27,12,'crampon1923','Peut-être que mon père me touchera, et je passerai à ses yeux pour m''être joué de lui, et j''attirerai sur moi une malédiction au lieu d''une bénédiction. "'),
('gn',27,13,'crampon1923','Sa mère lui dit: " Je prends sur moi ta malédiction, mon fils. Ecoute seulement ma voix et va me prendre les chevreaux. "'),
('gn',27,14,'crampon1923','Jacob alla les prendre et les apporta à sa mère, qui en fit un bon plat, selon le goût de son père.'),
('gn',27,15,'crampon1923','Et Rebecca prit les habits d''Esaü, son fils aîné, les plus beaux, qu''elle avait dans la maison, et elle en revêtit Jacob, son fils cadet.'),
('gn',27,16,'crampon1923','Puis elle lui couvrit les mains de la peau des chevreaux, ainsi que la partie lisse du cou.'),
('gn',27,17,'crampon1923','Et elle mit dans la main de Jacob, son fils, le bon plat et le pain qu''elle avait préparés.'),
('gn',27,18,'crampon1923','Il vint vers son père et dit: " Mon père! " — " Me voici, dit Isaac; qui es-tu, mon fils? "'),
('gn',27,19,'crampon1923','Jacob répondit à son père: « Je suis Esaü, ton premier-né; j''ai fait ce que tu m''as dit. Lève-toi, je te prie, assieds-toi et mange de ma chasse, afin que ton âme me bénisse. »'),
('gn',27,20,'crampon1923','Isaac dit à son fils: " Comment as-tu trouvé si vite, mon fils? " Jacob, répondit: " C''est que Yahweh, ton Dieu, l''a fait venir devant moi. "'),
('gn',27,21,'crampon1923','Et Isaac dit à Jacob: " Approche donc, que je te touche, mon fils, pour savoir si tu es bien mon fils Esaü, ou non. "'),
('gn',27,22,'crampon1923','Jacob s''étant approché d''Isaac, son père, celui-ci le toucha et dit: " La voix est la voix de Jacob, mais les mains sont les mains d''Esaü. "'),
('gn',27,23,'crampon1923','Il ne le reconnut pas, parce que ses mains étaient velues, comme les mains d''Esaü, son frère, et il le bénit.'),
('gn',27,24,'crampon1923','Il dit: " C''est bien toi qui es mon fils Esaü? " — " C''est moi ", répondit Jacob.'),
('gn',27,25,'crampon1923','Et Isaac dit: " Sers-moi, que je mange du gibier de mon fils et que mon âme te bénisse. " Jacob le servit, et il mangea; il lui présenta aussi du vin, et il but.'),
('gn',27,26,'crampon1923','Alors Isaac, son père, lui dit: " Approche-toi donc et baise-moi, mon fils. "'),
('gn',27,27,'crampon1923','Jacob s''approcha et le baisa; et Isaac sentit l''odeur de ses vêtements, et il le bénit en disant: " Voici, l''odeur de mon fils est comme l''odeur d''un champ qu''a béni Yahweh. "'),
('gn',27,28,'crampon1923','Que Dieu te donne de la rosée du ciel et de la graisse de la terre, et abondance de froment et de vin!'),
('gn',27,29,'crampon1923','Que des peuples te servent, et que des nations se prosternent devant toi! Sois le maître de tes frères, et que les fils de ta mère se prosternent devant toi! Maudit soit qui te maudira, et béni soit qui te bénira!'),
('gn',27,30,'crampon1923','Isaac avait achevé de bénir Jacob, et Jacob venait de quitter Isaac, son père, lorsqu''Esaü, son frère, revint de la chasse.'),
('gn',27,31,'crampon1923','Il prépara, lui aussi, un bon plat, et l''apporta à son père; et il dit à son père: " Que mon père se lève et mange de la chasse de son fils, afin que ton âme me bénisse. "'),
('gn',27,32,'crampon1923','Isaac, son père, lui dit: " Qui es-tu? " Il répondit: " Je suis ton fils, ton premier-né, Esaü. "'),
('gn',27,33,'crampon1923','Isaac fut saisi d''une terreur extrême, et il dit: " Qui est donc celui qui a chassé du gibier et m''en a apporté? J''ai mangé de tout avant que tu vinsses, et je l''ai béni; et il sera béni en effet. "'),
('gn',27,34,'crampon1923','Lorsqu''Esaü eut entendu les paroles de son père, il jeta un grand cri, une plainte très amère, et il dit à son père: " Bénis-moi, moi aussi, mon père. "'),
('gn',27,35,'crampon1923','Isaac dit: " Ton frère est venu avec ruse, et il a pris ta bénédiction. "'),
('gn',27,36,'crampon1923','Esaü dit: " Est-ce parce qu''on l''appelle Jacob qu''il m''a supplanté deux fois? Il a pris mon droit d''aînesse, et voilà maintenant qu''il a pris ma bénédiction! " Il ajouta: " N''as-tu pas réservé pour moi une bénédiction? "'),
('gn',27,37,'crampon1923','Isaac répondit et dit à Esaü: " Voici, je l''ai établi ton maître et je lui ai donné tous ses frères pour serviteurs, et je l''ai pourvu de froment et de vin; et pour toi donc, que puis-je faire, mon fils?'),
('gn',27,38,'crampon1923','Esaü dit à son père: " N''as-tu que cette seule bénédiction, mon père? Bénis-moi, moi aussi, mon père! " Et Esaü éleva la voix et pleura.'),
('gn',27,39,'crampon1923','Isaac, son père, lui répondit: " Privée de la graisse de la terre sera ta demeure, privée de la rosée qui descend du ciel.'),
('gn',27,40,'crampon1923','Tu vivras de ton épée, et tu seras asservi à ton frère; mais il arrivera que, en secouant son joug, tu le briseras de dessus ton cou. "'),
('gn',27,41,'crampon1923','Esaü conçut de la haine contre Jacob à cause de la bénédiction que son père lui avait donnée, et Esaü dit en son cœur: " Les jours où je ferai le deuil de mon père approchent; alors je tuerai Jacob, mon frère. "'),
('gn',27,42,'crampon1923','On rapporta à Rebecca les paroles d''Esaü, son fils aîné. Elle fit appeler Jacob, son fils cadet, et lui dit: " Voici qu''Esaü, ton frère, veut se venger de toi en te tuant.'),
('gn',27,43,'crampon1923','Maintenant donc, mon fils, écoute ma voix: lève-toi, fuis vers Laban, mon frère, à Haran;'),
('gn',27,44,'crampon1923','et tu resteras quelque temps auprès de lui, jusqu''à ce que la fureur de ton frère soit apaisée,'),
('gn',27,45,'crampon1923','jusqu''à ce que la colère de ton frère se soit détournée de toi, et qu''il ait oublié ce que tu lui as fait; alors je t''enverrai chercher de là. Pourquoi serais-je privée de vous deux en un même jour? "'),
('gn',27,46,'crampon1923','Rebecca dit à Isaac: " Je suis dégoûtée de la vie, à cause des filles de Heth. Si Jacob prend une femme, comme celles-là, parmi les filles de Heth, parmi les filles de ce pays, à quoi me sert la vie? "'),
('gn',28,1,'crampon1923','Isaac appela Jacob et le bénit, et il lui donna cet ordre: " Tu ne prendras pas pour femme une des filles de Chanaan.'),
('gn',28,2,'crampon1923','Lève-toi, va en Paddan-Aram, chez Bathuel, père de ta mère, et prends-y une femme parmi les filles de Laban, frère de ta mère.'),
('gn',28,3,'crampon1923','Que Dieu le tout-puissant te bénisse, qu''il te fasse croître et multiplier, afin que tu deviennes une multitude de peuples!'),
('gn',28,4,'crampon1923','Qu''il te donne la bénédiction d''Abraham, à toi et à ta postérité avec toi, afin que tu possèdes le pays où tu séjournes, et que Dieu a donné à Abraham! "'),
('gn',28,5,'crampon1923','Et Isaac congédia Jacob, qui s''en alla en Paddan-Aram, vers Laban, fils de Bathuel l''Araméen, frère de Rebecca, la mère de Jacob et d''Esaü.'),
('gn',28,6,'crampon1923','Esaü vit qu''Isaac avait béni Jacob et qu''il l''avait envoyé en Paddan-Aram pour y prendre une femme, et qu''en le bénissant, il lui avait donné cet ordre: " Tu ne prendras pas pour femme une des filles de Chanaan ",'),
('gn',28,7,'crampon1923','et que Jacob, obéissant à son père et à sa mère, était parti pour Paddan-Aram.'),
('gn',28,8,'crampon1923','Esaü vit donc que les filles de Chanaan déplaisaient à Isaac, son père,'),
('gn',28,9,'crampon1923','et Esaü s''en alla vers Ismaël, et il prit pour femme, outre les femmes qu''il avait déjà, Mahéleth, fille d''Ismaël, fils d''Abraham, et sœur de Nabaïoth.'),
('gn',28,10,'crampon1923','Jacob partit de Bersabée et s''en alla à Haran.'),
('gn',28,11,'crampon1923','Il arriva dans un lieu; et il y passa la nuit, parce que le soleil était couché. Ayant pris une des pierres qui étaient là, il en fit son chevet, et il se coucha dans ce lieu.'),
('gn',28,12,'crampon1923','Il eut un songe: et voici, une échelle était posée sur la terre et son sommet touchait au ciel; et voici, sur elle des anges de Dieu montaient et descendaient,'),
('gn',28,13,'crampon1923','et au haut se tenait Yahweh. Il dit: " Je suis Yahweh, le Dieu d''Abraham, ton père, et le Dieu d''Isaac. Cette terre sur laquelle tu es couché, je te la donnerai, à toi et à ta postérité.'),
('gn',28,14,'crampon1923','Ta postérité sera comme la poussière de la terre; tu t''étendras à l''occident et à l''orient, au septentrion et au midi, et toutes les familles de la terre seront bénies en toi et en ta postérité.'),
('gn',28,15,'crampon1923','Voici, je suis avec toi, et je te garderai partout où tu iras et je te ramènerai dans ce pays. Car je ne t''abandonnerai point que je n''aie fait ce que je t''ai dit. "'),
('gn',28,16,'crampon1923','Jacob s''éveilla de son sommeil et il dit: " Certainement Yahweh est en ce lieu, et moi je ne le savais pas! "'),
('gn',28,17,'crampon1923','Saisi de crainte, il ajouta: " Que ce lieu est redoutable! C''est bien ici la maison de Dieu, c''est ici la porte du ciel. "'),
('gn',28,18,'crampon1923','S''étant levé de bon matin, Jacob prit la pierre dont il avait fait son chevet, la dressa pour monument et versa de l''huile sur son sommet.'),
('gn',28,19,'crampon1923','Il nomma ce lieu Béthel; mais primitivement la ville s''appelait Luz.'),
('gn',28,20,'crampon1923','Et Jacob fit un vœu en disant: " Si Dieu est avec moi et me garde dans ce voyage que je fais; s''il me donne du pain à manger et des habits pour me vêtir,'),
('gn',28,21,'crampon1923','et si je retourne heureusement à la maison de mon père, Yahweh sera mon Dieu;'),
('gn',28,22,'crampon1923','cette pierre que j''ai dressée pour monument sera une maison de Dieu, et je vous paierai la dîme de tout ce que vous me donnerez. "'),
('gn',29,1,'crampon1923','Jacob reprit sa marche et s''en alla au pays des fils de l''Orient.'),
('gn',29,2,'crampon1923','Il regarda, et voici, il y avait un puits dans la campagne, et voici, il y avait à côté trois troupeaux de brebis qui étaient couchés, car c''était à ce puits qu''on abreuvait les troupeaux, et la pierre qui était sur l''ouverture du puits était grande.'),
('gn',29,3,'crampon1923','Là se réunissaient tous les troupeaux; on roulait la pierre de dessus l''ouverture du puits, on faisait boire les troupeaux, et l''on remettait la pierre à sa place sur l''ouverture du puits.'),
('gn',29,4,'crampon1923','Jacob dit aux bergers: " Mes frères, d''où êtes-vous? " ils répondirent: " Nous sommes de Haran. "'),
('gn',29,5,'crampon1923','Il leur dit: " Connaissez-vous Laban, fils de Nachor? " Ils répondirent: " Nous le connaissons. "'),
('gn',29,6,'crampon1923','Il leur dit: " Est-il en bonne santé? " Ils répondirent: " Il est en bonne santé, et voici Rachel, sa fille, qui vient avec les brebis. "'),
('gn',29,7,'crampon1923','Il dit: " Voici, il est encore grand jour, et ce n''est pas le moment de rassembler les troupeaux; abreuvez les brebis et retournez les faire paître. "'),
('gn',29,8,'crampon1923','Ils répondirent: " Nous ne le pouvons pas jusqu''à ce que tous les troupeaux soient rassemblés et qu''on roule la pierre de dessus l''ouverture du puits; alors nous abreuverons les brebis. "'),
('gn',29,9,'crampon1923','Il s''entretenait encore avec eux, lorsque Rachel arriva avec les brebis de son père; car elle était bergère.'),
('gn',29,10,'crampon1923','Dès que Jacob vit Rachel, fille de Laban, frère de sa mère, et les brebis de Laban, frère de sa mère, il s''approcha, roula la pierre de dessus l''ouverture du puits, et abreuva les brebis de Laban, frère de sa mère.'),
('gn',29,11,'crampon1923','Et Jacob baisa Rachel, et il éleva la voix et pleura.'),
('gn',29,12,'crampon1923','Jacob apprit à Rachel qu''il était frère de son père, qu''il était fils de Rebecca; et elle courut l''annoncer à son père.'),
('gn',29,13,'crampon1923','Quand Laban eut entendu parler de Jacob, fils de sa sœur, il courut au-devant de lui, et l''ayant pris dans ses bras, il lui donna des baisers et l''amena dans sa maison. Jacob raconta à Laban toutes ces choses,'),
('gn',29,14,'crampon1923','et Laban lui dit: " Oui, tu es mes os et ma chair. " Et Jacob demeura avec lui un mois entier.'),
('gn',29,15,'crampon1923','Alors Laban dit à Jacob: " Est-ce que, parce que tu es mon frère, tu me serviras pour rien? Dis-moi quel sera ton salaire. "'),
('gn',29,16,'crampon1923','Or Laban avait deux filles; l''aînée se nommait Lia, et la cadette Rachel.'),
('gn',29,17,'crampon1923','Lia avait les yeux malades; mais Rachel était belle de taille et belle de visage.'),
('gn',29,18,'crampon1923','Comme Jacob aimait Rachel, il dit: " Je te servirai sept ans pour Rachel, ta fille cadette. "'),
('gn',29,19,'crampon1923','Et Laban dit: " Mieux vaut te la donner que la donner à un autre; reste avec moi. "'),
('gn',29,20,'crampon1923','Et Jacob servit pour Rachel sept années, et elles furent à ses yeux comme quelques jours, parce qu''il l''aimait.'),
('gn',29,21,'crampon1923','Jacob dit à Laban: " Donne-moi ma femme, car mon temps est accompli, et j''irai vers elle. "'),
('gn',29,22,'crampon1923','Laban réunit tous les gens du lieu et fit un festin;'),
('gn',29,23,'crampon1923','et le soir, prenant Lia, sa fille, il l''amena à Jacob, qui alla vers elle.'),
('gn',29,24,'crampon1923','Et Laban donna sa servante Zelpha pour servante à Lia, sa fille.'),
('gn',29,25,'crampon1923','Le matin venu, voilà que c''était Lia. Et Jacob dit à Laban: " Que m''as-tu fait? N''est-ce pas pour Rachel que j''ai servi chez toi? Pourquoi m''as-tu trompé? "'),
('gn',29,26,'crampon1923','Laban répondit: " Ce n''est point l''usage dans notre pays de donner la cadette avant l''aînée.'),
('gn',29,27,'crampon1923','Achève la semaine de celle-ci, et nous te donnerons aussi l''autre pour le service que tu feras encore chez moi pendant sept autres années. "'),
('gn',29,28,'crampon1923','Jacob fit ainsi, et il acheva la semaine de Lia; puis Laban lui donna pour femme Rachel, sa fille.'),
('gn',29,29,'crampon1923','Et Laban donna sa servante Bala pour servante à Rachel, sa fille.'),
('gn',29,30,'crampon1923','Jacob alla aussi vers Rachel et il l''aima aussi plus que Lia; il servit encore chez Laban sept autres années.'),
('gn',29,31,'crampon1923','Yahweh vit que Lia était haïe, et il la rendit féconde, tandis que Rachel était stérile.'),
('gn',29,32,'crampon1923','Lia conçut et enfanta un fils, et elle le nomma Ruben, car elle dit: " Yahweh a regardé mon affliction; maintenant mon mari m''aimera. "'),
('gn',29,33,'crampon1923','Elle conçut encore et enfanta un fils, et elle dit: " Yahweh a entendu que j''étais haïe, et il m''a encore donné celui-là ". Et elle le nomma Siméon.'),
('gn',29,34,'crampon1923','Elle conçut encore et enfanta un fils, et elle dit: " Cette fois mon mari s''attachera à moi car je lui ai enfanté trois fils. " C''est pourquoi on le nomma Lévi.'),
('gn',29,35,'crampon1923','Elle conçut encore et enfanta un fils, et elle dit: " Cette fois je louerai Yahweh. " C''est pourquoi elle le nomma Juda. Et elle cessa d''avoir des enfants.'),
('gn',30,1,'crampon1923','Rachel voyant qu''elle n''enfantait pas d''enfant à Jacob, fut jalouse de sa sœur, et elle dit à Jacob: " Donne-moi des enfants, ou je meurs! "'),
('gn',30,2,'crampon1923','La colère de Jacob s''enflamma contre Rachel, et il dit: " Suis-je à la place de Dieu, qui t''a refusé la fécondité? "'),
('gn',30,3,'crampon1923','Elle dit: " Voici ma servante Bala; va vers elle; qu''elle enfante sur mes genoux, et par elle j''aurai, moi aussi, une famille. "'),
('gn',30,4,'crampon1923','Et elle lui donna Bala, sa servante, pour femme, et Jacob alla vers elle.'),
('gn',30,5,'crampon1923','Bala conçut et enfanta un fils à Jacob.'),
('gn',30,6,'crampon1923','Et Rachel dit: " Dieu m''a rendu justice, et même il a entendu ma voix et m''a donné un fils. " C''est pourquoi elle le nomma Dan.'),
('gn',30,7,'crampon1923','Bala, servante de Rachel, conçut encore et enfanta un second fils à Jacob.'),
('gn',30,8,'crampon1923','Et Rachel dit: " J''ai lutté auprès de Dieu à l''encontre de ma sœur, et je l''ai emporté. " Et elle le nomma Nephthali.'),
('gn',30,9,'crampon1923','Lorsque Lia vit qu''elle avait cessé d''avoir des enfants, elle prit Zelpha, sa servante, et la donna pour femme à Jacob.'),
('gn',30,10,'crampon1923','Zelpha, servante de Lia, enfanta un fils à Jacob;'),
('gn',30,11,'crampon1923','et Lia dit: " Quelle bonne fortune! " et elle le nomma Gad.'),
('gn',30,12,'crampon1923','Zelpha, servante de Lia, enfanta un second fils à Jacob;'),
('gn',30,13,'crampon1923','et Lia dit: " Pour mon bonheur! car les filles me diront bienheureuse. " Et elle le nomma Aser.'),
('gn',30,14,'crampon1923','Ruben sortit au temps de la moisson des blés et, ayant trouvé des mandragores dans les champs, il les apporta à Lia, sa mère. Alors Rachel dit à Lia: " Donne-moi, je te prie, des mandragores de ton fils. "'),
('gn',30,15,'crampon1923','Elle lui répondit: " Est-ce peu que tu aies pris mon mari, pour que tu prennes encore les mandragores de mon fils? " Et Rachel dit: " Eh bien, qu''il couche avec toi cette nuit pour les mandragores de ton fils. "'),
('gn',30,16,'crampon1923','Le soir, comme Jacob revenait des champs, Lia sortit à sa rencontre et lui dit: " C''est vers moi que tu viendras, car je t''ai loué pour les mandragores de mon fils. " Et il coucha avec elle cette nuit-là.'),
('gn',30,17,'crampon1923','Dieu exauça Lia; elle conçut et enfanta à Jacob un cinquième fils;'),
('gn',30,18,'crampon1923','et Lia dit: " Dieu m''a donné mon salaire, parce que j''ai donné ma servante à mon mari. " Et elle le nomma Issachar.'),
('gn',30,19,'crampon1923','Lia conçut encore et enfanta un sixième fils à Jacob;'),
('gn',30,20,'crampon1923','et elle dit: " Dieu m''a fait un beau don; cette fois mon mari habitera avec moi, puisque je lui ai enfanté six fils. " Et elle le nomma Zabulon.'),
('gn',30,21,'crampon1923','Elle enfanta ensuite une fille, qu''elle appela Dina.'),
('gn',30,22,'crampon1923','Dieu se souvint de Rachel; il l''exauça et la rendit féconde.'),
('gn',30,23,'crampon1923','Elle conçut et enfanta un fils, et elle dit: " Dieu a ôté mon opprobre. "'),
('gn',30,24,'crampon1923','Et elle le nomma Joseph, en disant: " Que Yahweh m''ajoute encore un autre fils! "'),
('gn',30,25,'crampon1923','Lorsque Rachel eut enfanté Joseph, Jacob dit à Laban: " Laisse-moi partir, et que je retourne chez moi, dans mon pays.'),
('gn',30,26,'crampon1923','Donne-moi mes femmes, ainsi que mes enfants, pour lesquels je t''ai servi, et je m''en irai, car tu sais quel service j''ai fait pour toi. "'),
('gn',30,27,'crampon1923','Laban lui dit: " Si j''ai trouvé grâce à tes yeux... J''ai observé que Yahweh m''a béni à cause de toi;'),
('gn',30,28,'crampon1923','fixe-moi ton salaire, et je te le donnerai. "'),
('gn',30,29,'crampon1923','Jacob lui dit: " Tu sais toi-même comment je t''ai servi et ce qu''est devenu ton bétail avec moi.'),
('gn',30,30,'crampon1923','Car c''était peu de chose que ton bien avant moi; mais il s''est extrêmement accru, et Yahweh t''a béni sur mes pas. Maintenant quand travaillerai-je aussi pour ma maison? "'),
('gn',30,31,'crampon1923','Laban dit: " Que te donnerai-je? " Et Jacob dit: " Tu ne me donneras rien. Si tu m''accordes ce que je vais dire, je recommencerai à paître ton troupeau et à le garder.'),
('gn',30,32,'crampon1923','Je passerai aujourd''hui à travers tout ton troupeau, en mettant à part parmi les agneaux toute bête tachetée et marquetée et toute bête noire, et parmi les chèvres tout ce qui est marqueté et tacheté: ce sera mon salaire.'),
('gn',30,33,'crampon1923','Ma droiture témoignera pour moi demain, quand tu viendras reconnaître mon salaire. Tout ce qui ne sera pas tacheté et marqueté parmi les chèvres, et noir parmi les agneaux sera chez moi un vol.'),
('gn',30,34,'crampon1923','Laban dit: " Eh bien, qu''il en soit selon ta parole. "'),
('gn',30,35,'crampon1923','Et le jour même, il mit à part les boucs rayés et marquetés, toutes les chèvres tachetées et marquetées, toutes celles qui avaient du blanc, et tout ce qui était noir parmi les agneaux; et il les mit entre les mains de ses fils.'),
('gn',30,36,'crampon1923','Puis il mit l''espace de trois journées de chemin entre lui et Jacob. Et Jacob faisait paître le reste du troupeau de Laban.'),
('gn',30,37,'crampon1923','Jacob prit des baguettes vertes de peuplier, d''amandier et de platane; il y pela des bandes blanches, mettant à nu le blanc qui était sur les baguettes.'),
('gn',30,38,'crampon1923','Puis il plaça les baguettes qu''il avait pelées en regard des brebis dans les rigoles, dans les abreuvoirs où les brebis venaient boire; et elles entraient en chaleur quand elles venaient boire.'),
('gn',30,39,'crampon1923','Et les brebis, entrant en chaleur devant les baguettes, faisaient des petits rayés, tachetés et marquetés.'),
('gn',30,40,'crampon1923','Jacob mettait à part les agneaux, et il tournait la face du troupeau vers ce qui était rayé et tout ce qui était noir dans le troupeau de Laban. Il se fit ainsi des troupeaux à lui, qu''il ne joignit pas au troupeau de Laban.'),
('gn',30,41,'crampon1923','En outre, c''était quand les brebis vigoureuses entraient en chaleur que Jacob mettait sous les yeux des brebis les baguettes dans les abreuvoirs, afin qu''elles entrassent en chaleur près des baguettes.'),
('gn',30,42,'crampon1923','Quand les brebis étaient chétives, il ne les mettait point, en sorte que les agneaux chétifs étaient pour Laban, et les vigoureux pour Jacob.'),
('gn',30,43,'crampon1923','Cet homme devint ainsi extrêmement riche; il eut de nombreux troupeaux, des servantes et des serviteurs, des chameaux et des ânes'),
('gn',31,1,'crampon1923','Jacob entendit les propos des fils de Laban, qui disaient: " Jacob a pris tout ce qui était à notre père, et c''est avec le bien de notre père qu''il s''est fait toute cette richesse. "'),
('gn',31,2,'crampon1923','Jacob remarqua aussi le visage de Laban, et voici, il n''était plus à son égard comme auparavant.'),
('gn',31,3,'crampon1923','Et Yahweh dit à Jacob: " Retourne au pays de tes pères et au lieu de ta naissance, et je serai avec toi. "'),
('gn',31,4,'crampon1923','Alors Jacob fit dire à Rachel et à Lia de venir le trouver aux champs, où il faisait paître son troupeau.'),
('gn',31,5,'crampon1923','Il leur dit: " Je vois que le visage de votre père n''est plus le même envers moi qu''auparavant; or le Dieu de mon père a été avec moi.'),
('gn',31,6,'crampon1923','Vous savez vous-mêmes que j''ai servi votre père de tout mon pouvoir;'),
('gn',31,7,'crampon1923','et votre père s''est joué de moi, changeant dix fois mon salaire; mais Dieu ne lui a pas permis de me causer du préjudice.'),
('gn',31,8,'crampon1923','Quand il disait: Les bêtes tachetées seront ton salaire, toutes les brebis faisaient des agneaux tachetés. Et s''il disait: Les bêtes rayées seront ton salaire, toutes les brebis faisaient des agneaux rayés.'),
('gn',31,9,'crampon1923','Dieu a donc pris le bétail de votre père et me l''a donné.'),
('gn',31,10,'crampon1923','Au temps où les brebis entrent en chaleur, je levai les yeux et je vis en songe que les béliers qui couvraient les brebis étaient rayés, tachetés et marquetés.'),
('gn',31,11,'crampon1923','Et un ange de Dieu me dit en songe: Jacob! Je répondis: Me voici.'),
('gn',31,12,'crampon1923','Et il dit: Lève les yeux et regarde: tous les béliers qui couvrent les brebis sont rayés, tachetés et marquetés; car j''ai vu tout ce que t''a fait Laban.'),
('gn',31,13,'crampon1923','Je suis le Dieu de Béthel, où tu as oint un monument, où tu m''as fait un vœu. Maintenant lève-toi, sors de ce pays et retourne au pays de ta naissance. "'),
('gn',31,14,'crampon1923','Rachel et Lia répondirent en disant: " Est-ce que nous avons encore une part et un héritage dans la maison de notre père?'),
('gn',31,15,'crampon1923','Ne sommes-nous pas regardées par lui comme des étrangères, puisqu''il nous a vendues et qu''il mange notre argent?'),
('gn',31,16,'crampon1923','D''ailleurs tout le bien que Dieu a enlevé à notre père, nous l''avons, nous et nos enfants. Fais donc maintenant ce que Dieu t''a ordonné. "'),
('gn',31,17,'crampon1923','Jacob se leva et fit monter ses enfants et ses femmes sur les chameaux.'),
('gn',31,18,'crampon1923','Il emmena tout son troupeau et tout le bien qu''il avait acquis, le troupeau qu''il possédait, qu''il avait acquis à Paddan-Aram; et il s''en alla vers Isaac, son père, au pays de Chanaan.'),
('gn',31,19,'crampon1923','Comme Laban était allé tondre ses brebis, Rachel déroba les théraphim de son père.'),
('gn',31,20,'crampon1923','Et Jacob trompa Laban, l''Araméen, en ne l''informant pas de sa fuite.'),
('gn',31,21,'crampon1923','Il s''enfuit, lui et tout ce qui lui appartenait et, s''étant levé, il traversa le fleuve et se dirigea vers la montagne de Galaad.'),
('gn',31,22,'crampon1923','Le troisième jour, on annonça à Laban que Jacob s''était enfui.'),
('gn',31,23,'crampon1923','Il prit avec lui ses frères et le poursuivit pendant sept journées de chemin; il l''atteignit à la montagne de Galaad.'),
('gn',31,24,'crampon1923','Et Dieu vint en songe, de nuit, vers Laban l''Araméen, et il lui dit: " Garde-toi de rien dire à Jacob, ni en bien ni en mal. "'),
('gn',31,25,'crampon1923','Laban atteignit donc Jacob. — Jacob avait dressé sa tente sur la montagne, et Laban avait aussi dressé la sienne, avec ses frères, sur la montagne de Galaad.'),
('gn',31,26,'crampon1923','Laban dit à Jacob: " Qu''as-tu fait? tu as abusé mon esprit et tu as emmené mes filles comme des captives prises par l''épée?'),
('gn',31,27,'crampon1923','Pourquoi as-tu pris secrètement la fuite et m''as-tu trompé, au lieu de m''avertir, moi qui t''aurais laissé aller dans l''allégresse des chants, au son du tambourin et de la harpe?'),
('gn',31,28,'crampon1923','Tu ne m''as pas laissé embrasser mes fils et mes filles! Vraiment tu as agi en insensé.'),
('gn',31,29,'crampon1923','Ma main est assez forte pour vous faire du mal; mais le Dieu de votre père m''a parlé cette nuit en disant: Garde-toi de rien dire à Jacob, ni en bien ni en mal.'),
('gn',31,30,'crampon1923','Et maintenant, tu es parti parce que tu languissais après la maison de ton père; mais, pourquoi as-tu dérobé mes dieux? "'),
('gn',31,31,'crampon1923','Jacob répondit et dit à Laban: " C''est que j''avais de la crainte, en me disant que peut-être tu m''enlèverais tes filles.'),
('gn',31,32,'crampon1923','Quant à celui chez qui tu trouveras tes dieux, il ne vivra pas! En présence de nos frères, reconnais ce qui t''appartient chez moi et prends-le. " — Or Jacob ignorait que Rachel les eût dérobés. —'),
('gn',31,33,'crampon1923','Laban entra dans la tente de Jacob, dans la tente de Lia et dans la tente des deux servantes, et il ne trouva rien. Puis il sortit de la tente de Lia et entra dans la tente de Rachel.'),
('gn',31,34,'crampon1923','Rachel avait pris les théraphim, les avait mis dans la selle du chameau et s''était assise dessus. Laban fouilla toute la tente, sans rien trouver.'),
('gn',31,35,'crampon1923','Et Rachel dit à son père: " Que mon seigneur ne s''irrite point de ce que je ne puis me lever devant toi, car j''ai ce qui est ordinaire aux femmes. " Il chercha, mais ne trouva pas les théraphim.'),
('gn',31,36,'crampon1923','Jacob se mit en colère et adressa des reproches à Laban; et Jacob prit la parole et dit à Laban: " Quel est mon crime, quelle est ma faute, que tu t''acharnes après moi?'),
('gn',31,37,'crampon1923','Quand tu as fouillé tous mes effets, qu''as-tu trouvé des effets de ta maison? Produis-le ici devant mes frères et tes frères, et qu''ils soient juges entre nous deux.'),
('gn',31,38,'crampon1923','Voilà vingt ans que j''ai passés chez toi; tes brebis et tes chèvres n''ont pas avorté, et je n''ai pas mangé les béliers de ton troupeau.'),
('gn',31,39,'crampon1923','Ce qui était déchiré par les bêtes sauvages, je ne te l''ai pas rapporté; c''est moi qui en ai supporté la perte. Tu me réclamais ce qui avait été dérobé de jour et ce qui avait été dérobé de nuit.'),
('gn',31,40,'crampon1923','J''étais dévoré le jour par la chaleur, et la nuit par le froid, et mon sommeil fuyait de mes yeux.'),
('gn',31,41,'crampon1923','Voilà vingt ans que je suis dans ta maison; je t''ai servi quatorze ans pour tes deux filles et six ans pour ton bétail, et tu as changé mon salaire dix fois.'),
('gn',31,42,'crampon1923','Si le Dieu de mon père, le Dieu d''Abraham et la Terreur d''Isaac n''eût pas été pour moi, tu m''aurais maintenant laissé partir à vide. Dieu a vu ma souffrance et le travail de mes mains, et cette nuit il a jugé entre nous. "'),
('gn',31,43,'crampon1923','Laban répondit et dit à Jacob: " Ces filles sont mes filles, ces enfants mes enfants, ces troupeaux mes troupeaux, et tout ce que tu vois est à moi. Que ferais-je aujourd''hui à mes filles, à elles et aux fils qu''elles ont enfantés?'),
('gn',31,44,'crampon1923','Maintenant donc, viens, faisons alliance, moi et toi, et qu''il y ait un témoin entre moi et toi.'),
('gn',31,45,'crampon1923','Jacob prit une pierre et la dressa pour monument.'),
('gn',31,46,'crampon1923','Et Jacob dit à ses frères: " Amassez des pierres. " Ils prirent des pierres et en firent un monceau, et ils mangèrent là sur le monceau.'),
('gn',31,47,'crampon1923','Laban l''appela Yegar-Sahadutha, et Jacob l''appela Galaad.'),
('gn',31,48,'crampon1923','Et Laban dit: " Ce monceau est témoin entre moi et toi aujourd''hui. " C''est pourquoi on lui donna le nom de Galaad,'),
('gn',31,49,'crampon1923','et aussi celui de Mitspa, parce que Laban dit: " Que Yahweh nous surveille, moi et toi, quand nous serons séparés l''un de l''autre.'),
('gn',31,50,'crampon1923','Si tu maltraites mes filles et si tu prends d''autres femmes à côté de mes filles, ce n''est pas un homme qui sera avec nous; mais, prends-y garde, c''est Dieu qui sera témoin entre moi et toi. "'),
('gn',31,51,'crampon1923','Laban dit encore à Jacob: " Voici ce monceau et voici le monument que j''ai dressé entre moi et toi.'),
('gn',31,52,'crampon1923','Ce monceau est témoin et ce monument est témoin que je n''avancerai pas vers toi au delà de ce monceau, et que tu n''avanceras pas vers moi au delà de ce monceau et de ce monument, pour faire du mal.'),
('gn',31,53,'crampon1923','Que le Dieu d''Abraham, le Dieu de Nachor et le Dieu de leurs pères soient juges entre nous! " Et Jacob jura par la Terreur d''Isaac.'),
('gn',31,54,'crampon1923','Et Jacob offrit un sacrifice sur la montagne, et il invita ses frères au repas. Ils mangèrent donc et passèrent la nuit sur la montagne.'),
('gn',32,1,'crampon1923','Laban se leva de bon matin; il baisa ses fils et ses filles et les bénit; puis il partit, pour retourner dans sa maison.'),
('gn',32,2,'crampon1923','Jacob poursuivit son chemin, et des anges de Dieu le rencontrèrent.'),
('gn',32,3,'crampon1923','En les voyant, il dit: " C''est le camp de Dieu! " et il donna à ce lieu le nom de Mahanaïm.'),
('gn',32,4,'crampon1923','Jacob envoya devant lui des messagers vers Esaü, son frère, au pays de Seïr, dans la campagne d''Edom.'),
('gn',32,5,'crampon1923','Il leur donna cet ordre: " Voici ce que vous direz à mon seigneur, à Esaü: Ainsi parle ton serviteur Jacob: J''ai séjourné chez Laban et j''y suis resté jusqu''à présent,'),
('gn',32,6,'crampon1923','J''ai des bœufs et des ânes, des brebis, des serviteurs et des servantes, et j''en fais informer mon seigneur, pour trouver grâce à tes yeux. "'),
('gn',32,7,'crampon1923','Les messagers revinrent auprès de Jacob en disant: " Nous sommes allés vers ton frère Esaü, et il marche à ta rencontre avec quatre cents hommes. "'),
('gn',32,8,'crampon1923','Jacob eut une grande frayeur et fut dans l''angoisse. Il partagea en deux camps les gens qui étaient avec lui, les brebis les bœufs et les chameaux,'),
('gn',32,9,'crampon1923','et il dit: " Si Esaü rencontre l''un des camps et le frappe, le camp qui restera pourra être sauvé. "'),
('gn',32,10,'crampon1923','Jacob dit: " Dieu de mon père Abraham, Dieu de mon père Isaac, Yahweh, qui m''avez dit: Retourne en ton pays et au lieu de ta naissance, et je te ferai du bien:'),
('gn',32,11,'crampon1923','je suis trop petit pour toutes les grâces et pour toute la fidélité dont vous avez usé envers votre serviteur; car j''ai passé ce Jourdain avec mon bâton, et maintenant je suis devenu deux camps.'),
('gn',32,12,'crampon1923','Délivrez-moi, je vous prie, de la main de mon frère, de la main d''Esaü; car je crains qu''il ne vienne me frapper, la mère avec les enfants.'),
('gn',32,13,'crampon1923','Et vous, vous avez dit: Je te ferai du bien et je rendrai ta postérité pareille au sable de la mer, si nombreux qu''on ne peut le compter. "'),
('gn',32,14,'crampon1923','Jacob passa là cette nuit. Et il prit de ce qu''il avait sous la main, pour faire un présent à Esaü, son frère:'),
('gn',32,15,'crampon1923','deux cents chèvres et vingt boucs, deux cents brebis et vingt béliers,'),
('gn',32,16,'crampon1923','trente chamelles qui allaitaient, avec leurs petits, quarante vaches et dix taureaux, vingt ânesses et dix ânons.'),
('gn',32,17,'crampon1923','Il les remit à ses serviteurs, chaque troupeau à part, et il leur dit: " Passez devant moi, et laissez un intervalle entre chaque troupeau. "'),
('gn',32,18,'crampon1923','Et il donna ordre au premier: " Quand Esaü, mon frère, te rencontrera et te demandera: A qui es-tu, où vas-tu, à qui appartient ce troupeau qui va devant toi?'),
('gn',32,19,'crampon1923','tu répondras: A ton serviteur Jacob; c''est un présent qu''il envoie à mon seigneur, à Esaü; et voici que lui-même vient derrière nous. "'),
('gn',32,20,'crampon1923','Il donna le même ordre au second, au troisième et à tous ceux qui suivaient les troupeaux, en disant: " Vous parlerez ainsi à Esaü quand vous le rencontrerez;'),
('gn',32,21,'crampon1923','vous direz: Voici, ton serviteur Jacob vient aussi derrière nous. " Car il se disait: " Je l''apaiserai par ce présent qui va devant moi, et ensuite je verrai sa face; peut-être me fera-t-il bon accueil. "'),
('gn',32,22,'crampon1923','Le présent passa devant lui, et il resta cette nuit-là dans le camp.'),
('gn',32,23,'crampon1923','Il se leva dans la même nuit et, ayant pris ses deux femmes, ses deux servantes et ses onze enfants, il passa le gué du Jaboc.'),
('gn',32,24,'crampon1923','Il les prit et leur fit passer le torrent; il fit aussi passer ce qui lui appartenait.'),
('gn',32,25,'crampon1923','Jacob resta seul; et un homme lutta avec lui jusqu''au lever de l''aurore.'),
('gn',32,26,'crampon1923','Voyant qu''il ne pouvait le vaincre, il le toucha à l''articulation de la hanche, et l''articulation de la hanche de Jacob se démit pendant qu''il luttait avec lui.'),
('gn',32,27,'crampon1923','Et il dit à Jacob: " Laisse-moi aller, car l''aurore se lève. " Jacob répondit: " Je ne te laisserai point aller que tu ne m''aies béni. "'),
('gn',32,28,'crampon1923','Il lui dit: " Quel est ton nom? " Il répondit: " Jacob. "'),
('gn',32,29,'crampon1923','Et il dit: " Ton nom ne sera plus Jacob, mais Israël, car tu as combattu avec Dieu et avec des hommes, et tu l''as emporté. "'),
('gn',32,30,'crampon1923','Jacob l''interrogea, en disant: " Fais-moi, je te prie, connaître ton nom. " Il dit: " Pourquoi demandes-tu quel est mon nom? " Et il le bénit là.'),
('gn',32,31,'crampon1923','Jacob nomma ce lieu Phanuel; " car, dit-il, j''ai vu Dieu face à face, et ma vie a été sauve. "'),
('gn',32,32,'crampon1923','Et le soleil se leva quand il eut passé Phanuel, mais il boitait de la hanche.'),
('gn',32,33,'crampon1923','C''est pourquoi les enfants d''Israël ne mangent point jusqu''à ce jour le grand nerf qui est à l''articulation de la hanche, parce que Dieu a touché l''articulation de la hanche de Jacob au grand nerf.'),
('gn',33,1,'crampon1923','Jacob leva les yeux et regarda, et voici, Esaü venait, ayant avec lui quatre cents hommes. Ayant distribué les enfants par groupes auprès de Lia, auprès de Rachel et auprès des deux servantes,'),
('gn',33,2,'crampon1923','il plaça en tête les servantes avec leurs enfants, puis Lia avec ses enfants, et enfin Rachel avec Joseph.'),
('gn',33,3,'crampon1923','Lui-même passa devant eux, et il se courba vers la terre sept fois, jusqu''à ce qu''il fût proche de son frère Esaü.'),
('gn',33,4,'crampon1923','Esaü courut à sa rencontre, l''embrassa, se jeta à son cou et le baisa; et ils pleurèrent.'),
('gn',33,5,'crampon1923','Puis, levant les yeux, Esaü vit les femmes et les enfants, et il dit: " Qui sont ceux que tu as là? " Jacob répondit: " Ce sont les enfants que Dieu a accordés à ton serviteur. "'),
('gn',33,6,'crampon1923','Les servantes s''approchèrent, elles et leurs enfants, et se prosternèrent.'),
('gn',33,7,'crampon1923','Lia et ses enfants s''approchèrent aussi, et ils se prosternèrent; ensuite s''approchèrent Joseph et Rachel, et ils se prosternèrent.'),
('gn',33,8,'crampon1923','Et Esaü dit: " Que veux-tu faire avec tout ce camp que j''ai rencontré? " Et Jacob dit: " C''est pour trouver grâce aux yeux de mon seigneur. "'),
('gn',33,9,'crampon1923','Esaü dit: " Je suis dans l''abondance, mon frère; garde ce qui est à toi. "'),
('gn',33,10,'crampon1923','Et Jacob dit: " Non, je te prie, si j''ai trouvé grâce à tes yeux, accepte mon présent de ma main; car c''est pour cela que j''ai vu ta face comme on voit la face de Dieu, et tu m''as accueilli favorablement.'),
('gn',33,11,'crampon1923','Accepte donc mon offrande qui t''a été amenée, car Dieu m''a accordé sa faveur et je ne manque de rien. " Il le pressa si bien qu''Esaü accepta.'),
('gn',33,12,'crampon1923','Esaü dit: " Partons, mettons-nous en route; je marcherai devant toi. "'),
('gn',33,13,'crampon1923','Jacob répondit: " Mon seigneur sait que les enfants sont délicats, et que je suis chargé de brebis et de vaches qui allaitent; si on les pressait un seul jour, tout le troupeau périrait.'),
('gn',33,14,'crampon1923','Que mon seigneur prenne les devants sur son serviteur, et moi, je suivrai doucement, au pas du troupeau qui marche devant moi, et au pas des enfants, jusqu''à ce que j''arrive chez mon seigneur, à Séir. "'),
('gn',33,15,'crampon1923','Esaü dit: " Permets du moins que je laisse auprès de toi une partie des gens qui sont avec moi. " Jacob répondit: " Pourquoi cela? Que je trouve grâce aux yeux de mon seigneur. "'),
('gn',33,16,'crampon1923','Et Esaü reprit ce jour-là le chemin de Séir.'),
('gn',33,17,'crampon1923','Jacob partit pour Socoth et il se construisit une maison. Il fit aussi des cabanes pour ses troupeaux; c''est pourquoi on a appelé ce lieu Socoth.'),
('gn',33,18,'crampon1923','A son retour de Paddan-Aram, Jacob arriva heureusement à la ville de Sichem, au pays de Chanaan, et il campa devant la ville.'),
('gn',33,19,'crampon1923','Il acheta des fils de Hémor, père de Sichem, pour cent késitas, la pièce de terre où il avait dressé sa tente;'),
('gn',33,20,'crampon1923','il éleva là un autel, et l''appela El-Elohé-Israël.'),
('gn',34,1,'crampon1923','Dina, la fille que Lia avait enfantée à Jacob, sortit pour voir les filles du pays.'),
('gn',34,2,'crampon1923','Sichem, fils de Hémor, le Hévéen, prince du pays, l''ayant aperçue, l''enleva, coucha avec elle et lui fit violence.'),
('gn',34,3,'crampon1923','Son âme s''attacha à Dina, fille de Jacob; il aima la jeune fille et parla au cœur de la jeune fille.'),
('gn',34,4,'crampon1923','Et Sichem dit à Hémor, son père: " Prends-moi cette jeune fille pour femme. "'),
('gn',34,5,'crampon1923','Or Jacob apprit qu''il avait outragé Dina, sa fille; mais, comme ses fils étaient aux champs avec son troupeau, Jacob garda le silence jusqu''à leur retour.'),
('gn',34,6,'crampon1923','Hémor, père de Sichem, sortit vers Jacob, pour lui parler.'),
('gn',34,7,'crampon1923','Or les fils de Jacob étaient revenus des champs quand ils apprirent la chose; ces hommes furent outrés et entrèrent en une grande colère, parce que Sichem avait commis une infamie contre Israël, en couchant avec la fille de Jacob, ce qui ne devait pas se faire.'),
('gn',34,8,'crampon1923','Hémor leur parla ainsi: " L''âme de Sichem, mon fils, s''est attachée à votre fille; donnez-la-lui pour femme, je vous prie.'),
('gn',34,9,'crampon1923','Alliez-vous avec nous; vous nous donnerez vos filles, et vous prendrez pour vous les nôtres.'),
('gn',34,10,'crampon1923','Vous habiterez chez nous, et le pays sera à votre disposition, pour vous y établir, y trafiquer et y acquérir des propriétés. "'),
('gn',34,11,'crampon1923','Sichem dit au père et aux frères de Dina: " Que je trouve grâce à vos yeux, et je donnerai ce que vous me direz.'),
('gn',34,12,'crampon1923','Exigez de moi un fort prix d''achat et de grands présents, et ce que vous me direz, je le donnerai; mais donnez-moi la jeune fille pour femme. "'),
('gn',34,13,'crampon1923','Les fils de Jacob, répondirent et parlèrent avec ruse à Sichem et à Hémor, son père, parce que Sichem avait déshonoré Dina, leur sœur;'),
('gn',34,14,'crampon1923','ils leur dirent: " C''est une chose que nous ne pouvons pas faire que de donner notre sœur à un homme non circoncis, car ce serait un opprobre pour nous.'),
('gn',34,15,'crampon1923','Nous ne consentirons à votre désir qu''à la condition que vous deveniez comme nous, et que tout mâle parmi vous soit circoncis.'),
('gn',34,16,'crampon1923','Ainsi nous vous donnerons nos filles, et nous prendrons pour nous les vôtres; nous habiterons avec vous et nous formerons un seul peuple.'),
('gn',34,17,'crampon1923','Mais si vous ne voulez pas nous écouter et vous circoncire, nous reprendrons notre fille et nous nous en irons. "'),
('gn',34,18,'crampon1923','Leurs paroles plurent à Hémor et à Sichem, fils de Hémor;'),
('gn',34,19,'crampon1923','et le jeune homme ne tarda pas à faire la chose, car il était épris de la fille de Jacob, et il était l''homme le plus considéré de la maison de son père.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('gn',34,20,'crampon1923','Hémor et Sichem, son fils, se rendirent donc à la porte de la ville, et ils parlèrent aux hommes de leur ville, en disant:'),
('gn',34,21,'crampon1923','" Ces gens-là sont des hommes pacifiques au milieu de nous; qu''ils s''établissent dans le pays et qu''ils y trafiquent; voici que le pays, à droite et à gauche, est assez vaste pour eux. Nous prendrons leurs filles pour femmes, et nous leur donnerons nos filles.'),
('gn',34,22,'crampon1923','Mais ces hommes ne consentiront à habiter avec nous, pour devenir un même peuple, qu''à une condition, c''est que tout mâle parmi nous soit circoncis, comme ils sont eux-mêmes circoncis.'),
('gn',34,23,'crampon1923','Leurs troupeaux et leurs biens et toutes leurs bêtes de somme ne seront-ils pas à nous? Seulement, accédons à leur désir et qu''ils s''établissent chez nous. "'),
('gn',34,24,'crampon1923','Tous ceux qui sortaient par la porte de la ville écoutèrent Hémor et Sichem, son fils, et tout mâle fut circoncis, tout homme sortant par la porte de la ville.'),
('gn',34,25,'crampon1923','Le troisième jour, lorsqu''ils étaient souffrants, deux fils de Jacob, Siméon et Lévi, frères de Dina, prirent chacun leur épée, marchèrent sans crainte sur la ville et tuèrent tous les mâles.'),
('gn',34,26,'crampon1923','Ils passèrent aussi au fil de l''épée Hémor et Sichem, son fils; et, ayant enlevé Dina de la maison de Sichem, ils sortirent.'),
('gn',34,27,'crampon1923','Les fils de Jacob se jetèrent sur les morts et pillèrent la ville, parce qu''on avait déshonoré leur sœur.'),
('gn',34,28,'crampon1923','Ils prirent leurs brebis, leurs bœufs et leurs ânes, ce qui était dans la ville et ce qui était dans les champs.'),
('gn',34,29,'crampon1923','Ils emmenèrent comme butin tous leurs biens, leurs enfants et leurs femmes, et tout ce qui se trouvait dans les maisons.'),
('gn',34,30,'crampon1923','Alors Jacob dit à Siméon et à Lévi: " Vous m''avez troublé, en me rendant odieux aux habitants du pays, aux Chananéens et aux Phérézéens. Je n''ai avec moi que peu de gens; ils s''assembleront contre moi et me tueront, et je serai détruit, moi et ma maison. "'),
('gn',34,31,'crampon1923','Ils répondirent: " Traitera-t-on notre sœur comme une prostituée? "'),
('gn',35,1,'crampon1923','Dieu dit à Jacob: " Lève-toi, monte à Béthel et demeures-y, et dresse là un autel au Dieu qui t''est apparu quand tu fuyais devant Esaü, ton frère. "'),
('gn',35,2,'crampon1923','Jacob dit à sa famille et à tous ceux qui étaient avec lui: " Otez les dieux étrangers qui sont au milieu de vous; purifiez-vous et changez de vêtements.'),
('gn',35,3,'crampon1923','Nous nous lèverons et nous monterons à Béthel, et là je dresserai un autel au Dieu qui m''a exaucé au jour de mon angoisse, et qui a été avec moi, dans le voyage que j''ai fait. "'),
('gn',35,4,'crampon1923','Et ils donnèrent à Jacob tous les dieux étrangers qui étaient entre leurs mains et les boucles qu''ils avaient aux oreilles, et Jacob les enfouit sous le térébinthe qui est à Sichem.'),
('gn',35,5,'crampon1923','Ils partirent, et la terreur de Dieu se répandit sur les villes d''alentour, et on ne poursuivit pas les fils de Jacob.'),
('gn',35,6,'crampon1923','Jacob, avec tous les gens qui étaient avec lui, arriva à Luz, au pays de Chanaan: c''est Béthel.'),
('gn',35,7,'crampon1923','Il y bâtit un autel, et il appela ce lieu El-Béthel, car c''est là que Dieu lui était apparu lorsqu''il fuyait devant son frère.'),
('gn',35,8,'crampon1923','Alors mourut Débora, nourrice de Rebecca, et elle fut enterrée au-dessous de Béthel, au pied du chêne auquel on donna le nom de Chêne des pleurs.'),
('gn',35,9,'crampon1923','Dieu apparut encore à Jacob, après son retour de Paddan-Aram, et il le bénit.'),
('gn',35,10,'crampon1923','Dieu lui dit: " Ton nom est Jacob; tu ne seras plus appelé Jacob, mais Israël sera ton nom. " Et il le nomma Israël.'),
('gn',35,11,'crampon1923','Dieu lui dit: " Je suis le Dieu tout-puissant. Sois fécond et multiplie; il naîtra de toi une nation et une assemblée de nations, et de tes reins sortiront des rois.'),
('gn',35,12,'crampon1923','Le pays que j''ai donné à Abraham et à Isaac, je te le donnerai, et je donnerai ce pays à ta postérité après toi. "'),
('gn',35,13,'crampon1923','Et Dieu remonta d''auprès de lui, dans le lieu où il lui avait parlé.'),
('gn',35,14,'crampon1923','Et dans le lieu où il lui avait parlé, Jacob dressa un monument de pierre, sur lequel il fit une libation et versa de l''huile.'),
('gn',35,15,'crampon1923','Il donna le nom de Béthel au lieu où Dieu lui avait parlé.'),
('gn',35,16,'crampon1923','Ils partirent de Béthel. Il y avait encore une certaine distance avant d''arriver à Ephrata, lorsque Rachel enfanta, et son accouchement fut pénible.'),
('gn',35,17,'crampon1923','Pendant les douleurs de l''enfantement, la sage-femme lui dit: " Ne crains point, car c''est encore un fils que tu vas avoir. "'),
('gn',35,18,'crampon1923','Comme son âme s''en allait, — car elle était mourante, — elle le nomma Bénoni; mais son père l''appela Benjamin.'),
('gn',35,19,'crampon1923','Rachel mourut, et elle fut enterrée au chemin d''Ephrata, qui est Bethléem.'),
('gn',35,20,'crampon1923','Jacob éleva un monument sur sa tombe; c''est le monument de la Tombe de Rachel, qui subsiste encore aujourd''hui.'),
('gn',35,21,'crampon1923','Israël partit, et il dressa sa tente au delà de Migdal-Eder.'),
('gn',35,22,'crampon1923','Pendant qu''Israël demeurait dans cette contrée, Ruben vint et coucha avec Bala, concubine de son père; et Israël l''apprit. Les fils de Jacob étaient au nombre de douze.'),
('gn',35,23,'crampon1923','Fils de Lia: Ruben, premier-né de Jacob, Siméon, Lévi, Juda, Issachar et Zabulon.'),
('gn',35,24,'crampon1923','Fils de Rachel: Joseph et Benjamin.'),
('gn',35,25,'crampon1923','Fils de Bala, servante de Rachel: Dan et Nephthali.'),
('gn',35,26,'crampon1923','Fils de Zelpha, servante de Lia: Gad et Aser. Ce sont là les fils de Jacob, qui lui naquirent à Paddan-Aram.'),
('gn',35,27,'crampon1923','Jacob arriva auprès d''Isaac, son père, à Mambré, à Qiryath-Arbé, qui est Hébron, où avaient séjourné Abraham et Isaac.'),
('gn',35,28,'crampon1923','Les jours d''Isaac furent de cent quatre-vingts ans.'),
('gn',35,29,'crampon1923','Isaac expira et mourut, et il fut réuni à son peuple, vieux et rassasié de jours. Esaü et Jacob, ses fils, l''enterrèrent.'),
('gn',36,1,'crampon1923','Voici l''histoire d''Esaü, qui est Edom.'),
('gn',36,2,'crampon1923','Esaü prit ses femmes parmi les filles de Chanaan: Ada, fille d''Elon, le Héthéen; Oolibama, fille d''Ana, fille de Sébéon, le Hévéen;'),
('gn',36,3,'crampon1923','et Basemath, fille d''Ismaël, sœur de Nabaïoth.'),
('gn',36,4,'crampon1923','Ada enfanta à Esaü Eliphaz, Basemath enfanta Rahuel,'),
('gn',36,5,'crampon1923','et Oolibama enfanta Jéhus, Ihélon et Coré. Ce sont là les fils d''Esaü, qui lui naquirent au pays de Chanaan.'),
('gn',36,6,'crampon1923','Esaü prit ses femmes, ses fils et ses filles, et toutes les personnes de sa maison, ses troupeaux, tout son bétail et tous les biens qu''il avait acquis dans le pays de Chanaan, et il s''en alla dans un autre pays, loin de Jacob, son frère.'),
('gn',36,7,'crampon1923','Car leurs biens étaient trop considérables pour qu''ils demeurassent ensemble, et le pays où ils séjournaient ne pouvait leur suffire à cause de leurs troupeaux.'),
('gn',36,8,'crampon1923','Esaü s''établit dans la montagne de Séir; Esaü est Edom.'),
('gn',36,9,'crampon1923','Voici la postérité d''Esaü, père d''Edom, dans la montagne de Séir.'),
('gn',36,10,'crampon1923','Voici les noms des fils d''Esaü: Eliphaz, fils d''Ada, femme d''Esaü; Rahuel, fils de Basemath, femme d''Esaü. —'),
('gn',36,11,'crampon1923','Les fils d''Eliphaz furent: Théman, Omar, Sépho, Gatham et Cénez.'),
('gn',36,12,'crampon1923','Thamna fut concubine d''Eliphaz, fils d''Esaü, et elle enfanta Amalech à Eliphaz. Ce sont là les fils d''Ada, femme d''Esaü. —'),
('gn',36,13,'crampon1923','Voici les fils de Rahuel: Nahath, Zara, Samma et Méza. Ce sont là les fils de Basemath, femme d''Esaü. —'),
('gn',36,14,'crampon1923','Voici les fils d''Oolibama, fille d''Ana, fille de Sébéon, femme d''Esaü: elle enfanta à Esaü Jéhus, Ihélon et Coré.'),
('gn',36,15,'crampon1923','Voici les chefs des tribus issues des fils d''Esaü. Fils d''Eliphaz, premier-né d''Esaü: le chef Théman, le chef Omar, le chef Sépho, le chef Cénez,'),
('gn',36,16,'crampon1923','le chef Coré, le chef Gatham, le chef Amalech. Ce sont là les chefs issus d''Eliphaz, au pays d''Edom; ce sont là les fils d''Ada. —'),
('gn',36,17,'crampon1923','Fils de Rahuel, fils d''Esaü: le chef Nahath, le chef Zara, le chef Samma et le chef Méza. Ce sont là les chefs issus de Rahuel, au pays d''Edom; ce sont là les fils de Basemath, femme d''Esaü. —'),
('gn',36,18,'crampon1923','Fils d''Oolibama, femme d''Esaü: le chef Jéhus, le chef Ihélon et le chef Coré. Ce sont là les chefs issus d''Oolibama, fille d''Ana et femme d''Esaü. —'),
('gn',36,19,'crampon1923','Ce sont là les fils d''Esaü, et ce sont là leurs chefs; c''est Edom.'),
('gn',36,20,'crampon1923','Voici les fils de Séir, le Horréen, qui habitaient le pays: Lotan, Sobal, Sébéon, Ana,'),
('gn',36,21,'crampon1923','Dison, Eser et Disan. Ce sont là les chefs des Horréens, fils de Séir, au pays d''Edom. —'),
('gn',36,22,'crampon1923','Les fils de Lotan furent Hori et Héman, et Thamma était sœur de Lotan. —'),
('gn',36,23,'crampon1923','Voici les fils de Sobal: Alvan, Manahat, Ebal, Sépho et Onam. —'),
('gn',36,24,'crampon1923','Voici les fils de Sébéon: Aja et Ana. C''est cet Ana qui trouva les sources chaudes dans le désert, en faisant paître les ânes de Sébéon, son père. —'),
('gn',36,25,'crampon1923','Voici les enfants d''Ana: Dison et Oolibama, fille d''Ana. —'),
('gn',36,26,'crampon1923','Voici les fils de Dison: Hamdan, Eséban, Jéthram et Charan. —'),
('gn',36,27,'crampon1923','Voici les fils d''Eser: Balan, Zavan et Acan. —'),
('gn',36,28,'crampon1923','Voici les fils de Disan: Hus et Aram.'),
('gn',36,29,'crampon1923','Voici les chefs des Horréens: le chef Lotan, le chef Sobal, le chef Sébéon, le chef Ana,'),
('gn',36,30,'crampon1923','le chef Dison, le chef Eser, le chef Disan. Ce sont là les chefs des Horréens, chacun de leurs chefs au pays de Séir.'),
('gn',36,31,'crampon1923','Voici les rois qui ont régné dans le pays d''Edom, avant qu''un roi régnât sur les enfants d''Israël:'),
('gn',36,32,'crampon1923','Béla, fils de Béor, régna en Edom, et le nom de sa ville était Denaba. —'),
('gn',36,33,'crampon1923','Béla mourut, et à sa place régna Jobab, fils de Zara, de Bosra. —'),
('gn',36,34,'crampon1923','Jobab mourut, et à sa place régna Husam, du pays des Thémanites. —'),
('gn',36,35,'crampon1923','Husam mourut, et à sa place régna Adad, fils de Badad, qui défit Madian dans les champs de Moab; le nom de sa ville était Avith. —'),
('gn',36,36,'crampon1923','Hadad mourut, et à sa place régna Semla, de Masréca. —'),
('gn',36,37,'crampon1923','Semla mourut, et à sa place régna Saül, de Rohoboth sur le fleuve. —'),
('gn',36,38,'crampon1923','Saül mourut, et à sa place régna Balanan, fils d''Achor. —'),
('gn',36,39,'crampon1923','Balanan, fils d''Achor, mourut, et à sa place régna Hadar; le nom de sa ville était Phaü, et le nom de sa femme Méétabel, fille de Matred, fille de Mézaab.'),
('gn',36,40,'crampon1923','Voici les noms des chefs issus d''Esaü, selon leurs tribus, leurs territoires et d''après leurs noms: le chef Thamma, le chef Alva, le chef Jétheth,'),
('gn',36,41,'crampon1923','le chef Oolibama, le chef Ela, le chef Phinon,'),
('gn',36,42,'crampon1923','le chef Cénez, le chef Théman, le chef Mabsar,'),
('gn',36,43,'crampon1923','le chef Magdiel, le chef Hiram. Ce sont là les chefs d''Edom, selon leurs demeures dans le pays qu''ils occupent. C''est là Esaü, père d''Edom.'),
('gn',37,1,'crampon1923','Jacob s''établit dans le pays où son père avait séjourné dans le pays de Chanaan.'),
('gn',37,2,'crampon1923','Voici l''histoire de Jacob. Joseph, âgé de dix-sept ans, faisait paître les brebis avec ses frères; comme il était encore jeune, il se trouvait avec les fils de Bala et avec les fils de Zelpha, femmes de son père; et Joseph rapporta à leur père de mauvais bruits qui couraient sur leur compte.'),
('gn',37,3,'crampon1923','Or Israël aimait Joseph plus que tous ses autres fils, parce que c''était un fils de sa vieillesse; et il lui fit une robe longue.'),
('gn',37,4,'crampon1923','Ses frères, voyant que leur père l''aimait plus qu''eux tous, le prirent en haine, et ils ne pouvaient plus lui parler amicalement.'),
('gn',37,5,'crampon1923','Joseph eut un songe, et il le raconta à ses frères, qui le haïrent encore davantage.'),
('gn',37,6,'crampon1923','Il leur dit: " Ecoutez, je vous prie, le songe que j''ai eu:'),
('gn',37,7,'crampon1923','Nous étions à lier des gerbes au milieu des champs; et voici, ma gerbe s''est levée et s''est tenue debout, et vos gerbes l''ont entourée et se sont prosternées devant elle. "'),
('gn',37,8,'crampon1923','Ses frères lui dirent: " Est-ce que tu régneras sur nous? est-ce que tu nous domineras? " Et ils le haïrent encore davantage pour ses songes et pour ses paroles.'),
('gn',37,9,'crampon1923','Il eut encore un autre songe, qu''il raconta à ses frères. Il dit: " J''ai eu encore un songe: le soleil, la lune et onze étoiles se prosternaient devant moi. "'),
('gn',37,10,'crampon1923','Il le raconta à son père et à ses frères, et son père le réprimanda, en disant: " Que signifie ce songe que tu as eu? Faudra-t-il que nous venions, moi, ta mère et tes frères, nous prosterner à terre devant toi? "'),
('gn',37,11,'crampon1923','Et ses frères furent jaloux de lui, mais son père conservait la chose dans son cœur.'),
('gn',37,12,'crampon1923','Les frères de Joseph allèrent paître les troupeaux de leur père à Sichem.'),
('gn',37,13,'crampon1923','Et Israël dit à Joseph: " Tes frères ne paissent-ils pas le troupeau à Sichem? Viens, que je t''envoie vers eux. " Il répondit: " Me voici. "'),
('gn',37,14,'crampon1923','Et Israël lui dit: " Va donc, et vois si tes frères vont bien et si le troupeau est en bon état, et tu m''en apporteras des nouvelles. " Et il l''envoya de la vallée d''Hébron, et Joseph alla à Sichem.'),
('gn',37,15,'crampon1923','Un homme, l''ayant rencontré errant dans la campagne, le questionna, en disant: " Que cherches-tu? "'),
('gn',37,16,'crampon1923','Il répondit: " Je cherche mes frères; indique-moi, je te prie, où ils font paître leur troupeau. "'),
('gn',37,17,'crampon1923','Et l''homme dit: " Ils sont partis d''ici; car je les ai entendus dire: Allons à Dothaïn. " Joseph alla après ses frères, et il les trouva à Dothaïn.'),
('gn',37,18,'crampon1923','Ils l''aperçurent de loin et, avant qu''il fût près d''eux, ils complotèrent de le faire mourir.'),
('gn',37,19,'crampon1923','Ils se dirent l''un à l''autre: " Voici l''homme aux songes; c''est bien lui qui arrive.'),
('gn',37,20,'crampon1923','Venez donc, tuons-le et jetons-le dans une des citernes, et nous dirons qu''une bête féroce l''a dévoré; nous verrons ce qui en sera de ses songes! "'),
('gn',37,21,'crampon1923','Ruben entendit et il le délivra de leurs mains. Il dit: " Ne le frappons pas à mort. "'),
('gn',37,22,'crampon1923','Ruben leur dit: " Ne versez pas le sang; jetez-le dans cette citerne qui est dans le désert, et ne portez pas la main sur lui. " — Son dessein était de le délivrer de leurs mains, pour le faire retourner vers son père. —'),
('gn',37,23,'crampon1923','Lorsque Joseph arriva auprès de ses frères, ils le dépouillèrent de sa robe, de la robe longue qu''il portait;'),
('gn',37,24,'crampon1923','et, l''ayant pris, ils le jetèrent dans la citerne. Cette citerne était vide: il n''y avait pas d''eau.'),
('gn',37,25,'crampon1923','Puis ils s''assirent pour manger. Levant les yeux, ils virent, et voici qu''une caravane d''Ismaélites venait de Galaad; leurs chameaux étaient chargés d''astragale, de baume et de ladanum, qu''ils transportaient en Egypte.'),
('gn',37,26,'crampon1923','Alors Juda dit à ses frères: " Que gagnerons-nous à tuer notre frère et à cacher son sang?'),
('gn',37,27,'crampon1923','Allons le vendre aux Ismaélites et ne portons pas la main sur lui; car il est notre frère, notre chair. " Ses frères l''écoutèrent'),
('gn',37,28,'crampon1923','et, quand les marchands madianites passèrent, ils tirèrent Joseph et le firent remonter de la citerne; et ils le vendirent pour vingt pièces d''argent aux Ismaélites, qui l''emmenèrent en Egypte.'),
('gn',37,29,'crampon1923','Ruben revint à la citerne, et voici que Joseph n''était plus dans la citerne.'),
('gn',37,30,'crampon1923','Il déchira ses vêtements et, étant retourné vers ses frères, il dit: " L''enfant n''y est plus, et moi, où irai-je? "'),
('gn',37,31,'crampon1923','Ils prirent alors la robe de Joseph et, ayant tué un bouc, ils plongèrent la robe dans le sang.'),
('gn',37,32,'crampon1923','Et ils envoyèrent à leur père la longue robe, en lui faisant dire: " Voilà ce que nous avons trouvé; reconnais si c''est la robe de ton fils, ou non. "'),
('gn',37,33,'crampon1923','Jacob la reconnut et dit: " C''est la robe de mon fils! Une bête féroce l''a dévoré! Joseph a été mis en pièces! "'),
('gn',37,34,'crampon1923','Et il déchira ses vêtements, mit un sac sur ses reins et fit le deuil de son fils pendant longtemps.'),
('gn',37,35,'crampon1923','Tous ses fils et toutes ses filles vinrent pour le consoler; mais il refusa d''être consolé; il disait: " Je descendrai dans le deuil vers mon fils au séjour des morts. " Et son père le pleura.'),
('gn',37,36,'crampon1923','Les Madianites le vendirent en Egypte à Putiphar, officier de Pharaon, chef des gardes.'),
('gn',38,1,'crampon1923','En ce temps-là Juda, s''éloignant de ses frères, descendit et arriva jusqu''auprès d''un homme d''Odollam, nommé Hira.'),
('gn',38,2,'crampon1923','Là, Juda vit la fille d''un Chananéen, nommé Sué, et il la prit pour femme et alla vers elle.'),
('gn',38,3,'crampon1923','Elle conçut et enfanta un fils, et il le nomma Her.'),
('gn',38,4,'crampon1923','Elle conçut encore et enfanta un fils, et elle le nomma Onan.'),
('gn',38,5,'crampon1923','Elle conçut de nouveau et enfanta un fils, et elle le nomma Séla; Juda était à Achzib quand elle le mit au monde.'),
('gn',38,6,'crampon1923','Juda prit pour Her, son premier-né, une femme nommée Thamar.'),
('gn',38,7,'crampon1923','Her, premier-né de Juda, fut méchant aux yeux de Yahweh et Yahweh le fit mourir.'),
('gn',38,8,'crampon1923','Alors Juda dit à Onan: " Va vers la femme de ton frère, remplis ton devoir de beau-frère et suscite une postérité à ton frère. "'),
('gn',38,9,'crampon1923','Mais Onan savait que cette postérité ne serait pas à lui et, lorsqu''il allait vers la femme de son frère, il se souillait à terre afin de ne pas donner de postérité à son frère.'),
('gn',38,10,'crampon1923','Son action déplut au Seigneur, qui le fit aussi mourir.'),
('gn',38,11,'crampon1923','Et Juda dit à Thamar, sa belle-fille: " Demeure comme veuve dans la maison de ton père jusqu''à ce que Séla, mon fils, soit devenu grand. " Car il se disait: " Il ne faut pas que lui aussi meure comme ses frères. " Thamar s''en alla et demeura dans la maison de son père.'),
('gn',38,12,'crampon1923','Après beaucoup de jours, la fille de Sué, femme de Juda, mourut. Lorsque Juda eut fini son deuil, il monta vers ceux qui tondaient ses brebis à Thamna, lui et son ami Hira, l''Odollamite.'),
('gn',38,13,'crampon1923','On en informa Thamar, en disant: " Voici ton beau-père qui monte à Thamna pour tondre ses brebis. "'),
('gn',38,14,'crampon1923','Alors elle ôta ses vêtements de veuve, se couvrit d''un voile, et, ainsi enveloppée, elle s''assit à l''entrée d''Enaïm, sur le chemin de Thamna, car elle voyait que Séla était devenu grand et qu''elle ne lui était pas donnée pour femme.'),
('gn',38,15,'crampon1923','Juda, l''ayant vue, la prit pour une femme de mauvaise vie; car elle avait couvert son visage.'),
('gn',38,16,'crampon1923','Il se dirigea de son côté, vers le chemin, et dit: " Laisse-moi aller vers toi. " Car il ignorait que ce fût sa belle-fille. Elle dit: " Que me donneras-tu pour venir vers moi? "'),
('gn',38,17,'crampon1923','Il répondit: " Je t''enverrai un chevreau du troupeau. " Elle dit: " A condition que tu me donnes un gage jusqu''à ce que tu l''envoies. "'),
('gn',38,18,'crampon1923','Il dit: Quel gage dois-je te donner? " Elle dit: " Ton anneau, ton cordon et ton bâton que tu tiens à la main. " Il les lui donna et alla vers elle, et elle devint enceinte de lui.'),
('gn',38,19,'crampon1923','Puis, s''étant levée, elle s''en alla; et elle ôta son voile et revêtit ses vêtements de veuve.'),
('gn',38,20,'crampon1923','Juda envoya le chevreau par son ami, l''Odollamite, pour retirer le gage des mains de cette femme; mais il ne la trouva point.'),
('gn',38,21,'crampon1923','Il interrogea les gens du lieu, en disant: " Où est cette prostituée qui se tenait à Enaïm au bord du chemin? " Ils répondirent: " Il n''y a point eu ici de prostituée. "'),
('gn',38,22,'crampon1923','Il revint donc vers Juda et dit: " Je ne l''ai point trouvée; et même les gens du lieu ont dit: il n''y a point eu ici de prostituée. "'),
('gn',38,23,'crampon1923','Juda dit: " Qu''elle garde son gage; il ne faut pas qu''on se moque de nous. Voici, j''ai envoyé le chevreau promis, et tu ne l''as pas trouvée. "'),
('gn',38,24,'crampon1923','Environ trois mois après, on vint dire à Juda: " Thamar, ta belle-fille, s''est prostituée, et même la voilà enceinte à la suite de ses prostitutions. " Juda dit: " Faites-la sortir et qu''elle soit brûlée. "'),
('gn',38,25,'crampon1923','Comme on l''emmenait dehors, elle envoya dire à son beau-père: " C''est de l''homme à qui ces objets appartiennent que je suis enceinte. Regarde bien, ajouta-t-elle, à qui sont cet anneau, ce cordon et ce bâton. "'),
('gn',38,26,'crampon1923','Juda les reconnut et dit: " Elle est plus juste que moi, puisque je ne l''ai pas donnée à Séla, mon fils. " Et il ne la connut plus.'),
('gn',38,27,'crampon1923','Quand elle fut au moment d''enfanter, voici, il y avait deux jumeaux dans son sein.'),
('gn',38,28,'crampon1923','Pendant l''accouchement, l''un d''eux étendit la main; la sage-femme la prit et y attacha un fil écarlate, en disant: " C''est celui-ci qui est sorti le premier. "'),
('gn',38,29,'crampon1923','Mais il retira sa main, et voici que son frère sortit. " Quelle brèche tu as faite! dit la sage-femme; la brèche soit sur toi! " Et on le nomma Pharès.'),
('gn',38,30,'crampon1923','Ensuite sortit son frère, qui avait à la main le fil écarlate; et on le nomma Zara.'),
('gn',39,1,'crampon1923','Joseph fut emmené en Egypte, et Putiphar, officier de Pharaon, chef des gardes, Egyptien, l''acheta des Ismaélites qui l''y avaient amené.'),
('gn',39,2,'crampon1923','Yahweh fut avec Joseph, qui faisait prospérer toutes choses; il habitait dans la maison de son maître, l''Egyptien.'),
('gn',39,3,'crampon1923','Son maître vit que Yahweh était avec lui et que Yahweh faisait réussir entre ses mains tout ce qu''il faisait.'),
('gn',39,4,'crampon1923','Joseph trouva donc grâce à ses yeux et il fut employé à son service; son maître l''établit sur sa maison et remit en ses mains tout ce qu''il avait.'),
('gn',39,5,'crampon1923','Dès qu''il l''eut établi sur sa maison et sur tout ce qu''il avait, Yahweh bénit la maison de l''Egyptien à cause de Joseph, et la bénédiction de Yahweh fut sur tout ce qu''il avait, soit à la maison, soit aux champs.'),
('gn',39,6,'crampon1923','Et il abandonna tout ce qu''il avait aux mains de Joseph, ne s''informant plus de rien avec lui, si ce n''est des aliments qu''il prenait. Or Joseph était beau de corps et beau de figure.'),
('gn',39,7,'crampon1923','Il arriva, après ces choses, que la femme de son maître jeta les yeux sur Joseph et lui dit: " Couche avec moi. "'),
('gn',39,8,'crampon1923','Il refusa et dit à la femme de son maître: " Voici, mon maître ne s''informe avec moi de rien dans la maison et il a remis tout ce qu''il a entre mes mains.'),
('gn',39,9,'crampon1923','Il n''est pas plus grand que moi dans cette maison, et il ne m''a rien interdit que toi, parce que tu es sa femme. Comment ferais-je un si grand mal et pécherais-je contre Dieu? "'),
('gn',39,10,'crampon1923','Quoiqu''elle en parlât tous les jours à Joseph, il ne consentit pas à coucher auprès d''elle ni à être avec elle.'),
('gn',39,11,'crampon1923','Un jour qu''il était entré dans la maison pour faire son service, sans qu''il y eût là aucun des gens de la maison,'),
('gn',39,12,'crampon1923','elle le saisit par son vêtement, en disant: " Couche avec moi. " Mais il lui laissa son vêtement dans la main, et il s''enfuit au dehors.'),
('gn',39,13,'crampon1923','Quand elle vit qu''il lui avait laissé son vêtement dans la main et qu''il s''était enfui dehors,'),
('gn',39,14,'crampon1923','elle appela les gens de sa maison et leur parla en disant: " Voyez, il nous a amené un Hébreu pour folâtrer avec nous. Cet homme est venu vers moi pour coucher avec moi, et j''ai appelé à grands cris.'),
('gn',39,15,'crampon1923','Et quand il a entendu que j''élevais la voix et que je criais, il a laissé son vêtement à côté de moi et s''est enfui au dehors. "'),
('gn',39,16,'crampon1923','Puis elle posa près d''elle le vêtement de Joseph jusqu''à ce que son maître rentrât à la maison.'),
('gn',39,17,'crampon1923','Et elle lui parla selon ces paroles-là, en disant: " Le serviteur hébreu que tu nous as amené est venu vers moi pour folâtrer avec moi.'),
('gn',39,18,'crampon1923','Et comme j''ai élevé la voix et jeté des cris, il a laissé son vêtement à côté de moi et s''est enfui dehors. "'),
('gn',39,19,'crampon1923','Quand le maître de Joseph eut entendu les paroles de sa femme, qui lui parlait en ces termes: " Voilà ce que m''a fait ton serviteur ", sa colère s''enflamma.'),
('gn',39,20,'crampon1923','Il prit Joseph et le mit dans la prison; c''était le lieu où étaient détenus les prisonniers du roi. Et il fut là en prison.'),
('gn',39,21,'crampon1923','Yahweh fut avec Joseph; il étendit sur lui sa bonté, et le mit en faveur aux yeux du chef de la prison.'),
('gn',39,22,'crampon1923','Et le chef de la prison plaça sous sa surveillance tous les prisonniers qui étaient dans la prison, et tout ce qui s''y faisait se faisait par lui.'),
('gn',39,23,'crampon1923','Le chef de la prison ne regardait à rien de tout ce que Joseph avait en mains, parce que Yahweh était avec lui; et Yahweh faisait réussir tout ce qu''il faisait,'),
('gn',40,1,'crampon1923','Après ces choses, il arriva que l''échanson et le panetier du roi d''Egypte offensèrent leur maître, le roi d''Egypte.'),
('gn',40,2,'crampon1923','Pharaon fut irrité contre ses deux officiers, contre le chef des échansons et le chef des panetiers;'),
('gn',40,3,'crampon1923','et il les fit enfermer chez le chef des gardes, dans la prison, dans le lieu où Joseph était enfermé.'),
('gn',40,4,'crampon1923','Le chef des gardes établit Joseph auprès d''eux, et il les servait; et ils furent un certain temps en prison.'),
('gn',40,5,'crampon1923','L''échanson et le panetier du roi d''Egypte, qui étaient enfermés dans la prison, eurent tous deux un songe dans la même nuit, chacun le sien, ayant une signification différente.'),
('gn',40,6,'crampon1923','Joseph, étant venu le matin vers eux, les regarda; et voici, ils étaient tristes.'),
('gn',40,7,'crampon1923','Il interrogea donc les officiers de Pharaon qui étaient avec lui en prison, dans la maison de son maître, et leur dit: " Pourquoi avez-vous le visage triste aujourd''hui? "'),
('gn',40,8,'crampon1923','Ils lui dirent: " Nous avons eu un songe, et il n''y a personne ici pour l''expliquer. " Et Joseph leur dit: " N''est-ce pas à Dieu qu''appartiennent les interprétations? Racontez-moi, je vous prie, votre songe. "'),
('gn',40,9,'crampon1923','Le chef des échansons raconta son songe à Joseph, en disant: " Dans mon songe, voici, il y avait un cep devant moi,'),
('gn',40,10,'crampon1923','et ce cep avait trois branches; il poussa des bourgeons, la fleur sortit et ses grappes donnèrent des raisins mûrs.'),
('gn',40,11,'crampon1923','La coupe de Pharaon était dans ma main; je pris des raisins, j''en pressai le jus dans la coupe de Pharaon et je mis la coupe dans la main de Pharaon. "'),
('gn',40,12,'crampon1923','Joseph lui dit: " En voici l''interprétation: les trois branches sont trois jours.'),
('gn',40,13,'crampon1923','Encore trois jours, et Pharaon relèvera ta tête et te rétablira dans ta charge, et tu mettras la coupe de Pharaon dans sa main, selon ton premier office, lorsque tu étais son échanson.'),
('gn',40,14,'crampon1923','Si tu te souviens de moi quand le bonheur te sera rendu, et si tu daignes user de bonté à mon égard, rappelle-moi au souvenir de Pharaon, et fais-moi sortir de cette maison.'),
('gn',40,15,'crampon1923','Car c''est par un rapt que j''ai été enlevé du pays des Hébreux, et ici même je n''ai rien fait pour qu''on m''ait mis dans cette prison. "'),
('gn',40,16,'crampon1923','Le chef des panetiers, voyant que Joseph avait donné une interprétation favorable, lui dit: " Moi aussi, dans mon songe, voici que j''avais sur la tête trois corbeilles de pain blanc.'),
('gn',40,17,'crampon1923','Dans la corbeille de dessus se trouvaient toutes sortes de pâtisseries pour Pharaon, et les oiseaux les mangeaient dans la corbeille qui était sur ma tête. "'),
('gn',40,18,'crampon1923','Joseph répondit: " En voici l''interprétation: les trois corbeilles sont trois jours.'),
('gn',40,19,'crampon1923','Encore trois jours, et Pharaon enlèvera ta tête de dessus toi et te pendra à un bois, et les oiseaux dévoreront ta chair de dessus toi. "'),
('gn',40,20,'crampon1923','Le troisième jour, qui était le jour de la naissance de Pharaon, il donna un festin à tous ses serviteurs; et il éleva la tête du chef des échansons et la tête du chef des panetiers:'),
('gn',40,21,'crampon1923','il rétablit le chef des échansons dans son office d''échanson, et celui-ci mit la coupe dans la main de Pharaon;'),
('gn',40,22,'crampon1923','et il fit pendre le chef des panetiers, selon l''interprétation que Joseph leur avait donnée.'),
('gn',40,23,'crampon1923','Mais le chef des échansons ne parla pas de Joseph, et l''oublia.'),
('gn',41,1,'crampon1923','Deux ans s''étant écoulés, Pharaon eut un songe. Voici, il se tenait près du fleuve,'),
('gn',41,2,'crampon1923','et voici que du fleuve montaient sept vaches belles à voir et grasses de chair, et elles se mirent à paître dans la verdure.'),
('gn',41,3,'crampon1923','Et voici qu''après elles montaient du fleuve sept autres vaches, laides à voir et maigres de chair, et elles vinrent se mettre à côté des vaches qui étaient sur le bord du fleuve.'),
('gn',41,4,'crampon1923','Et les vaches laides à voir et maigres de chair dévorèrent les sept vaches belles à voir et grasses. Alors Pharaon s''éveilla.'),
('gn',41,5,'crampon1923','Il se rendormit, et il eut un second songe. Et voici, sept épis s''élevaient d''une même tige, gras et beaux.'),
('gn',41,6,'crampon1923','Et sept épis maigres et brûlés par le vent d''orient poussaient après ceux-là.'),
('gn',41,7,'crampon1923','Et les épis maigres engloutirent les sept épis gras et pleins. Alors Pharaon s''éveilla. Et voilà, c''était un songe.'),
('gn',41,8,'crampon1923','Le matin, Pharaon eut l''esprit agité, et il fit appeler tous les scribes et tous les sages d''Egypte. Il leur raconta ses songes, mais personne ne put les expliquer à Pharaon.'),
('gn',41,9,'crampon1923','Alors le chef des échansons, prenant la parole, dit à Pharaon: " Je vais rappeler aujourd''hui mes fautes.'),
('gn',41,10,'crampon1923','Pharaon était irrité contre ses serviteurs, et il m''avait mis en prison dans la maison du chef des gardes, moi et le chef des panetiers.'),
('gn',41,11,'crampon1923','Nous eûmes un songe dans la même nuit, moi et lui, nous révâmes chacun selon la signification de son songe.'),
('gn',41,12,'crampon1923','Il y avait là avec nous un jeune Hébreu, serviteur du chef des gardes. Nous lui racontâmes nos songes, et il nous en donna l''interprétation; à chacun il interpréta son songe,'),
('gn',41,13,'crampon1923','et les choses se passèrent comme il avait interprété: moi, Pharaon me rétablit dans mon poste, et lui, on le pendit. "'),
('gn',41,14,'crampon1923','Pharaon envoya appeler Joseph, et on le fit sortir en hâte de la prison. Il se rasa, mit d''autres vêtements et se rendit vers Pharaon.'),
('gn',41,15,'crampon1923','Et Pharaon dit à Joseph: " J''ai eu un songe que personne ne peut interpréter; et j''ai entendu dire de toi que, quand tu entends un songe, tu l''interprètes. "'),
('gn',41,16,'crampon1923','Joseph répondit à Pharaon en disant: " Ce n''est pas moi, c''est Dieu qui donnera une réponse favorable à Pharaon. "'),
('gn',41,17,'crampon1923','Pharaon dit alors à Joseph: " Dans mon songe, voici, je me tenais sur le bord du fleuve,'),
('gn',41,18,'crampon1923','et voici que du fleuve montaient sept vaches grasses de chair et de belle apparence, et elles se mirent à paître dans la verdure.'),
('gn',41,19,'crampon1923','Et voici qu''après elles montaient sept autres vaches, maigres, fort laides d''aspect et décharnées; je n''en ai point vu de pareilles en laideur dans tout le pays d''Egypte.'),
('gn',41,20,'crampon1923','Les vaches maigres et laides dévorèrent les sept premières vaches, celles qui étaient grasses;'),
('gn',41,21,'crampon1923','celles-ci entrèrent dans leur ventre, sans qu''il parût qu''elles y fussent entrées; leur aspect était aussi laid qu''auparavant. Et je m''éveillai.'),
('gn',41,22,'crampon1923','Je vis encore en songe, et voici sept épis qui s''élevaient sur une même tige, pleins et beaux;'),
('gn',41,23,'crampon1923','et voici, sept épis chétifs, maigres et brûlés par le vent d''orient, qui poussaient après ceux-là.'),
('gn',41,24,'crampon1923','Et les épis maigres engloutirent les sept beaux épis. J''ai raconté cela aux scribes, et aucun d''eux ne me l''explique. "'),
('gn',41,25,'crampon1923','Joseph dit à Pharaon: " Le songe de Pharaon est un; Dieu a fait connaître à Pharaon ce qu''il va faire.'),
('gn',41,26,'crampon1923','Les sept belles vaches sont sept années, et les sept beaux épis sont sept années, c''est un seul songe.'),
('gn',41,27,'crampon1923','Les sept vaches chétives et laides qui montaient après elles sont sept années, et les sept épis vides, brûlés par le vent d''orient, seront sept années de famine.'),
('gn',41,28,'crampon1923','Telle est la parole que j''ai dite à Pharaon: Dieu a fait voir à Pharaon ce qu''il va faire.'),
('gn',41,29,'crampon1923','Voici, sept années de grande abondance vont venir dans tout le pays d''Egypte.'),
('gn',41,30,'crampon1923','Sept années de famine viendront ensuite, et l''on oubliera toute cette abondance dans le pays d''Egypte, et la famine consumera le pays.'),
('gn',41,31,'crampon1923','On ne s''apercevra plus de l''abondance à cause de cette famine qui suivra dans le pays; tant elle sera grande.'),
('gn',41,32,'crampon1923','Et si le songe a été répété à Pharaon deux fois, c''est que la chose est décidée de la part de Dieu, et que Dieu se hâtera de l''exécuter.'),
('gn',41,33,'crampon1923','Maintenant, que Pharaon trouve un homme intelligent et sage, et qu''il l''établisse sur le pays d''Egypte.'),
('gn',41,34,'crampon1923','Que Pharaon établisse en outre des intendants sur le pays, pour lever un cinquième des récoltes du pays d''Egypte pendant les sept années d''abondance.'),
('gn',41,35,'crampon1923','Qu''ils rassemblent tout le produit de ces bonnes années qui viennent; qu''ils fassent des amas de blé à la disposition de Pharaon, comme provisions dans les villes, et qu''ils les conservent.'),
('gn',41,36,'crampon1923','Ces provisions seront pour le pays une réserve pour les sept années de famine qui arriveront au pays d''Egypte, et le pays ne sera pas consumé par la famine. "'),
('gn',41,37,'crampon1923','Ces paroles plurent à Pharaon et à tous ses serviteurs.'),
('gn',41,38,'crampon1923','Et Pharaon dit à ses serviteurs: " Pourrions-nous trouver un homme pareil à celui-ci, ayant en lui l''esprit de Dieu? "'),
('gn',41,39,'crampon1923','Et Pharaon dit à Joseph: " Puisque Dieu t''a fait connaître toutes ces choses, il n''y a personne qui soit aussi intelligent et sage que toi.'),
('gn',41,40,'crampon1923','C''est toi qui gouverneras ma maison, et tout mon peuple obéira à ta bouche; par le trône seulement je serai plus grand que toi. "'),
('gn',41,41,'crampon1923','Et Pharaon dit à Joseph: " Voici que je t''établis sur tout le pays d''Egypte. "'),
('gn',41,42,'crampon1923','Et Pharaon ôta son anneau de sa main et le mit à la main de Joseph, et il le fit revêtir d''habits de fin lin et lui mit au cou un collier d''or.'),
('gn',41,43,'crampon1923','Il le fit monter sur le second de ses chars, et on criait devant lui: " A genoux! " C''est ainsi qu''il fut établi sur tout le pays d''Egypte.'),
('gn',41,44,'crampon1923','Et Pharaon dit à Joseph: " Je suis Pharaon, et sans toi nul ne lèvera la main ni le pied dans tout le pays d''Egypte. "'),
('gn',41,45,'crampon1923','Pharaon nomma Joseph Tsaphnath-Panéach, et il lui donna pour femme Aseneth, fille de Putiphar, prêtre d''On. Et Joseph partit pour visiter le pays d''Egypte.'),
('gn',41,46,'crampon1923','Joseph était âgé de trente ans lorsqu''il se présenta devant Pharaon, roi d''Egypte; et il quitta Pharaon pour parcourir tout le pays d''Egypte.'),
('gn',41,47,'crampon1923','La terre rapporta à pleines mains pendant les sept années d''abondance.'),
('gn',41,48,'crampon1923','Joseph rassembla tous les produits des sept bonnes années qu''il y eut au pays d''Egypte, et il fit des approvisionnements dans les villes, déposant dans l''intérieur de chaque ville les productions des champs d''alentour.'),
('gn',41,49,'crampon1923','Joseph amassa du blé comme le sable de la mer, en si grande quantité, qu''on cessa de compter, parce qu''il était sans nombre.'),
('gn',41,50,'crampon1923','Avant qu''arrivât l''année de famine, il naquit à Joseph deux fils, que lui enfanta Aseneth, fille de Putiphar, prêtre d''On.'),
('gn',41,51,'crampon1923','Joseph donna au premier-né le nom de Manassé, " car, dit-il, Dieu m''a fait oublier toute ma peine et toute la maison de mon père. "'),
('gn',41,52,'crampon1923','Il donna au second le nom d''Ephraïm, " car, dit-il, Dieu m''a fait fructifier dans le pays de mon affliction. "'),
('gn',41,53,'crampon1923','Les sept années d''abondance qu''il y eut en Egypte étant achevées,'),
('gn',41,54,'crampon1923','les sept années de famine commencèrent à venir, comme Joseph l''avait annoncé. Il y eut famine dans tous les pays, tandis qu''il y avait du pain dans tout le pays d''Egypte.'),
('gn',41,55,'crampon1923','Puis tout le pays d''Egypte fut aussi affamé, et le peuple cria à Pharaon pour avoir du pain. Et Pharaon dit à tous les Egyptiens: " Allez vers Joseph, faites ce qu''il vous dira. "'),
('gn',41,56,'crampon1923','La famine étant sur toute la face du pays, Joseph ouvrit tous les greniers qu''on y avait établis et vendit du blé aux Egyptiens; et la famine s''accrut dans le pays d''Egypte.'),
('gn',41,57,'crampon1923','De toute la terre on venait en Egypte pour acheter du blé auprès de Joseph; car la famine s''était aggravée sur toute la terre.'),
('gn',42,1,'crampon1923','Jacob, voyant qu''il y avait du blé en Egypte, dit à ses fils: " Pourquoi vous regardez-vous les uns les autres?'),
('gn',42,2,'crampon1923','Il dit: Voici, j''ai appris, qu''il y a du blé en Egypte; descendez-y pour nous en acheter là, afin que nous vivions et que nous ne mourions point. "'),
('gn',42,3,'crampon1923','Les frères de Joseph descendirent au nombre de dix pour acheter du blé en Egypte.'),
('gn',42,4,'crampon1923','Mais pour Benjamin, frère de Joseph, Jacob ne l''envoya pas avec ses frères, car il s''était dit: " Il est à craindre qu''il ne lui arrive malheur. "'),
('gn',42,5,'crampon1923','Les fils d''Israël vinrent donc pour acheter du blé, avec d''autres qui venaient aussi, car la famine était au pays de Chanaan.'),
('gn',42,6,'crampon1923','Joseph était le chef du pays, et c''est lui qui vendait le blé à tous les gens du pays. Les frères de Joseph, étant arrivés, se prosternèrent devant lui, la face contre terre.'),
('gn',42,7,'crampon1923','En voyant ses frères, Joseph les reconnut, mais il feignit d''être un étranger pour eux, et leur parla avec rudesse, en disant: " D''où venez-vous? " Ils répondirent: " Du pays de Chanaan, pour acheter des vivres. "'),
('gn',42,8,'crampon1923','Joseph reconnut donc ses frères, mais eux ne le reconnurent pas.'),
('gn',42,9,'crampon1923','Joseph se souvint alors des songes qu''il avait eus à leur sujet, et il leur dit: " Vous êtes des espions; c''est pour reconnaître les points faibles du pays que vous êtes venus. "'),
('gn',42,10,'crampon1923','Ils lui répondirent: " Non, mon seigneur; tes serviteurs sont venus pour acheter des vivres.'),
('gn',42,11,'crampon1923','Tous nous sommes fils d''un même homme; nous sommes d''honnêtes gens; tes serviteurs ne sont pas des espions. "'),
('gn',42,12,'crampon1923','Il leur dit: " Point du tout; vous êtes venus reconnaître les endroits faibles du pays. "'),
('gn',42,13,'crampon1923','Ils répondirent: " Nous, tes serviteurs, nous sommes douze frères, fils d''un même homme, au pays de Chanaan. Et voici, le plus jeune est maintenant avec notre père, et il y en a un qui n''est plus. "'),
('gn',42,14,'crampon1923','Joseph leur dit: " Il en est comme je viens de vous le dire vous êtes des espions.'),
('gn',42,15,'crampon1923','En ceci vous serez éprouvés: par la vie de Pharaon! vous ne sortirez point d''ici que votre jeune frère ne soit venu.'),
('gn',42,16,'crampon1923','Envoyez l''un de vous chercher votre frère, et vous, restez prisonniers. Vos paroles seront ainsi mises à l''épreuve, et l''on verra si la vérité est avec vous; sinon, par la vie de Pharaon! vous êtes des espions. "'),
('gn',42,17,'crampon1923','Et il les fit mettre ensemble en prison pendant trois jours.'),
('gn',42,18,'crampon1923','Le troisième jour, Joseph leur dit: " Faites ceci et vous vivrez: je crains Dieu!'),
('gn',42,19,'crampon1923','Si vous êtes d''honnêtes gens, que l''un de vous, votre frère, reste lié dans votre prison; et vous, allez, emportez du blé pour calmer la faim de vos familles.'),
('gn',42,20,'crampon1923','Et amenez-moi votre plus jeune frère; et vos paroles seront reconnues vraies, et vous ne mourrez point. " Et ils firent ainsi.'),
('gn',42,21,'crampon1923','Alors ils se dirent l''un à l''autre: " Vraiment nous sommes punis à cause de notre frère; car nous avons vu l''angoisse de son âme, quand il nous demandait grâce, et nous ne l''avons pas écouté! Voilà pourquoi cette détresse est venue vers nous. "'),
('gn',42,22,'crampon1923','Ruben, prenant la parole, leur dit: " Ne vous disais-je pas: Ne commettez pas de péché contre l''enfant? Et vous n''avez pas écouté; et voici, son sang est redemandé. "'),
('gn',42,23,'crampon1923','Ils ne savaient pas que Joseph comprenait, car ils lui parlaient par l''interprète.'),
('gn',42,24,'crampon1923','Et il s''éloigna d''eux et il pleura. Etant ensuite revenu vers eux, il leur parla; et il prit parmi eux Siméon et le fit lier sous leurs yeux.'),
('gn',42,25,'crampon1923','Puis Joseph commanda qu''on remplît de blé leurs vaisseaux, qu''on remit l''argent de chacun dans son sac et qu''on leur donnât des provisions pour la route. Et il leur fut fait ainsi.'),
('gn',42,26,'crampon1923','Ayant chargé le blé sur leurs ânes, ils partirent.'),
('gn',42,27,'crampon1923','A l''endroit où ils passèrent la nuit, l''un d''eux ouvrit son sac pour donner du fourrage à son âne, et il vit son argent, qui était à l''entrée du sac.'),
('gn',42,28,'crampon1923','Il dit à ses frères: " On a remis mon argent; le voici dans mon sac! " Et le cœur leur manqua, et ils se dirent en tremblant l''un à l''autre: " Qu''est-ce que Dieu nous a fait? "'),
('gn',42,29,'crampon1923','Ils revinrent auprès de Jacob, leur père, au pays de Chanaan, et ils lui racontèrent tout ce qui leur était arrivé, en disant:'),
('gn',42,30,'crampon1923','" L''homme qui est le maître du pays nous a parlé durement et nous a pris pour des gens espionnant le pays.'),
('gn',42,31,'crampon1923','Nous lui avons dit: Nous sommes d''honnêtes gens, nous ne sommes pas des espions.'),
('gn',42,32,'crampon1923','Nous sommes douze frères, fils d''un même père; l''un n''est plus, et le plus jeune est maintenant avec notre père, au pays de Chanaan.'),
('gn',42,33,'crampon1923','Et l''homme qui est le maître du pays nous a dit: En ceci je saurai que vous êtes d''honnêtes gens: laissez auprès de moi l''un de vous, votre frère; prenez de quoi calmer la faim de vos familles et partez;'),
('gn',42,34,'crampon1923','et amenez-moi votre plus jeune frère. Je saurai ainsi que vous n''êtes pas des espions, mais que vous êtes d''honnêtes gens. Je vous rendrai alors votre frère et vous pourrez trafiquer dans le pays. "'),
('gn',42,35,'crampon1923','Comme ils vidaient leurs sacs, le paquet d''argent de chacun était dans son sac. Ils virent, eux et leur père, leurs paquets d''argent, et ils furent effrayés.'),
('gn',42,36,'crampon1923','Jacob, leur père, leur dit: " Vous me faites sans enfants! Joseph n''est plus, Siméon n''est plus, et vous allez prendre Benjamin! C''est sur moi que tout cela retombe. "'),
('gn',42,37,'crampon1923','Ruben dit à son père: " Tu feras mourir mes deux fils, si je ne te ramène pas Benjamin; remets-le entre mes mains, et moi, je te le ramènerai. "'),
('gn',42,38,'crampon1923','Il dit: " Mon fils ne descendra point avec vous, car son frère est mort, et lui reste seul. S''il lui arrivait malheur dans le voyage que vous allez faire, vous feriez descendre mes cheveux blancs avec douleur dans le séjour des morts. "'),
('gn',43,1,'crampon1923','La famine s''appesantissait sur le pays.'),
('gn',43,2,'crampon1923','Quand ils eurent fini de manger le blé qu''ils avaient apporté d''Egypte, leur père leur dit: " Retournez nous acheter un peu de vivres. "'),
('gn',43,3,'crampon1923','Juda lui répondit: " Cet homme nous a fait cette déclaration formelle: Vous ne verrez point ma face que votre frère ne soit avec vous.'),
('gn',43,4,'crampon1923','Si donc tu laisses venir notre frère avec nous, nous descendrons et nous t''achèterons des vivres.'),
('gn',43,5,'crampon1923','Mais si tu ne le laisses pas venir, nous ne descendrons point; car cet homme nous a dit: Vous ne verrez pas ma face que votre frère ne soit avec vous. "'),
('gn',43,6,'crampon1923','Et Israël dit: " Pourquoi m''avez-vous causé cette peine, de dire à cet homme que vous aviez encore un frère? "'),
('gn',43,7,'crampon1923','Ils dirent: " Cet homme nous a adressé beaucoup de questions sur nous et sur notre famille, en disant: Votre père vit-il encore? Avez-vous un autre frère? Et nous avons répondu selon ces questions. Pouvions-nous savoir qu''il dirait: Faites descendre votre frère? "'),
('gn',43,8,'crampon1923','Et Juda dit à Israël, son père: " Laisse partir l''enfant avec moi, afin que nous nous levions et nous mettions en route, et nous vivrons et ne mourrons point, nous, toi et nos petits enfants.'),
('gn',43,9,'crampon1923','C''est moi qui réponds de lui, tu le redemanderas de ma main. Si je ne le ramène pas auprès de toi, si je ne le mets pas devant toi, je serai coupable envers toi à tout jamais.'),
('gn',43,10,'crampon1923','Car si nous n''avions pas tant tardé, nous serions maintenant deux fois de retour. "'),
('gn',43,11,'crampon1923','Israël, leur père, leur dit: " Eh bien, puisqu''il le faut, faites ceci: Prenez dans vos vaisseaux des meilleures productions du pays et portez à cet homme un présent: un peu de baume et un peu de miel, de l''astragale, du ladanum, des pistaches et des amandes.'),
('gn',43,12,'crampon1923','Prenez dans vos mains de l''argent en double, et reportez celui qui a été mis à l''entrée de vos sacs, peut-être par erreur.'),
('gn',43,13,'crampon1923','Prenez votre frère, levez-vous et retournez vers cet homme.'),
('gn',43,14,'crampon1923','Que le Dieu tout-puissant vous fasse trouver grâce devant cet homme, afin qu''il laisse revenir avec vous votre autre frère, ainsi que Benjamin! Pour moi, si je dois être privé de mes enfants, que j''en sois privé! "'),
('gn',43,15,'crampon1923','Les hommes prirent ce présent, et ils prirent dans leurs mains de l''argent au double, ainsi que Benjamin; et, s''étant levés, ils descendirent en Egypte et se présentèrent devant Joseph.'),
('gn',43,16,'crampon1923','Dès que Joseph vit Benjamin avec eux, il dit à son intendant: " Fais entrer ces gens dans la maison, tue des victimes et apprête un repas, car ces gens mangeront avec moi à midi. "'),
('gn',43,17,'crampon1923','Cet homme fit ce que Joseph avait ordonné, et il conduisit ces gens dans la maison de Joseph.'),
('gn',43,18,'crampon1923','Pendant qu''on les conduisait à la maison de Joseph, les hommes eurent peur, et ils dirent: " C''est à cause de l''argent rapporté l''autre fois dans nos sacs qu''on nous emmène; c''est pour nous assaillir, tomber sur nous, nous prendre comme esclaves avec nos ânes. "'),
('gn',43,19,'crampon1923','S''étant approchés de l''intendant de la maison de Joseph, ils lui adressèrent la parole, à l''entrée de la maison,'),
('gn',43,20,'crampon1923','en disant: " Pardon, mon seigneur. Nous sommes déjà descendus une fois pour acheter des vivres.'),
('gn',43,21,'crampon1923','Au retour, quand nous arrivâmes à l''endroit où nous devions passer la nuit, nous avons ouvert nos sacs, et voici, l''argent de chacun était à l''entrée de son sac, notre argent selon son poids: nous le rapportons avec nous;'),
('gn',43,22,'crampon1923','et en même temps nous avons apporté d''autre argent pour acheter des vivres. Nous ne savons pas qui a mis notre argent dans nos sacs. "'),
('gn',43,23,'crampon1923','Il leur dit: " Que la paix soit avec vous! Ne craignez rien. C''est votre Dieu, le Dieu de votre père, qui vous a donné un trésor dans vos sacs. Votre argent m''a été remis. " Et il leur amena Siméon.'),
('gn',43,24,'crampon1923','Cet homme, les ayant fait entrer dans la maison de Joseph, leur donna de l''eau et ils se lavèrent les pieds; il donna aussi du fourrage à leurs ânes.'),
('gn',43,25,'crampon1923','Ils préparèrent leur présent, en attendant que Joseph vint à midi; car on leur avait annoncé qu''ils mangeraient chez lui.'),
('gn',43,26,'crampon1923','Quand Joseph fut arrivé chez lui, ils lui apportèrent dans la maison le présent qu''ils avaient dans la main, et se prosternèrent par terre devant lui.'),
('gn',43,27,'crampon1923','Il leur demanda comment ils se portaient, puis il dit: " Votre vieux père, dont vous avez parlé, est-il en bonne santé? vit-il encore? "'),
('gn',43,28,'crampon1923','Ils répondirent: " Ton serviteur, notre père, est en bonne santé; il vit encore "; et ils s''inclinèrent et se prosternèrent.'),
('gn',43,29,'crampon1923','Joseph leva les yeux, et il vit Benjamin, son frère, fils de sa mère; il dit: " Est-ce là votre jeune frère dont vous m''avez parlé? " Et il dit: " Que Dieu te soit favorable, mon fils! "'),
('gn',43,30,'crampon1923','Alors, en toute hâte, car ses entrailles étaient émues pour son frère, Joseph chercha un endroit pour pleurer; il entra dans sa chambre et il y pleura.'),
('gn',43,31,'crampon1923','Après s''être lavé le visage, il sortit et, faisant des efforts pour se contenir, il dit: " Servez à manger. "'),
('gn',43,32,'crampon1923','On le servit à part, et ses frères à part, à part aussi les Egyptiens qui mangeaient avec lui, car les Egyptiens ne peuvent prendre leurs repas avec les Hébreux: c''est une abomination pour les Egyptiens.'),
('gn',43,33,'crampon1923','Les frères de Joseph s''assirent devant lui, le premier-né selon son droit d''aînesse, et le plus jeune selon son âge; et ils se regardaient les uns les autres avec étonnement.'),
('gn',43,34,'crampon1923','Il leur fit porter des portions de devant lui, et la portion de Benjamin était cinq fois plus forte que les portions d''eux tous. Ils burent joyeusement avec lui.'),
('gn',44,1,'crampon1923','Joseph donna cet ordre à l''intendant de sa maison: " Remplis de vivres les sacs de ces gens, autant qu''ils en pourront porter, et mets l''argent de chacun à l''entrée de son sac.'),
('gn',44,2,'crampon1923','Tu mettras aussi ma coupe, la coupe d''argent, à l''entrée du sac du plus jeune, avec l''argent de son blé. " L''intendant fit ce que Joseph lui avait ordonné.'),
('gn',44,3,'crampon1923','Le matin, dès qu''il fit jour, on renvoya les hommes avec leurs ânes.'),
('gn',44,4,'crampon1923','Ils étaient sortis de la ville, sans en être encore bien éloignés, lorsque Joseph dit à son intendant: " Lève-toi, poursuis ces gens; et, quand tu les auras atteints, tu leur diras: Pourquoi avez-vous rendu le mal pour le bien?'),
('gn',44,5,'crampon1923','N''est-ce pas la coupe dans laquelle boit mon seigneur, et dont il se sert pour deviner? C''est une action mauvaise que vous avez faite. "'),
('gn',44,6,'crampon1923','L''intendant, les ayant rejoints, leur dit ces mêmes paroles.'),
('gn',44,7,'crampon1923','Ils lui répondirent: " Pourquoi mon seigneur parle-t-il ainsi? Dieu préserve tes serviteurs d''avoir commis une telle action!'),
('gn',44,8,'crampon1923','Voici, nous t''avons rapporté du pays de Chanaan l''argent que nous avons trouvé à l''entrée de nos sacs; comment aurions-nous dérobé dans la maison de ton seigneur de l''argent ou de l''or?'),
('gn',44,9,'crampon1923','Que celui de tes serviteurs sur qui sera trouvée la coupe meure, et que nous soyons aussi nous-mêmes les esclaves de mon seigneur. "'),
('gn',44,10,'crampon1923','Il leur dit: " Eh bien, qu''il en soit selon vos paroles! Celui chez qui se trouvera la coupe sera mon esclave; et vous, vous serez quittes. "'),
('gn',44,11,'crampon1923','Chacun descendit aussitôt son sac à terre et chacun ouvrit son sac.'),
('gn',44,12,'crampon1923','L''intendant les fouilla, commençant par le plus âgé et finissant par le plus jeune; et la coupe se trouva dans le sac de Benjamin.'),
('gn',44,13,'crampon1923','Ils déchirèrent leurs vêtements et, chacun ayant rechargé son âne, ils retournèrent à la ville.'),
('gn',44,14,'crampon1923','Juda avec ses frères arriva à la maison de Joseph, qui s''y trouvait encore, et ils se prosternèrent devant lui jusqu''à terre.'),
('gn',44,15,'crampon1923','Joseph leur dit: " Quelle action avez-vous faite? Ne saviez-vous pas qu''un homme tel que moi saurait bien deviner? "'),
('gn',44,16,'crampon1923','Juda répondit: " Que pouvons-nous dire à mon seigneur? Comment parler? comment nous justifier? Dieu a trouvé l''iniquité de tes serviteurs. Nous voici esclaves de mon seigneur, nous et celui chez qui s''est trouvée la coupe. "'),
('gn',44,17,'crampon1923','Et Joseph dit: " Dieu me garde de faire cela! l''homme chez qui la coupe a été trouvée sera mon esclave; et vous, remontez en paix vers votre père. "'),
('gn',44,18,'crampon1923','Alors Juda, s''approchant de Joseph, lui dit: " De grâce, mon seigneur, que ton serviteur puisse dire une parole aux oreilles de mon seigneur, et que ta colère ne s''enflamme pas contre ton serviteur! car tu es l''égal de Pharaon.'),
('gn',44,19,'crampon1923','Mon seigneur a interrogé ses serviteurs, en disant: Avez-vous un père ou un frère.'),
('gn',44,20,'crampon1923','Et nous avons répondu à mon seigneur: Nous avons un vieux père et un jeune frère, enfant de sa vieillesse; cet enfant avait un frère qui est mort, et il reste seul de la même mère, et son père l''aime.'),
('gn',44,21,'crampon1923','Tu as dit à tes serviteurs: Faites-le descendre vers moi, et que je pose mes yeux sur lui.'),
('gn',44,22,'crampon1923','Nous avons répondu à mon seigneur: L''enfant ne peut pas quitter son père; s''il le quitte, son père mourra.'),
('gn',44,23,'crampon1923','Tu as dit à tes serviteurs: Si votre jeune frère ne descend pas avec vous, vous ne reverrez plus ma face.'),
('gn',44,24,'crampon1923','Lorsque nous sommes remontés vers ton serviteur, mon père, nous lui avons rapporté les paroles de mon seigneur.'),
('gn',44,25,'crampon1923','Et quand notre père a dit: Retournez, achetez-nous un peu de vivres,'),
('gn',44,26,'crampon1923','nous avons répondu: Nous ne pouvons pas descendre; mais, si notre plus jeune frère est avec nous, nous descendrons, car nous ne pouvons voir la face de cet homme à moins que notre jeune frère ne soit avec nous.'),
('gn',44,27,'crampon1923','Ton serviteur, notre père, nous a dit: Vous savez que ma femme m''a enfanté deux fils.'),
('gn',44,28,'crampon1923','L''un s''en est allé d''avec moi, et j''ai dit: Il faut qu''il ait été dévoré, car je ne l''ai pas revu jusqu''à présent.'),
('gn',44,29,'crampon1923','Si vous me prenez encore celui-ci et qu''il lui arrive malheur, vous ferez descendre mes cheveux blancs avec douleur au séjour des morts. —'),
('gn',44,30,'crampon1923','Maintenant, quand je retournerai auprès de ton serviteur, mon père, sans avoir avec nous l''enfant, à l''âme duquel est attachée son âme,'),
('gn',44,31,'crampon1923','dès qu''il verra que l''enfant n''y est pas, il mourra, et tes serviteurs auront fait descendre avec douleur au séjour des morts les cheveux blancs de ton serviteur, notre père.'),
('gn',44,32,'crampon1923','Car ton serviteur a répondu de l''enfant en le prenant à mon père; il a dit: Si je ne le ramène pas auprès de toi, je serai coupable envers mon père à tout jamais.'),
('gn',44,33,'crampon1923','Permets donc, je te prie, que moi, ton serviteur, je reste à la place de l''enfant comme esclave de mon seigneur, et que l''enfant remonte avec ses frères.'),
('gn',44,34,'crampon1923','Comment pourrais-je remonter vers mon père, si l''enfant n''est pas avec moi? Non, que je ne voie point l''affliction qui accablerait mon père! "'),
('gn',45,1,'crampon1923','Alors Joseph ne put se contenir devant tous ceux qui étaient présents; il s''écria: " Faites sortir tout le monde. " Et il ne resta personne avec lui quand il se fit connaître à ses frères.'),
('gn',45,2,'crampon1923','Il éleva la voix en pleurant; les Egyptiens l''entendirent, et la maison de Pharaon l''entendit.'),
('gn',45,3,'crampon1923','Joseph dit à ses frères: " Je suis Joseph! Mon père vit-il encore? " Mais ses frères ne purent lui répondre, tant ils étaient bouleversés devant lui.'),
('gn',45,4,'crampon1923','Et Joseph dit à ses frères: " Approchez-vous de moi "; et ils s''approchèrent. Il dit: " Je suis Joseph, votre frère, que vous avez vendu pour être mené en Egypte.'),
('gn',45,5,'crampon1923','Maintenant ne vous affligez pas et ne soyez pas fâchés contre vous-mêmes de ce que vous m''avez vendu pour être conduit ici; c''est pour vous sauver la vie que Dieu m''a envoyé devant vous.'),
('gn',45,6,'crampon1923','Car voilà deux ans que la famine est dans ce pays, et pendant cinq années encore il n''y aura ni labour ni moisson.'),
('gn',45,7,'crampon1923','Dieu m''a envoyé devant vous pour vous assurer un reste dans le pays et vous faire subsister pour une grande délivrance.'),
('gn',45,8,'crampon1923','Et maintenant, ce n''est pas vous qui m''avez envoyé ici, mais c''est Dieu; il m''a établi père de Pharaon, seigneur sur toute sa maison et gouverneur de tout le pays d''Egypte.'),
('gn',45,9,'crampon1923','Hâtez-vous de monter vers mon père, et vous lui direz: Ainsi a parlé ton fils Joseph: Dieu m''a établi seigneur sur toute l''Egypte; descends vers moi sans tarder.'),
('gn',45,10,'crampon1923','Tu habiteras dans le pays de Gessen, et tu seras près de moi, toi et tes fils, et les fils de tes fils, tes brebis et tes bœufs, et tout ce qui est à toi.'),
('gn',45,11,'crampon1923','Là, je te nourrirai, — car il y aura encore cinq années de famine, — afin que tu ne souffres pas, toi, ta maison et tout ce qui est à toi.'),
('gn',45,12,'crampon1923','Voici, vos yeux voient, ainsi que les yeux de mon frère Benjamin, que c''est ma bouche qui vous parle.'),
('gn',45,13,'crampon1923','Racontez à mon père toute ma gloire en Egypte et tout ce que vous avez vu, et faites au plus tôt descendre ici mon père. "'),
('gn',45,14,'crampon1923','Alors il se jeta au cou de Benjamin, son frère, et pleura; et Benjamin pleura sur son cou.'),
('gn',45,15,'crampon1923','Il baisa aussi tous ses frères, et pleura en les tenant embrassés; puis ses frères s''entretinrent avec lui.'),
('gn',45,16,'crampon1923','Le bruit se répandit dans la maison de Pharaon que les frères de Joseph étaient venus: ce qui fut agréable à Pharaon et à ses serviteurs.'),
('gn',45,17,'crampon1923','Et Pharaon dit à Joseph: " Dis à tes frères: Faites ceci: chargez vos bêtes et partez pour le pays de Chanaan'),
('gn',45,18,'crampon1923','et, ayant pris votre père et vos familles, revenez auprès de moi. Je vous donnerai ce qu''il y a de meilleur au pays d''Egypte, et vous mangerez la graisse du pays.'),
('gn',45,19,'crampon1923','Tu es autorisé à leur dire: Faites ceci: prenez dans le pays d''Egypte des chariots pour vos enfants et pour vos femmes; amenez votre père et venez.'),
('gn',45,20,'crampon1923','Que vos yeux ne s''arrêtent pas avec regret sur les objets que vous devrez laisser, car ce qu''il y a de meilleur dans tout le pays d''Egypte est à votre disposition. "'),
('gn',45,21,'crampon1923','Les fils d''Israël firent ainsi; Joseph leur donna des chariots, selon l''ordre de Pharaon, ainsi que des provisions pour la route.'),
('gn',45,22,'crampon1923','Il leur donna à tous des vêtements de rechange, et il donna à Benjamin trois cents pièces d''argent et cinq vêtements de rechange.'),
('gn',45,23,'crampon1923','Il envoya également à son père dix ânes chargés des meilleurs produits de l''Egypte, et dix ânesses chargées de blé, de pain et de vivres, pour son père pendant le voyage.'),
('gn',45,24,'crampon1923','Puis il congédia ses frères, qui partirent; et il leur dit: " Ne vous querellez pas en chemin. "'),
('gn',45,25,'crampon1923','Ayant monté de l''Egypte, ils arrivèrent dans le pays de Chanaan, auprès de Jacob, leur père.'),
('gn',45,26,'crampon1923','Ils lui dirent: " Joseph vit encore, c''est même lui qui gouverne tout le pays d''Egypte. " Mais son cœur resta froid, parce qu''il ne les croyait pas.'),
('gn',45,27,'crampon1923','Ils lui rapportèrent alors toutes les paroles que Joseph avait dites. Lorsqu''il eut vu les chariots que Joseph avait envoyés pour le transporter, l''esprit de Jacob, leur père, se ranima,'),
('gn',45,28,'crampon1923','et Israël dit: " C''est assez! Joseph, mon fils, vit encore! j''irai et je le verrai avant de mourir. "'),
('gn',46,1,'crampon1923','Israël partit avec tout ce qui lui appartenait. Arrivé à Bersabée, il offrit des sacrifices au Dieu de son père Isaac.'),
('gn',46,2,'crampon1923','Et Dieu parla à Israël dans une vision de nuit, et il dit: " Jacob! Jacob! " Israël répondit: " Me voici. "'),
('gn',46,3,'crampon1923','Et Dieu dit: " Je suis le Dieu fort, le Dieu de ton père. Ne crains point de descendre en Egypte, car là je te ferai devenir une grande nation.'),
('gn',46,4,'crampon1923','Moi-même je descendrai avec toi en Egypte, et moi-même aussi je t''en ferai sûrement remonter; et Joseph posera sa main sur tes yeux. "'),
('gn',46,5,'crampon1923','Jacob, se levant, quitta Bersabée; et les fils d''Israël mirent Jacob, leur père, ainsi que leurs femmes et leurs enfants, sur les chariots que Pharaon avait envoyés pour le transporter.'),
('gn',46,6,'crampon1923','Ils prirent aussi leurs troupeaux et leurs biens qu''ils avaient acquis dans le pays de Chanaan. Et Jacob se rendit en Egypte avec toute sa famille.'),
('gn',46,7,'crampon1923','Il emmena avec lui en Egypte ses fils et les fils de ses fils, ses filles et les filles de ses fils, et toute sa famille.'),
('gn',46,8,'crampon1923','Voici les noms des fils d''Israël qui vinrent en Egypte: Jacob et ses fils. — Premier-né de Jacob, Ruben. —'),
('gn',46,9,'crampon1923','Fils de Ruben: Hénoch, Phallu, Hesron et Charmi. —'),
('gn',46,10,'crampon1923','Fils de Siméon: Jamuel, Jamin, Ahod, Jachin et Sohar, et Saul, fils de la Chananéenne. —'),
('gn',46,11,'crampon1923','Fils de Lévi: Gerson, Caat et Mérari. —'),
('gn',46,12,'crampon1923','Fils de Juda: Her, Onan, Séla, Pharès et Zara; mais Her et Onan étaient morts au pays de Chanaan. Les fils de Pharès furent Hesron et Hamul. —'),
('gn',46,13,'crampon1923','Fils d''Issachar: Thola, Phua, Job et Semron. —'),
('gn',46,14,'crampon1923','Fils de Zabulon: Sared, Elon et Jahélel —'),
('gn',46,15,'crampon1923','Ce sont là les fils que Lia enfanta à Jacob à Paddan-Aram, avec sa fille Dina. Ses fils et ses filles étaient en tout trente-trois personnes.'),
('gn',46,16,'crampon1923','Fils de Gad: Séphion, Haggi, Suni, Esebon, Heri, Arodi et Aréli. —'),
('gn',46,17,'crampon1923','Fils d''Aser: Jamné, Jésua, Jessui et Béria, et Sara, leur sœur. Les fils de Béria furent Héber et Melchiel. —'),
('gn',46,18,'crampon1923','Ce sont là les fils de Zelpha, que Laban avait donnée à Lia, sa fille; et elle les enfanta à Jacob: en tout seize personnes.'),
('gn',46,19,'crampon1923','Fils de Rachel, femme de Jacob: Joseph et Benjamin.'),
('gn',46,20,'crampon1923','Il naquit à Joseph, au pays d''Egypte, des fils que lui enfanta Aseneth, fille de Putiphar, prêtre d''On, savoir Manassé et Ephraïm. —'),
('gn',46,21,'crampon1923','Fils de Benjamin: Béla, Bochor, Asbel, Géra, Naaman, Echi, Ros, Mophim, Ophim et Ared. —'),
('gn',46,22,'crampon1923','Ce sont là les fils de Rachel, qui naquirent à Jacob: en tout quatorze personnes.'),
('gn',46,23,'crampon1923','Fils de Dan: Husim. —'),
('gn',46,24,'crampon1923','Fils de Nephtali: Jasiel, Guni, Jéser et Salem. —'),
('gn',46,25,'crampon1923','Ce sont là les fils de Bala, que Laban avait donnée à Rachel, sa fille; et elle les enfanta à Jacob: en tout sept personnes.'),
('gn',46,26,'crampon1923','Toutes les personnes qui vinrent avec Jacob en Egypte, issues de lui, sans compter les femmes des fils de Jacob, étaient au nombre de soixante-six en tout.'),
('gn',46,27,'crampon1923','Les fils de Joseph qui lui étaient nés en Egypte étaient deux. — Le total des personnes de la famille de Jacob qui vinrent en Egypte était de soixante-dix.'),
('gn',46,28,'crampon1923','Jacob avait envoyé Juda devant lui vers Joseph pour préparer son arrivée en Gessen. Lorsque Jacob et les siens furent entrés en Gessen,'),
('gn',46,29,'crampon1923','Joseph fit atteler son char et y monta, pour aller en Gessen, à la rencontre d''Israël, son père. Il se montra à lui et, s''étant jeté à son cou, il pleura longtemps sur son cou.'),
('gn',46,30,'crampon1923','Israël dit à Joseph: " Je puis mourir maintenant, puisque j''ai vu ton visage et que tu vis encore! "'),
('gn',46,31,'crampon1923','Joseph dit à ses frères et à la famille de son père: " Je vais avertir Pharaon et je lui dirai: Mes frères et la famille de mon père, qui étaient au pays de Chanaan, sont venus vers moi.'),
('gn',46,32,'crampon1923','Ces hommes font paître des brebis, car ce sont des propriétaires de troupeaux; ils ont amené leurs brebis et leurs bœufs, et tout ce qui leur appartient.'),
('gn',46,33,'crampon1923','Et quand Pharaon vous appellera et dira: Quelle est votre occupation?'),
('gn',46,34,'crampon1923','vous répondrez: Nous, tes serviteurs, sommes des propriétaires de troupeaux depuis notre jeunesse jusqu''à présent comme l''étaient nos pères. De cette manière vous habiterez dans le pays de Gessen, car tous les bergers sont en abomination aux Egyptiens. "'),
('gn',47,1,'crampon1923','Joseph alla porter la nouvelle à Pharaon, en disant: " Mon père et mes frères sont venus du pays de Chanaan avec leurs brebis et leurs bœufs, et tout ce qui leur appartient, et les voici dans le pays de Gessen. "'),
('gn',47,2,'crampon1923','Ayant pris cinq de ses frères, il les présenta à Pharaon;'),
('gn',47,3,'crampon1923','et Pharaon leur dit: " Quelle est votre occupation? " Ils répondirent à Pharaon: " Nous, tes serviteurs, sommes bergers, comme l''étaient nos pères. "'),
('gn',47,4,'crampon1923','Ils dirent encore à Pharaon: " Nous sommes venus pour séjourner dans le pays, car il n''y a plus de pâture pour les brebis de tes serviteurs, la famine s''étant appesantie sur le pays de Chanaan. Permets donc à tes serviteurs d''habiter dans le pays de Gessen. "'),
('gn',47,5,'crampon1923','Pharaon dit à Joseph: " Ton père et tes frères sont venus auprès de toi. Le pays d''Egypte est devant toi: établis ton père et tes frères dans la meilleure partie du pays.'),
('gn',47,6,'crampon1923','Qu''ils demeurent dans le pays de Gessen; et, si tu trouves parmi eux des hommes capables, mets-les à la tête des troupeaux qui m''appartiennent. "'),
('gn',47,7,'crampon1923','Joseph fit venir Jacob, son père, et le présenta à Pharaon. Jacob bénit Pharaon;'),
('gn',47,8,'crampon1923','et Pharaon dit à Jacob: " Quel est le nombre de jours des années de ta vie? "'),
('gn',47,9,'crampon1923','Jacob répondit à Pharaon: " Les jours des années de mon pèlerinage sont de cent trente ans. Courts et mauvais ont été les jours des années de ma vie, et ils n''ont point atteint les jours des années de la vie de mes pères durant leur pèlerinage. "'),
('gn',47,10,'crampon1923','Jacob bénit encore Pharaon et se retira de devant Pharaon.'),
('gn',47,11,'crampon1923','Joseph établit son père et ses frères, et leur assigna une propriété dans le pays d''Egypte, dans la meilleure partie du pays, dans la contrée de Ramsès, ainsi que Pharaon l''avait ordonné;'),
('gn',47,12,'crampon1923','et Joseph fournit de pain son père et ses frères, et toute la famille de son père, selon le nombre des enfants.'),
('gn',47,13,'crampon1923','Il n''y avait plus de pain dans tout le pays, car la famine était très grande; le pays d''Egypte et le pays de Chanaan étaient épuisés à cause de la famine.'),
('gn',47,14,'crampon1923','Joseph recueillit tout l''argent qui se trouvait dans le pays d''Egypte et dans le pays de Chanaan, contre le blé qu''on achetait, et il fit entrer cet argent dans la maison de Pharaon.'),
('gn',47,15,'crampon1923','Quand il n''y eut plus d''argent dans le pays d''Egypte et dans le pays de Chanaan, tous les Egyptiens vinrent à Joseph, en disant: " Donne-nous du pain! Pourquoi mourrions-nous en ta présence? Car nous sommes à bout d''argent. "'),
('gn',47,16,'crampon1923','Joseph dit: " Amenez vos troupeaux, et je vous donnerai du pain en échange de vos troupeaux, puisque vous êtes à bout d''argent. "'),
('gn',47,17,'crampon1923','Ils amenèrent leurs troupeaux à Joseph, et Joseph leur donna du pain en échange des chevaux, des troupeaux de brebis et de bœufs, et des ânes. Il leur fournit ainsi du pain cette année-là, en échange de tous leurs troupeaux.'),
('gn',47,18,'crampon1923','Lorsque cette année fut écoulée, ils vinrent à Joseph l''année suivante, et lui dirent: " Nous ne cacherons point à mon seigneur que l''argent est épuisé et que les troupeaux de bétail ont été donnés à mon seigneur; il ne reste devant mon seigneur que nos corps et nos terres.'),
('gn',47,19,'crampon1923','Pourquoi péririons-nous sous tes yeux, nous et nos terres? Achète-nous, ainsi que nos terres, pour du pain, et nous serons, nous et nos terres, serfs de Pharaon; et donne-nous de quoi semer, afin que nous vivions et que nous ne mourions pas, et que nos terres ne soient pas désolées. "'),
('gn',47,20,'crampon1923','Joseph acquit ainsi toutes les terres de l''Egypte à Pharaon; car les Egyptiens vendirent chacun leur champ, parce que la famine les pressait, et le pays devint la propriété de Pharaon.'),
('gn',47,21,'crampon1923','Il fit passer le peuple dans les villes, d''une extrémité à l''autre du territoire de l''Egypte.'),
('gn',47,22,'crampon1923','Il n''y eut que les terres des prêtres qu''il n''acquit pas; car les prêtres recevaient de Pharaon une portion déterminée, et ils vécurent de leur revenu que Pharaon leur assignait: c''est pourquoi ils ne vendirent point leurs terres.'),
('gn',47,23,'crampon1923','Joseph dit au peuple: " Je vous ai acquis aujourd''hui avec vos terres pour Pharaon. Voici pour vous de la semence, ensemencez la terre.'),
('gn',47,24,'crampon1923','A la récolte, vous donnerez le cinquième à Pharaon, et vous aurez les quatre autres parties pour ensemencer vos champs et pour vous nourrir, vous et ceux qui sont dans vos maisons, et pour nourrir vos enfants. "'),
('gn',47,25,'crampon1923','Ils dirent: " Nous te devons la vie! Que nous trouvions grâce auprès de mon seigneur, et nous serons esclaves de Pharaon. "'),
('gn',47,26,'crampon1923','Joseph fit de cela une loi, qui subsiste jusqu''à ce jour, et en vertu de laquelle le cinquième du produit des terres d''Egypte appartient à Pharaon; seules les terres des prêtres ne sont pas à lui.'),
('gn',47,27,'crampon1923','Israël habita au pays d''Egypte, dans la contrée de Gessen; ils y acquirent des possessions, ils furent féconds et multiplièrent beaucoup.'),
('gn',47,28,'crampon1923','Jacob vécut dix-sept ans dans le pays d''Egypte; et les jours de Jacob, les années de sa vie furent de cent quarante-sept ans.'),
('gn',47,29,'crampon1923','Quand les jours d''Israël approchèrent de leur fin, il appela son fils Joseph et lui dit: " Si j''ai trouvé grâce à tes yeux, mets, je te prie, ta main sous ma cuisse, et use envers moi de bonté et de fidélité: ne m''enterre pas en Egypte.'),
('gn',47,30,'crampon1923','Quand je serai couché avec mes pères, tu me transporteras hors de l''Egypte, et tu m''enterreras dans leurs sépulcres. " Joseph répondit: " Je ferai selon ta parole. "'),
('gn',47,31,'crampon1923','Et Jacob dit: " Jure-le-moi. " Joseph le lui jura; et Israël se prosterna sur le chevet du lit.'),
('gn',48,1,'crampon1923','Après ces choses, on vint dire à Joseph: " Voici que ton père est malade. " Il prit avec lui ses deux fils, Manassé et Ephraïm.'),
('gn',48,2,'crampon1923','On avertit Jacob, en disant: " Voici ton fils Joseph qui vient vers toi. " Israël rassembla ses forces et s''assit sur son lit.'),
('gn',48,3,'crampon1923','Jacob dit à Joseph: " Le Dieu tout-puissant m''est apparu à Luz, dans le pays de Chanaan, et il m''a béni,'),
('gn',48,4,'crampon1923','en disant: Je te rendrai fécond, je te multiplierai, et je te ferai devenir une assemblée de peuples; je donnerai ce pays à ta postérité après toi, pour qu''elle le possède à jamais.'),
('gn',48,5,'crampon1923','Et maintenant, les deux fils qui te sont nés dans le pays d''Egypte, avant mon arrivée vers toi en Egypte, seront miens; Ephraïm et Manassé seront miens, comme Ruben et Siméon.'),
('gn',48,6,'crampon1923','Mais les enfants que tu as engendrés après eux seront tiens; ils seront appelés du nom de leurs frères quant à leur part d''héritage.'),
('gn',48,7,'crampon1923','Et moi, quand je revenais de Paddan, Rachel mourut en route auprès de moi, dans le pays de Chanaan, à une certaine distance d''Ephrata; et c''est là que je l''ai enterrée sur le chemin d''Ephrata, qui est Bethléem. "'),
('gn',48,8,'crampon1923','Alors Israël vit les fils de Joseph, et dit: " Qui sont ceux-ci? "'),
('gn',48,9,'crampon1923','Joseph répondit à son père: " Ce sont mes fils, que Dieu m''a donnés ici. " Et Israël dit: " Fais-les approcher de moi, je te prie, afin que je les bénisse. "'),
('gn',48,10,'crampon1923','Car les yeux d''Israël étaient obscurcis par l''âge, et il ne pouvait plus bien voir. Joseph les fit approcher de lui, et Israël les baisa, en les tenant embrassés.'),
('gn',48,11,'crampon1923','Et Israël dit à Joseph: " Je ne pensais plus revoir ton visage, et voici que Dieu me fait voir aussi ta postérité! "'),
('gn',48,12,'crampon1923','Joseph les retira d''entre les genoux de son père et, s''étant prosterné en terre devant lui,'),
('gn',48,13,'crampon1923','Joseph les prit tous les deux, Ephraïm à sa droite, à la gauche d''Israël, et Manassé à sa gauche, à la droite d''Israël, et il les fit approcher.'),
('gn',48,14,'crampon1923','Israël étendit sa main droite et la posa sur la tête d''Ephraïm, qui était le plus jeune, et il posa sa main gauche sur la tête de Manassé; c''est à dessein qu''il posa ainsi ses mains, car Manassé était l''aîné.'),
('gn',48,15,'crampon1923','Il bénit Joseph, en disant: " Que le Dieu en présence duquel ont marché mes pères Abraham et Isaac, que le Dieu qui m''a nourri depuis que j''existe jusqu''à ce jour,'),
('gn',48,16,'crampon1923','que l''ange qui m''a délivré de tout mal, bénisse ces enfants! Qu''ils soient appelés de mon nom et du nom de mes pères, Abraham et Isaac, et qu''ils multiplient en abondance au milieu du pays! "'),
('gn',48,17,'crampon1923','Joseph, voyant que son père posait sa main droite sur la tête d''Ephraïm, en eut du déplaisir; il prit la main de son père pour l''écarter de dessus la tête d''Ephraïm et la porter sur celle de Manassé;'),
('gn',48,18,'crampon1923','et Joseph dit à son père: " Pas ainsi, mon père, car celui-ci est le premier-né: mets ta main droite sur sa tête. "'),
('gn',48,19,'crampon1923','Mais son père refusa, en disant: " Je le sais, mon fils, je le sais; lui aussi deviendra un peuple, lui aussi sera grand; mais son frère cadet sera plus grand que lui, et sa postérité deviendra une multitude de nations. "'),
('gn',48,20,'crampon1923','Il les bénit donc ce jour-là et dit: " Par toi Israël bénira, en disant: Que Dieu te rende tel qu''Ephraïm et Manassé! " Et il mit Ephraïm avant Manassé.'),
('gn',48,21,'crampon1923','Israël dit à Joseph: " Voici que je vais mourir. Mais Dieu sera avec vous, et il vous ramènera dans le pays de vos pères.'),
('gn',48,22,'crampon1923','Je te donne, de plus qu''à tes frères, une portion que j''ai prise de la main des Amorrhéens avec mon épée et mon arc. "'),
('gn',49,1,'crampon1923','Jacob appela ses fils et leur dit: " Rassemblez-vous, et je vous annoncerai ce qui vous arrivera à la fin des jours.'),
('gn',49,2,'crampon1923','Rassemblez-vous et écoutez, fils de Jacob; écoutez Israël, votre père.'),
('gn',49,3,'crampon1923','RUBEN, toi, mon premier-né, ma force, et le premier fruit de ma vigueur, supérieur en dignité et supérieur en puissance,'),
('gn',49,4,'crampon1923','tu as bouillonné comme l''eau; tu n''auras pas la prééminence! Car tu es monté sur la couche de ton père, et tu as souillé ma couche en y montant!'),
('gn',49,5,'crampon1923','SIMÉON et LÉVI sont frères; leurs glaives sont des instruments de violence.'),
('gn',49,6,'crampon1923','Que mon âme n''entre point dans leur conseil! Que mon âme ne s''unisse point à leur assemblée! Car, dans leur colère, ils ont égorgé des hommes, et, dans leur emportement, ils ont coupé les jarrets des taureaux.'),
('gn',49,7,'crampon1923','Maudite soit leur colère, car elle a été violente, et leur fureur, car elle a été cruelle! Je les diviserai en Jacob, et je les disperserai en Israël.'),
('gn',49,8,'crampon1923','Toi, JUDA, tes frères te loueront; ta main sera sur le cou de tes ennemis; les fils de ton père se prosterneront devant toi.'),
('gn',49,9,'crampon1923','Juda est un jeune lion. Tu es remonté du carnage, mon fils! Il a ployé les genoux, il s''est couché comme un lion, comme une lionne: qui le fera lever?'),
('gn',49,10,'crampon1923','Le sceptre ne s''éloignera point de Juda, ni le bâton de commandement d''entre ses pieds, jusqu''à ce que vienne Schiloh; c''est à lui que les peuples obéiront.'),
('gn',49,11,'crampon1923','Il attache à la vigne son ânon, au cep le petit de son ânesse; il lave son vêtement dans le vin, son manteau dans le sang de la grappe.'),
('gn',49,12,'crampon1923','Il a les yeux rouges de vin, et les dents blanches de lait.'),
('gn',49,13,'crampon1923','ZABULON habite le bord de la mer, il est sur le rivage où abordent les navires; son flanc est du côté de Sidon.'),
('gn',49,14,'crampon1923','ISSACHAR est un âne robuste, qui se couche dans ses parcs.'),
('gn',49,15,'crampon1923','Il voit que le repos est bon, et que le pays est agréable; et il courbe son épaule sous le fardeau; il est devenu un homme asservi au tribut.'),
('gn',49,16,'crampon1923','DAN juge son peuple, comme l''une des tribus d''Israël.'),
('gn',49,17,'crampon1923','Dan est un serpent sur le chemin, une vipère sur le sentier, qui mord les talons du cheval, pour que le cavalier tombe à la renverse.'),
('gn',49,18,'crampon1923','J''espère en ton secours, ô Yahweh!'),
('gn',49,19,'crampon1923','GAD, des bandes armées le pressent, et lui, à son tour, les presse sur les talons.'),
('gn',49,20,'crampon1923','D''ASER vient le pain savoureux, il fournit les mets délicats des rois.'),
('gn',49,21,'crampon1923','NEPHTALI est une biche en liberté, il prononce des paroles gracieuses.'),
('gn',49,22,'crampon1923','JOSEPH est le rejeton d''un arbre fertile, le rejeton d''un arbre fertile sur les bords d''une source; ses branches s''élancent au-dessus de la muraille.'),
('gn',49,23,'crampon1923','Des archers le provoquent, ils lui lancent des flèches et l''attaquent.'),
('gn',49,24,'crampon1923','Mais son arc reste ferme, ses bras et ses mains sont rendus agiles, par les mains du Puissant de Jacob, par celui qui est le Pasteur et le Rocher d''Israël.'),
('gn',49,25,'crampon1923','Que du Dieu de ton père — il t''aidera! — et du Tout-Puissant — il te bénira! te viennent les bénédictions du ciel en haut, les bénédictions de l''abîme en bas, les bénédictions des mamelles et du sein maternel!'),
('gn',49,26,'crampon1923','Les bénédictions de ton père surpassent les bénédictions des montagnes antiques, la beauté des collines éternelles: qu''elles soient sur la tête de Joseph, sur le front du prince de ses frères!')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('gn',49,27,'crampon1923','BENJAMIN est un loup qui déchire; le matin il dévore la proie, le soir il partage le butin.'),
('gn',49,28,'crampon1923','Ce sont là tous ceux qui formèrent les douze tribus d''Israël; c''est ainsi que leur parla leur père et qu''il les bénit. Il les bénit chacun selon sa bénédiction.'),
('gn',49,29,'crampon1923','Puis il leur donna cet ordre: " Je vais être réuni à mon peuple; enterrez-moi avec mes pères dans la caverne qui est dans le champ d''Ephron, le Héthéen,'),
('gn',49,30,'crampon1923','dans la caverne du champ de Macpéla, en face de Mambré, au pays de Chanaan: c''est la caverne qu''Abraham a acquise d''Ephron, le Héthéen, avec le champ, pour avoir un sépulcre qui lui appartienne.'),
('gn',49,31,'crampon1923','C''est là qu''on a enterré Abraham et Sara, sa femme, c''est là qu''on a enterré Isaac et Rebecca, sa femme, et c''est là que j''ai enterré Lia. "'),
('gn',49,32,'crampon1923','Le champ et la caverne qui s''y trouve ont été acquis des fils de Heth.'),
('gn',49,33,'crampon1923','Lorsque Jacob eut achevé de donner ses ordres à ses fils, ayant retiré ses pieds dans le lit, il expira et fut réuni à ses pères.'),
('gn',50,1,'crampon1923','Joseph se jeta sur le visage de son père, pleura sur lui et le baisa.'),
('gn',50,2,'crampon1923','Puis il ordonna aux médecins à son service d''embaumer son père, et les médecins embaumèrent Israël.'),
('gn',50,3,'crampon1923','Ils y employèrent quarante jours, car c''est le temps que l''on emploie à embaumer; et les Egyptiens le pleurèrent soixante-dix jours.'),
('gn',50,4,'crampon1923','Quand les jours de son deuil furent passés, Joseph s''adressa aux gens de la maison de Pharaon, et leur dit: " Si j''ai trouvé grâce à vos yeux, rapportez ceci, je vous prie, aux oreilles de Pharaon:'),
('gn',50,5,'crampon1923','Mon père m''a fait jurer, en disant: Voici que je vais mourir; tu m''enterreras dans le sépulcre que je me suis creusé au pays de Chanaan. Je voudrais donc y monter pour enterrer mon père; et je reviendrai. "'),
('gn',50,6,'crampon1923','Pharaon répondit: " Monte et enterre ton père, comme il te l''a fait jurer. "'),
('gn',50,7,'crampon1923','Joseph monta pour enterrer son père. Avec lui montèrent tous les serviteurs de Pharaon, les anciens de sa maison, et tous les anciens du pays d''Egypte,'),
('gn',50,8,'crampon1923','toute la maison de Joseph, ses frères et la maison de son père: ils ne laissèrent dans le pays de Gessen que leurs petits enfants, leurs brebis et leurs bœufs.'),
('gn',50,9,'crampon1923','Il montait encore avec Joseph des chars et des cavaliers, en sorte que le cortège était très nombreux.'),
('gn',50,10,'crampon1923','Arrivés à l''aire d''Atad, qui est au delà du Jourdain, ils firent entendre de grandes et profondes lamentations, et Joseph célébra en l''honneur de son père un deuil de sept jours.'),
('gn',50,11,'crampon1923','Les habitants du pays, les Chananéens, ayant vu ce deuil dans l''aire d''Atad, dirent: " Voilà un grand deuil parmi les Egyptiens! " C''est pourquoi l''on a donné le nom d''Abel-Mitsraïm à ce lieu, qui est au delà du Jourdain.'),
('gn',50,12,'crampon1923','Les fils de Jacob firent donc envers lui comme il leur avait commandé.'),
('gn',50,13,'crampon1923','Ses fils le transportèrent au pays de Chanaan et l''enterrèrent dans la caverne du champ de Macpéla, qu''Abraham avait acquise d''Ephron le Héthéen, avec le champ, pour avoir un sépulcre qui lui appartint, vis-à-vis de Mambré.'),
('gn',50,14,'crampon1923','Après avoir enterré son père, Joseph retourna en Egypte avec ses frères et tous ceux qui étaient montés avec lui pour enterrer son père.'),
('gn',50,15,'crampon1923','Quand les frères de Joseph virent que leur père était mort, ils dirent: " Si Joseph nous prenait en haine, et nous rendait tout le mal que nous lui avons fait! "'),
('gn',50,16,'crampon1923','Et ils firent dire à Joseph: " Ton père a donné cet ordre avant de mourir:'),
('gn',50,17,'crampon1923','Vous parlerez ainsi à Joseph: Oh! pardonne le crime de tes frères et leur péché, car ils t''ont fait du mal! Maintenant donc, je te prie, pardonne le crime des serviteurs du Dieu de ton père. " Joseph pleura, en entendant ces paroles.'),
('gn',50,18,'crampon1923','Ses frères vinrent eux-mêmes se prosterner devant lui, en disant: " Nous sommes tes serviteurs. "'),
('gn',50,19,'crampon1923','Joseph leur dit: " Soyez sans crainte; car suis-je à la place de Dieu?'),
('gn',50,20,'crampon1923','Vous aviez dans la pensée de me faire du mal; mais Dieu avait dans la sienne d''en faire sortir du bien, afin d''accomplir ce qui arrive aujourd''hui, afin de conserver la vie à un peuple nombreux.'),
('gn',50,21,'crampon1923','Soyez donc sans crainte; je vous entretiendrai, vous et vos enfants. " C''est ainsi qu''il les consola, en parlant à leurs cœurs.'),
('gn',50,22,'crampon1923','Joseph demeura en Egypte, lui et la maison de son père. Il vécut cent dix ans.'),
('gn',50,23,'crampon1923','Joseph vit les fils d''Ephraïm jusqu''à la troisième génération; des fils de Machir, fils de Manassé, naquirent aussi sur les genoux de Joseph.'),
('gn',50,24,'crampon1923','Joseph dit à ses frères: " Pour moi, je vais mourir; mais Dieu vous visitera certainement et vous fera remonter de ce pays dans le pays qu''il a juré de donner à Abraham, à Isaac et à Jacob. "'),
('gn',50,25,'crampon1923','Joseph fit jurer les fils d''Israël, en disant: " Certainement Dieu vous visitera, et vous ferez remonter mes os d''ici. "'),
('gn',50,26,'crampon1923','Joseph mourut, âgé de cent dix ans. On l''embauma et on le mit dans un cercueil en Egypte.'),
('ex',1,1,'crampon1923','Voici les noms des enfants d''Israël venus en Egypte; — ils y vinrent avec Jacob, chacun avec sa famille —:'),
('ex',1,2,'crampon1923','Ruben, Siméon, Lévi, Juda,'),
('ex',1,3,'crampon1923','Issachar, Zabulon, Benjamin,'),
('ex',1,4,'crampon1923','Dan, Nephtali, Gad et Aser.'),
('ex',1,5,'crampon1923','Toutes les personnes issues de Jacob étaient au nombre de soixante-dix, et Joseph était déjà en Egypte.'),
('ex',1,6,'crampon1923','Joseph mourut, ainsi que tous ses frères et toute cette génération.'),
('ex',1,7,'crampon1923','Les enfants d''Israël furent féconds et multiplièrent; ils devinrent nombreux et très puissants, et le pays en fut rempli.'),
('ex',1,8,'crampon1923','Il s''éleva sur l''Egypte un nouveau roi qui ne connaissait pas Joseph.'),
('ex',1,9,'crampon1923','Il dit à son peuple: " Voici que les enfants d''Israël forment un peuple plus nombreux et plus puissant que nous.'),
('ex',1,10,'crampon1923','Allons! Prenons des précautions contre lui, de peur qu''il ne s''accroisse, et que, une guerre survenant, il ne se joigne à nos ennemis pour nous combattre, et ne sorte ensuite du pays. "'),
('ex',1,11,'crampon1923','Les Egyptiens établirent donc sur Israël des chefs de corvée, afin de l''accabler par des travaux pénibles. C''est ainsi qu''il bâtit des villes pour servir de magasins à Pharaon, savoir Pithom et Ramsès.'),
('ex',1,12,'crampon1923','Mais plus on l''accablait, plus il multipliait et s''accroissait, et l''on prit en aversion les enfants d''Israël.'),
('ex',1,13,'crampon1923','Les Egyptiens firent travailler les enfants d''Israël par force;'),
('ex',1,14,'crampon1923','ils leur rendaient la vie amère par de rudes travaux, mortier, briques et toute sorte de travaux des champs, tout le travail qu''ils leur imposaient avec dureté.'),
('ex',1,15,'crampon1923','Le roi d''Egypte parla aussi aux sages-femmes des Hébreux, dont l''une se nommait Séphora, et l''autre Phua.'),
('ex',1,16,'crampon1923','Il leur dit: " Quand vous accoucherez les femmes des Hébreux, et que vous les verrez sur le double siège, si c''est un fils, faites-le mourir; si c''est une fille, elle peut vivre. "'),
('ex',1,17,'crampon1923','Mais les sages-femmes craignirent Dieu, et ne firent pas comme leur avait dit le roi d''Egypte; elles laissèrent vivre les garçons.'),
('ex',1,18,'crampon1923','Le roi d''Egypte fit appeler les sages-femmes et leur dit: " Pourquoi avez-vous agi ainsi, et avez-vous laissé vivre les garçons? "'),
('ex',1,19,'crampon1923','Les sages-femmes répondirent à Pharaon: " C''est que les femmes des Hébreux ne ressemblent pas aux Egyptiennes: elles sont vigoureuses, et elles accouchent avant l''arrivée de la sage-femme. "'),
('ex',1,20,'crampon1923','Et Dieu fit du bien aux sages-femmes, et le peuple devint nombreux et extrêmement fort.'),
('ex',1,21,'crampon1923','Parce que les sages-femmes avaient craint Dieu, Dieu fit prospérer leur maison.'),
('ex',1,22,'crampon1923','Alors Pharaon donna cet ordre à tout son peuple: " Vous jetterez dans le fleuve tout fils qui naîtra et vous laisserez vivre toutes les filles. "'),
('ex',2,1,'crampon1923','Un homme de la maison de Lévi était allé prendre pour femme une fille de Lévi.'),
('ex',2,2,'crampon1923','Cette femme devint enceinte et enfanta un fils. Voyant qu''il était beau, elle le cacha pendant trois mois.'),
('ex',2,3,'crampon1923','Comme elle ne pouvait plus le tenir caché, elle prit une caisse de jonc et, l''ayant enduite de bitume et de poix, elle y mit l''enfant et le déposa parmi les roseaux, sur le bord du fleuve.'),
('ex',2,4,'crampon1923','La sœur de l''enfant se tenait à quelque distance pour savoir ce qui lui arriverait.'),
('ex',2,5,'crampon1923','La fille de Pharaon descendit au fleuve pour se baigner, et ses compagnes se promenaient le long du fleuve. Ayant aperçu la caisse au milieu des roseaux, elle envoya sa servante pour la prendre.'),
('ex',2,6,'crampon1923','Elle l''ouvrit et vit l''enfant: c''était un petit garçon qui pleurait; elle en eut pitié, et elle dit: " C''est un enfant des Hébreux. "'),
('ex',2,7,'crampon1923','Alors la sœur de l''enfant dit à la fille de Pharaon: " Veux-tu que j''aille te chercher une nourrice parmi les femmes des Hébreux pour allaiter cet enfant? "'),
('ex',2,8,'crampon1923','— " Va " lui dit la fille de Pharaon; et la jeune fille alla chercher la mère de l''enfant.'),
('ex',2,9,'crampon1923','La fille de Pharaon lui dit: " Emporte cet enfant et allaite-le-moi; je te donnerai ton salaire. " La femme prit l''enfant et l''allaita.'),
('ex',2,10,'crampon1923','Quand il eut grandi, elle l''amena à la fille de Pharaon, et il fut pour elle comme un fils. Elle lui donna le nom de Moïse, " car, dit-elle, je l''ai tiré des eaux. "'),
('ex',2,11,'crampon1923','En ce temps-là, Moïse, devenu grand, sortit vers ses frères, et il fut témoin de leurs pénibles travaux; il vit un Egyptien qui frappait un Hébreu d''entre ses frères.'),
('ex',2,12,'crampon1923','Ayant tourné les yeux de côté et d''autre, et voyant qu''il n''y avait là personne, il tua l''Egyptien et le cacha dans le sable.'),
('ex',2,13,'crampon1923','Il sortit encore le jour suivant, et voici, deux Hébreux se querellaient. Il dit au coupable: " Pourquoi frappes-tu ton camarade? "'),
('ex',2,14,'crampon1923','Et cet homme répondit: " Qui t''a établi chef et juge sur nous? Est-ce que tu veux me tuer, comme tu as tué l''Egyptien? " Moïse fut effrayé, et il dit: " Certainement la chose est connue. "'),
('ex',2,15,'crampon1923','Pharaon, ayant appris ce qui s''était passé, cherchait à faire mourir Moïse; mais Moïse s''enfuit de devant Pharaon; il se retira dans le pays de Madian, et il s''assit près du puits.'),
('ex',2,16,'crampon1923','Le prêtre de Madian avait sept filles. Elles vinrent puiser de l''eau, et elles remplirent les auges pour abreuver le troupeau de leur père.'),
('ex',2,17,'crampon1923','Les bergers, étant arrivés, les chassèrent; alors Moïse se leva, prit leur défense et fit boire leur troupeau.'),
('ex',2,18,'crampon1923','Quand elles furent de retour auprès de Raguel, leur père, il dit: " Pourquoi revenez-vous sitôt aujourd''hui? "'),
('ex',2,19,'crampon1923','Elles répondirent: " Un Egyptien nous a délivrées de la main des bergers, et même il a puisé pour nous de l''eau et il a fait boire le troupeau. "'),
('ex',2,20,'crampon1923','Il dit à ses filles: " Où est-il? Pourquoi avez-vous laissé cet homme? Rappelez-le, pour qu''il prenne quelque nourriture. "'),
('ex',2,21,'crampon1923','Moïse consentit à demeurer chez cet homme, qui lui donna pour femme Séphora, sa fille.'),
('ex',2,22,'crampon1923','Elle enfanta un fils, qu''il appela Gersam, " car, dit-il, je suis un étranger sur une terre étrangère. "'),
('ex',2,23,'crampon1923','Durant ces longs jours, le roi d''Egypte mourut. Les enfants d''Israël, gémissant encore sous la servitude, poussèrent des cris, et ces cris, arrachés par la servitude, montèrent jusqu''à Dieu.'),
('ex',2,24,'crampon1923','Dieu entendit leurs gémissements, et se souvint de son alliance avec Abraham, Isaac et Jacob.'),
('ex',2,25,'crampon1923','Dieu regarda les enfants d''Israël et il les reconnut.'),
('ex',3,1,'crampon1923','Moïse faisait paître le troupeau de Jéthro, son beau-père, prêtre de Madian. Il mena le troupeau au delà du désert, et arriva à la montagne de Dieu, à Horeb.'),
('ex',3,2,'crampon1923','L''ange de Yahweh lui apparut en flamme de feu, du milieu du buisson. Et Moïse vit, et voici, le buisson était tout en feu, et le buisson ne se consumait pas.'),
('ex',3,3,'crampon1923','Moïse dit: " Je veux faire un détour pour considérer cette grande vision, et voir pourquoi le buisson ne se consume point. "'),
('ex',3,4,'crampon1923','Yahweh vit qu''il se détournait pour regarder; et Dieu l''appela du milieu du buisson, et dit: " Moïse! Moïse! " Il répondit: " Me voici. "'),
('ex',3,5,'crampon1923','Dieu dit: " N''approche pas d''ici, ôte tes sandales de tes pieds, car le lieu sur lequel tu te tiens est une terre sainte. "'),
('ex',3,6,'crampon1923','Il ajouta: " Je suis le Dieu de ton père, le Dieu d''Abraham, le Dieu d''Isaac et le Dieu de Jacob. " Moïse se cacha le visage, car il craignait de regarder Dieu.'),
('ex',3,7,'crampon1923','Yahweh dit: " J''ai vu la souffrance de mon peuple qui est en Egypte, et j''ai entendu le cri que lui font pousser ses exacteurs, car je connais ses douleurs.'),
('ex',3,8,'crampon1923','Je suis descendu pour le délivrer de la main des Egyptiens et pour le faire monter de ce pays dans une terre fertile et spacieuse, dans une terre où coulent le lait et le miel, au lieu qu''habitent les Chananéens, les Héthéens, les Amorrhéens, les Phérézéens, les Hévéens et les Jébuséens.'),
('ex',3,9,'crampon1923','Et maintenant voici, le cri des enfants d''Israël est venu jusqu''à moi, et j''ai vu l''oppression que font peser sur eux les Egyptiens.'),
('ex',3,10,'crampon1923','Et maintenant, va, je t''envoie auprès de Pharaon, pour faire sortir mon peuple, les enfants d''Israël. "'),
('ex',3,11,'crampon1923','Moïse dit à Dieu: " Qui suis-je, pour aller vers Pharaon et pour faire sortir d''Egypte les enfants d''Israël? "'),
('ex',3,12,'crampon1923','Dieu dit: " Je serai avec toi; et ceci sera pour toi le signe que c''est moi qui t''ai envoyé: Quand tu auras fait sortir le peuple d''Egypte, vous servirez Dieu sur cette montagne. "'),
('ex',3,13,'crampon1923','Moïse dit à Dieu: " Voici, j''irai vers les enfants d''Israël, et je leur dirai: Le Dieu de vos pères m''envoie vers vous. S''ils me demandent quel est son nom, que leur répondrai-je? "'),
('ex',3,14,'crampon1923','Et Dieu dit à Moïse: " Je suis celui qui suis. " Et il ajouta: " C''est ainsi, que tu répondras aux enfants d''Israël: Celui qui est m''envoie vers vous. "'),
('ex',3,15,'crampon1923','Dieu dit encore à Moïse: " Tu parleras ainsi aux enfants d''Israël: Yahweh, le Dieu de vos pères, le Dieu d''Abraham, le Dieu d''Isaac et le Dieu de Jacob, m''envoie vers vous. C''est là mon nom pour l''éternité; c''est là mon souvenir de génération en génération.'),
('ex',3,16,'crampon1923','Va, rassemble les anciens d''Israël et dis-leur: Yahweh, le Dieu de vos pères, m''est apparu, le Dieu d''Abraham, d''Isaac et de Jacob, en disant: Je vous ai visités, j''ai vu ce qu''on vous fait en Egypte,'),
('ex',3,17,'crampon1923','et j''ai dit: Je vous ferai monter de l''Egypte, où l''on vous opprime, dans le pays des Chananéens, des Héthéens, des Amorrhéens, des Phérézéens, des Hévéens et des Jébuséens, dans un pays où coulent le lait et le miel.'),
('ex',3,18,'crampon1923','Ils écouteront ta voix, et tu iras, toi et les anciens d''Israël, vers le roi d''Egypte, et vous lui direz: Yahweh, le Dieu des Hébreux, s''est présenté à nous. Et maintenant, laisse-nous aller à trois journées de marche dans le désert, pour offrir des sacrifices à Yahweh notre Dieu.'),
('ex',3,19,'crampon1923','Je sais que le roi d''Egypte ne vous permettra pas d''aller, si ce n''est forcé par une main puissante.'),
('ex',3,20,'crampon1923','J''étendrai ma main et je frapperai l''Egypte par toutes sortes de prodiges que je ferai au milieu d''elle; après quoi, il vous laissera aller.'),
('ex',3,21,'crampon1923','Je ferai même que ce peuple trouve grâce aux yeux des Egyptiens et, quand vous partirez, vous ne partirez point les mains vides.'),
('ex',3,22,'crampon1923','Mais chaque femme demandera à sa voisine et à celle qui demeure dans sa maison des objets d''argent, des objets d''or et des vêtements que vous mettrez sur vos fils et vos filles. Et vous dépouillerez l''Egypte. "'),
('ex',4,1,'crampon1923','Moïse répondit, en disant: " Ils ne me croiront pas et ils n''écouteront pas ma voix; mais ils diront: Yahweh ne t''est point apparu. "'),
('ex',4,2,'crampon1923','Yahweh lui dit: " Qu''y a-t-il dans ta main? " Il répondit: " Un bâton. "'),
('ex',4,3,'crampon1923','Et Yahweh dit: " Jette-le à terre. " Il le jeta à terre, et ce bâton devint un serpent, et Moïse s''enfuyait devant lui.'),
('ex',4,4,'crampon1923','Yahweh dit à Moïse: " Etends ta main, et saisis-le par la queue, — et il étendit la main et le saisit, et le serpent redevint un bâton dans sa main, —'),
('ex',4,5,'crampon1923','afin qu''ils croient que Yahweh, le Dieu de leurs pères, t''est apparu, le Dieu d''Abraham, le Dieu d''Isaac et le Dieu de Jacob. "'),
('ex',4,6,'crampon1923','Yahweh lui dit encore: " Mets ta main dans ton sein. " Il mit sa main dans son sein, puis il l''en retira et voici qu''elle était couverte de lèpre, blanche comme la neige.'),
('ex',4,7,'crampon1923','Yahweh dit: " Remets ta main dans ton sein, — et il remit sa main dans son sein, puis il la retira de son sein, et voici qu''elle était redevenue semblable à sa chair. —'),
('ex',4,8,'crampon1923','S''ils ne te croient pas, et s''ils n''écoutent pas la voix du premier signe, ils croiront à la voix du second.'),
('ex',4,9,'crampon1923','Et s''ils ne croient pas même à ces deux signes, et n''écoutent pas ta voix, tu prendras de l''eau du fleuve, et tu la répandras sur le sol, et l''eau que tu auras prise du fleuve deviendra du sang sur le sol. "'),
('ex',4,10,'crampon1923','Moïse dit à Yahweh: " Ah! Seigneur, je ne suis pas un homme à la parole facile, et cela dès hier et dès avant-hier, et même encore depuis que vous parlez à votre serviteur; j''ai la bouche et la langue embarrassées. "'),
('ex',4,11,'crampon1923','Yahweh lui dit: " Qui a donné la bouche à l''homme, et qui rend muet ou sourd, voyant ou aveugle? N''est-ce pas moi, Yahweh?'),
('ex',4,12,'crampon1923','Va donc, je serai avec ta bouche et je t''enseignerai ce que tu devras dire. "'),
('ex',4,13,'crampon1923','Moïse dit: " Ah! Seigneur, envoyez votre message par qui vous voudrez l''envoyer. "'),
('ex',4,14,'crampon1923','Alors la colère de Yahweh s''enflamma contre Moïse, et il dit: " N''y a-t-il pas Aaron, ton frère, le Lévite? Je sais qu''il parlera facilement, lui. Et même, voici qu''il vient à ta rencontre et, en te voyant, il se réjouira dans son cœur.'),
('ex',4,15,'crampon1923','Tu lui parleras et tu mettras les paroles dans sa bouche, et moi je serai avec ta bouche et avec sa bouche, et je vous enseignerai ce que vous aurez à faire.'),
('ex',4,16,'crampon1923','C''est lui qui parlera pour toi au peuple; il te servira de bouche, et tu lui seras un Dieu.'),
('ex',4,17,'crampon1923','Quant à ce bâton, prends-le dans ta main; c''est avec quoi tu feras les signes. "'),
('ex',4,18,'crampon1923','Moïse s''en alla. De retour auprès de Jéthro, son beau-père, il lui dit: " Laisse-moi partir, je te prie, et retourner auprès de mes frères qui sont en Egypte, pour voir s''ils sont encore vivants. " Jéthro dit à Moïse: " Va en paix. "'),
('ex',4,19,'crampon1923','Yahweh dit à Moïse, en Madian: " Va, retourne en Egypte, car tous ceux qui en voulaient à ta vie sont morts. "'),
('ex',4,20,'crampon1923','Moïse prit donc sa femme et ses fils, et, les ayant fait monter sur des ânes, il retourna au pays d''Egypte; Moïse prit dans sa main le bâton de Dieu.'),
('ex',4,21,'crampon1923','Yahweh dit à Moïse: " En partant pour retourner en Egypte, considère tous les prodiges que j''ai mis dans ta main: tu les feras devant Pharaon. Et moi, j''endurcirai son cœur, et il ne laissera pas aller le peuple.'),
('ex',4,22,'crampon1923','Tu diras à Pharaon: Ainsi parle Yahweh: " Israël est mon fils, mon premier-né.'),
('ex',4,23,'crampon1923','Je te dis: Laisse aller mon fils, pour qu''il me serve; si tu refuses de le laisser aller, je ferai périr ton fils, ton premier-né. "'),
('ex',4,24,'crampon1923','Sur la route, dans un lieu où Moïse passa la nuit, Yahweh vint à sa rencontre et voulut le faire mourir.'),
('ex',4,25,'crampon1923','Séphora prit une pierre tranchante, coupa le prépuce de son fils, et en toucha les pieds de Moïse, en disant: " Tu es pour moi un époux de sang! "'),
('ex',4,26,'crampon1923','Et Yahweh le laissa. C''est alors qu''elle dit: " Epoux de sang ", à cause de la circoncision.'),
('ex',4,27,'crampon1923','Yahweh dit à Aaron: " Va au-devant de Moïse dans le désert. " Aaron partit et, ayant rencontré Moïse à la montagne de Dieu, il le baisa.'),
('ex',4,28,'crampon1923','Moïse fit connaître à Aaron toutes les paroles avec lesquelles Yahweh l''avait envoyé, et tous les signes qu’il lui avait ordonné de faire.'),
('ex',4,29,'crampon1923','Moïse et Aaron poursuivirent leur chemin, et ils assemblèrent tous les anciens des enfants d''Israël.'),
('ex',4,30,'crampon1923','Aaron rapporta toutes les paroles que Yahweh avait dites à Moïse, et il fit les signes sous les yeux du peuple.'),
('ex',4,31,'crampon1923','Et le peuple crut; ils apprirent que Yahweh avait visité les enfants d''Israël et qu''il avait vu leur souffrance; et, s''étant inclinés, ils adorèrent.'),
('ex',5,1,'crampon1923','Ensuite Moïse et Aaron se rendirent auprès de Pharaon et lui dirent: " Ainsi parle Yahweh, le Dieu d''Israël: Laisse aller mon peuple, pour qu''il célèbre une fête en mon honneur dans le désert. "'),
('ex',5,2,'crampon1923','Pharaon répondit: " Qui est Yahweh pour que j''obéisse à sa voix, en laissant aller Israël? Je ne connais pas Yahweh, et je ne laisserai pas aller Israël. "'),
('ex',5,3,'crampon1923','Ils dirent: " Le Dieu des Hébreux s''est présenté à nous. Permets-nous de faire trois journées de marche au désert, pour offrir des sacrifices à Yahweh, afin qu''il ne nous frappe pas de la peste ou de l''épée. "'),
('ex',5,4,'crampon1923','Mais le roi d''Egypte leur dit: " Pourquoi, Moïse et Aaron, détournez-vous le peuple de son ouvrage? Allez à vos corvées! "'),
('ex',5,5,'crampon1923','Pharaon dit: " Voici que le peuple du pays est maintenant nombreux, et vous lui feriez interrompre ses corvées! "'),
('ex',5,6,'crampon1923','Ce jour-là même, Pharaon donna cet ordre aux exacteurs du peuple et aux scribes:'),
('ex',5,7,'crampon1923','" Vous ne donnerez plus, comme on l''a fait jusqu''ici, de paille au peuple pour faire des briques; qu''ils aillent eux-mêmes ramasser de la paille.'),
('ex',5,8,'crampon1923','Néanmoins vous lui imposerez la quantité de briques qu''ils faisaient auparavant, sans en rien retrancher, car ce sont des paresseux; voilà pourquoi ils crient, en disant: Nous voudrions aller faire des sacrifices à notre Dieu.'),
('ex',5,9,'crampon1923','Qu''on charge de travail ces gens-là; qu''ils soient à la besogne et qu''ils ne prêtent plus l''oreille à des paroles de mensonge. "'),
('ex',5,10,'crampon1923','Les exacteurs du peuple et les scribes vinrent donc dire au peuple: " Ainsi parle Pharaon: Je ne vous donne plus de paille;'),
('ex',5,11,'crampon1923','allez vous-mêmes prendre de la paille où vous en trouverez, car on ne retranchera rien de votre tâche. "'),
('ex',5,12,'crampon1923','Le peuple se répandit dans tout le pays d''Egypte pour ramasser du chaume pour en faire de la paille hachée.'),
('ex',5,13,'crampon1923','Les exacteurs les pressaient, en disant: " Achevez vos travaux, ce qui est fixé pour chaque jour, comme lorsqu''on avait de la paille. "'),
('ex',5,14,'crampon1923','On battit les scribes des enfants d''Israël, que les exacteurs de Pharaon avaient établis sur eux; on disait: " Pourquoi n''avez-vous pas achevé hier et aujourd''hui votre tâche de briques, comme précédemment? "'),
('ex',5,15,'crampon1923','Les scribes des enfants d''Israël allèrent se plaindre à Pharaon, en disant: " Pourquoi en agis-tu ainsi envers tes serviteurs?'),
('ex',5,16,'crampon1923','On ne fournit pas de paille à tes serviteurs, et l''on nous dit: Faites des briques! Et voici, tes serviteurs sont battus, et ton peuple se trouve en faute. "'),
('ex',5,17,'crampon1923','Pharaon répondit: " Vous êtes des paresseux, des paresseux! Voilà pourquoi vous dites: Nous voudrions aller offrir des sacrifices à Yahweh.'),
('ex',5,18,'crampon1923','Et maintenant, allez travailler; on ne vous donnera pas de paille, et vous livrerez la même quantité de briques. "'),
('ex',5,19,'crampon1923','Les scribes des enfants d''Israël virent leur cruelle situation, puisqu''on leur disait: " Vous ne retrancherez rien de vos briques; chaque jour la tâche du jour! "'),
('ex',5,20,'crampon1923','Ayant trouvé Moïse et Aaron, qui se tenaient là pour les attendre à leur sortie de chez Pharaon,'),
('ex',5,21,'crampon1923','ils leur dirent: " Que Yahweh vous voie, et qu''il juge, vous qui avez changé en aversion notre faveur aux yeux de Pharaon et de ses serviteurs, et qui avez mis dans leurs mains une épée pour nous tuer. "'),
('ex',5,22,'crampon1923','Alors Moïse retourna vers Yahweh, et dit: " Seigneur, pourquoi avez-vous fait du mal à ce peuple? pourquoi donc m''avez-vous envoyé?'),
('ex',5,23,'crampon1923','Depuis que je suis allé vers Pharaon pour parler en votre nom, il maltraite ce peuple, et vous n''avez en aucune manière délivré votre peuple. "'),
('ex',6,1,'crampon1923','Yahweh dit à Moïse: " Tu verras bientôt ce que je ferai à Pharaon: contraint par une main puissante, il les laissera aller; contraint par une main puissante, il les chassera de son pays. "'),
('ex',6,2,'crampon1923','Dieu parla à Moïse, en disant: " Je suis Yahweh.'),
('ex',6,3,'crampon1923','Je suis apparu à Abraham, à Isaac et à Jacob comme Dieu tout-puissant, mais sous mon nom de Yahweh, je ne me suis pas fait connaître à eux.'),
('ex',6,4,'crampon1923','J''ai aussi établi mon alliance avec eux pour leur donner le pays de Chanaan, le pays de leurs pèlerinages, où ils ont séjourné en étrangers.'),
('ex',6,5,'crampon1923','J''ai entendu le gémissement des enfants d''Israël que les Egyptiens tiennent dans la servitude, et je me suis souvenu de mon alliance.'),
('ex',6,6,'crampon1923','C''est pourquoi dis aux enfants d''Israël: Je suis Yahweh; je vous affranchirai des corvées des Egyptiens, je vous délivrerai de leur servitude, et je vous sauverai avec un bras étendu et par de grands jugements.'),
('ex',6,7,'crampon1923','Je vous prendrai pour mon peuple, je serai votre Dieu, et vous saurez que je suis Yahweh, votre Dieu, qui vous affranchis des corvées des Egyptiens.'),
('ex',6,8,'crampon1923','Je vous ferai entrer dans le pays que j''ai juré de donner à Abraham, à Isaac et à Jacob; je vous le donnerai en possession: je suis Yahweh. "'),
('ex',6,9,'crampon1923','Ainsi parla Moïse aux enfants d''Israël; mais ils n''écoutèrent pas Moïse, à cause de leur angoisse et de leur dure servitude.'),
('ex',6,10,'crampon1923','Yahweh parla à Moïse, en disant:'),
('ex',6,11,'crampon1923','" Va parler à Pharaon, roi d''Egypte, pour qu''il laisse aller les enfants d''Israël hors de son pays. "'),
('ex',6,12,'crampon1923','Moïse répondit en présence de Yahweh: " Voici, les enfants d''Israël ne m''ont point écouté; comment Pharaon m''écoutera-t-il, moi qui ai la parole difficile? "'),
('ex',6,13,'crampon1923','Yahweh parla à Moïse et à Aaron, et leur donna des ordres au sujet des enfants d''Israël et au sujet de Pharaon, roi d''Egypte, pour faire sortir les enfants d''Israël du pays d''Egypte.'),
('ex',6,14,'crampon1923','Voici les chefs de leurs maisons: Fils de Ruben, premier-né d''Israël: Hénoch, Phallu, Hesron et Charmi; ce sont là les familles de Ruben.'),
('ex',6,15,'crampon1923','Fils de Siméon: Jamuel, Jamin, Ahod, Jachin, Soar, et Saul, fils de la Chananéenne; ce sont là les familles de Siméon.'),
('ex',6,16,'crampon1923','Voici les noms des fils de Lévi avec leurs postérités: Gerson, Caath et Mérari. Les années de la vie de Lévi furent de cent trente-sept ans. —'),
('ex',6,17,'crampon1923','Fils de Gerson: Lobni et Séméi, selon leurs familles. —'),
('ex',6,18,'crampon1923','Fils de Caath: Amram, Isaar, Hébron et Oziel. Les années de la vie de Caath furent de cent trente-trois ans. —'),
('ex',6,19,'crampon1923','Fils de Mérari: Moholi et Musi. — Ce sont là les familles de Lévi avec leurs postérités.'),
('ex',6,20,'crampon1923','Amram prit pour femme Jochabed, sa tante, qui lui enfanta Aaron et Moïse. Les années de la vie d''Amram furent de cent trente-sept ans. —'),
('ex',6,21,'crampon1923','Fils d''Isaar: Coré, Nepheg et Zéchri.'),
('ex',6,22,'crampon1923','Fils d''Oziel: Misaël, Elisaphan et Séthri.'),
('ex',6,23,'crampon1923','Aaron prit pour femme Elisabeth, fille d''Aminadab, sœur de Naasson; et elle lui enfanta Nadab, Abiu, Eléazar et Ithamar.'),
('ex',6,24,'crampon1923','Fils de Coré: Aser, Elcana et Abiasaph; ce sont là les familles des Corites.'),
('ex',6,25,'crampon1923','Eléazar, fils d''Aaron, prit pour femme une des filles de Phuthiel, qui lui enfanta Phinées. Tels sont les chefs des maisons des Lévites, selon leurs familles.'),
('ex',6,26,'crampon1923','Ce sont là l''Aaron et le Moïse auxquels Yahweh dit: " Faites sortir du pays d''Egypte les enfants d''Israël selon leurs armées. "'),
('ex',6,27,'crampon1923','Ce sont eux qui parlèrent à Pharaon, roi d''Egypte, pour faire sortir d''Egypte les enfants d''Israël; c''est ce Moïse et cet Aaron.'),
('ex',6,28,'crampon1923','Lorsque Yahweh parla à Moïse dans le pays d''Egypte,'),
('ex',6,29,'crampon1923','Yahweh dit à Moïse: " Je suis Yahweh. Dis à Pharaon, roi d''Egypte, tout ce que je te dis. "'),
('ex',6,30,'crampon1923','Et Moïse répondit en présence de Yahweh: " Voici, j''ai la parole difficile; comment Pharaon m''écoutera-t-il? "'),
('ex',7,1,'crampon1923','Yahweh dit à Moïse: " Vois, j''ai fait de toi un dieu pour Pharaon, et Aaron, ton frère, sera ton prophète.'),
('ex',7,2,'crampon1923','Toi, tu diras tout ce que je te commanderai, et Aaron, ton frère, parlera à Pharaon, pour qu''il laisse partir de son pays les enfants d''Israël.'),
('ex',7,3,'crampon1923','Et moi, j''endurcirai le cœur de Pharaon, et je multiplierai mes signes et mes prodiges dans le pays d''Egypte.'),
('ex',7,4,'crampon1923','Pharaon ne vous écoutera pas et je mettrai ma main sur l''Egypte, et je ferai sortir du pays d''Egypte mes armées, mon peuple, les enfants d''Israël, par de grands jugements.'),
('ex',7,5,'crampon1923','Les Egyptiens connaîtront que je suis Yahweh, lorsque j''étendrai ma main sur l''Egypte et que je ferai sortir du milieu d''eux les enfants d''Israël. "'),
('ex',7,6,'crampon1923','Moïse et Aaron firent ce que Yahweh leur avait ordonné; ainsi firent-ils.'),
('ex',7,7,'crampon1923','Moïse était âgé de quatre-vingts ans, et Aaron de quatre-vingt-trois ans, lorsqu''ils parlèrent à Pharaon.'),
('ex',7,8,'crampon1923','Yahweh dit à Moïse et à Aaron:'),
('ex',7,9,'crampon1923','" Lorsque Pharaon vous parlera, en disant: Faites un miracle, tu diras à Aaron: Prends ton bâton et jette-le devant Pharaon; il deviendra un serpent. "'),
('ex',7,10,'crampon1923','Moïse et Aaron allèrent auprès de Pharaon, et ils firent ce que Yahweh avait ordonné. Aaron jeta son bâton devant Pharaon et devant ses serviteurs, et il devint un serpent.'),
('ex',7,11,'crampon1923','Pharaon aussi appela ses sages et ses enchanteurs; et les magiciens d''Egypte, eux aussi, firent la même chose par leurs enchantements:'),
('ex',7,12,'crampon1923','ils jetèrent chacun leur bâton, et ces bâtons devinrent des serpents. Mais le bâton d''Aaron engloutit leurs bâtons.'),
('ex',7,13,'crampon1923','Et le cœur de Pharaon s''endurcit, et il n''écouta point Moïse et Aaron, selon que Yahweh l''avait dit.'),
('ex',7,14,'crampon1923','Yahweh dit à Moïse: " Le cœur de Pharaon est endurci; il refuse de laisser aller le peuple.'),
('ex',7,15,'crampon1923','Va vers Pharaon dès le matin; voici qu''il sortira pour aller au bord de l''eau, et tu te tiendras pour l''attendre sur la rive du fleuve. Tu prendras en main le bâton qui a été changé en serpent,'),
('ex',7,16,'crampon1923','et tu lui diras: Yahweh, Dieu des Hébreux, m''a envoyé vers toi pour te dire: Laisse aller mon peuple, afin qu''il me serve dans le désert. Et voici, jusqu''à présent tu n''as point écouté.'),
('ex',7,17,'crampon1923','Ainsi dit Yahweh: A ceci tu connaîtras que je suis Yahweh: je vais frapper les eaux du fleuve avec le bâton qui est dans ma main, et elles seront changées en sang.'),
('ex',7,18,'crampon1923','Les poissons qui sont dans le fleuve mourront, le fleuve deviendra infect, et les Egyptiens répugneront à boire de l''eau du fleuve. "'),
('ex',7,19,'crampon1923','Yahweh dit à Moïse: " Dis à Aaron: Prends ton bâton et étends ta main sur les eaux de l''Egypte, sur ses rivières, sur ses canaux, sur ses étangs et sur tous ses réservoirs d''eau. Elles deviendront du sang, et il y aura du sang dans tout le pays d''Egypte, dans les vases de bois comme dans les vases de pierre. "'),
('ex',7,20,'crampon1923','Moïse et Aaron firent ce que Yahweh avait ordonné. Aaron, levant le bâton, frappa les eaux qui étaient dans le fleuve, sous les yeux de Pharaon et sous les yeux de ses serviteurs, et toutes les eaux du fleuve furent changées en sang.'),
('ex',7,21,'crampon1923','Les poissons qui étaient dans le fleuve moururent, le fleuve devint infect, les Egyptiens ne pouvaient plus boire de l''eau du fleuve, et il y eut du sang dans tout le pays d''Egypte.'),
('ex',7,22,'crampon1923','Mais les magiciens d''Egypte firent la même chose par leurs enchantements, et le cœur de Pharaon s''endurcit, et il n''écouta point Moïse et Aaron, selon que Yahweh l''avait dit.'),
('ex',7,23,'crampon1923','Pharaon s''en retourna et, étant entré dans sa maison, il n''appliqua point son cœur à ces choses.'),
('ex',7,24,'crampon1923','Tous les Egyptiens creusèrent aux environs du fleuve pour trouver de l''eau potable, car ils ne pouvaient boire de l''eau du fleuve.'),
('ex',7,25,'crampon1923','Il s''écoula sept jours, après que Yahweh eut frappé le fleuve.'),
('ex',7,26,'crampon1923','Yahweh dit à Moïse: " Va vers Pharaon, et tu lui diras: Ainsi dit Yahweh: Laisse aller mon peuple, afin qu''il me serve.'),
('ex',7,27,'crampon1923','Si tu refuses de le laisser aller, voici que je vais frapper du fléau des grenouilles toute l''étendue de ton pays.'),
('ex',7,28,'crampon1923','Le fleuve fourmillera de grenouilles; elles monteront et entreront dans ta maison, dans ta chambre à coucher et sur ton lit, dans la maison de tes serviteurs, et au milieu de ton peuple, dans tes fours et dans tes pétrins;'),
('ex',7,29,'crampon1923','sur toi, sur ton peuple et sur tous tes serviteurs les grenouilles monteront. "'),
('ex',8,1,'crampon1923','Yahweh dit à Moïse: " Dis à Aaron: étends ta main avec ton bâton sur les rivières, sur les canaux et sur les étangs, et fais monter les grenouilles sur le pays d''Egypte. "'),
('ex',8,2,'crampon1923','Aaron étendit sa main sur les eaux de l''Egypte, et les grenouilles montèrent et couvrirent le pays d''Egypte.'),
('ex',8,3,'crampon1923','Mais les magiciens firent la même chose par leurs enchantements; ils firent monter les grenouilles sur le pays d''Egypte.'),
('ex',8,4,'crampon1923','Pharaon appela Moïse et Aaron, et leur dit: " Priez Yahweh afin qu''il éloigne les grenouilles de moi et de mon peuple, et je laisserai aller le peuple, pour qu''il offre des sacrifices à Yahweh. "'),
('ex',8,5,'crampon1923','Moïse dit à Pharaon: " Donne-moi tes ordres! Pour quand dois-je faire des prières en ta faveur, en faveur de tes serviteurs et de ton peuple, afin que Yahweh éloigne les grenouilles de toi et de tes maisons, de manière à ce qu''il n''en reste plus que dans le fleuve? "'),
('ex',8,6,'crampon1923','Il répondit: " Pour demain ". Et Moïse dit: " Il en sera ainsi, afin que tu saches que nul n''est pareil à Yahweh, notre Dieu.'),
('ex',8,7,'crampon1923','Les grenouilles se retireront de toi et de tes maisons, de tes serviteurs et de ton peuple; il n''en restera que dans le fleuve. "'),
('ex',8,8,'crampon1923','Moïse et Aaron sortirent de chez Pharaon, et Moïse cria vers Yahweh au sujet des grenouilles dont il avait affligé Pharaon.'),
('ex',8,9,'crampon1923','Yahweh fit selon la parole de Moïse, et les grenouilles moururent dans les maisons, dans les cours et dans les champs.'),
('ex',8,10,'crampon1923','On les entassa en monceaux, et le pays en fut infecté.'),
('ex',8,11,'crampon1923','Mais Pharaon, voyant qu''on respirait, endurcit son cœur, et il n''écouta point Moïse et Aaron, selon que Yahweh l''avait dit.'),
('ex',8,12,'crampon1923','Yahweh dit à Moïse: " Dis à Aaron: Etends ton bâton et frappe la poussière de la terre, et elle se changera en moustiques dans tout le pays d''Egypte. "'),
('ex',8,13,'crampon1923','Ils firent ainsi; Aaron étendit sa main avec son bâton et frappa la poussière de la terre, et les moustiques furent sur les hommes et sur les animaux. Toute la poussière de la terre fut changée en moustiques, dans tout le pays d''Egypte.'),
('ex',8,14,'crampon1923','Les magiciens firent de même avec leurs enchantements, afin de produire des moustiques; mais ils ne le purent pas. Les moustiques étaient sur les hommes et sur les animaux.'),
('ex',8,15,'crampon1923','Et les magiciens dirent à Pharaon: " C''est le doigt d''un dieu! " Et le cœur de Pharaon s''endurcit, et il ne les écouta pas, selon que Yahweh l''avait dit.'),
('ex',8,16,'crampon1923','Yahweh dit à Moïse: " Lève-toi de bon matin et présente-toi devant Pharaon, au moment où il sort pour aller au bord de l''eau. Tu lui diras: Ainsi parle Yahweh: Laisse aller mon peuple afin qu''il me serve.'),
('ex',8,17,'crampon1923','Si tu ne laisses pas aller mon peuple, je vais envoyer des scarabées contre toi, contre tes serviteurs, contre ton peuple et contre tes maisons; les maisons des Egyptiens seront remplies de scarabées, ainsi que la terre qu''ils habitent.'),
('ex',8,18,'crampon1923','Mais je distinguerai, ce jour-là, le pays de Gessen, où mon peuple habite, et là il n''y aura point de scarabées, afin que tu saches que moi, Yahweh, je suis au milieu de cette terre.'),
('ex',8,19,'crampon1923','J''établirai ainsi une différence entre mon peuple et ton peuple; c''est demain que ce signe aura lieu. "'),
('ex',8,20,'crampon1923','Yahweh fit ainsi; il vint une multitude de scarabées dans la maison de Pharaon et de ses serviteurs, et tout le pays d''Egypte fut ravagé par les scarabées.'),
('ex',8,21,'crampon1923','Pharaon appela Moïse et Aaron, et leur dit: " Allez, offrez des sacrifices à votre Dieu dans ce pays. "'),
('ex',8,22,'crampon1923','Moïse répondit: " Il ne convient pas de faire ainsi, car c''est une abomination pour les Egyptiens que les sacrifices que nous offrons à Yahweh, notre Dieu; et si nous offrons, sous les yeux des Egyptiens, des sacrifices qui sont pour eux des abominations, ne nous lapideront-ils pas?'),
('ex',8,23,'crampon1923','Nous irons à trois journées de marche dans le désert pour offrir des sacrifices à Yahweh, notre Dieu, selon qu''il nous le dira. "'),
('ex',8,24,'crampon1923','Pharaon dit: " Pour moi, je vous laisserai aller, pour offrir des sacrifices à Yahweh, votre Dieu, dans le désert; seulement ne vous éloignez pas trop dans votre marche. Faites des prières pour moi. "'),
('ex',8,25,'crampon1923','Moïse répondit: Voici, je vais sortir de chez toi, et je prierai Yahweh, et demain les scarabées se retireront de Pharaon, de ses serviteurs et de son peuple. Mais que Pharaon ne trompe plus, en ne permettant pas au peuple d''aller offrir des sacrifices à Yahweh! "'),
('ex',8,26,'crampon1923','Moïse sortit de chez Pharaon et pria Yahweh.'),
('ex',8,27,'crampon1923','Et Yahweh fit selon la parole de Moïse, et les scarabées s''éloignèrent de Pharaon, de ses serviteurs et de son peuple; il n''en resta pas un seul.'),
('ex',8,28,'crampon1923','Mais Pharaon endurcit son cœur cette fois encore, et il ne laissa pas aller le peuple.'),
('ex',9,1,'crampon1923','Yahweh dit à Moïse: " Va vers Pharaon et dis-lui: Ainsi parle Yahweh, le Dieu des Hébreux: Laisse aller mon peuple, afin qu''il me serve.'),
('ex',9,2,'crampon1923','Si tu refuses de le laisser aller, et si tu le retiens encore,'),
('ex',9,3,'crampon1923','voici que la main de Yahweh sera sur tes troupeaux qui sont dans les champs, sur les chevaux, sur les ânes, sur les chameaux, sur les bœufs et sur les brebis: ce sera une peste très meurtrière.'),
('ex',9,4,'crampon1923','Yahweh fera une distinction entre les troupeaux d''Israël et les troupeaux des Egyptiens, et il ne périra rien de tout ce qui appartient aux enfants d''Israël. "'),
('ex',9,5,'crampon1923','Yahweh fixa le moment, en disant: " Demain Yahweh fera cela dans le pays. "'),
('ex',9,6,'crampon1923','Et Yahweh fit ainsi dès le lendemain. Tout le bétail des Egyptiens périt, et il ne mourut pas une bête des troupeaux des enfants d''Israël.'),
('ex',9,7,'crampon1923','Pharaon prit des informations, et voici, pas une bête des troupeaux d''Israël n''avait péri. Mais le cœur de Pharaon s''endurcit, et il ne laissa pas aller le peuple.'),
('ex',9,8,'crampon1923','Yahweh dit à Moïse et à Aaron: " Prenez plein vos mains de cendre de fournaise, et que Moïse la jette vers le ciel sous les yeux de Pharaon;'),
('ex',9,9,'crampon1923','qu''elle devienne une fine poussière sur tout le pays d''Egypte, et qu''elle forme, dans tout le pays d''Egypte, sur les hommes et sur les animaux, des tumeurs bourgeonnant en pustules. "'),
('ex',9,10,'crampon1923','Ils prirent de la cendre de fournaise et se présentèrent devant Pharaon; Moïse la jeta vers le ciel, et elle produisit sur les hommes et sur les animaux des tumeurs bourgeonnant en pustules.'),
('ex',9,11,'crampon1923','Les magiciens ne purent se tenir devant Moïse à cause des tumeurs, car les tumeurs étaient sur les magiciens, comme sur tous les Egyptiens.'),
('ex',9,12,'crampon1923','Et Yahweh endurcit le cœur de Pharaon, et Pharaon n''écouta pas Moïse et Aaron, selon que Yahweh l''avait dit à Moïse.'),
('ex',9,13,'crampon1923','Yahweh dit à Moïse: " Lève-toi de bon matin et présente-toi devant Pharaon; tu lui diras: Ainsi parle Yahweh, Dieu des Hébreux: Laisse aller mon peuple, afin qu''il me serve.'),
('ex',9,14,'crampon1923','Car, cette fois, je vais envoyer tous mes fléaux contre ton cœur, ainsi que sur tes serviteurs et sur ton peuple, afin que tu saches que nul n''est semblable à moi par toute la terre.'),
('ex',9,15,'crampon1923','Si j''avais étendu ma main et que je t''eusse frappé de la peste, toi et ton peuple, tu aurais été effacé de la terre.'),
('ex',9,16,'crampon1923','Mais à cette fin je t''ai laissé subsister, afin que tu voies ma puissance, et qu''on célèbre mon nom par toute la terre.'),
('ex',9,17,'crampon1923','Tu te mets encore comme une barrière devant mon peuple pour ne pas le laisser aller!'),
('ex',9,18,'crampon1923','Voici que, demain, à cette heure, je ferai pleuvoir une grêle si forte, qu''il n''y en a pas eu de semblable en Egypte depuis le jour où elle a été fondée jusqu''à présent.'),
('ex',9,19,'crampon1923','Et maintenant fais mettre en sûreté ton bétail et tout ce que tu as dans les champs; car tous les hommes et tous les animaux qui se trouveront dans les champs et qui ne seront pas ramenés dans les maisons seront frappés de la grêle et périront. "'),
('ex',9,20,'crampon1923','Ceux des serviteurs de Pharaon qui craignirent la parole de Yahweh firent retirer dans les maisons leurs serviteurs et leurs troupeaux.'),
('ex',9,21,'crampon1923','Mais ceux qui n''appliquèrent pas leur cœur à la parole de Yahweh laissèrent leurs serviteurs et leurs troupeaux dans les champs.'),
('ex',9,22,'crampon1923','Yahweh dit à Moïse: " Etends ta main vers le ciel, afin qu''il tombe de la grêle dans tout le pays d''Egypte sur les hommes, sur les animaux et sur toutes les herbes des champs. "'),
('ex',9,23,'crampon1923','Moïse étendit son bâton vers le ciel, et Yahweh envoya le tonnerre et la grêle, et le feu se précipitait sur la terre. Yahweh fit pleuvoir de la grêle sur le pays d''Egypte.'),
('ex',9,24,'crampon1923','Il tomba de la grêle et du feu mêlé à la grêle; elle était si forte qu''il n''y en avait point eu de semblable dans tout le pays d''Egypte, depuis qu''il forme une nation.'),
('ex',9,25,'crampon1923','La grêle frappa, dans tout le pays d''Egypte, tout ce qui était dans les champs, depuis les hommes jusqu''aux animaux; la grêle frappa aussi toutes les herbes des champs et brisa tous les arbres des champs.'),
('ex',9,26,'crampon1923','Il n''y eut que dans le pays de Gessen, où étaient les enfants d''Israël, qu''il ne tomba pas de grêle.'),
('ex',9,27,'crampon1923','Pharaon fit appeler Moïse et Aaron, et leur dit: " Cette fois, j''ai péché; c''est Yahweh qui est juste, et moi et mon peuple qui sommes coupables.'),
('ex',9,28,'crampon1923','Priez Yahweh, pour qu''il n''y ait plus de tonnerres et de grêle, et je vous laisserai aller et l''on ne vous retiendra plus. "'),
('ex',9,29,'crampon1923','Moïse lui dit: " En sortant de la ville, je lèverai mes mains vers Yahweh, et les tonnerres cesseront, et il n''y aura plus de grêle, afin que tu saches que la terre est à Yahweh.'),
('ex',9,30,'crampon1923','Mais je sais que toi et tes serviteurs, vous ne craindrez pas encore Yahweh Dieu. "'),
('ex',9,31,'crampon1923','Le lin et l''orge avaient été frappés, car l''orge était en épis et le lin en fleurs;'),
('ex',9,32,'crampon1923','mais le froment et l''épeautre n''avaient pas été frappés, parce qu''ils sont tardifs.'),
('ex',9,33,'crampon1923','Moïse quitta Pharaon et sortit de la ville; il leva ses mains vers Yahweh, et les tonnerres et la grêle cessèrent, et la pluie ne tomba plus sur la terre.'),
('ex',9,34,'crampon1923','Pharaon, voyant que la pluie, la grêle et les tonnerres avaient cessé, continua de pécher,'),
('ex',9,35,'crampon1923','et il appesantit son cœur, lui et ses serviteurs. Le cœur de Pharaon s''endurcit, et il ne laissa pas aller les enfants d''Israël, selon que Yahweh l''avait dit par l''intermédiaire de Moïse.'),
('ex',10,1,'crampon1923','Yahweh dit à Moïse: " Va vers Pharaon, car j''ai appesanti son cœur et le cœur de ses serviteurs, afin d''opérer mes signes au milieu d''eux'),
('ex',10,2,'crampon1923','et afin que tu racontes aux oreilles de ton fils et du fils de ton fils quelles grandes choses j''ai faites en Egypte et quels signes j''ai opérés au milieu d''eux; et vous saurez que je suis Yahweh. "'),
('ex',10,3,'crampon1923','Moïse et Aaron allèrent vers Pharaon et lui dirent: " Ainsi parle Yahweh, le Dieu des Hébreux: Jusques à quand refuseras-tu de t''humilier devant moi? Laisse aller mon peuple, afin qu''il me serve.'),
('ex',10,4,'crampon1923','Si tu refuses de laisser aller mon peuple, voici que je ferai venir demain des sauterelles dans toute l''étendue de ton pays.'),
('ex',10,5,'crampon1923','Elles couvriront la face de la terre, et l''on ne pourra plus voir la terre; elles dévoreront le reste qui a échappé, ce que vous a laissé la grêle, et elles dévoreront tous les arbres qui croissent dans vos champs;'),
('ex',10,6,'crampon1923','elles rempliront tes maisons, les maisons de tous tes serviteurs et celles de tous les Egyptiens. Tes pères et les pères de tes pères n''ont jamais vu pareille calamité depuis qu''ils existent sur la terre jusqu''à ce jour. " Moïse se retira et sortit de chez Pharaon.'),
('ex',10,7,'crampon1923','Les serviteurs de Pharaon lui dirent: " Jusques à quand cet homme sera-t-il pour nous un piège? Laisse aller ces gens, et qu''ils servent Yahweh leur Dieu. Ne vois-tu pas encore que l''Egypte va à sa ruine? "'),
('ex',10,8,'crampon1923','On fit revenir Moïse et Aaron auprès de Pharaon, et il leur dit: " Allez, servez Yahweh, votre Dieu. Qui sont ceux qui doivent y aller? "'),
('ex',10,9,'crampon1923','Moïse répondit: " Nous irons avec nos enfants et nos vieillards, avec nos fils et nos filles, avec nos brebis et nos bœufs; car c''est pour nous une fête en l''honneur de Yahweh. "'),
('ex',10,10,'crampon1923','Pharaon leur dit: " Que Yahweh soit avec vous, comme je vais vous laisser aller, vous et vos enfants! Prenez garde, car vous avez de mauvais desseins!'),
('ex',10,11,'crampon1923','Non, non; allez, vous les hommes, et servez Yahweh, puisque c''est là ce que vous demandez. " Et on les chassa de devant Pharaon.'),
('ex',10,12,'crampon1923','Yahweh dit à Moïse: " Etends ta main sur le pays d''Egypte pour les sauterelles; qu''elles montent sur le pays d''Egypte; qu''elles dévorent toute l''herbe de la terre, tout ce que la grêle a laissé. "'),
('ex',10,13,'crampon1923','Moïse étendit son bâton sur le pays d''Egypte, et Yahweh fit souffler sur le pays un vent d''orient tout ce jour-là et toute la nuit. Le matin venu, le vent d''orient avait apporté les sauterelles.'),
('ex',10,14,'crampon1923','Les sauterelles montèrent sur tout le pays d''Egypte et se posèrent sur tout le territoire de l''Egypte, en si grande quantité, que jamais il n''y avait eu et qu''il n''y aura jamais rien de semblable.'),
('ex',10,15,'crampon1923','Elles couvrirent la face de toute la terre, et la terre en fut assombrie; elles dévorèrent toute l''herbe de la terre et tous les fruits des arbres, ce que la grêle avait laissé, et il ne resta aucune verdure aux arbres ni à l''herbe des champs, dans tout le pays d''Egypte.'),
('ex',10,16,'crampon1923','Pharaon appela aussitôt Moïse et Aaron, et dit: " J''ai péché contre Yahweh, votre Dieu, et contre vous.'),
('ex',10,17,'crampon1923','Mais pardonne mon péché encore cette fois seulement; et priez Yahweh, votre Dieu, afin qu''il éloigne de moi au moins ce fléau mortel. "'),
('ex',10,18,'crampon1923','Moïse sortit de chez Pharaon et pria Yahweh.'),
('ex',10,19,'crampon1923','Et Yahweh fit souffler un vent d''occident très fort, qui emporta les sauterelles et les poussa dans la mer Rouge; il ne resta pas une seule sauterelle dans toute l''étendue de l''Egypte. —'),
('ex',10,20,'crampon1923','Yahweh endurcit le cœur de Pharaon, et Pharaon ne laissa point aller les enfants d''Israël.'),
('ex',10,21,'crampon1923','Yahweh dit à Moïse: " Etends ta main vers le ciel, et qu''il y ait des ténèbres sur le pays d''Egypte, qu''on palpe les ténèbres. "'),
('ex',10,22,'crampon1923','Moïse étendit sa main vers le ciel, et il y eut d''épaisses ténèbres dans tout le pays d''Egypte, pendant trois jours.'),
('ex',10,23,'crampon1923','Ils ne se voyaient pas les uns les autres, et nul ne se leva de la place où il était, pendant trois jours; mais tous les enfants d''Israël avaient de la lumière dans les lieux qu''ils habitaient.'),
('ex',10,24,'crampon1923','Pharaon appela Moïse, et dit: " Allez, servez Yahweh. Vos brebis et vos bœufs seuls resteront, et vos petits enfants mêmes pourront aller avec vous. "'),
('ex',10,25,'crampon1923','Moïse répondit: " Tu dois mettre entre nos mains de quoi faire des sacrifices et des holocaustes à Yahweh, notre Dieu.'),
('ex',10,26,'crampon1923','Nos troupeaux viendront aussi avec nous; il n''en restera pas un ongle; car c''est d''eux que nous prendrons de quoi servir Yahweh, notre Dieu; et nous ne savons pas nous-mêmes, jusqu''à ce que nous soyons arrivés là, avec quoi nous devons servir Yahweh. "'),
('ex',10,27,'crampon1923','Yahweh endurcit le cœur de Pharaon, et Pharaon ne voulut pas les laisser aller.'),
('ex',10,28,'crampon1923','Pharaon dit à Moïse: " Sors de chez moi! Garde-toi de paraître encore en ma présence, car le jour où tu paraîtras en ma présence, tu mourras. "'),
('ex',10,29,'crampon1923','Et Moïse répondit: " Tu l''as dit: je ne paraîtrai plus devant toi. "'),
('ex',11,1,'crampon1923','Yahweh dit à Moïse: " Je ferai venir encore une seule plaie sur Pharaon et sur l''Egypte et, après cela, il vous laissera partir d''ici; et lorsqu''il vous laissera aller tout à fait, il vous chassera même d''ici.'),
('ex',11,2,'crampon1923','Parle donc au peuple pour que chaque homme demande à son voisin et chaque femme à sa voisine des objets d''argent et des objets d''or. "'),
('ex',11,3,'crampon1923','Et Yahweh fit trouver faveur au peuple aux yeux des Egyptiens; Moïse lui-même était très considéré dans le pays d''Egypte aux yeux des serviteurs de Pharaon et aux yeux du peuple.'),
('ex',11,4,'crampon1923','Moïse dit: " Ainsi parle Yahweh: Au milieu de la nuit je passerai au travers de l''Egypte;'),
('ex',11,5,'crampon1923','et tout premier-né dans le pays d''Egypte mourra, depuis le premier-né de Pharaon assis sur son trône, jusqu''au premier-né de la servante qui est derrière la meule, et tout premier-né du bétail.'),
('ex',11,6,'crampon1923','Il y aura dans tout le pays d''Egypte une grande clameur, telle qu''il n''y en a point eu et qu''il n''y en aura plus de semblable.'),
('ex',11,7,'crampon1923','Mais parmi tous les enfants d''Israël, personne, depuis les hommes jusqu''aux animaux, pas même un chien, ne remuera sa langue, afin que vous sachiez quelle différence Yahweh fait entre l''Egypte et Israël.'),
('ex',11,8,'crampon1923','Alors tous tes serviteurs qui sont ici descendront vers moi et se prosterneront devant moi, en disant: Sors, toi et tout le peuple qui est à ta suite! Après quoi, je sortirai. " Et Moïse sortit de chez Pharaon en grande colère.'),
('ex',11,9,'crampon1923','Yahweh dit à Moïse: " Pharaon ne vous écoutera point, afin que mes prodiges se multiplient dans le pays d''Egypte. "'),
('ex',11,10,'crampon1923','Moïse et Aaron opérèrent tous ces prodiges devant Pharaon, et Yahweh endurcit le cœur de Pharaon, et il ne laissa point aller les enfants d''Israël hors de son pays.'),
('ex',12,1,'crampon1923','Yahweh dit à Moïse et à Aaron dans le pays d''Egypte:'),
('ex',12,2,'crampon1923','" Que ce mois-ci soit pour vous le commencement des mois; il sera pour vous le premier des mois de l''année.'),
('ex',12,3,'crampon1923','Parlez à toute l''assemblée d''Israël, et dites: Le dixième jour de ce mois, que chacun prenne un agneau par famille, un agneau par maison.'),
('ex',12,4,'crampon1923','Si la maison est trop peu nombreuse pour un agneau, on le prendra en commun avec le voisin le plus proche, selon le nombre des personnes; vous compterez pour cet agneau d''après ce que chacun peut manger.'),
('ex',12,5,'crampon1923','Ce sera un agneau sans défaut, mâle, âgé d''un an; vous prendrez, soit un agneau, soit un chevreau.'),
('ex',12,6,'crampon1923','Vous le garderez jusqu''au quatorzième jour de ce mois, et toute l''assemblée d''Israël l''immolera entre les deux soirs.'),
('ex',12,7,'crampon1923','On prendra de son sang, et on en mettra sur les deux montants et sur le linteau de la porte, dans les maisons où on le mangera.'),
('ex',12,8,'crampon1923','On en mangera la chair cette nuit-là; on la mangera rôtie au feu, avec des pains sans levain et des herbes amères.'),
('ex',12,9,'crampon1923','Vous n''en mangerez rien cru ou bouilli dans l''eau, mais tout sera rôti au feu, tête, jambes et entrailles.'),
('ex',12,10,'crampon1923','Vous n''en laisserez rien jusqu''au matin, et, s''il en reste quelque chose, vous le brûlerez au feu.'),
('ex',12,11,'crampon1923','Vous le mangerez ainsi: les reins ceints, les sandales aux pieds, et le bâton à la main, et vous le mangerez à la hâte. C''est la Pâque de Yahweh.'),
('ex',12,12,'crampon1923','Je passerai cette nuit-là, par le pays d''Egypte, et je frapperai de mort tous les premiers-nés du pays d''Egypte, depuis les hommes jusqu''aux animaux, et j''exécuterai des jugements sur tous les dieux de l''Egypte. Je suis Yahweh.'),
('ex',12,13,'crampon1923','Le sang sera un signe en votre faveur sur les maisons où vous êtes: je verrai le sang et je passerai par-dessus vous, et il n''y aura point pour vous de plaie meurtrière quand je frapperai le pays d''Egypte.'),
('ex',12,14,'crampon1923','Vous conserverez le souvenir de ce jour, et vous le célébrerez par une fête en l''honneur de Yahweh; vous le célébrerez de génération en génération comme une institution perpétuelle.'),
('ex',12,15,'crampon1923','Pendant sept jours, vous mangerez des pains sans levain; dès le premier jour il n''y aura plus de levain dans vos maisons; car quiconque mangera du pain levé, du premier jour au septième, sera retranché d''Israël.'),
('ex',12,16,'crampon1923','Le premier jour, vous aurez une sainte assemblée, et le septième jour, vous aurez une sainte assemblée. On ne fera aucun travail pendant ces jours-là; vous pourrez seulement préparer la nourriture de chacun.'),
('ex',12,17,'crampon1923','Vous observerez les azymes, car c''est en ce jour même que j''ai fait sortir vos armées du pays d''Egypte. Vous observerez ce jour de génération en génération comme une institution perpétuelle.'),
('ex',12,18,'crampon1923','Le premier mois, le quatorzième jour du mois, au soir, vous mangerez des pains sans levain jusqu''au soir du vingt et unième jour.'),
('ex',12,19,'crampon1923','Sept jours durant, il ne doit pas se trouver de levain dans vos maisons, car quiconque mangera du pain levé sera retranché de l''assemblée d''Israël, que ce soit un étranger ou un indigène.'),
('ex',12,20,'crampon1923','Vous ne mangerez point de pain levé; dans toutes vos demeures vous mangerez des pains sans levain. "'),
('ex',12,21,'crampon1923','Moïse convoqua tous les anciens d''Israël, et leur dit: " Choisissez et prenez un agneau pour vos familles, et immolez la Pâque.'),
('ex',12,22,'crampon1923','Puis, prenant un bouquet d''hysope, vous le tremperez dans le sang qui sera dans le bassin, et vous toucherez avec le sang qui sera dans le bassin le linteau et les deux montants de la porte. Nul d''entre vous ne sortira de l''entrée de sa maison jusqu''au matin.'),
('ex',12,23,'crampon1923','Yahweh passera pour frapper l''Egypte et, en voyant le sang sur le linteau et sur les deux montants, Yahweh passera vos portes, et il ne permettra pas au Destructeur d''entrer dans vos maisons pour frapper.'),
('ex',12,24,'crampon1923','Vous observerez cet ordre comme une institution pour vous et pour vos enfants à perpétuité.'),
('ex',12,25,'crampon1923','Lorsque vous serez entrés dans le pays que Yahweh vous donnera, selon sa promesse, vous observerez ce rite sacré.'),
('ex',12,26,'crampon1923','Et quand vos enfants vous diront: Quelle signification a pour vous ce rite sacré?'),
('ex',12,27,'crampon1923','vous répondrez: C''est un sacrifice de Pâque en l''honneur de Yahweh, qui a passé par-dessus les maisons des enfants d''Israël en Egypte, lorsqu''il frappa l''Egypte et sauva nos maisons. " Le peuple s''inclina et se prosterna.'),
('ex',12,28,'crampon1923','Et les enfants d''Israël s''en allèrent et firent ce que Yahweh avait ordonné à Moïse et à Aaron; ainsi firent-ils.'),
('ex',12,29,'crampon1923','Au milieu de la nuit, Yahweh frappa tous les premiers-nés dans le pays d''Egypte, depuis le premier-né de Pharaon assis sur son trône, jusqu''au premier-né du captif dans sa prison, et à tous les premiers-nés des animaux.'),
('ex',12,30,'crampon1923','Pharaon se leva pendant la nuit, lui et tous ses serviteurs, et tous les Egyptiens, et il y eut une grande clameur en Egypte, car il n''y avait point de maison où il n''y eût un mort.'),
('ex',12,31,'crampon1923','Dans la nuit même, Pharaon appela Moïse et Aaron, et leur dit: " Levez-vous, sortez du milieu de mon peuple, vous et les enfants d''Israël, et allez servir Yahweh, comme vous l''avez dit.'),
('ex',12,32,'crampon1923','Prenez vos brebis et vos bœufs, comme vous l''avez dit; allez, et bénissez-moi. "'),
('ex',12,33,'crampon1923','Les Egyptiens pressaient vivement le peuple, ayant hâte de le renvoyer du pays, car ils disaient: " Nous sommes tous morts! "'),
('ex',12,34,'crampon1923','Le peuple emporta sa pâte avant qu''elle fût levée; ayant serré dans leurs manteaux les corbeilles, ils les mirent sur leurs épaules.'),
('ex',12,35,'crampon1923','Les enfants d''Israël firent selon la parole de Moïse; ils demandèrent aux Egyptiens des objets d''argent, des objets d''or et des vêtements.'),
('ex',12,36,'crampon1923','Et Yahweh avait fait trouver au peuple faveur aux yeux des Egyptiens, qui accueillirent leur demande. Et ils dépouillèrent les Egyptiens.'),
('ex',12,37,'crampon1923','Les enfants d''Israël partirent de Ramsès pour Socoth, au nombre d''environ six cent mille piétons, sans les enfants.'),
('ex',12,38,'crampon1923','En outre, une grande multitude de gens de toute sorte monta avec eux; ils avaient aussi des troupeaux considérables de brebis et de bœufs.'),
('ex',12,39,'crampon1923','Ils cuisirent en galettes non levées la pâte qu''ils avaient emportée d''Egypte; car elle n''était pas levée, parce qu''ils avaient été chassés d''Egypte sans pouvoir tarder, ni prendre de provisions avec eux.'),
('ex',12,40,'crampon1923','Le séjour des enfants d''Israël en Egypte fut de quatre cents trente ans.'),
('ex',12,41,'crampon1923','Et au bout de quatre cent trente ans, ce jour-là même, toutes les armées de Yahweh sortirent du pays d''Egypte.'),
('ex',12,42,'crampon1923','Ce fut une nuit de veille pour Yahweh quand il fit sortir Israël du pays d''Egypte; cette même nuit sera une veille en l''honneur de Yahweh, pour tous les enfants d''Israël selon leurs générations.'),
('ex',12,43,'crampon1923','Yahweh dit à Moïse et à Aaron: " Voici une ordonnance au sujet de la Pâque: Aucun étranger n''en mangera.'),
('ex',12,44,'crampon1923','Tu circonciras tout esclave acquis à prix d''argent, et il en mangera;'),
('ex',12,45,'crampon1923','mais le domicilié et le mercenaire n''en mangeront point.'),
('ex',12,46,'crampon1923','On ne la mangera que dans la maison; vous n''emporterez point de chair hors de la maison, et vous ne briserez aucun os.'),
('ex',12,47,'crampon1923','Toute l''assemblée d''Israël fera la Pâque.'),
('ex',12,48,'crampon1923','Si un étranger séjournant chez toi veut faire la Pâque de Yahweh, tout mâle de sa maison devra être circoncis, et alors il s''approchera pour la faire, et il sera comme l''indigène du pays mais aucun incirconcis n''en mangera.'),
('ex',12,49,'crampon1923','Une même loi sera pour l''indigène et pour l''étranger séjournant au milieu de vous. "'),
('ex',12,50,'crampon1923','Tous les enfants d''Israël firent ce que Yahweh avait ordonné à Moïse et à Aaron; ainsi firent-ils.'),
('ex',12,51,'crampon1923','Et ce même jour, Yahweh fit sortir du pays d''Egypte les enfants d''Israël selon leurs armées.'),
('ex',13,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('ex',13,2,'crampon1923','" Consacre-moi tout premier-né, tout premier-né parmi les enfants d''Israël, aussi bien des hommes que des animaux; il m''appartient. "'),
('ex',13,3,'crampon1923','Moïse dit au peuple: " Souvenez-vous du jour où vous êtes sortis d''Egypte, de la maison de servitude; car c''est par la puissance de sa main que Yahweh vous en a fait sortir. On ne mangera point de pain levé.'),
('ex',13,4,'crampon1923','Vous sortez aujourd''hui, dans le mois des épis.'),
('ex',13,5,'crampon1923','Quand Yahweh t''aura fait entrer dans le pays des Chananéens, des Héthéens, des Amorrhéens, des Hévéens et des Jébuséens, qu''il a juré à tes pères de te donner, pays où coulent le lait et le miel, tu observeras ce rite dans ce même mois.'),
('ex',13,6,'crampon1923','Pendant sept jours, tu mangeras des pains sans levain, et le septième jour, il y aura une fête en l''honneur de Yahweh.'),
('ex',13,7,'crampon1923','On mangera des pains sans levain pendant les sept jours; on ne verra pas chez toi de pain levé, on ne verra pas chez toi de levain, dans toute l''étendue de ton pays.'),
('ex',13,8,'crampon1923','Tu diras alors à ton fils: C''est en mémoire de ce que Yahweh a fait pour moi, lorsque je suis sorti d''Egypte.'),
('ex',13,9,'crampon1923','Ce sera pour toi comme un signe sur ta main et comme un souvenir entre tes yeux, afin que la loi de Yahweh soit dans ta bouche; car c''est par sa main puissante que Yahweh t''a fait sortir d''Egypte.'),
('ex',13,10,'crampon1923','Tu observeras cette ordonnance au temps fixé, d''année en année.'),
('ex',13,11,'crampon1923','Quand Yahweh t''aura fait entrer dans le pays des Chananéens, comme il l''a juré à toi et à tes pères, et qu''il te l''aura donné,'),
('ex',13,12,'crampon1923','tu consacreras à Yahweh tout premier-né, même tout premier-né des animaux qui seront à toi: les mâles appartiennent à Yahweh.'),
('ex',13,13,'crampon1923','Tu rachèteras avec un agneau tout premier-né de l''âne, et, si tu ne le rachètes pas, tu lui briseras la nuque. Tu rachèteras aussi tout premier-né de l''homme parmi tes fils.'),
('ex',13,14,'crampon1923','Et lorsque ton fils t''interrogera un jour, en disant: Que signifie cela? tu lui répondras: Par sa main puissante Yahweh nous a fait sortir d''Egypte, de la maison de servitude.'),
('ex',13,15,'crampon1923','Comme Pharaon s''obstinait à ne point nous laisser aller, Yahweh fit mourir tous les premiers-nés dans le pays d''Egypte, depuis les premiers-nés des hommes jusqu''aux premiers-nés des animaux. Voilà pourquoi j''offre en sacrifice à Yahweh tout mâle premier-né des animaux, et je rachète tout premier-né de mes fils.'),
('ex',13,16,'crampon1923','Ce sera comme un signe sur ta main et comme des fronteaux entre tes yeux; car c''est par la puissance de sa main que Yahweh nous a fait sortir d''Egypte. "'),
('ex',13,17,'crampon1923','Lorsque Pharaon laissa aller le peuple, Dieu ne le conduisit point par le chemin du pays des Philistins, quoique le plus court; car Dieu dit: " Le peuple pourrait se repentir en voyant la guerre, et retourner en Egypte. "'),
('ex',13,18,'crampon1923','Mais Dieu fit faire au peuple un détour par le chemin du désert, vers la mer Rouge. Les enfants d''Israël montèrent en bon ordre hors du pays d''Egypte.'),
('ex',13,19,'crampon1923','Moïse prit avec lui les os de Joseph; car Joseph avait fait jurer les enfants d''Israël, en disant: " Dieu vous visitera, et vous emporterez avec vous mes os loin d''ici. "'),
('ex',13,20,'crampon1923','Etant sortis de Socoth, ils campèrent à Etham, à l''extrémité du désert.'),
('ex',13,21,'crampon1923','Yahweh allait devant eux, le jour dans une colonne de nuée, pour les guider dans leur chemin, et la nuit dans une colonne de feu, pour les éclairer, afin qu''ils pussent marcher le jour et la nuit.'),
('ex',13,22,'crampon1923','La colonne de nuée ne se retira point de devant le peuple pendant le jour, ni la colonne de feu pendant la nuit.'),
('ex',14,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('ex',14,2,'crampon1923','" Parle aux enfants d''Israël; qu''ils changent de direction et qu''ils viennent camper devant Phihahiroth, entre Magdalum et la mer, vis-à-vis de Beelséphon; vous camperez en face de ce lieu, près de la mer.'),
('ex',14,3,'crampon1923','Pharaon dira des enfants d''Israël: Ils sont égarés dans le pays; le désert les tient enfermés.'),
('ex',14,4,'crampon1923','Et j''endurcirai le cœur de Pharaon, et il les poursuivra; je ferai éclater ma gloire dans Pharaon et dans toute son armée, et les Egyptiens sauront que je suis Yahweh. " Et les enfants d''Israël firent ainsi.'),
('ex',14,5,'crampon1923','On annonça au roi d''Egypte que le peuple avait pris la fuite. Alors le cœur de Pharaon et celui de ses serviteurs furent changés à l''égard du peuple; ils dirent: " Qu''avons-nous fait de laisser aller Israël et de nous priver de ses services? "'),
('ex',14,6,'crampon1923','Et Pharaon fit atteler son char, et il prit son peuple avec lui.'),
('ex',14,7,'crampon1923','Il prit six cents chars d''élite, et tous les chars de l''Egypte, et sur tous il y avait des chefs.'),
('ex',14,8,'crampon1923','Yahweh endurcit le cœur de Pharaon, roi d''Egypte, et Pharaon poursuivit les enfants d''Israël; et les enfants d''Israël étaient sortis par une main élevée.'),
('ex',14,9,'crampon1923','Les Egyptiens les poursuivirent donc et les atteignirent comme ils étaient campés près de la mer; tous les chevaux des chars de Pharaon, ses cavaliers et son armée les atteignirent près de Phihahiroth, vis-à-vis de Beelsephon.'),
('ex',14,10,'crampon1923','Pharaon approchait. Les enfants d''Israël levèrent les yeux, et voici, les Egyptiens étaient en marche derrière eux; et les enfants d''Israël, saisis d''une grande frayeur, poussèrent des cris vers Yahweh.'),
('ex',14,11,'crampon1923','Ils dirent à Moïse: " N''y avait-il donc pas des sépulcres en Egypte, que tu nous aies menés mourir au désert? Que nous as-tu fait, en nous faisant sortir d''Egypte?'),
('ex',14,12,'crampon1923','N''est-ce pas là ce que nous te disions en Egypte: Laisse-nous servir les Egyptiens, car il vaut mieux pour nous servir les Egyptiens que de mourir au désert? "'),
('ex',14,13,'crampon1923','Moïse répondit au peuple: " N''ayez point de crainte, restez en place, et regardez le salut que Yahweh va vous accorder en ce jour; car les Egyptiens que vous voyez aujourd''hui, vous ne les reverrez jamais.'),
('ex',14,14,'crampon1923','Yahweh combattra pour vous, et vous, tenez-vous tranquilles. "'),
('ex',14,15,'crampon1923','Yahweh dit à Moïse: " Pourquoi cries-tu vers moi? Dis aux enfants d''Israël de se mettre en marche.'),
('ex',14,16,'crampon1923','Toi, lève ton bâton, étends ta main sur la mer, et divise-la; et les enfants d''Israël entreront au milieu de la mer à sec.'),
('ex',14,17,'crampon1923','Et moi, je vais endurcir le cœur des Egyptiens pour qu''ils y entrent après eux, et je ferai éclater ma gloire dans Pharaon et dans toute son armée, ses chars et ses cavaliers.'),
('ex',14,18,'crampon1923','Et les Egyptiens sauront que je suis Yahweh, quand j''aurai fait éclaté ma gloire sur Pharaon, ses chars et ses cavaliers. "'),
('ex',14,19,'crampon1923','L''ange de Dieu, qui marchait devant le camp d''Israël, partit et alla derrière eux; et la colonne de nuée qui les précédait, partit et se tint derrière eux.'),
('ex',14,20,'crampon1923','Elle vint se mettre entre le camp des Egyptiens et le camp d''Israël, et cette nuée était ténébreuse d''un côté, et de l''autre elle éclairait la nuit; et les deux camps n''approchèrent point l''un de l''autre pendant toute la nuit.'),
('ex',14,21,'crampon1923','Moïse ayant étendu sa main sur la mer, Yahweh refoula la mer par un vent impétueux d''orient qui souffla toute la nuit; il mit la mer à sec, et les eaux se divisèrent.'),
('ex',14,22,'crampon1923','Les enfants d''Israël entrèrent au milieu de la mer à sec, et les eaux formaient pour eux une muraille à leur droite et à leur gauche.'),
('ex',14,23,'crampon1923','Les Egyptiens les poursuivirent, et tous les chevaux de Pharaon, ses chars et ses cavaliers, entrèrent à leur suite au milieu de la mer.'),
('ex',14,24,'crampon1923','A la veille du matin, Yahweh, dans la colonne de feu et de fumée, regarda le camp des Egyptiens, et jeta l''épouvante dans le camp des Egyptiens.'),
('ex',14,25,'crampon1923','Il fit tomber les roues hors de leurs chars, qui n''avançaient plus qu''à grand''peine. Les Egyptiens dirent alors: " Fuyons devant Israël, car Yahweh combat pour lui contre l''Egypte. "'),
('ex',14,26,'crampon1923','Yahweh dit à Moïse: " Etends ta main sur la mer, et les eaux reviendront sur les Egyptiens, sur leurs chars et sur leurs cavaliers. "'),
('ex',14,27,'crampon1923','Moïse étendit sa main sur la mer, et, au point du jour, la mer reprit sa place habituelle; les Egyptiens en fuyant la rencontrèrent, et Yahweh culbuta les Egyptiens au milieu de la mer.'),
('ex',14,28,'crampon1923','Les eaux, en revenant, couvrirent les chars, les cavaliers et toute l''armée de Pharaon qui étaient entrés dans la mer à la suite des enfants d''Israël, et il n''en échappa pas un seul.'),
('ex',14,29,'crampon1923','Mais les enfants d''Israël avaient marché à sec au milieu de la mer, les eaux ayant formé pour eux une muraille à droite et à gauche.'),
('ex',14,30,'crampon1923','En ce jour-là, Yahweh délivra Israël de la main des Egyptiens, et Israël vit sur le rivage de la mer les Egyptiens qui étaient morts.'),
('ex',14,31,'crampon1923','Israël vit la main puissante que Yahweh avait montrée à l''égard des Egyptiens; et le peuple craignit Yahweh, et il crut à Yahweh et à Moïse, son serviteur.'),
('ex',15,1,'crampon1923','Alors Moïse et les enfants d''Israël chantèrent ce cantique à Yahweh; ils dirent: Je chanterai à Yahweh, car il a fait éclater sa gloire: il a précipité dans la mer cheval et cavalier.'),
('ex',15,2,'crampon1923','Yahweh est ma force et l''objet de mes chants; c''est lui qui m''a sauvé; c''est lui qui est mon Dieu: je le célébrerai; le Dieu de mon père: je l''exalterai.'),
('ex',15,3,'crampon1923','Yahweh est un vaillant guerrier; Yahweh est son nom.'),
('ex',15,4,'crampon1923','Il a jeté dans la mer les chars de Pharaon et son armée; l''élite de ses capitaines a été engloutie dans la mer Rouge.'),
('ex',15,5,'crampon1923','Les flots les couvrent; ils sont descendus au fond des eaux comme une pierre.'),
('ex',15,6,'crampon1923','Ta droite, ô Yahweh, s''est signalée par sa force, ta droite, ô Yahweh, a écrasé l''ennemi.'),
('ex',15,7,'crampon1923','Dans la plénitude de ta majesté, tu renverses tes adversaires; tu déchaînes ta colère, elle les consume comme du chaume.'),
('ex',15,8,'crampon1923','Au souffle de tes narines, les eaux se sont amoncelées. Les flots se sont dressés comme un monceau; les vagues se sont durcies au sein de la mer.'),
('ex',15,9,'crampon1923','L''ennemi disait: " Je poursuivrai, j''atteindrai, je partagerai les dépouilles, ma vengeance sera assouvie, je tirerai l''épée, ma main les détruira. "'),
('ex',15,10,'crampon1923','Tu as soufflé de ton haleine, la mer les a couverts, ils se sont enfoncés, comme du plomb, dans les vastes eaux.'),
('ex',15,11,'crampon1923','Qui est comme toi parmi les dieux, ô Yahweh? Qui est comme toi, auguste en sainteté, redoutable à la louange même, opérant des prodiges?'),
('ex',15,12,'crampon1923','Tu as étendu ta droite, la terre les a engloutis.'),
('ex',15,13,'crampon1923','Par ta grâce tu conduis ce peuple que tu as délivré; par ta puissance tu le diriges vers ta demeure sainte.'),
('ex',15,14,'crampon1923','Les peuples l''ont appris, ils tremblent; la terreur s''empare des Philistins;'),
('ex',15,15,'crampon1923','Déjà les princes d''Edom sont dans l''épouvante; l''angoisse s''empare des forts de Moab; tous les habitants de Chanaan ont perdu courage,'),
('ex',15,16,'crampon1923','la terreur et la détresse tomberont sur eux; par la grandeur de ton bras, ils deviendront immobiles comme une pierre, jusqu''à ce que ton peuple ait passé, ô Yahweh, jusqu''à ce qu''il ait passé, le peuple que tu as acquis.'),
('ex',15,17,'crampon1923','Tu les amèneras et les établiras sur la montagne de ton héritage, au lieu dont tu as fait ta demeure, ô Yahweh, au sanctuaire, Seigneur, que tes mains ont préparé.'),
('ex',15,18,'crampon1923','Yahweh régnera à jamais et toujours!'),
('ex',15,19,'crampon1923','Car les chevaux de Pharaon, ses chars et ses cavaliers sont entrés dans la mer, et Yahweh a ramené sur eux les eaux de la mer; mais les enfants d''Israël ont marché à sec au milieu de la mer.'),
('ex',15,20,'crampon1923','Marie, la prophétesse, sœur d''Aaron, prit à la main un tambourin, et toutes les femmes vinrent à sa suite avec des tambourins et en dansant.'),
('ex',15,21,'crampon1923','Marie répondait aux enfants d''Israël: Chantez Yahweh, car il a fait éclater sa gloire: il a précipité dans la mer cheval et cavalier.'),
('ex',15,22,'crampon1923','Moïse fit partir Israël de la mer Rouge. Ils s''avancèrent vers le désert de Sur, et marchèrent trois jours dans ce désert sans trouver d''eau.'),
('ex',15,23,'crampon1923','Ils arrivèrent à Mara, mais ils ne purent boire l''eau de Mara, parce qu''elle était amère. C''est pourquoi ce lieu fut appelé Mara.'),
('ex',15,24,'crampon1923','Le peuple murmura contre Moïse, en disant: " Que boirons-nous? "'),
('ex',15,25,'crampon1923','Moïse cria à Yahweh, et Yahweh lui indiqua un bois; il le jeta dans l''eau, et l''eau devint douce. Là Yahweh donna au peuple un statut et un droit, et là il le mit à l''épreuve.'),
('ex',15,26,'crampon1923','Il dit: " Si tu écoutes la voix de Yahweh, ton Dieu, si tu fais ce qui est droit à ses yeux, si tu prêtes l''oreille à ses commandements, et si tu observes toutes ses lois, je ne mettrai sur toi aucune des maladies que j''ai mises sur les Egyptiens; car je suis Yahweh qui te guérit. "'),
('ex',15,27,'crampon1923','Ils arrivèrent à Elim, où il y avait douze sources d''eau et soixante-dix palmiers; et ils campèrent là, près de l''eau.'),
('ex',16,1,'crampon1923','Ils partirent d''Elim, et toute l''assemblée des enfants d''Israël arriva au désert de Sin, qui est entre Elim et le Sinaï, le quinzième jour du second mois après leur sortie du pays d''Egypte.'),
('ex',16,2,'crampon1923','Toute l''assemblée des enfants d''Israël murmura dans le désert contre Moïse et Aaron.'),
('ex',16,3,'crampon1923','Les enfants d''Israël leur dirent: " Que ne sommes-nous morts par la main de Yahweh dans le pays d''Egypte, quand nous étions assis devant les pots de viande, que nous mangions du pain à satiété? Car vous nous avez amenés dans ce désert pour faire mourir de faim toute cette multitude. "'),
('ex',16,4,'crampon1923','Yahweh dit à Moïse: " Voici, je vais faire pleuvoir pour vous du pain du haut du ciel. Le peuple sortira et en ramassera jour par jour la provision nécessaire, afin que je le mette à l''épreuve, pour voir s''il marchera, ou non, dans ma loi.'),
('ex',16,5,'crampon1923','Le sixième jour, ils prépareront ce qu''ils auront rapporté, et il y en aura le double de ce qu''ils en ramassent chaque jour. "'),
('ex',16,6,'crampon1923','Moïse et Aaron dirent à tous les enfants d''Israël: " Ce soir, vous reconnaîtrez que c''est Yahweh qui vous a fait sortir du pays d''Egypte;'),
('ex',16,7,'crampon1923','et, au matin, vous verrez la gloire de Yahweh, car il a entendu vos murmures qui sont contre Yahweh; nous, que sommes-nous, pour que vous murmuriez contre nous? "'),
('ex',16,8,'crampon1923','Moïse dit: " Ce sera quand Yahweh vous donnera ce soir de la viande à manger et, au matin, du pain à satiété; car Yahweh a entendu les murmures que vous avez proférés contre lui. Nous, que sommes-nous? Ce n''est pas contre nous que sont vos murmures, c''est contre Yahweh. "'),
('ex',16,9,'crampon1923','Moïse dit à Aaron: " Dis à toute l''assemblée des enfants d''Israël: Approchez-vous devant Yahweh, car il a entendu vos murmures. "'),
('ex',16,10,'crampon1923','Pendant qu''Aaron parlait à toute l''assemblée des enfants d''Israël, ils se tournèrent du côté du désert, et voici que la gloire de Yahweh apparut dans la nuée.'),
('ex',16,11,'crampon1923','Yahweh parla à Moïse en ces termes:'),
('ex',16,12,'crampon1923','" J''ai entendu les murmures des enfants d''Israël. Dis-leur: Entre les deux soirs vous mangerez de la viande, et au matin vous vous rassasierez de pain, et vous saurez que je suis Yahweh, votre Dieu. "'),
('ex',16,13,'crampon1923','Le soir, on vit monter des cailles, qui couvrirent le camp, et le matin il y avait une couche de rosée autour du camp.'),
('ex',16,14,'crampon1923','Quand cette rosée fut dissipée, voici qu''il y avait à la surface du désert quelque chose de menu, de granuleux, de menu comme le givre sur le sol.'),
('ex',16,15,'crampon1923','Les enfants d''Israël le virent, et ils se dirent les uns aux autres: " Qu''est-ce que cela? " car ils ne savaient pas ce que c''était. Moïse leur dit: " C''est le pain que Yahweh vous donne pour nourriture.'),
('ex',16,16,'crampon1923','Voici ce que Yahweh a ordonné: Que chacun de vous en ramasse ce qu''il faut pour sa nourriture, un gomor par tête, suivant le nombre des personnes; chacun en prendra pour ceux qui sont dans sa tente. "'),
('ex',16,17,'crampon1923','Les enfants d''Israël firent ainsi, et ils recueillirent les uns plus, les autres moins.'),
('ex',16,18,'crampon1923','On mesurait ensuite avec le gomor, et celui qui en avait ramassé beaucoup n''avait rien de trop, et celui qui en avait ramassé peu n''en manquait pas: chacun en recueillait selon sa consommation.'),
('ex',16,19,'crampon1923','Moïse leur dit: " Que personne n''en laisse jusqu''au lendemain matin ".'),
('ex',16,20,'crampon1923','Ils n''écoutèrent pas Moïse, et des gens en gardèrent jusqu''au matin; mais il s''y mit des vers et tout devint infect. Moïse fut irrité contre eux.'),
('ex',16,21,'crampon1923','Tous les matins, ils ramassaient de la manne, chacun selon sa consommation, et quand le soleil faisait sentir ses ardeurs, le reste se liquéfiait.'),
('ex',16,22,'crampon1923','Le sixième jour, ils ramassèrent une quantité double de nourriture, deux gomors pour chacun. Tous les principaux du peuple vinrent en informer Moïse,'),
('ex',16,23,'crampon1923','qui leur dit: " C''est ce que Yahweh a ordonné. Demain est un jour de repos, un sabbat consacré à Yahweh: faites cuire au four ce que vous avez à faire cuire, faites bouillir ce que vous avez à faire bouillir, et tout ce qui restera, mettez-le en réserve pour le lendemain matin. "'),
('ex',16,24,'crampon1923','Ils mirent donc l''excédant en réserve jusqu''au matin, comme Moïse l''avait ordonné, et il ne devint point infect, et les vers ne s''y mirent point.'),
('ex',16,25,'crampon1923','Moïse dit: " Mangez-le aujourd''hui, car c''est le jour du sabbat en l''honneur de Yahweh; aujourd''hui vous n''en trouveriez point dans la campagne.'),
('ex',16,26,'crampon1923','Vous en recueillerez pendant six jours; mais le septième jour, qui est le sabbat, il n''y en aura point. "'),
('ex',16,27,'crampon1923','Le septième jour, quelques-uns du peuple sortirent pour en ramasser, mais ils n''en trouvèrent pas.'),
('ex',16,28,'crampon1923','Alors Yahweh dit à Moïse: " Jusques à quand refuserez-vous d''observer mes commandements, et mes lois?'),
('ex',16,29,'crampon1923','Voyez: c''est parce que Yahweh vous a donné le sabbat qu''il vous donne, le sixième jour, du pain pour deux jours. Que chacun reste à sa place, et que nul ne sorte le septième jour du lieu où il est. "'),
('ex',16,30,'crampon1923','Et le peuple se reposa le septième jour.'),
('ex',16,31,'crampon1923','La maison d''Israël donna à cette nourriture le nom de manne. Elle ressemblait à de la graine de coriandre; elle était blanche et avait le goût d''un gâteau de miel.'),
('ex',16,32,'crampon1923','Moïse dit: " Voici ce que Yahweh a ordonné: Emplis-en un gomor, pour la conserver pour vos descendants, afin qu''ils voient le pain dont je vous ai nourris dans le désert, lorsque je vous ai fait sortir du pays d''Egypte. "'),
('ex',16,33,'crampon1923','Et Moïse dit à Aaron: " Prends un vase, mets-y de la manne plein un gomor, et dépose-le devant Yahweh, afin qu''il soit conservé pour vos descendants. "'),
('ex',16,34,'crampon1923','Comme Yahweh l''avait ordonné à Moïse, Aaron le déposa devant le Témoignage, afin qu''il fût conservé.'),
('ex',16,35,'crampon1923','Les enfants d''Israël ont mangé la manne pendant quarante ans, jusqu''à leur arrivée dans un pays habité; ils ont mangé la manne jusqu''à leur arrivée aux frontières du pays de Chanaan.'),
('ex',16,36,'crampon1923','Le gomor est la dixième partie de l''épha.'),
('ex',17,1,'crampon1923','Toute l''assemblée des enfants d''Israël partit du désert de Sin, selon les marches que Yahweh lui ordonnait, et ils campèrent à Raphidim, où le peuple ne trouva point d''eau à boire.'),
('ex',17,2,'crampon1923','Alors le peuple chercha querelle à Moïse, en disant: " Donnez-nous de l''eau à boire. " Moïse leur répondit: " Pourquoi me cherchez-vous querelle? Pourquoi tentez-vous Yahweh? "'),
('ex',17,3,'crampon1923','Et le peuple était là, pressé par la soif, et il murmurait contre Moïse; il disait: " Pourquoi nous as-tu fait monter hors d''Egypte, pour nous faire mourir de soif avec mes enfants et mes troupeaux? "'),
('ex',17,4,'crampon1923','Moïse cria vers Yahweh, en disant: " Que ferai-je pour ce peuple? Encore un peu, et ils me lapideront! "'),
('ex',17,5,'crampon1923','Yahweh dit à Moïse: " Passe devant le peuple et prends avec toi des anciens d''Israël; prends aussi dans ta main ton bâton, avec lequel tu as frappé le fleuve, et va.'),
('ex',17,6,'crampon1923','Voici, je me tiendrai devant toi sur le rocher qui est en Horeb; tu frapperas le rocher, et il en sortira de l''eau, et le peuple boira. " Moïse fit ainsi en présence des anciens d''Israël.'),
('ex',17,7,'crampon1923','Et il donna à ce lieu le nom de Massah et Méribah, parce que les enfants d''Israël avaient contesté, et parce qu''ils avaient tenté Yahweh en disant: " Yahweh est-il au milieu de nous, ou non? "'),
('ex',17,8,'crampon1923','Amalec vint attaquer Israël à Raphidim.'),
('ex',17,9,'crampon1923','Et Moïse dit à Josué: " Choisis-nous des hommes, et va combattre Amalec; demain je me tiendrai sur le sommet de la colline, le bâton de Dieu dans ma main. "'),
('ex',17,10,'crampon1923','Josué fit selon que lui avait dit Moïse, il combattit Amalec. Et Moïse, Aaron et Hur montèrent au sommet de la colline.'),
('ex',17,11,'crampon1923','Lorsque Moïse tenait sa main levée, Israël était le plus fort, et lorsqu''il laissait tomber sa main, Amalec était le plus fort.'),
('ex',17,12,'crampon1923','Comme les mains de Moïse étaient fatiguées, ils prirent une pierre, qu''ils placèrent sous lui, et il s''assit dessus; et Aaron et Hur soutenaient ses mains, l''un d''un côté, l''autre de l''autre; ainsi ses mains restèrent fermes jusqu''au coucher du soleil.'),
('ex',17,13,'crampon1923','Et Josué défit Amalec et son peuple à la pointe de l''épée.'),
('ex',17,14,'crampon1923','Yahweh dit à Moïse: " Ecris cela en souvenir dans le livre, et déclare à Josué que j''effacerai la mémoire d''Amalec de dessous le ciel. "'),
('ex',17,15,'crampon1923','Moïse construisit un autel, et le nomma Yahweh-Nessi'),
('ex',17,16,'crampon1923','et il dit: " Puisqu''on a levé la main contre le trône de Yahweh, Yahweh est en guerre contre Amalec d''âge en âge. " Note: Yahweh-Nessi: c''est-à-dire: Yahweh - ma bannière')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ex',18,1,'crampon1923','Jéthro, prêtre de Madian, beau-père de Moïse, apprit tout ce que Dieu avait fait en faveur de Moïse et d''Israël, son peuple: que Yahweh avait fait sortir Israël d''Egypte.'),
('ex',18,2,'crampon1923','Jéthro, beau-père de Moïse, prit Séphora, femme de Moïse, qui avait été renvoyée,'),
('ex',18,3,'crampon1923','et les deux fils de Séphora, dont l''un se nommait Gersam, parce que Moïse avait dit: " Je suis un étranger sur une terre étrangère ",'),
('ex',18,4,'crampon1923','et l''autre s''appelait Eliézer, parce qu''il avait dit: " Le Dieu de mon père m''a secouru, et il m''a délivré de l''épée de Pharaon. "'),
('ex',18,5,'crampon1923','Jéthro, beau-père de Moïse, avec les fils et la femme de Moïse, vint donc vers lui au désert où il campait, à la montagne de Dieu.'),
('ex',18,6,'crampon1923','Il fit dire à Moïse: " Moi, ton beau-père, Jéthro, je viens vers toi, ainsi que ta femme et ses deux fils avec elle. "'),
('ex',18,7,'crampon1923','Moïse sortit au-devant de son beau-père et, s''étant prosterné, il le baisa; puis ils s''informèrent réciproquement de leur santé, et ils entrèrent dans la tente de Moïse.'),
('ex',18,8,'crampon1923','Moïse raconta à son beau-père tout ce que Yahweh avait fait à Pharaon et à l''Egypte à cause d''Israël, toutes les souffrances qui leur étaient survenues en chemin, et comment Yahweh les en avait délivrés.'),
('ex',18,9,'crampon1923','Jéthro se réjouit de tout le bien que Yahweh avait fait à Israël, et de ce qu''il l''avait délivré de la main des Egyptiens. Et Jéthro dit:'),
('ex',18,10,'crampon1923','" Béni soit Yahweh qui vous a délivrés de la main des Egyptiens et de la main de Pharaon, et qui a délivré le peuple de la main des Egyptiens!'),
('ex',18,11,'crampon1923','Je sais maintenant que Yahweh est plus grand que tous les dieux, car il s''est montré grand alors que les Egyptiens opprimaient Israël. "'),
('ex',18,12,'crampon1923','Jéthro, beau-père de Moïse, offrit à Dieu un holocauste et des sacrifices. Aaron et tous les anciens d''Israël vinrent prendre part au repas, avec le beau-père de Moïse, en présence de Dieu.'),
('ex',18,13,'crampon1923','Le lendemain, Moïse s''assit pour juger le peuple, et le peuple se tint devant lui depuis le matin jusqu''au soir.'),
('ex',18,14,'crampon1923','Le beau-père de Moïse, voyant tout ce qu''il faisait pour le peuple, dit: " Que fais-tu là pour ces gens? Pourquoi sièges-tu seul, et tout le peuple se tient-il devant toi depuis le matin jusqu''au soir? "'),
('ex',18,15,'crampon1923','Moïse répondit à son beau-père: " C''est que le peuple vient à moi pour consulter Dieu.'),
('ex',18,16,'crampon1923','Quand ils ont quelque affaire, ils viennent à moi; je prononce entre eux, en faisant connaître les ordres de Dieu et ses lois. "'),
('ex',18,17,'crampon1923','Le beau-père de Moïse lui dit: " Ce que tu fais n''est pas bien.'),
('ex',18,18,'crampon1923','Tu succomberas certainement, toi et le peuple qui est avec toi; car la tâche est au-dessus de tes forces, et tu ne saurais y suffire seul.'),
('ex',18,19,'crampon1923','Maintenant, écoute ma voix; je vais te donner un conseil, et que Dieu soit avec toi! Toi, sois le représentant du peuple auprès de Dieu, et porte les affaires devant Dieu.'),
('ex',18,20,'crampon1923','Apprends-leur les ordonnances et les lois, et fais-leur connaître la voie qu''ils doivent suivre et ce qu''ils doivent faire.'),
('ex',18,21,'crampon1923','Maintenant choisis parmi tout le peuple des hommes capables et craignant Dieu, des hommes intègres, ennemis de la cupidité, et établis-les sur eux comme chefs de milliers, chefs de centaines, chefs de cinquantaines et chefs de dizaines.'),
('ex',18,22,'crampon1923','Ils jugeront le peuple en tout temps, porteront devant toi toutes les causes importantes, et décideront eux-mêmes dans toutes les petites causes. Allège ainsi ta charge, et qu''ils la portent avec toi.'),
('ex',18,23,'crampon1923','Si tu fais cela, et que Dieu te donne des ordres, tu pourras y tenir et tout ce peuple aussi viendra en paix en son lieu. "'),
('ex',18,24,'crampon1923','Moïse écouta la voix de son beau-père et fit tout ce qu''il avait dit.'),
('ex',18,25,'crampon1923','Moïse choisit dans tout Israël des hommes capables, et il les préposa au peuple comme chefs de milliers, chefs de centaines, chefs de cinquantaines et chefs de dizaines.'),
('ex',18,26,'crampon1923','Ils jugeaient le peuple en tout temps; ils portaient devant Moïse toutes les affaires graves, et décidaient eux-mêmes toutes les petites causes.'),
('ex',18,27,'crampon1923','Moïse prit congé de son beau-père, et Jéthro s''en retourna dans son pays.'),
('ex',19,1,'crampon1923','Ce fut au troisième mois après que les enfants d''Israël furent sortis d''Egypte, en ce jour, qu''ils arrivèrent au désert de Sinaï.'),
('ex',19,2,'crampon1923','Ils étaient partis de Raphidim; arrivés au désert de Sinaï, ils campèrent dans le désert; Israël campa là, vis-à-vis de la montagne.'),
('ex',19,3,'crampon1923','Moïse monta vers Dieu, et Yahweh l''appela du haut de la montagne en disant: " Tu parleras ainsi à la maison de Jacob et tu diras aux enfants d''Israël:'),
('ex',19,4,'crampon1923','Vous avez vu ce que j''ai fait à l''Egypte, et comment je vous ai portés sur des ailes d''aigle et amenés vers moi.'),
('ex',19,5,'crampon1923','Maintenant, si vous écoutez ma voix et si vous gardez mon alliance, vous serez mon peuple particulier parmi tous les peuples, car toute la terre est à moi;'),
('ex',19,6,'crampon1923','mais vous, vous serez pour moi un royaume de prêtres et une nation sainte. Telles sont les paroles que tu diras aux enfants d''Israël. "'),
('ex',19,7,'crampon1923','Moïse vint appeler les anciens du peuple, et il mit devant eux toutes ces paroles, selon que Yahweh le lui avait ordonné.'),
('ex',19,8,'crampon1923','Le peuple tout entier répondit: " Nous ferons tout ce qu''a dit Yahweh. " Moïse alla porter à Yahweh les paroles du peuple,'),
('ex',19,9,'crampon1923','et Yahweh dit à Moïse: " Voici, je vais venir à toi dans une nuée épaisse, afin que le peuple entende quand je parlerai avec toi, et qu''en toi aussi il ait foi à jamais. " Et Moïse rapporta à Yahweh les paroles du peuple.'),
('ex',19,10,'crampon1923','Et Yahweh dit à Moïse: " Va vers le peuple, et sanctifie-les aujourd''hui et demain, et qu''ils lavent leurs vêtements.'),
('ex',19,11,'crampon1923','Qu''ils soient prêts pour le troisième jour; car le troisième jour Yahweh descendra, aux yeux de tout le peuple, sur la montagne de Sinaï.'),
('ex',19,12,'crampon1923','Tu fixeras au peuple une limite à l''entour, en disant: Gardez-vous de monter sur la montagne ou d''en toucher le bord; quiconque touchera la montagne sera mis à mort.'),
('ex',19,13,'crampon1923','On ne mettra pas la main sur lui, mais on le lapidera ou on le percera de flèches; bête ou homme, il ne doit pas vivre. Quand la trompette sonnera, ils monteront sur la montagne. "'),
('ex',19,14,'crampon1923','Moïse descendit de la montagne vers le peuple; il sanctifia le peuple, et ils lavèrent leurs vêtements.'),
('ex',19,15,'crampon1923','Puis il dit au peuple: " Soyez prêts dans trois jours; ne vous approchez d''aucune femme. "'),
('ex',19,16,'crampon1923','Le troisième jour au matin, il y eut des tonnerres, des éclairs, une nuée épaisse sur la montagne, et un son de trompe très fort, et tout le peuple qui était dans le camp trembla.'),
('ex',19,17,'crampon1923','Moïse fit sortir le peuple du camp, à la rencontre de Dieu, et ils se tinrent au pied de la montagne.'),
('ex',19,18,'crampon1923','La montagne de Sinaï était toute fumante, parce que Yahweh y était descendu au milieu du feu, et la fumée s''élevait comme la fumée d''une fournaise, et toute la montagne tremblait fortement.'),
('ex',19,19,'crampon1923','Le son de la trompe devenait de plus en plus fort. Moïse parla, et Dieu lui répondit par une voix.'),
('ex',19,20,'crampon1923','Yahweh descendit sur la montagne de Sinaï, sur le sommet de la montagne, et Yahweh appela Moïse sur le sommet de la montagne, et Moïse monta.'),
('ex',19,21,'crampon1923','Yahweh dit à Moïse: " Descends, et défends expressément au peuple de rompre les barrières vers Yahweh pour regarder, de peur qu''un grand nombre d''entre eux ne périssent.'),
('ex',19,22,'crampon1923','Que même les prêtres, qui s''approchent de Yahweh, se sanctifient, de peur que Yahweh ne les frappe de mort. "'),
('ex',19,23,'crampon1923','Moïse dit à Yahweh: " Le peuple ne pourra pas monter sur la montagne de Sinaï, puisque vous nous en avez fait la défense expresse, en disant: Pose des limites autour de la montagne, et sanctifie-la. "'),
('ex',19,24,'crampon1923','Yahweh lui dit: " Va, descends, tu remonteras ensuite avec Aaron; mais que les prêtres et le peuple ne rompent point la barrière pour monter vers Yahweh, de peur qu''il ne les frappe de mort. "'),
('ex',19,25,'crampon1923','Moïse descendit vers le peuple et lui dit ces choses.'),
('ex',20,1,'crampon1923','Et Dieu prononça toutes ces paroles, en disant:'),
('ex',20,2,'crampon1923','Je suis Yahweh, ton dieu, qui t''ai fait sortir du pays d''Egypte, de la maison de servitude.'),
('ex',20,3,'crampon1923','Tu n''auras pas d''autres dieux devant ma face.'),
('ex',20,4,'crampon1923','Tu ne te feras pas d''image taillée, ni aucune figure de ce qui est en haut dans le ciel, ou de ce qui est en bas sur la terre, ou de ce qui est dans les eaux au-dessous de la terre.'),
('ex',20,5,'crampon1923','Tu ne te prosterneras point devant elles et tu ne les serviras point. Car moi Yahweh, ton Dieu, je suis un Dieu jaloux, qui punis l''iniquité des pères sur les enfants, sur la troisième et sur la quatrième génération pour ceux qui me haïssent,'),
('ex',20,6,'crampon1923','et faisant miséricorde jusqu''à mille générations, pour ceux m''aiment et qui gardent mes commandements.'),
('ex',20,7,'crampon1923','Tu ne prendras point le nom de Yahweh, ton Dieu, en vain, car Yahweh ne laissera pas impuni celui qui prendra son nom en vain.'),
('ex',20,8,'crampon1923','Souviens-toi du jour du sabbat pour le sanctifier.'),
('ex',20,9,'crampon1923','Pendant six jours tu travailleras, et tu feras tout ton ouvrage.'),
('ex',20,10,'crampon1923','Mais le septième jour est un sabbat consacré à Yahweh, ton Dieu: tu ne feras aucun ouvrage, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton bétail, ni l''étranger qui est dans tes portes.'),
('ex',20,11,'crampon1923','Car pendant six jours Yahweh a fait le ciel, la terre, la mer et tout ce qu''ils contiennent, et il s''est reposé le septième jour: c''est pourquoi Yahweh a béni le jour du sabbat et l''a sanctifié.'),
('ex',20,12,'crampon1923','Honore ton père et ta mère, afin que tes jours soient prolongés dans le pays que Yahweh, ton Dieu, te donne.'),
('ex',20,13,'crampon1923','Tu ne tueras point.'),
('ex',20,14,'crampon1923','Tu ne commettras point d''adultère.'),
('ex',20,15,'crampon1923','Tu ne déroberas point.'),
('ex',20,16,'crampon1923','Tu ne porteras point de faux témoignages contre ton prochain.'),
('ex',20,17,'crampon1923','Tu ne convoiteras point la maison de ton prochain; tu ne convoiteras point la femme de ton prochain, ni son serviteur, ni sa servante, ni son bœuf, ni son âne, ni rien de ce qui appartient à ton prochain.'),
('ex',20,18,'crampon1923','Tout le peuple entendait les tonnerres et le son de la trompette; il voyait les flammes et la montagne fumante; à ce spectacle, il tremblait et se tenait à distance.'),
('ex',20,19,'crampon1923','Ils dirent à Moïse: " Parles-nous, toi, et nous écouterons; mais que Dieu ne nous parle point, de peur que nous ne mourrions. "'),
('ex',20,20,'crampon1923','Moïse répondit au peuple: " Ne vous effrayez pas, car c''est pour vous mettre à l''épreuve que Dieu est venu, et pour que sa crainte vous soit présente, afin que vous ne péchiez pas. "'),
('ex',20,21,'crampon1923','Et le peuple resta à distance; mais Moïse s''approcha de la nuée où était Dieu.'),
('ex',20,22,'crampon1923','Et Yahweh dit à Moïse: " Tu parleras ainsi aux enfants d''Israël: vous avez vu que je vous ai parlé du ciel.'),
('ex',20,23,'crampon1923','Vous ne ferez point à côté de moi de dieux d''argent et vous ne ferez point de dieux d''or.'),
('ex',20,24,'crampon1923','Tu m''élèveras un autel de terre, sur lequel tu offriras tes holocaustes et tes sacrifices pacifiques, tes brebis et tes bœufs. Dans tous les lieux où j''aurai fait souvenir de mon nom, je viendrai vers toi, et je te bénirai.'),
('ex',20,25,'crampon1923','Si tu m''élèves un autel de pierre, tu ne le construiras point en pierres taillées, car, en levant ton ciseau sur la pierre, tu la rendrais profane.'),
('ex',20,26,'crampon1923','Tu ne monteras point par des degrés à mon autel, afin que ta nudité n''y soit pas découverte.'),
('ex',21,1,'crampon1923','Voici les lois que tu leur donneras:'),
('ex',21,2,'crampon1923','Quand tu achèteras un serviteur hébreu, il servira six années; la septième, il sortira libre, sans rien payer.'),
('ex',21,3,'crampon1923','S''il est entré seul, il sortira seul; s''il avait une femme, sa femme sortira avec lui.'),
('ex',21,4,'crampon1923','Mais si c''est son maître qui lui a donné une femme, et qu''elle lui ait enfanté des fils et des filles, la femme et ses enfants appartiendront à son maître, et il sortira seul.'),
('ex',21,5,'crampon1923','Si le serviteur dit: " J''aime mon maître, ma femme et mes enfants; je ne veux pas sortir libre ",'),
('ex',21,6,'crampon1923','alors son maître le conduira devant Dieu; puis, l''ayant fait approcher de la porte ou du poteau, son maître lui percera l''oreille avec un poinçon, et le serviteur sera pour toujours à son service.'),
('ex',21,7,'crampon1923','Lorsqu''un homme aura vendu sa fille pour être servante, elle ne sortira point comme sortent les serviteurs.'),
('ex',21,8,'crampon1923','Si elle déplaît à son maître, qui se l''était destinée, il permettra qu''on la rachète; mais il ne pourra pas la vendre à des étrangers, après lui avoir été infidèle.'),
('ex',21,9,'crampon1923','S''il la destine à son fils, il la traitera selon le droit des filles.'),
('ex',21,10,'crampon1923','Et s''il prend une autre femme, il ne retranchera rien à la première pour la nourriture, le vêtement et le couvert.'),
('ex',21,11,'crampon1923','Et s''il ne fait pas pour elle ces trois choses, elle pourra sortir sans rien payer, sans donner d''argent.'),
('ex',21,12,'crampon1923','Celui qui frappe un homme à mort doit être mis à mort.'),
('ex',21,13,'crampon1923','Mais s''il ne lui a pas tendu d''embûches et que Dieu l''ait présenté à sa main, je te fixerai un lieu où il pourra se réfugier.'),
('ex',21,14,'crampon1923','Mais si un homme agit méchamment contre son prochain pour le tuer par ruse, tu l''arracheras même de mon autel pour le faire mourir.'),
('ex',21,15,'crampon1923','Celui qui frappe son père ou sa mère doit être mis à mort.'),
('ex',21,16,'crampon1923','Celui qui dérobe un homme, soit qu''il le vende, soit qu''on le retrouve entre ses mains, doit être mis à mort.'),
('ex',21,17,'crampon1923','Celui qui maudira son père ou sa mère sera puni de mort.'),
('ex',21,18,'crampon1923','Lorsque des hommes se querellent, et que l''un en frappe un autre avec une pierre ou avec le poing, sans causer sa mort, mais en l''obligeant à tenir le lit,'),
('ex',21,19,'crampon1923','celui qui l''aura frappé sera quitte, si l''autre en relève et qu''il puisse se promener, dehors avec son bâton; seulement, il le dédommagera de son chômage et il le fera soigner.'),
('ex',21,20,'crampon1923','Quand un homme frappe du bâton son serviteur ou sa servante, et que ceux-ci meurent sous sa main, ils seront vengés.'),
('ex',21,21,'crampon1923','Mais si le serviteur survit un jour ou deux, il ne sera pas vengé; car il est la propriété de son maître.'),
('ex',21,22,'crampon1923','Lorsque des hommes se battent, et qu''ils heurtent une femme enceinte, s''ils la font accoucher, sans autre accident, le coupable sera passible d''une amende que lui imposera le mari de la femme, et qu''il paiera selon la décision des juges.'),
('ex',21,23,'crampon1923','Mais s''il y a un accident, tu donneras vie pour vie,'),
('ex',21,24,'crampon1923','œil pour œil, dent pour dent, main pour main, pied pour pied,'),
('ex',21,25,'crampon1923','brûlure pour brûlure, blessure pour blessure, meurtrissure pour meurtrissure.'),
('ex',21,26,'crampon1923','Si un homme donne un coup dans l''œil de son serviteur ou de sa servante, et qu''il lui fasse perdre l''œil, il le mettra en liberté en compensation de son œil.'),
('ex',21,27,'crampon1923','Et s''il fait tomber une dent à son serviteur ou à sa servante, il le mettra en liberté en compensation de sa dent.'),
('ex',21,28,'crampon1923','Si un bœuf frappe de sa corne un homme ou une femme, et que la mort s''en suive, le bœuf sera lapidé, on n''en mangera pas la chair, mais le maître du bœuf sera quitte.'),
('ex',21,29,'crampon1923','Mais si le bœuf frappait de la corne depuis longtemps, et que son maître, en ayant été averti, ne l''ait pas surveillé, le bœuf sera lapidé, s''il tue un homme ou une femme, et son maître aussi sera mis à mort.'),
('ex',21,30,'crampon1923','Si on impose au maître un prix pour le rachat de sa vie, il paiera tout ce qui lui aura été imposé.'),
('ex',21,31,'crampon1923','Si le bœuf frappe un fils ou une fille, on appliquera encore cette loi;'),
('ex',21,32,'crampon1923','mais si le bœuf frappe un serviteur ou une servante, on paiera trente sicles d''argent au maître de l''esclave, et le bœuf sera lapidé.'),
('ex',21,33,'crampon1923','Si un homme ouvre une citerne, ou bien si un homme creuse une citerne et ne la couvre pas, et qu''il y tombe un bœuf ou un âne,'),
('ex',21,34,'crampon1923','le possesseur de la citerne indemnisera: il rendra au maître la valeur de la bête en argent, et la bête tuée sera pour lui.'),
('ex',21,35,'crampon1923','Si le bœuf d''un homme frappe de la corne le bœuf d''un autre homme, et que la mort s''en suive, ils vendront le bœuf vivant et s''en partageront le prix; ils se partageront aussi le bœuf tué.'),
('ex',21,36,'crampon1923','Mais s''il est reconnu que le bœuf frappait de la corne depuis longtemps, et que son maître ne l''ait pas surveillé, celui-ci indemnisera en donnant bœuf pour bœuf, et le bœuf tué sera pour lui.'),
('ex',21,37,'crampon1923','Si un homme dérobe un bœuf ou un agneau et qu''il l''égorge ou le vende, il restituera cinq bœufs pour le bœuf, et quatre agneaux pour l''agneau.'),
('ex',22,1,'crampon1923','Si le voleur est surpris la nuit faisant effraction, et qu''il soit frappé et meure, on n''est pas responsable du sang pour lui;'),
('ex',22,2,'crampon1923','mais si le soleil est levé, on sera responsable du sang pour lui. — Le voleur fera restitution: s''il n''a rien, on le vendra pour ce qu''il a volé.'),
('ex',22,3,'crampon1923','Si ce qu''il a volé, bœuf, âne ou brebis, se trouve encore vivant entre ses mains, il restituera le double.'),
('ex',22,4,'crampon1923','Si un homme fait du dégât dans un champ ou dans une vigne, en laissant son bétail brouter le champ d''autrui, il donnera en dédommagement le meilleur de son champ et le meilleur de sa vigne.'),
('ex',22,5,'crampon1923','Si un feu éclate et que, après avoir atteint les épines, il consume des gerbes, ou du blé sur pied, ou un champ, celui qui aura allumé l''incendie donnera un dédommagement.'),
('ex',22,6,'crampon1923','Si un homme donne en garde à un autre de l''argent ou des objets, et qu''on les vole de la maison de ce dernier, le voleur, si on le trouve, restituera le double.'),
('ex',22,7,'crampon1923','Si le voleur n''est pas trouvé, le maître de la maison se présentera devant Dieu, pour déclarer s''il n''a pas mis la main sur le bien de son prochain.'),
('ex',22,8,'crampon1923','Quel que soit le corps du délit, bœuf, âne, brebis, vêtement ou tout objet perdu, au sujet duquel on dira: " C''est bien cela! " la cause des deux parties ira jusqu''à Dieu, et celui que Dieu aura condamné restituera le double à son prochain.'),
('ex',22,9,'crampon1923','Si un homme donne en garde à un autre un bœuf, une brebis, une tête de bétail quelconque, et que l''animal meure, se casse un membre, ou soit enlevé, sans qu''il y ait de témoin,'),
('ex',22,10,'crampon1923','le serment de Yahweh interviendra entre les deux parties, pour qu''on sache si le dépositaire n''a pas mis la main sur le bien de son prochain; et le propriétaire de la bête acceptera ce serment, et l''autre n''aura pas à indemniser.'),
('ex',22,11,'crampon1923','Mais si la bête a été dérobée chez lui, il aura à indemniser le propriétaire.'),
('ex',22,12,'crampon1923','Si elle a été déchirée par une bête féroce, il en produira les restes en témoignage, et il n''aura point à indemniser pour la bête déchirée.'),
('ex',22,13,'crampon1923','Si un homme emprunte à un autre une bête, et qu''elle se casse un membre ou meure, son propriétaire n''étant pas présent, il y aura lieu à indemnité.'),
('ex',22,14,'crampon1923','Si le propriétaire est présent, on n''indemnisera pas. Si la bête était louée, le prix de louage sera une compensation.'),
('ex',22,15,'crampon1923','Si un homme séduit une vierge qui n''est pas fiancée, et couche avec elle, il paiera sa dot et la prendra pour femme.'),
('ex',22,16,'crampon1923','Si le père refuse de la lui accorder, le séducteur paiera l''argent qu''on donne pour la dot des vierges.'),
('ex',22,17,'crampon1923','Tu ne laisseras pas vivre la magicienne.'),
('ex',22,18,'crampon1923','Quiconque a commerce avec une bête sera mis à mort.'),
('ex',22,19,'crampon1923','Celui qui offre des sacrifices aux dieux, et non à Yahweh seul, sera voué à l''anathème.'),
('ex',22,20,'crampon1923','Tu ne maltraiteras point l''étranger et tu ne l''opprimeras point, car vous avez été des étrangers dans le pays d''Egypte.'),
('ex',22,21,'crampon1923','Vous n''affligerez point la veuve ni l''orphelin.'),
('ex',22,22,'crampon1923','Si tu les affliges, ils crieront vers moi, et j''entendrai leur cri;'),
('ex',22,23,'crampon1923','ma colère s''enflammera, et je vous détruirai par l''épée, et vos femmes seront des veuves et vos enfants des orphelins.'),
('ex',22,24,'crampon1923','Si tu prêtes de l''argent à quelqu''un de mon peuple, au pauvre qui est avec toi, tu ne seras point à son égard comme un créancier, tu n''exigeras pas de lui d''intérêt.'),
('ex',22,25,'crampon1923','Si tu prends en gage le manteau de ton prochain, tu le lui rendras avant le coucher du soleil;'),
('ex',22,26,'crampon1923','car c''est sa seule couverture, c''est le vêtement dont il s''enveloppe le corps: sur quoi coucherait-il? S''il crie vers moi, je l''entendrai car je suis compatissant.'),
('ex',22,27,'crampon1923','Tu ne blasphémeras pas contre Dieu, et tu ne maudiras pas un prince de ton peuple.'),
('ex',22,28,'crampon1923','Tu ne différeras point de m''offrir les prémices de ta moisson et de ton pressoir. Tu me donneras le premier-né de tes fils.'),
('ex',22,29,'crampon1923','Tu feras de même du premier-né de ta vache et de ta brebis: il restera sept jours avec sa mère et le huitième jour tu me le donneras.'),
('ex',22,30,'crampon1923','Vous serez pour moi des hommes saints; vous ne mangerez point la chair déchirée qui se trouvera dans les champs: vous la jetterez aux chiens.'),
('ex',23,1,'crampon1923','Tu ne sèmeras pas de faux bruit; tu ne donneras pas la main à un méchant en lui servant de témoin à charge.'),
('ex',23,2,'crampon1923','Tu ne suivras point la multitude pour faire le mal, et tu ne déposeras point dans un procès en te mettant du côté du grand nombre pour faire fléchir la justice.'),
('ex',23,3,'crampon1923','Tu ne favoriseras pas non plus un faible dans son procès.'),
('ex',23,4,'crampon1923','Si tu rencontres le bœuf de ton ennemi ou son âne égaré, tu ne manqueras pas de le lui ramener.'),
('ex',23,5,'crampon1923','Si tu vois l''âne de celui qui te hait succombant sous sa charge, tu te garderas de l''abandonner; joins tes efforts aux siens pour le décharger.'),
('ex',23,6,'crampon1923','Tu ne feras pas fléchir le droit du pauvre dans son procès.'),
('ex',23,7,'crampon1923','Tu t''éloigneras d''une cause mensongère, et tu ne feras pas mourir l''innocent et le juste; car je n''absoudrai point un coupable.'),
('ex',23,8,'crampon1923','Tu n''accepteras pas de présents; car les présents aveuglent les clairvoyants et ruinent les causes justes.'),
('ex',23,9,'crampon1923','Tu n''opprimeras pas l''étranger; vous savez ce que ressent l''étranger, car vous avez été étrangers dans le pays d''Egypte.'),
('ex',23,10,'crampon1923','Pendant six années tu ensemenceras ta terre et tu en récolteras les produits.'),
('ex',23,11,'crampon1923','Mais, la septième, tu les laisseras et les abandonneras; et les indigents de ton peuple les mangeront, et les bêtes des champs mangeront ce qui restera. Tu feras de même pour tes vignes et les oliviers.'),
('ex',23,12,'crampon1923','Pendant six jours tu feras ton ouvrage; mais le septième jour tu te reposeras, afin que ton bœuf et ton âne aient du repos, et que le fils de ta servante et l''étranger respirent.'),
('ex',23,13,'crampon1923','Vous prendrez garde à tout ce que je vous ai dit; vous ne prononcerez point le nom de dieux étrangers, et on n''en entendra pas sortir de votre bouche.'),
('ex',23,14,'crampon1923','Trois fois chaque année tu célébreras une fête en mon honneur.'),
('ex',23,15,'crampon1923','Tu observeras la fête des Azymes: pendant sept jours tu mangeras des pains sans levain, comme je t''en ai donné l''ordre, au temps fixé, au mois d''abib, car c''est dans ce mois que tu es sorti d''Egypte; et l''on ne se présentera pas les mains vides devant ma face.'),
('ex',23,16,'crampon1923','Tu observeras la fête de la Moisson, des prémices de ton travail, de ce que tu auras semé dans les champs; et la fête de la Récolte, à la fin de l''année, quand tu recueilleras des champs le fruit de ton travail.'),
('ex',23,17,'crampon1923','Trois fois l''année, tous tes mâles se présenteront devant le seigneur Yahweh.'),
('ex',23,18,'crampon1923','Tu n''offriras pas avec du pain levé le sang de ma victime, et la graisse de ma fête ne sera pas gardée pendant la nuit jusqu''au matin.'),
('ex',23,19,'crampon1923','Tu apporteras les prémices des premiers fruits de ton sol à la maison de Yahweh, ton Dieu. Tu ne feras pas cuire un chevreau dans le lait de sa mère.'),
('ex',23,20,'crampon1923','Voici que j''envoie un ange devant toi, pour te garder dans le chemin et pour te faire arriver au lieu que j''ai préparé.'),
('ex',23,21,'crampon1923','Sois sur tes gardes en sa présence et écoute sa voix; ne lui résiste pas, car il ne pardonnerait pas votre transgression, parce que mon nom est en lui.'),
('ex',23,22,'crampon1923','Mais si tu écoutes sa voix, et si tu fais tout ce que je dirai, je serai l''ennemi de tes ennemis et l''adversaire de tes adversaires.'),
('ex',23,23,'crampon1923','Car mon ange marchera devant toi et te conduira vers les Amorrhéens, les Héthéens, les Phérézéens, les Chananéens, les Hévéens et les Jébuséens, et je les exterminerai.'),
('ex',23,24,'crampon1923','Tu n''adoreras pas leurs dieux et tu ne les serviras pas; tu ne les imiteras pas dans leurs pratiques, mais tu renverseras et briseras leurs stèles.'),
('ex',23,25,'crampon1923','Vous servirez Yahweh, votre Dieu, et il bénira ton pain et ton eau, et j''éloignerai la maladie du milieu de toi.'),
('ex',23,26,'crampon1923','Il n''y aura dans ton pays ni femme qui perde son fruit, ni femme stérile; je remplirai le nombre de tes jours.'),
('ex',23,27,'crampon1923','J''enverrai ma terreur devant toi, je jetterai dans la confusion tous les peuples chez lesquels tu arriveras, et je ferai tourner le dos devant toi à tous tes ennemis.'),
('ex',23,28,'crampon1923','J''enverrai devant toi les frelons, qui chasseront loin de ta face les Hévéens, les Chananéens et les Héthéens.'),
('ex',23,29,'crampon1923','Je ne les chasserai pas de ta face en une seule année, de peur que le pays ne devienne un désert, et que les bêtes sauvages ne se multiplient contre toi.'),
('ex',23,30,'crampon1923','Je les chasserai peu à peu de devant toi, jusqu''à ce que tu augmentes en nombre et que tu puisses occuper le pays.'),
('ex',23,31,'crampon1923','J''établirai tes limites depuis la mer Rouge jusqu''à la mer des Philistins, et depuis le désert jusqu''au fleuve; car je livrerai entre vos mains les habitants du pays, et tu les chasseras de devant toi.'),
('ex',23,32,'crampon1923','Tu ne feras pas alliance avec eux, ni avec leurs dieux.'),
('ex',23,33,'crampon1923','Ils n''habiteront pas dans ton pays, de peur qu''ils ne te fassent pécher contre moi; tu servirais leurs dieux, et ce serait un piège pour toi. "'),
('ex',24,1,'crampon1923','Dieu dit à Moïse: " Monte vers Yahweh, toi et Aaron, Nadab et Abiu, et soixante-dix des anciens d''Israël, et prosternez-vous de loin.'),
('ex',24,2,'crampon1923','Moïse s''approchera seul de Yahweh; les autres ne s''approcheront pas, et le peuple ne montera pas avec lui. "'),
('ex',24,3,'crampon1923','Moïse vint rapporter au peuple toutes les paroles de Yahweh et toutes les lois; et le peuple entier répondit d''une seule voix: " Toutes les paroles qu''a dites Yahweh, nous les accomplirons. "'),
('ex',24,4,'crampon1923','Moïse écrivit toutes les paroles de Yahweh. Puis, s''étant levé de bon matin, il bâtit un autel au pied de la montagne, et dressa douze stèles pour les douze tribus d''Israël.'),
('ex',24,5,'crampon1923','Il envoya des jeunes gens, enfants d''Israël, et ils offrirent à Yahweh des holocaustes et immolèrent des taureaux en sacrifices d''actions de grâces.'),
('ex',24,6,'crampon1923','Moïse prit la moitié du sang, qu''il mit dans des bassins, et il répandit l''autre moitié sur l''autel.'),
('ex',24,7,'crampon1923','Ayant pris le livre de l''alliance, il le lut en présence du peuple, qui répondit: " Tout ce qu''a dit Yahweh, nous le ferons et nous y obéirons. "'),
('ex',24,8,'crampon1923','Moïse prit le sang et en aspergea le peuple, en disant: " Voici le sang de l''alliance que Yahweh a conclue avec vous sur toutes ces paroles. "'),
('ex',24,9,'crampon1923','Moïse monta avec Aaron, Nadab et Abiu et soixante-dix des anciens d''Israël;'),
('ex',24,10,'crampon1923','et ils virent le Dieu d''Israël: sous ses pieds était comme un ouvrage de brillants saphirs, pur comme le ciel même.'),
('ex',24,11,'crampon1923','Et il n''étendit pas sa main sur les élus des enfants d''Israël: ils virent Dieu, et ils mangèrent et burent.'),
('ex',24,12,'crampon1923','Yahweh dit à Moïse: " Monte vers moi sur la montagne, et restes-y; je te donnerai les tables de pierre, la loi et les préceptes que j''ai écrits pour leur instruction. "'),
('ex',24,13,'crampon1923','Moïse se leva, avec Josué, son serviteur, et Moïse monta vers la montagne de Dieu.'),
('ex',24,14,'crampon1923','Il dit aux anciens: Attendez-nous ici, jusqu''à ce que nous revenions auprès de vous. Voici Aaron et Hur seront avec vous; si quelqu''un a un différend, qu''il s''adresse à eux. "'),
('ex',24,15,'crampon1923','Moïse monta vers la montagne, et la nuée couvrit la montagne;'),
('ex',24,16,'crampon1923','la gloire de Yahweh reposa sur la montagne de Sinaï, et la nuée la couvrit pendant six jours. Le septième jour, Yahweh appela Moïse du milieu de la nuée.'),
('ex',24,17,'crampon1923','L''aspect de la gloire de Yahweh était, aux yeux des enfants d''Israël, comme un feu dévorant sur le sommet de la montagne.'),
('ex',24,18,'crampon1923','Moïse entra au milieu de la nuée, et monta à la montagne; et Moïse demeura sur la montagne quarante jours et quarante nuits.'),
('ex',25,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('ex',25,2,'crampon1923','" Dis aux enfants d''Israël de prélever pour moi une offrande; de tout homme qui la donnera de bon cœur vous recevrez pour moi l''offrande.'),
('ex',25,3,'crampon1923','Voici l''offrande que vous recevrez d''eux: de l''or, de l''argent et de l''airain;'),
('ex',25,4,'crampon1923','de la pourpre violette, de la pourpre écarlate, du cramoisi, du fin lin et du poil de chèvre;'),
('ex',25,5,'crampon1923','des peaux de béliers teintes en rouge, des peaux de veaux marins et du bois d''acacia;'),
('ex',25,6,'crampon1923','de l''huile pour le chandelier, des aromates pour l''huile d''onction et pour le parfum d''encensement;'),
('ex',25,7,'crampon1923','des pierres d''onyx et d''autres pierres à enchâsser pour l''éphod et le pectoral.'),
('ex',25,8,'crampon1923','Ils me feront un sanctuaire, et j''habiterai au milieu d''eux.'),
('ex',25,9,'crampon1923','Vous vous conformerez à tout ce que je vais vous montrer, au modèle du tabernacle, et au modèle de tous ses ustensiles. "'),
('ex',25,10,'crampon1923','" Ils feront une arche de bois d''acacia; sa longueur sera de deux coudées et demie, sa largeur d''une coudée et demie, et sa hauteur d''une coudée et demie.'),
('ex',25,11,'crampon1923','Tu la revêtiras d''or pur, en dedans et en dehors, et tu y feras une guirlande d''or tout autour.'),
('ex',25,12,'crampon1923','Tu fondras pour elle quatre anneaux d''or, que tu mettras à ses quatre pieds, deux anneaux d''un côté et deux anneaux de l''autre.'),
('ex',25,13,'crampon1923','Tu feras des barres de bois d''acacia, et tu les revêtiras d''or.'),
('ex',25,14,'crampon1923','Tu passeras les barres dans les anneaux sur les côtés de l''arche, pour qu''elles servent à porter l''arche.'),
('ex',25,15,'crampon1923','Les barres resteront dans les anneaux de l''arche, et n''en seront point retirées.'),
('ex',25,16,'crampon1923','Tu mettras dans l''arche le témoignage que je te donnerai.'),
('ex',25,17,'crampon1923','Tu feras un propitiatoire d''or pur; sa longueur sera de deux coudées et demie, et sa largeur d''une coudée et demie.'),
('ex',25,18,'crampon1923','Tu feras deux chérubins d''or; tu les feras d''or battu, aux deux extrémités du propitiatoire.'),
('ex',25,19,'crampon1923','Fais un chérubin à l''une des extrémités et un chérubin à l''autre extrémité; vous ferez les chérubins sortant du propitiatoire à ses deux extrémités.'),
('ex',25,20,'crampon1923','Les chérubins auront leurs ailes déployées vers le haut, couvrant de leurs ailes le propitiatoire, et se faisant face l''un à l''autre; les faces des chérubins seront tournées vers le propitiatoire.'),
('ex',25,21,'crampon1923','Tu mettras le propitiatoire au-dessus de l''arche, et tu mettras dans l''arche le témoignage que je te donnerai.'),
('ex',25,22,'crampon1923','Là je me rencontrerai avec toi et je te communiquerai, de dessus le propitiatoire, du milieu des deux chérubins qui sont sur l''arche du témoignage, tous les ordres que je te donnerai pour les enfants d''Israël.'),
('ex',25,23,'crampon1923','Tu feras une table de bois d''acacia; sa longueur sera de deux coudées, sa largeur d''une coudée, et sa hauteur d''une coudée et demie.'),
('ex',25,24,'crampon1923','Tu la revêtiras d''or pur, et tu y mettras une guirlande d''or tout autour.'),
('ex',25,25,'crampon1923','Tu lui feras à l''entour un châssis d''une palme, et tu feras une guirlande d''or au châssis, tout autour.'),
('ex',25,26,'crampon1923','Tu feras pour la table quatre anneaux d''or; et tu mettras les anneaux aux quatre coins, qui seront à ses quatre pieds.'),
('ex',25,27,'crampon1923','Les anneaux seront près du châssis, pour recevoir les barres qui doivent porter la table.'),
('ex',25,28,'crampon1923','Tu feras les barres de bois d''acacia, et tu les revêtiras d''or; elles serviront à porter la table.'),
('ex',25,29,'crampon1923','Tu feras ses plats, ses cassolettes, ses coupes et ses tasses servant aux libations; tu les feras d''or pur.'),
('ex',25,30,'crampon1923','Tu placeras sur la table les pains de proposition, perpétuellement devant ma face.'),
('ex',25,31,'crampon1923','Tu feras un chandelier d''or pur; le chandelier, avec son pied et sa tige, sera fait d''or battu; ses calices, ses boutons et ses fleurs seront d''une même pièce.'),
('ex',25,32,'crampon1923','Six branches sortiront de ses côtés; trois branches du chandelier de l''un de ses côtés, et trois branches du chandelier du second de ses côtés.'),
('ex',25,33,'crampon1923','Il y aura sur la première branche trois calices en fleurs d''amandier, bouton et fleur, et sur la seconde branche trois calices en fleurs d''amandier, bouton et fleur; il en sera de même pour les six branches partant du chandelier.'),
('ex',25,34,'crampon1923','A la tige du chandelier, il y aura quatre calices en fleurs d''amandier, leurs boutons et leurs fleurs.'),
('ex',25,35,'crampon1923','Il y aura un bouton sous les deux premières branches partant de la tige du chandelier, un bouton sous les deux branches suivantes partant de la tige du chandelier, et un bouton sous les deux dernières branches partant de la tige du chandelier, selon les six branches sortant de la tige du chandelier.'),
('ex',25,36,'crampon1923','Ces boutons et ces branches seront d''une même pièce avec le chandelier; le tout sera une masse d''or battu, d''or pur.'),
('ex',25,37,'crampon1923','Tu feras ses lampes, au nombre de sept, et on placera ses lampes sur les branches, de manière à éclairer en face.'),
('ex',25,38,'crampon1923','Ses mouchettes et ses vases à cendre seront en or pur.'),
('ex',25,39,'crampon1923','On emploiera un talent d''or pur pour faire le chandelier avec tous ses ustensiles.'),
('ex',25,40,'crampon1923','Regarde, et fais selon le modèle qui t''est montré sur la montagne. "'),
('ex',26,1,'crampon1923','" Tu feras la Demeure de dix tentures; tu les feras de lin retors, de pourpre violette, de pourpre écarlate et de cramoisi, avec des chérubins, ouvrage d''habile tisseur.'),
('ex',26,2,'crampon1923','La longueur d''une tenture sera de vingt-huit coudées, et la largeur d''une tenture sera de quatre coudées; la dimension sera la même pour toutes les tentures.'),
('ex',26,3,'crampon1923','Cinq de ces tentures seront jointes ensemble; les cinq autres seront aussi jointes ensemble.'),
('ex',26,4,'crampon1923','Tu mettras des lacets de pourpre violette au bord de la tenture terminant le premier assemblage; et tu feras de même au bord de la tenture terminant le second assemblage.'),
('ex',26,5,'crampon1923','Tu feras cinquante lacets à la première tenture, et tu feras cinquante lacets au bord de la tenture terminant le second assemblage, et ces lacets se correspondront les uns aux autres.'),
('ex',26,6,'crampon1923','Tu feras cinquante agrafes d''or, avec lesquelles tu joindras les tentures l''une à l''autre, en sorte que la Demeure forme un seul tout.'),
('ex',26,7,'crampon1923','Tu feras aussi des tentures de poil de chèvre pour former une tente sur la Demeure; tu feras onze de ces tentures.'),
('ex',26,8,'crampon1923','La longueur d''une tenture sera de trente coudées, et la largeur d''une tenture sera de quatre coudées; la dimension sera la même pour les onze tentures.'),
('ex',26,9,'crampon1923','Tu joindras à part cinq de ces tentures, et les six autres à part, et tu replieras la sixième tenture sur le devant de la tente.'),
('ex',26,10,'crampon1923','Tu mettras cinquante lacets au bord de la tenture terminant le premier assemblage, et cinquante autres au bord de la tenture du second assemblage.'),
('ex',26,11,'crampon1923','Tu feras cinquante agrafes d''airain, tu introduiras les agrafes dans les lacets, et tu assembleras ainsi la tente, qui formera un seul tout.'),
('ex',26,12,'crampon1923','Quant à la partie qui sera de surplus dans les tentures de la tente, savoir la moitié de la tenture en plus, elle retombera sur le derrière de la Demeure,'),
('ex',26,13,'crampon1923','et les coudées en excédent l''une d''un côté, l''autre de l''autre, sur la longueur des tentures de la tente, retomberont sur les côtés de la Demeure, l''une d''un côté, l''autre de l''autre, pour la couvrir.'),
('ex',26,14,'crampon1923','Tu feras pour la tente une couverture en peaux de béliers teintes en rouge, et une couverture en peaux de veaux marins, par-dessus.'),
('ex',26,15,'crampon1923','Tu feras aussi les planches pour la Demeure, des planches de bois d''acacia, posées debout.'),
('ex',26,16,'crampon1923','La longueur d''une planche sera de dix coudées, et la largeur d''une planche sera d''une coudée et demie.'),
('ex',26,17,'crampon1923','Il y aura à chaque planche deux tenons, joints l''un à l''autre; tu feras de même pour toutes les planches de la Demeure.'),
('ex',26,18,'crampon1923','Tu feras les planches pour la Demeure: vingt planches pour la face du midi, à droite.'),
('ex',26,19,'crampon1923','Tu mettras sous les vingt planches quarante socles d''argent, deux socles sous chaque planche pour ses deux tenons.'),
('ex',26,20,'crampon1923','Pour le second côté de la Demeure, le côté du nord, tu feras vingt planches,'),
('ex',26,21,'crampon1923','ainsi que leurs quarante socles d''argent, deux socles sous chaque planche.'),
('ex',26,22,'crampon1923','Tu feras six planches pour le fond de la Demeure, du côté de l''occident.'),
('ex',26,23,'crampon1923','Tu feras deux planches pour les angles de la Demeure, dans le fond;'),
('ex',26,24,'crampon1923','elles seront doubles depuis le bas, formant ensemble un seul tout jusqu''à leur sommet, jusqu''au premier anneau. Ainsi en sera-t-il pour toutes les deux; elles seront placées aux deux angles.'),
('ex',26,25,'crampon1923','Il y aura ainsi huit planches, avec leurs socles d''argent, seize socles, deux socles sous chaque planche.'),
('ex',26,26,'crampon1923','Tu feras des traverses de bois d''acacia, cinq pour les planches de l''un des côtés de la Demeure,'),
('ex',26,27,'crampon1923','cinq traverses pour les planches du second côté de la Demeure, et cinq traverses pour les planches du côté de la Demeure qui en forme le fond, vers l''occident.'),
('ex',26,28,'crampon1923','La traverse du milieu s''étendra, le long des planches, d''une extrémité à l''autre.'),
('ex',26,29,'crampon1923','Tu revêtiras d''or les planches, et tu feras d''or leurs anneaux qui doivent recevoir les traverses, et tu revêtiras d''or les traverses.'),
('ex',26,30,'crampon1923','Tu dresseras la Demeure d''après le modèle qui t''a été montré sur la montagne.'),
('ex',26,31,'crampon1923','Tu feras un voile de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors; on y représentera des chérubins: ouvrage d''un habile tisseur.'),
('ex',26,32,'crampon1923','Tu le suspendras à quatre colonnes de bois d''acacia, revêtues d''or, avec des crochets d''or et posées sur quatre socles d''argent.'),
('ex',26,33,'crampon1923','Tu mettras le voile sous les agrafes, et c''est là, derrière le voile, que tu feras entrer l''arche du témoignage; le voile fera pour vous une séparation entre le Lieu saint et le Lieu très saint.'),
('ex',26,34,'crampon1923','Tu placeras le propitiatoire sur l''arche du témoignage dans le Lieu très saint.'),
('ex',26,35,'crampon1923','Tu placeras la table en dehors du voile, et le chandelier en face de la table, du côté méridional de la Demeure; et tu placeras la table du côté septentrional.'),
('ex',26,36,'crampon1923','Tu feras pour l''entrée de la tente un rideau en pourpre violette, pourpre écarlate, cramoisi et lin retors, ouvrage d''un dessin varié.'),
('ex',26,37,'crampon1923','Tu feras pour ce rideau cinq colonnes d''acacia, et tu les revêtiras d''or; elles auront des crochets d''or, et tu fondras pour elles cinq socles d''airain. "'),
('ex',27,1,'crampon1923','" Tu feras l''autel en bois d''acacia; sa longueur sera de cinq coudées, et sa largeur de cinq coudées. L''autel sera carré, et sa hauteur sera de trois coudées.'),
('ex',27,2,'crampon1923','A ses quatre coins, tu feras des cornes qui sortiront de l''autel, et tu le revêtiras d''airain.'),
('ex',27,3,'crampon1923','Tu feras pour l''autel des vases pour recueillir les cendres, des pelles, des bassins, des fourchettes et des brasiers; tu feras d''airain tous ces ustensiles.'),
('ex',27,4,'crampon1923','Tu feras à l''autel une grille d''airain en forme de treillis, et tu mettras quatre anneaux d''airain aux quatre bouts du treillis.'),
('ex',27,5,'crampon1923','Tu la placeras sous la corniche de l''autel, par en bas, et le treillis sera jusqu''à la moitié de la hauteur de l''autel.'),
('ex',27,6,'crampon1923','Tu feras pour l''autel des barres, des barres de bois d''acacia, que tu revêtiras d''airain.'),
('ex',27,7,'crampon1923','On passera ces barres dans les anneaux, et elles seront aux deux côtés de l''autel, quand on le transportera.'),
('ex',27,8,'crampon1923','Tu le feras creux, en planches; on le fera comme il t''a été montré sur la montagne. "'),
('ex',27,9,'crampon1923','" Tu feras le parvis de la Demeure. Du côté du midi, à droite, il y aura, pour former le parvis des rideaux de lin retors, sur une longueur de cent coudées pour un côté,'),
('ex',27,10,'crampon1923','avec vingt colonnes et leurs vingt socles d''airain; les crochets des colonnes et leurs tringles seront d''argent.'),
('ex',27,11,'crampon1923','De même, du côté du nord, il y aura des rideaux sur une longueur de cent coudées, avec vingt colonnes et leurs vingt socles d''airain; les crochets des colonnes et leurs tringles seront d''argent.'),
('ex',27,12,'crampon1923','Du côté de l''occident, il y aura, pour la largeur du parvis, cinquante coudées de rideaux, avec dix colonnes et leurs dix socles.'),
('ex',27,13,'crampon1923','Du côté de l''orient, sur le devant, le parvis aura une largeur de cinquante coudées;'),
('ex',27,14,'crampon1923','et il y aura quinze coudées de rideaux pour un côté de la porte, avec trois colonnes et leurs trois socles,'),
('ex',27,15,'crampon1923','et quinze coudées de rideaux pour le deuxième côté, avec trois colonnes et leurs trois socles.'),
('ex',27,16,'crampon1923','Pour la porte du parvis, il y aura une tenture de vingt coudées, en pourpre violette, pourpre écarlate, cramoisi, et lin retors, avec dessin varié, ainsi que quatre colonnes avec leurs quatre socles.'),
('ex',27,17,'crampon1923','Toutes les colonnes formant l''enceinte du parvis seront reliées par des tringles d''argent; elles auront des crochets d''argent et leurs socles seront d''airain.'),
('ex',27,18,'crampon1923','La longueur du parvis sera de cent coudées, sa largeur de cinquante coudées de chaque côté, et sa hauteur de cinq coudées; les rideaux seront de lin retors, et les socles d''airain.'),
('ex',27,19,'crampon1923','Tous les ustensiles destinés au service de la Demeure, tous ses pieux et tous les pieux du parvis seront d''airain. "'),
('ex',27,20,'crampon1923','" Tu ordonneras aux enfants d''Israël de t''apporter pour le luminaire de l''huile d''olives concassées, pour entretenir les lampes continuellement.'),
('ex',27,21,'crampon1923','Dans la tente de réunion, en dehors du voile qui est devant le témoignage, Aaron et ses fils la prépareront pour brûler du soir au matin en présence de Yahweh. C''est une loi perpétuelle, de génération en génération pour les enfants d''Israël. "'),
('ex',28,1,'crampon1923','" Fais venir auprès de toi Aaron ton frère, et ses fils avec lui, du milieu des enfants d''Israël, pour qu''il soit prêtre à mon service: Aaron, Nadab, Abiu, Eléazar et Ithamar, fils d''Aaron.'),
('ex',28,2,'crampon1923','Tu feras à Aaron, ton frère, des vêtements sacrés, pour marquer sa dignité et pour lui servir de parure.'),
('ex',28,3,'crampon1923','Tu t''adresseras à tous les hommes habiles que j''ai remplis d''un esprit de sagesse, et ils feront les vêtements d''Aaron, afin qu''il soit consacré pour qu''il exerce mon sacerdoce.'),
('ex',28,4,'crampon1923','Voici les vêtements qu''ils feront: un pectoral, un éphod, une robe, une tunique brodée, une tiare et une ceinture. Tels sont les vêtements sacrés qu''ils feront à Aaron, ton frère, et à ses fils, afin qu''ils soient prêtres à mon service.'),
('ex',28,5,'crampon1923','Ils emploieront de l''or, de la pourpre violette, de la pourpre écarlate, du cramoisi et du fin lin.'),
('ex',28,6,'crampon1923','Ils feront l''éphod d''or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors, mêlés dans un habile tissu.'),
('ex',28,7,'crampon1923','Il aura deux épaulettes qui réuniront ses deux extrémités, et ainsi il sera joint.'),
('ex',28,8,'crampon1923','La ceinture pour l''attacher en passant dessus sera du même travail et fera corps avec lui: elle sera d''or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors.'),
('ex',28,9,'crampon1923','Tu prendras deux pierres d''onyx, et tu y graveras les noms des fils d''Israël:'),
('ex',28,10,'crampon1923','six de leurs noms sur une pierre, et les six autres noms sur la seconde pierre, selon l''ordre de leurs naissances.'),
('ex',28,11,'crampon1923','Comme on taille les pierres précieuses et qu''on y grave des cachets, ainsi tu graveras sur les deux pierres les noms des enfants d''Israël, et tu les enchâsseras dans des chatons d''or.'),
('ex',28,12,'crampon1923','Tu placeras les deux pierres sur les épaulettes de l''éphod comme pierres de souvenir pour les enfants d''Israël, et Aaron portera leurs noms sur ses deux épaules devant Yahweh en souvenir.'),
('ex',28,13,'crampon1923','Tu feras des chatons d''or,'),
('ex',28,14,'crampon1923','et deux chaînettes d''or pur, tressées en forme de cordons, et tu fixeras aux chatons les chaînettes en forme de cordons.'),
('ex',28,15,'crampon1923','Tu feras un pectoral du jugement, artistement travaillé; tu le feras du même travail que l''éphod; tu le feras d''or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors.'),
('ex',28,16,'crampon1923','Il sera carré et double; sa longueur sera d''un empan et sa largeur d''un empan.'),
('ex',28,17,'crampon1923','Tu y adapteras une garniture de pierreries, quatre rangées de pierreries. Première rangée: une sardoine, une topaze, une émeraude;'),
('ex',28,18,'crampon1923','deuxième rangée: une escarboucle, un saphir, un diamant;'),
('ex',28,19,'crampon1923','troisième rangée: une opale, une agate, une améthyste;'),
('ex',28,20,'crampon1923','quatrième rangée: une chrysolithe, un onyx, un jaspe. Ces pierres seront enchâssées dans des rosettes d''or.'),
('ex',28,21,'crampon1923','Les pierres seront selon les noms des fils d''Israël, douze selon leurs noms; elles seront gravées comme des cachets, chacune avec son nom, pour les douze tribus. —'),
('ex',28,22,'crampon1923','Tu feras pour le pectoral des chaînettes d''or pur, tressées en forme de cordons.'),
('ex',28,23,'crampon1923','Tu feras sur le pectoral deux anneaux d''or et tu mettras les deux anneaux aux deux extrémités du pectoral.'),
('ex',28,24,'crampon1923','Tu passeras les deux cordons d''or dans les deux anneaux, aux extrémités du pectoral;'),
('ex',28,25,'crampon1923','et tu attacheras les deux bouts des deux cordons aux deux chatons, et tu les mettras sur les épaulettes de l''éphod, par devant. —'),
('ex',28,26,'crampon1923','Tu feras encore deux anneaux d''or, que tu mettras aux deux extrémités inférieures du pectoral, sur le bord intérieur appliqué contre l''éphod.'),
('ex',28,27,'crampon1923','Et tu feras deux autres anneaux d''or, que tu mettras au bas des deux épaulettes de l''éphod, sur le devant, près de son attache, au-dessus de la ceinture de l''éphod.'),
('ex',28,28,'crampon1923','On attachera le pectoral par ses anneaux aux anneaux de l''éphod avec un ruban de pourpre violette, afin que le pectoral soit au-dessus de la ceinture de l''éphod; et le pectoral ne pourra pas se séparer de l''éphod.'),
('ex',28,29,'crampon1923','C''est ainsi qu''Aaron lorsqu''il entrera dans le sanctuaire, portera sur son cœur les noms des fils d''Israël gravés sur le pectoral du jugement, en souvenir perpétuel devant Yahweh. —'),
('ex',28,30,'crampon1923','Tu joindras au pectoral du jugement l''Urim et le Thummin, et ils seront sur le cœur d''Aaron lorsqu''il se présentera devant Yahweh; et ainsi Aaron portera constamment sur son cœur, devant Yahweh, le jugement des enfants d''Israël.'),
('ex',28,31,'crampon1923','Tu feras la robe de l''éphod tout entière en pourpre violette.'),
('ex',28,32,'crampon1923','Il y aura au milieu une ouverture pour la tête, et cette ouverture aura tout autour un rebord tissé, comme à l''ouverture d''une cotte d''armes, afin que la robe ne se déchire pas.'),
('ex',28,33,'crampon1923','Tu mettras au bord inférieur des grenades de pourpre violette, de pourpre écarlate et de cramoisi, sur le bord inférieur tout autour,'),
('ex',28,34,'crampon1923','et des clochettes d''or au milieu d''elles tout autour: une clochette d''or et une grenade, une clochette d''or et une grenade sur le bord inférieur de la robe, tour autour.'),
('ex',28,35,'crampon1923','Aaron s''en revêtira pour remplir son ministère, et l''on entendra le son des clochettes quand il entrera dans le sanctuaire devant Yahweh, et quand il en sortira, et il ne mourra point.'),
('ex',28,36,'crampon1923','Tu feras une lame d''or pur, et tu y graveras, comme on grave sur un cachet: Sainteté à Yahweh.'),
('ex',28,37,'crampon1923','Tu l''attacheras avec un ruban de pourpre violette pour qu''elle soit sur la tiare; elle sera sur le devant de la tiare.'),
('ex',28,38,'crampon1923','Elle sera sur le front d''Aaron, et Aaron portera les fautes commises dans les choses saintes que consacreront les enfants d''Israël, en toute espèce de saintes offrandes; elle sera constamment sur son front devant Yahweh, pour qu''ils trouvent faveur devant Yahweh.'),
('ex',28,39,'crampon1923','Tu feras la tunique en lin; tu feras une tiare de lin, et tu feras une ceinture de diverses couleurs.'),
('ex',28,40,'crampon1923','Pour les fils d''Aaron, tu feras des tuniques, tu leur feras des ceintures et tu leur feras des mitres, pour marquer leur dignité et pour leur servir de parure.'),
('ex',28,41,'crampon1923','Tu revêtiras de ces ornements, Aaron, ton frère, et ses fils avec lui. Tu les oindras, tu les installeras et tu les consacreras, afin qu''ils soient prêtres à mon service.'),
('ex',28,42,'crampon1923','Fais-leur des caleçons de lin, pour couvrir leur nudité; ils iront depuis les reins jusqu''aux cuisses.'),
('ex',28,43,'crampon1923','Aaron et ses fils les porteront quand ils entreront dans la tente de réunion, ou quand ils s''approcheront de l''autel pour faire le service dans le sanctuaire; ainsi ils n''encourront point de faute et ne mourront point. C''est une loi perpétuelle pour Aaron et pour ses descendants après lui.'),
('ex',29,1,'crampon1923','Voici ce que tu feras pour les consacrer à mon service comme prêtres: Prends un jeune taureau et deux béliers sans défaut;'),
('ex',29,2,'crampon1923','des pains sans levain, des gâteaux sans levain pétris à l''huile, et des galettes sans levain arrosées d''huile: tu feras le tout de fleur de farine de froment.'),
('ex',29,3,'crampon1923','Tu les mettras dans une seule corbeille, et tu les présenteras dans la corbeille en même temps que tu présenteras le jeune taureau et les deux béliers.'),
('ex',29,4,'crampon1923','Tu feras avancer Aaron et ses fils à l''entrée de la tente de réunion, et tu les laveras avec de l''eau.'),
('ex',29,5,'crampon1923','Puis, ayant pris les vêtements, tu revêtiras Aaron de la tunique, de la robe de l''éphod, de l''éphod et du pectoral, et tu lui mettras la ceinture de l''éphod.'),
('ex',29,6,'crampon1923','Tu poseras la tiare sur sa tête, et tu mettras sur la tiare le diadème de sainteté.'),
('ex',29,7,'crampon1923','Tu prendras l''huile d''onction, tu en répandras sur sa tête et tu l''oindras.'),
('ex',29,8,'crampon1923','Tu feras approcher ses fils, et tu les revêtiras des tuniques.'),
('ex',29,9,'crampon1923','Tu mettras une ceinture à Aaron et à ses fils et tu attacheras des mitres aux fils d''Aaron. Le sacerdoce leur appartiendra par une loi perpétuelle, et tu installeras Aaron et ses fils.'),
('ex',29,10,'crampon1923','Tu amèneras le taureau devant la tente de réunion, et Aaron et ses fils poseront leurs mains sur la tête du taureau.'),
('ex',29,11,'crampon1923','Tu égorgeras le taureau devant Yahweh, à l''entrée de la tente de réunion;'),
('ex',29,12,'crampon1923','tu prendras du sang du taureau, tu en mettras avec ton doigt sur les cornes de l''autel, et tu répandras tout le sang au pied de l''autel.'),
('ex',29,13,'crampon1923','Tu prendras toute la graisse qui couvre les entrailles, le réseau du foie et les deux rognons avec la graisse qui les entoure, et tu feras fumer tout cela sur l''autel.'),
('ex',29,14,'crampon1923','Mais tu consumeras par le feu hors du camp la chair du taureau, sa peau et ses excréments: c''est un sacrifice pour le péché.'),
('ex',29,15,'crampon1923','Tu prendras l''un des béliers, et Aaron et ses fils poseront leurs mains sur la tête du bélier.'),
('ex',29,16,'crampon1923','Tu égorgeras le bélier, tu en prendras le sang et tu le répandras sur l''autel tout autour.'),
('ex',29,17,'crampon1923','Tu couperas le bélier par morceaux et, ayant lavé les entrailles et les jambes, tu les mettras sur les morceaux et sur sa tête,'),
('ex',29,18,'crampon1923','et tu feras fumer tout le bélier sur l''autel. C''est un holocauste à Yahweh, d''agréable odeur, un sacrifice par le feu pour Yahweh.'),
('ex',29,19,'crampon1923','Tu prendras le second bélier, et Aaron et ses fils poseront leurs mains sur la tête du bélier.'),
('ex',29,20,'crampon1923','Tu égorgeras le bélier et, ayant pris de son sang, tu en mettras sur le lobe de l''oreille droite d''Aaron et sur le lobe de l''oreille droite de ses fils, sur le pouce de leur main droite et sur le gros orteil de leur pied droit, et tu répandras le sang sur l''autel tout autour.'),
('ex',29,21,'crampon1923','Tu prendras du sang qui sera sur l''autel et de l''huile d''onction, et tu en aspergeras Aaron et ses vêtements, ses fils et leurs vêtements avec lui. Et ainsi il sera consacré, lui et ses vêlements, ainsi que ses fils et les vêtements de ses fils avec lui.'),
('ex',29,22,'crampon1923','Tu prendras la graisse du bélier, la queue, la graisse qui enveloppe les entrailles, le réseau du foie, les deux rognons et la graisse qui les entoure, et l''épaule droite, car c''est un bélier d''installation.'),
('ex',29,23,'crampon1923','Tu prendras aussi, dans la corbeille des pains sans levain placée devant Yahweh, un gâteau de pain, un gâteau à l''huile et une galette.'),
('ex',29,24,'crampon1923','Tu poseras toutes ces choses sur les paumes des mains d''Aaron et sur les paumes des mains de ses fils, et tu les balanceras comme offrande balancée devant Yahweh.'),
('ex',29,25,'crampon1923','Tu les ôteras ensuite de leurs mains et tu les feras brûler sur l''autel par-dessus l''holocauste, en agréable odeur devant Yahweh: c''est un sacrifice par le feu pour Yahweh.'),
('ex',29,26,'crampon1923','Tu prendras la poitrine du bélier qui aura servi à l''installation d''Aaron, et tu la balanceras comme offrande balancée devant Yahweh: ce sera ta portion.'),
('ex',29,27,'crampon1923','Du bélier d''installation, de ce qui revient à Aaron et de ce qui revient à ses fils, tu consacreras ce qui aura été balancé et ce qui aura été élevé, savoir la poitrine balancée et l''épaule élevée:'),
('ex',29,28,'crampon1923','ce sera pour Aaron et ses fils une redevance perpétuelle de la part des enfants d''Israël, car c''est une offrande élevée; et les enfants d''Israël auront à prélever une offrande sur leurs sacrifices d''actions de grâces, leur offrande prélevée pour Yahweh.'),
('ex',29,29,'crampon1923','Les vêtements sacrés d''Aaron seront après lui pour ses fils, qui en seront revêtus lorsqu''on les oindra et qu''on les installera.'),
('ex',29,30,'crampon1923','Sept jours durant, celui de ses fils qui sera prêtre à sa place les portera, celui qui entrera dans la tente de réunion pour faire le service dans le sanctuaire.'),
('ex',29,31,'crampon1923','Tu prendras le bélier d''installation, et tu en feras cuire la chair dans un lieu saint.'),
('ex',29,32,'crampon1923','Aaron et ses fils mangeront, à l''entrée de la tente de réunion, la chair du bélier et le pain qui sera dans la corbeille.'),
('ex',29,33,'crampon1923','Ils mangeront ainsi ce qui aura servi à faire l''expiation pour les installer et les consacrer; nul étranger n''en mangera, car ce sont des choses saintes.'),
('ex',29,34,'crampon1923','S''il reste jusqu''au lendemain de la chair de l''installation et du pain, tu brûleras ce reste, et on ne le mangera pas, car c''est une chose sainte.'),
('ex',29,35,'crampon1923','Tu feras ainsi à l''égard d''Aaron et de ses fils, selon tous les ordres que je t''ai donnés. Tu les installeras pendant sept jours.'),
('ex',29,36,'crampon1923','Tu offriras chaque jour un jeune taureau en sacrifice pour le péché, pour l''expiation; tu ôteras de l''autel le péché par cette expiation, et tu l''oindras pour le consacrer.'),
('ex',29,37,'crampon1923','Pendant sept jours, tu feras l''expiation pour l''autel et tu le consacreras; et l''autel sera très saint, et tout ce qui touchera l''autel sera sacré.'),
('ex',29,38,'crampon1923','Voici ce que tu offriras sur l''autel: deux agneaux d''un an, chaque jour, à perpétuité.'),
('ex',29,39,'crampon1923','Tu offriras l''un de ces agneaux le matin, et tu offriras l''autre agneau entre les deux soirs.'),
('ex',29,40,'crampon1923','Avec le premier agneau, tu offriras un dixième d''épha de fleur de farine pétrie avec un quart de hin d''huile d''olive concassée, et une libation d''un quart de hin de vin.'),
('ex',29,41,'crampon1923','Tu offriras le second agneau entre les deux soirs, tu l''accompagneras d''une offrande et d''une libation semblables à celles du matin. C''est un sacrifice d''agréable odeur, un sacrifice par le feu pour Yahweh:'),
('ex',29,42,'crampon1923','holocauste perpétuel qui doit être offert par vous d''âge en âge, à l''entrée de la tente de réunion, devant Yahweh, là où je me rencontrerai avec vous, pour t''y parler.'),
('ex',29,43,'crampon1923','Je me rencontrerai là avec les enfants d''Israël, et ce lieu sera consacré par ma gloire.'),
('ex',29,44,'crampon1923','Je consacrerai la tente de réunion et l''autel, et je consacrerai Aaron et ses fils, pour qu''ils soient prêtres à mon service.'),
('ex',29,45,'crampon1923','J''habiterai au milieu des enfants d''Israël, et je serai leur Dieu.'),
('ex',29,46,'crampon1923','Ils connaîtront que moi, Yahweh, je suis leur Dieu, qui les ai fait sortir du pays d''Egypte, pour habiter au milieu d''eux, moi Yahweh, leur Dieu.'),
('ex',30,1,'crampon1923','Tu feras un autel pour faire fumer l''encens, tu le feras de bois d''acacia;'),
('ex',30,2,'crampon1923','sa longueur sera d''une coudée, et sa largeur d''une coudée; il sera carré, et sa hauteur sera de deux coudées; ses cornes feront corps avec lui.'),
('ex',30,3,'crampon1923','Tu le revêtiras d''or pur, le dessus, les côtés tout autour et les cornes, et tu y feras une guirlande d''or tout autour.'),
('ex',30,4,'crampon1923','Tu feras pour lui deux anneaux d''or, au-dessous de la guirlande, sur ses deux arêtes: tu les feras aux deux côtés, pour recevoir les barres qui serviront à le porter.'),
('ex',30,5,'crampon1923','Tu feras les barres de bois d''acacia, et tu les revêtiras d''or.'),
('ex',30,6,'crampon1923','Tu placeras l''autel en face du voile qui est devant l''arche du témoignage, en face du propitiatoire qui est sur le témoignage, là où je me rencontrerai avec toi.'),
('ex',30,7,'crampon1923','Aaron y fera fumer l''encens; il le fera fumer chaque matin, lorsqu''il préparera les lampes,'),
('ex',30,8,'crampon1923','et il le fera fumer entre les deux soirs, lorsqu''Aaron mettra les lampes sur le chandelier. Encens perpétuel devant Yahweh, parmi vos descendants.'),
('ex',30,9,'crampon1923','Vous n''offrirez sur l''autel ni parfum profane, ni holocauste, ni offrande, et vous n''y répandrez pas de libation.'),
('ex',30,10,'crampon1923','Aaron fera l''expiation sur les cornes de l''autel une fois chaque année; avec le sang de la victime expiatoire, il y fera l''expiation une fois l''an parmi vos descendants. Cet autel sera très saint à Yahweh. "'),
('ex',30,11,'crampon1923','Yahweh parla à Moïse, en disant:'),
('ex',30,12,'crampon1923','" Quand tu compteras les enfants d''Israël pour en faire le recensement, ils donneront chacun à Yahweh une rançon pour leur âme, lorsqu''on les recensera, afin qu''ils ne soient frappés d''aucun fléau lors de leur recensement.'),
('ex',30,13,'crampon1923','Voici ce que donneront tous ceux qui seront compris dans le dénombrement: un demi-sicle, selon le sicle du sanctuaire, qui est de vingt guéras; un demi-sicle sera le don levé pour Yahweh.'),
('ex',30,14,'crampon1923','Tout homme compris dans le dénombrement, depuis l''âge de vingt ans et au-dessus, acquittera la contribution de Yahweh.'),
('ex',30,15,'crampon1923','Le riche ne paiera pas plus, et le pauvre ne paiera pas moins d''un demi-sicle, pour acquitter la contribution de Yahweh, comme rançon de vos âmes.'),
('ex',30,16,'crampon1923','Tu recevras des enfants d''Israël l''argent de la rançon, et tu l''appliqueras au service de la tente de réunion; il sera pour les enfants d''Israël un titre devant Yahweh pour la rançon de leurs âmes. "'),
('ex',30,17,'crampon1923','Yahweh parla à Moïse en disant:'),
('ex',30,18,'crampon1923','" Tu feras une cuve d''airain, avec sa base d''airain, pour les ablutions; tu la placeras entre la tente de réunion et l''autel, et tu y mettras de l''eau,'),
('ex',30,19,'crampon1923','et Aaron et ses fils en prendront pour se laver les mains et les pieds.'),
('ex',30,20,'crampon1923','Ils se laveront avec cette eau, afin qu''ils ne meurent point, et lorsqu''ils entreront dans la tente de réunion, et lorsqu''ils s''approcheront de l''autel pour faire le service, pour faire fumer un sacrifice à Yahweh.'),
('ex',30,21,'crampon1923','Ils se laveront les pieds et les mains, et ils ne mourront pas. Ce sera une loi perpétuelle pour eux, pour Aaron et sa postérité d''âge en âge. "'),
('ex',30,22,'crampon1923','Yahweh parla à Moïse, en disant:'),
('ex',30,23,'crampon1923','" Prends, parmi les meilleurs aromates, cinq cents sicles de myrrhe vierge, la moitié, soit deux cent cinquante sicles, de cinname aromatique, deux cent cinquante sicles de canne odorante,'),
('ex',30,24,'crampon1923','cinq cents sicles de casse, selon le sicle du sanctuaire, et un hin d''huile d''olive.'),
('ex',30,25,'crampon1923','Tu en feras une huile pour l''onction sainte, un parfum composé selon l''art du parfumeur: ce sera l''huile pour l''onction sainte.'),
('ex',30,26,'crampon1923','Tu en oindras la tente de réunion et l''arche du témoignage,'),
('ex',30,27,'crampon1923','la table et tous ses ustensiles, le chandelier et ses ustensiles, l''autel des parfums,'),
('ex',30,28,'crampon1923','l''autel des holocaustes et tous ses ustensiles, et la cuve avec sa base.'),
('ex',30,29,'crampon1923','Tu les consacreras, et ils seront très saints; tout ce qui les touchera sera saint.'),
('ex',30,30,'crampon1923','Tu oindras Aaron et ses fils, et tu les consacreras, pour qu''ils me servent comme prêtres.'),
('ex',30,31,'crampon1923','Tu parleras aux enfants d''Israël, en disant: Ce sera l''huile d''onction sainte, pour moi d''âge en âge.'),
('ex',30,32,'crampon1923','On n''en répandra pas sur le corps d''un homme, et vous n''en ferez pas une semblable, de même composition; c''est une chose sacrée, et vous la regarderez comme chose sacrée.'),
('ex',30,33,'crampon1923','Quiconque en composera de semblable, ou en mettra sur un étranger, sera retranché de son peuple. "'),
('ex',30,34,'crampon1923','Yahweh dit à Moïse: " Prends des aromates: résine, ongle odorant, galbanum; des aromates et de l''encens pur; ils seront en parties égales.'),
('ex',30,35,'crampon1923','Tu en feras un parfum pour l''encensement, composé selon l''art du parfumeur; il sera salé, pur et saint.'),
('ex',30,36,'crampon1923','Tu le réduiras en poudre, et tu en mettras devant le témoignage, dans la tente de réunion, où je me rencontrerai avec toi. Ce sera pour vous une chose très sainte.'),
('ex',30,37,'crampon1923','Le parfum que tu feras, vous n''en ferez pas pour vous de même composition; tu le regarderas comme une chose sacrée pour Yahweh.'),
('ex',30,38,'crampon1923','Quiconque en fera de semblable, pour en respirer l''odeur, sera retranché de son peuple, "'),
('ex',31,1,'crampon1923','Yahweh parla à Moïse en disant:'),
('ex',31,2,'crampon1923','" Sache que j''ai appelé par son nom Béséléel, fils d''Uri, fils de Hur, de la tribu de Juda.'),
('ex',31,3,'crampon1923','Je l''ai rempli de l''esprit de Dieu, de sagesse, d''intelligence et de savoir pour toutes sortes d''ouvrages:'),
('ex',31,4,'crampon1923','pour faire des inventions, pour travailler l''or, l''argent et l''airain,'),
('ex',31,5,'crampon1923','pour graver les pierres à enchâsser, pour tailler le bois et exécuter toutes sortes d''ouvrages.'),
('ex',31,6,'crampon1923','Et voici, je lui ai adjoint Ooliab, fils d''Achisamech, de la tribu de Dan, et j''ai mis la sagesse dans le cœur de tout homme habile, pour qu''ils exécutent tout ce que je t''ai ordonné:'),
('ex',31,7,'crampon1923','la tente de réunion, l''arche du témoignage, le propitiatoire, qui est dessus, et tous les meubles de la tente;'),
('ex',31,8,'crampon1923','la table et ses ustensiles, le chandelier d''or pur et tous ses ustensiles, l''autel des parfums,'),
('ex',31,9,'crampon1923','l''autel des holocaustes et tous ses ustensiles, la cuve avec sa base;'),
('ex',31,10,'crampon1923','les vêtements de cérémonie, les vêtements sacrés pour le prêtre Aaron, les vêtements de ses fils pour les fonctions du sacerdoce;'),
('ex',31,11,'crampon1923','l''huile d''onction et le parfum à brûler pour le sanctuaire. Ils exécuteront tous les ordres que je t''ai donnés. "'),
('ex',31,12,'crampon1923','Yahweh parla à Moïse, en disant:'),
('ex',31,13,'crampon1923','" Parle aux enfants d''Israël et dis-leur: Ne manquez pas d''observer mes sabbats; car c''est entre moi et vous un signe pour toutes vos générations, pour que vous sachiez que c''est moi, Yahweh, qui vous sanctifie.'),
('ex',31,14,'crampon1923','Vous observerez le sabbat, car c''est pour vous une chose sainte. Celui qui le profanera sera puni de mort; celui qui fera quelque ouvrage ce jour-là sera retranché du milieu de son peuple.'),
('ex',31,15,'crampon1923','On travaillera six jours; mais le septième jour sera un jour de repos complet, consacré à Yahweh. Quiconque fera un travail le jour du sabbat sera puni de mort.'),
('ex',31,16,'crampon1923','Les enfants d''Israël observeront le sabbat et le célébreront, eux et leurs descendants, comme une alliance perpétuelle.'),
('ex',31,17,'crampon1923','Ce sera, entre moi et les enfants d''Israël, un signe à perpétuité; car en six jours Yahweh a fait le ciel et la terre, et le septième jour il a cessé son œuvre et il s''est reposé. "'),
('ex',31,18,'crampon1923','Lorsque Yahweh eut achevé de parler à Moïse sur la montagne de Sinaï, il lui donna les deux tables du témoignage, tables de pierre, écrites du doigt de Dieu.'),
('ex',32,1,'crampon1923','Le peuple, voyant que Moïse tardait à descendre de la montagne, s''assembla autour d''Aaron et lui dit: " Allons, fais-nous un dieu qui marche devant nous. Car pour ce Moïse, l''homme qui nous a fait monter du pays d''Egypte, nous ne savons ce qu''il en est devenu. "'),
('ex',32,2,'crampon1923','Aaron leur dit: " Otez les anneaux d''or qui sont aux oreilles de vos femmes, de vos fils et de vos filles, et apportez-les-moi. "'),
('ex',32,3,'crampon1923','Tout le monde ôta les anneaux d''or qu''ils avaient aux oreilles, et ils les apportèrent à Aaron.'),
('ex',32,4,'crampon1923','Il les reçut de leurs mains, façonna l''or au burin, et en fit un veau en fonte. Et ils dirent: " Israël, voici ton Dieu, qui t''a fait monter du pays d''Egypte. "'),
('ex',32,5,'crampon1923','Ayant vu cela, Aaron construisit un autel devant l''image, et il s''écria: " Demain il y aura fête en l''honneur de Yahweh. "'),
('ex',32,6,'crampon1923','Le lendemain, s''étant levés de bon matin, ils offrirent des holocaustes et présentèrent des sacrifices pacifiques; et le peuple s''assit pour manger et pour boire, puis ils se levèrent pour se divertir.'),
('ex',32,7,'crampon1923','Yahweh dit à Moïse: " Va, descends; car ton peuple que tu as fait monter du pays d''Egypte, s''est conduit très mal.'),
('ex',32,8,'crampon1923','Ils se sont bien vite détournés de la voie que je leur avais prescrite; ils se sont fait un veau en fonte, ils se sont prosternés devant lui, et ils lui ont offert des sacrifices, et ils ont dit: Israël, voici ton Dieu, qui t''a fait monter du pays d''Egypte. "'),
('ex',32,9,'crampon1923','Yahweh dit à Moïse: " Je vois que ce peuple est un peuple au cou raide.'),
('ex',32,10,'crampon1923','Maintenant laisse-moi: que ma colère s''embrase contre eux et que je les consume! Mais je ferai de toi une grande nation. "'),
('ex',32,11,'crampon1923','Moïse implora Yahweh, son Dieu, et dit: " Pourquoi, Yahweh, votre colère s''embraserait-elle contre votre peuple, que vous avez fait sortir du pays d''Egypte par une grande puissance et par une main forte?'),
('ex',32,12,'crampon1923','Pourquoi les Egyptiens diraient-ils: C''est pour leur malheur qu''il les a fait sortir, c''est pour les faire périr dans les montagnes et pour les anéantir de dessus la terre? Revenez de l''ardeur de votre colère, et repentez-vous du mal que vous voulez faire à votre peuple.'),
('ex',32,13,'crampon1923','Souvenez-vous d''Abraham, d''Isaac et d''Israël, vos serviteurs, auxquels vous avez dit, en jurant par vous-même: Je multiplierai votre postérité comme les étoiles du ciel, et tout ce pays dont j''ai parlé, je le donnerai à vos descendants, et ils le posséderont à jamais. "'),
('ex',32,14,'crampon1923','Et Yahweh se repentit du mal qu''il avait parlé de faire à son peuple.'),
('ex',32,15,'crampon1923','Moïse revint et descendit de la montagne, ayant dans sa main les deux tables du témoignage, tables écrites sur leurs deux côtés; elles étaient écrites sur l''une et l''autre face.'),
('ex',32,16,'crampon1923','Les tables étaient l''ouvrage de Dieu, et l''écriture était l''écriture de Dieu, gravée sur les tables.'),
('ex',32,17,'crampon1923','Josué entendit le bruit que faisait le peuple en poussant des cris, et il dit à Moïse: Il y a un cri de bataille dans le camp! "'),
('ex',32,18,'crampon1923','Moïse répondit: " Ce n''est ni un bruit de cris de victoire, ni un bruit de cris de défaite; j''entends la voix de gens qui chantent. "'),
('ex',32,19,'crampon1923','Lorsqu''il fut près du camp, il vit le veau et les danses. Et la colère de Moïse s''enflamma; il jeta de ses mains les tables et les brisa au pied de la Montagne.'),
('ex',32,20,'crampon1923','Et, prenant le veau qu''ils avaient fait, il le brûla au feu, le broya jusqu''à le réduire en poudre, répandit cette poudre sur l''eau, et en fit boire aux enfants d''Israël.'),
('ex',32,21,'crampon1923','Moïse dit à Aaron: " Que t''a fait ce peuple pour que tu aies amené sur lui un si grand péché? "'),
('ex',32,22,'crampon1923','Aaron répondit: " Que la colère de mon seigneur ne s''enflamme pas! Tu sais toi-même que ce peuple est porté au mal.'),
('ex',32,23,'crampon1923','Ils m''ont dit: Fais-nous un dieu qui marche devant nous; car pour ce Moïse, cet homme qui nous a fait monter du pays d''Egypte, nous ne savons ce qu''il en est devenu.'),
('ex',32,24,'crampon1923','Je leur ai dit: Que ceux qui ont de l''or s''en dépouillent! Ils m''en ont donné, je l''ai jeté au feu, et il en est sorti ce veau. "'),
('ex',32,25,'crampon1923','Moïse vit que le peuple n''avait plus de frein, parce qu''Aaron lui avait ôté tout frein, l''exposant à devenir une risée parmi ses ennemis.'),
('ex',32,26,'crampon1923','Et Moïse se plaça à la porte du camp, et il dit: " A moi ceux qui sont pour Yahweh! " Et tous les enfants de Lévi se rassemblèrent auprès de lui.'),
('ex',32,27,'crampon1923','Il leur dit: " Ainsi parle Yahweh, le Dieu d''Israël: Que chacun de vous mette son épée à son côté; passez et repassez dans le camp d''une porte à l''autre, et que chacun tue son frère, chacun son ami, chacun son parent! "'),
('ex',32,28,'crampon1923','Les enfants de Lévi firent ce qu''ordonnait Moïse, et il périt ce jour-là environ trois mille hommes du peuple.'),
('ex',32,29,'crampon1923','Moïse dit: " Consacrez-vous aujourd''hui à Yahweh, puisque chacun de vous a été contre son fils et son père, afin qu''il vous donne aujourd''hui une bénédiction. "'),
('ex',32,30,'crampon1923','Le lendemain, Moïse dit au peuple: " Vous avez commis un grand péché. Et maintenant je vais monter vers Yahweh: peut-être obtiendrai-je le pardon de votre péché. "'),
('ex',32,31,'crampon1923','Moïse retourna vers Yahweh et dit: " Ah! ce peuple a commis un grand péché! Ils se sont fait un dieu d''or.'),
('ex',32,32,'crampon1923','Pardonnez maintenant leur péché; sinon effacez-moi de votre livre que vous avez écrit. "'),
('ex',32,33,'crampon1923','Yahweh dit à Moïse: " C''est celui qui a péché contre moi que j''effacerai de mon livre.'),
('ex',32,34,'crampon1923','Va maintenant, conduis le peuple où je t''ai dit. Voici, mon ange marchera devant toi, mais, au jour de ma visite, je les punirai de leur péché. "'),
('ex',32,35,'crampon1923','C''est ainsi que Yahweh frappa le peuple, parce qu''ils avaient fait le veau qu''Aaron avait fait.'),
('ex',33,1,'crampon1923','Yahweh dit à Moïse: " Va, pars d''ici, toi et le peuple que tu as fait monter du pays d''Egypte; monte au pays que j''ai promis avec serment à Abraham, à Isaac et à Jacob, en disant: Je le donnerai à ta postérité.'),
('ex',33,2,'crampon1923','J''enverrai devant toi un ange, et je chasserai le Chananéen, l''Amorrhéen, le Héthéen, le Phérézéen, le Hévéen et le Jébuséen.'),
('ex',33,3,'crampon1923','Monte vers un pays où coulent le lait et le miel; mais je ne monterai point au milieu de toi, car tu es un peuple au cou raide, pour ne pas t''anéantir en chemin. "'),
('ex',33,4,'crampon1923','En entendant ces dures paroles, le peuple prit le deuil, et personne ne mit ses ornements.'),
('ex',33,5,'crampon1923','Alors Yahweh dit à Moïse: " Dis aux enfants d''Israël: Vous êtes un peuple au cou raide; si je montais un seul instant au milieu de toi, je t''anéantirais. Et maintenant, enlève tes ornements de dessus toi, et je saurai ce que j''ai à te faire. "'),
('ex',33,6,'crampon1923','Les enfants d''Israël se dépouillèrent de leurs ornements, dès le mont Horeb.'),
('ex',33,7,'crampon1923','Moïse prit la tente et se la dressa hors du camp, à quelque distance; il l''appela tente de réunion; et quiconque cherchait Yahweh, se rendait à la tente de réunion, qui était hors du camp.'),
('ex',33,8,'crampon1923','Et lorsque Moïse se rendait à la tente, tout le peuple se levait, chacun se tenant à l''entrée de la tente, et on suivait des yeux Moïse, jusqu''à ce qu''il entrât dans la tente.'),
('ex',33,9,'crampon1923','Dès que Moïse était entré dans la tente, la colonne de nuée descendait et se tenait à l''entrée de la tente, et Yahweh parlait avec Moïse.'),
('ex',33,10,'crampon1923','Tout le peuple voyait la colonne de nuée qui se tenait à l''entrée de la tente; et tout le peuple se levait, et chacun se prosternait à l''entrée de sa tente.'),
('ex',33,11,'crampon1923','Et Yahweh parlait à Moïse face à face, comme un homme parle à son ami. Moïse retournait ensuite au camp; mais son serviteur Josué, fils de Nun, jeune homme, ne s''éloignait pas du milieu de la tente.'),
('ex',33,12,'crampon1923','Moïse dit à Yahweh: " Vous me dites: Fais monter ce peuple; et vous ne me faites pas connaître celui que vous enverrez avec moi. Cependant vous avez dit: Je te connais par ton nom, et tu as trouvé grâce à mes yeux.'),
('ex',33,13,'crampon1923','Et maintenant, si j''ai bien trouvé grâce à vos yeux, faites moi donc connaître vos voies, et que je vous connaisse, afin que je trouve grâce à vos yeux. Considérez que cette nation est votre peuple. "'),
('ex',33,14,'crampon1923','Yahweh répondit: " Ma face ira avec toi, et je te donnerai un repos. "'),
('ex',33,15,'crampon1923','Moïse dit: " Si votre face ne vient pas, ne nous faites pas partir d''ici.'),
('ex',33,16,'crampon1923','A quoi connaîtra-t-on que j''ai trouvé grâce à vos yeux, moi et votre peuple, sinon à ce que vous marcherez avec nous? C''est ce qui nous distinguera, moi et votre peuple, de tous les peuples qui sont sur la face de la terre. "'),
('ex',33,17,'crampon1923','Yahweh dit à Moïse: " Je ferai encore ce que tu demandes, car tu as trouvé grâce à mes yeux et je te connais par ton nom. "'),
('ex',33,18,'crampon1923','Moïse dit: " Faites-moi voir votre gloire. "'),
('ex',33,19,'crampon1923','Yahweh répondit: " Je ferai passer devant toi toute ma bonté, et je prononcerai devant toi le nom de Yahweh: car je fais grâce à qui je fais grâce, et miséricorde à qui je fais miséricorde. "'),
('ex',33,20,'crampon1923','Yahweh dit: " Tu ne pourras voir ma face, car l''homme ne peut me voir et vivre. "'),
('ex',33,21,'crampon1923','Yahweh dit: " Voici une place près de moi; tu te tiendras sur le rocher.'),
('ex',33,22,'crampon1923','Quand ma gloire passera, je te mettrai dans le creux du rocher, et je te couvrirai de ma main jusqu''à ce que j''aie passé.'),
('ex',33,23,'crampon1923','Alors je retirerai ma main et tu me verras par derrière; mais ma face ne saurait être vue. "'),
('ex',34,1,'crampon1923','Yahweh dit à Moïse: " Taille deux tables de pierre comme les premières, et j''y écrirai les paroles qui étaient sur les premières tables que tu as brisées:'),
('ex',34,2,'crampon1923','Sois prêt pour demain, et tu monteras dès le matin sur la montagne de Sinaï; tu te tiendras là devant moi, au sommet de la montagne.'),
('ex',34,3,'crampon1923','Que personne ne monte avec toi, et que personne ne se montre nulle part sur la montagne, et même que ni brebis ni bœufs ne paissent du côté de cette montagne. "')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ex',34,4,'crampon1923','Moïse tailla donc deux tables de pierre comme les premières; et, s''étant levé de bonne heure, il monta sur la montagne de Sinaï, selon que Yahweh le lui avait ordonné; et il prit dans sa main les deux tables de pierre.'),
('ex',34,5,'crampon1923','Yahweh descendit dans la nuée, se tint là avec lui et prononça le nom de Yahweh.'),
('ex',34,6,'crampon1923','Et Yahweh passa devant lui et s''écria: " Yahweh! Yahweh! Dieu miséricordieux et compatissant, lent à la colère, riche en bonté et en fidélité,'),
('ex',34,7,'crampon1923','qui conserve sa grâce jusqu''à mille générations, qui pardonne l''iniquité, la révolte et le péché; mais il ne les laisse pas impunis, visitant l''iniquité des pères sur les enfants et sur les enfants des enfants jusqu''à la troisième et à la quatrième génération! "'),
('ex',34,8,'crampon1923','Aussitôt Moïse s''inclina vers la terre et se prosterna,'),
('ex',34,9,'crampon1923','en disant: " Si j''ai trouvé grâce à vos yeux, Seigneur, daigne le Seigneur marcher au milieu de nous, car c''est un peuple au cou raide; pardonnez nos iniquités et nos péchés, et prenez-nous pour votre héritage. "'),
('ex',34,10,'crampon1923','Yahweh dit: " Voici que je fais une alliance: en présence de tout ton peuple, je ferai des prodiges qui n''ont eu lieu dans aucun pays et chez aucune nation; et tout le peuple qui t''environne verra l''œuvre de Yahweh, car terribles sont les choses que j''accomplirai avec toi.'),
('ex',34,11,'crampon1923','Prends garde à ce que je t''ordonne aujourd''hui. Voici, je chasserai devant toi l''Amorrhéen, le Chananéen, le Héthéen, le Phérézéen, le Hévéen, et le Jébuséen.'),
('ex',34,12,'crampon1923','Garde-toi de contracter alliance avec les habitants du pays contre lequel tu marches, de peur qu''ils ne soient un piège au milieu de toi.'),
('ex',34,13,'crampon1923','Mais vous renverserez leurs autels, vous briserez leurs stèles et vous abattrez leurs Aschérim.'),
('ex',34,14,'crampon1923','Tu n''adoreras aucun autre dieu; car Yahweh se nomme le jaloux, il est un Dieu jaloux.'),
('ex',34,15,'crampon1923','Ne contracte donc pas alliance avec les habitants du pays, de peur que, lorsqu''ils se prostituent à leurs dieux et leur offrent des sacrifices, ils ne t''invitent et que tu ne manges de leurs victimes;'),
('ex',34,16,'crampon1923','de peur que tu ne prennes de leurs filles pour tes fils, et que leurs filles, se prostituant à leurs dieux, n''entraînent tes fils à se prostituer aussi à leurs dieux.'),
('ex',34,17,'crampon1923','Tu ne feras point de dieux de métal fondu.'),
('ex',34,18,'crampon1923','Tu observeras la fête des Azymes: pendant sept jours tu mangeras des pains sans levain, comme je te l''ai prescrit, au temps fixé du mois d''abib, car c''est dans le mois d''abib que tu es sorti d''Egypte.'),
('ex',34,19,'crampon1923','Tout premier-né m''appartient; de même, tout premier-né mâle de tes troupeaux, soit bœuf, soit brebis.'),
('ex',34,20,'crampon1923','Tu rachèteras avec un agneau le premier-né de l''âne; et, si tu ne le rachètes pas, tu lui briseras la nuque. Tu rachèteras tout premier-né de tes fils; et l''on ne se présentera pas les mains vides devant ma face.'),
('ex',34,21,'crampon1923','Tu travailleras six jours, mais tu te reposeras le septième jour, même au temps du labourage et de la moisson.'),
('ex',34,22,'crampon1923','Tu célébreras la fête des Semaines, des premiers produits de la moisson du froment, et la fête de la récolte à la fin de l''année.'),
('ex',34,23,'crampon1923','Trois fois par an, tous les mâles se présenteront devant le Seigneur, Yahweh, Dieu Israël.'),
('ex',34,24,'crampon1923','Car je chasserai les nations devant toi et j''étendrai tes frontières; et personne ne convoitera ton pays pendant que tu monteras pour te présenter devant Yahweh, ton Dieu, trois fois par an.'),
('ex',34,25,'crampon1923','Tu n''offriras pas avec du pain levé le sang de ma victime, et le sacrifice de la fête de Pâque ne sera pas gardé pendant la nuit jusqu''au matin.'),
('ex',34,26,'crampon1923','Tu apporteras les prémices des premiers fruits de ton sol à la maison de Yahweh, ton Dieu. Tu ne feras pas cuire un chevreau dans le lait de sa mère. "'),
('ex',34,27,'crampon1923','Yahweh dit à Moïse: " Ecris, toi, ces paroles; car c''est d''après ces paroles que je fais alliance avec toi et avec Israël. "'),
('ex',34,28,'crampon1923','Moïse fut là avec Yahweh quarante jours et quarante nuits, sans manger de pain et sans boire d''eau. Et Yahweh écrivit sur les tables les paroles de l''alliance, les dix paroles.'),
('ex',34,29,'crampon1923','Moïse descendit de la montagne de Sinaï; Moïse avait dans sa main les deux tables du témoignage, en descendant de la montagne; et Moïse ne savait pas que la peau de son visage était devenue rayonnante pendant qu''il parlait avec Yahweh.'),
('ex',34,30,'crampon1923','Aaron et tous les enfants d''Israël virent Moïse, et voici, la peau de son visage rayonnait; et ils craignirent de s''approcher de lui.'),
('ex',34,31,'crampon1923','Moïse les appela, et Aaron et tous les princes de l''assemblée vinrent auprès de lui, et il leur parla.'),
('ex',34,32,'crampon1923','Ensuite tous les enfants d''Israël s''approchèrent, et il leur donna tous les ordres qu''il avait reçus de Yahweh sur la montagne de Sinaï.'),
('ex',34,33,'crampon1923','Lorsque Moïse eut achevé de leur parler, il mit un voile sur son visage.'),
('ex',34,34,'crampon1923','Quand Moïse entrait devant Yahweh pour parler avec lui, il ôtait le voile, jusqu''à ce qu''il sortit; puis il sortait et disait aux enfants d''Israël ce qui lui avait été ordonné.'),
('ex',34,35,'crampon1923','Les enfants d''Israël voyaient le visage de Moïse, ils voyaient que la peau du visage de Moïse était rayonnante; et Moïse remettait le voile sur son visage, jusqu''à ce qu''il entrât pour parler avec Yahweh.'),
('ex',35,1,'crampon1923','Moïse ayant convoqué toute l''assemblée d''Israël, leur dit: " Voici les choses que Yahweh a ordonné de faire:'),
('ex',35,2,'crampon1923','Tu travailleras six jours, mais le septième sera pour vous un jour consacré; un jour de repos complet en l''honneur de Yahweh. Quiconque fera un travail ce jour-là sera puni de mort.'),
('ex',35,3,'crampon1923','Vous n''allumerez de feu dans aucune de vos demeures le jour du sabbat. "'),
('ex',35,4,'crampon1923','Moïse parla à toute l''assemblée des enfants d''Israël, en disant: " Voici ce que Yahweh a ordonné:'),
('ex',35,5,'crampon1923','Prélevez sur vos biens une offrande pour Yahweh. Tout homme au cœur bien disposé apportera en offrande à Yahweh de l''or, de l''argent et de l''airain,'),
('ex',35,6,'crampon1923','de la pourpre violette, de la pourpre écarlate, du cramoisi, du fin lin et du poil de chèvre,'),
('ex',35,7,'crampon1923','des peaux de béliers teintes en rouge et des peaux de veaux marins, et du bois d''acacia,'),
('ex',35,8,'crampon1923','de l''huile pour le chandelier, des aromates pour l''huile d''onction et pour le parfum d''encensement,'),
('ex',35,9,'crampon1923','des pierres d''onyx et d''autres pierres à enchâsser pour l''éphod et pour le pectoral.'),
('ex',35,10,'crampon1923','Que tous ceux d''entre vous qui ont de l''habileté viennent et exécutent tout ce que Yahweh a ordonné:'),
('ex',35,11,'crampon1923','la Demeure, sa tente et sa couverture, ses anneaux, ses ais, ses traverses, ses colonnes et ses socles;'),
('ex',35,12,'crampon1923','l''arche et ses barres; le propitiatoire et le voile de séparation;'),
('ex',35,13,'crampon1923','la table avec ses barres et tous ses ustensiles, et les pains de proposition;'),
('ex',35,14,'crampon1923','le chandelier avec ses ustensiles, ses lampes et l''huile pour le chandelier;'),
('ex',35,15,'crampon1923','l''autel des parfums et ses barres; l''huile d''onction et le parfum pour l''encensement: la tenture de la porte pour l''entrée de la Demeure;'),
('ex',35,16,'crampon1923','l''autel des holocaustes, sa grille d''airain, ses barres et tous ses ustensiles; la cuve avec sa base;'),
('ex',35,17,'crampon1923','les rideaux du parvis, ses colonnes, ses socles et la tenture de la porte du parvis;'),
('ex',35,18,'crampon1923','les pieux de la Demeure, les pieux du parvis avec leurs cordages;'),
('ex',35,19,'crampon1923','les vêtements de cérémonie pour le service dans le sanctuaire, les vêtements sacrés pour le grand prêtre Aaron, et les vêtements de ses fils pour les fonctions du sacerdoce. "'),
('ex',35,20,'crampon1923','Toute l''assemblée des enfants d''Israël étant sortie de devant Moïse,'),
('ex',35,21,'crampon1923','tous ceux que leur cœur y portait et tous ceux dont l''esprit était bien disposé vinrent et apportèrent une offrande à Yahweh pour la construction de la tente de réunion, pour tout son service et pour les vêtements sacrés.'),
('ex',35,22,'crampon1923','Les hommes vinrent aussi bien que les femmes; tous ceux dont le cœur était bien disposé apportèrent des boucles, des anneaux, des bagues, des bracelets, toutes sortes d''objets d''or; chacun présenta l''offrande d''or qu''il avait destinée à Yahweh.'),
('ex',35,23,'crampon1923','Tous ceux qui avaient chez eux de la pourpre violette, de la pourpre écarlate et du cramoisi, du fin lin et du poil de chèvre, des peaux de béliers teintes en rouge et des peaux de veaux marins, les apportèrent.'),
('ex',35,24,'crampon1923','Tous ceux qui avaient prélevé une offrande d''argent et d''airain, apportèrent l''offrande à Yahweh. Tous ceux qui avaient chez eux du bois d''acacia pour tous les ouvrages destinés au culte, l''apportèrent.'),
('ex',35,25,'crampon1923','Toutes les femmes qui avaient de l''habileté, filèrent de leurs mains, et elles apportèrent leur ouvrage: de la pourpre violette, de la pourpre écarlate, du cramoisi et du fin lin.'),
('ex',35,26,'crampon1923','Toutes les femmes que leur cœur y portait, et qui avaient de l''habileté, filèrent du poil de chèvre.'),
('ex',35,27,'crampon1923','Les principaux du peuple apportèrent des pierres d''onyx et d''autres pierres à enchâsser pour l''éphod et le pectoral;'),
('ex',35,28,'crampon1923','des aromates et de l''huile pour le chandelier, pour l''huile d''onction et pour le parfum odoriférant.'),
('ex',35,29,'crampon1923','Tous les enfants d''Israël, hommes et femmes, qui étaient disposés de cœur à contribuer à tout ouvrage que Yahweh avait commandé de faire par l''organe de Moïse, apportèrent à Yahweh des offrandes volontaires.'),
('ex',35,30,'crampon1923','Moïse dit aux enfants d''Israël: " Sachez que Yahweh a choisi Béseléel, fils d''Uri, fils de Hur, de la tribu de Juda.'),
('ex',35,31,'crampon1923','Il l''a rempli de l''esprit de Dieu, de sagesse, d''intelligence et de savoir pour toutes sortes d''ouvrages,'),
('ex',35,32,'crampon1923','pour faire des inventions, pour travailler l''or, l''argent et l''airain,'),
('ex',35,33,'crampon1923','pour graver les pierres à enchâsser, pour tailler le bois et exécuter toutes sortes d''ouvrages d''art.'),
('ex',35,34,'crampon1923','Il a mis aussi dans son cœur le don d''enseignement, de même qu''en Ooliab, fils d''Achisamech, de la tribu de Dan.'),
('ex',35,35,'crampon1923','Il les a remplis d''intelligence pour exécuter tous les ouvrages de sculpture et d''art, pour tisser d''un dessin varié la pourpre violette, la pourpre écarlate, le cramoisi et le fin lin, pour exécuter toute espèce de travaux et pour faire des inventions.'),
('ex',36,1,'crampon1923','Béseléel, Ooliab et tous les hommes intelligents en qui Yahweh a mis de l''intelligence et de l''habileté pour savoir faire tous les ouvrages destinés au service du sanctuaire, les exécuteront selon tout ce que Yahweh a commandé. "'),
('ex',36,2,'crampon1923','Moïse appela Béseléel, Ooliab et tous les hommes intelligents dans le cœur desquels Yahweh avait mis de l''intelligence, tous ceux que leur cœur poussait à s''appliquer à cette œuvre pour l''exécuter.'),
('ex',36,3,'crampon1923','Ils prirent de devant Moïse toute l''offrande qu''avaient apportée les enfants d''Israël pour exécuter les ouvrages destinés au service du sanctuaire; et chaque matin le peuple continuait à apporter à Moïse des offrandes volontaires.'),
('ex',36,4,'crampon1923','Alors tous les hommes habiles qui exécutaient tous les ouvrages du sanctuaire, quittant chacun l''ouvrage qu''ils faisaient,'),
('ex',36,5,'crampon1923','vinrent dire à Moïse: " Le peuple apporte beaucoup plus qu''il ne faut pour l''exécution des ouvrages que Yahweh a ordonné de faire. "'),
('ex',36,6,'crampon1923','Moïse donna un ordre et on fit cette proclamation dans le camp: " Que personne, homme ou femme, ne s''occupe plus de l''offrande pour le sanctuaire ". Et on empêcha le peuple d''en apporter davantage.'),
('ex',36,7,'crampon1923','Les objets préparés suffisaient, et au delà, pour tous les ouvrages à exécuter.'),
('ex',36,8,'crampon1923','Tous les hommes habiles parmi ceux qui travaillaient à l''œuvre firent la Demeure de dix tentures; ils les firent de lin retors, de pourpre violette, de pourpre écarlate et de cramoisi, avec des chérubins, ouvrage d''habile tisseur.'),
('ex',36,9,'crampon1923','La longueur d''une tenture était de vingt-huit coudées, et la largeur d''une tenture était de quatre coudées; la dimension était la même pour toutes les tentures.'),
('ex',36,10,'crampon1923','Cinq de ces tentures furent jointes ensemble; les cinq autres furent aussi jointes ensemble.'),
('ex',36,11,'crampon1923','On mit des lacets de pourpre violette au bord de la tenture terminant le premier assemblage; on fit de même au bord de la tenture terminant le second assemblage.'),
('ex',36,12,'crampon1923','On fit cinquante lacets à la première tenture, et on fit cinquante lacets au bord de la tenture terminant le second assemblage, et ces lacets se correspondaient les uns aux autres.'),
('ex',36,13,'crampon1923','On fit cinquante agrafes d''or, avec lesquelles on joignit les tentures l''une à l''autre, en sorte que la Demeure forma un seul tout.'),
('ex',36,14,'crampon1923','On fit des tentures de poil de chèvre pour former une tente sur la Demeure; on fit onze de ces tentures.'),
('ex',36,15,'crampon1923','La longueur d''une tenture était de trente coudées, et la largeur d''une tenture de quatre coudées; La dimension était la même pour les onze tentures.'),
('ex',36,16,'crampon1923','On joignit à part cinq de ces tentures et les six autres à part.'),
('ex',36,17,'crampon1923','On mit cinquante lacets au bord de la tenture terminant un assemblage, et on mit cinquante lacets au bord de la tenture du second assemblage.'),
('ex',36,18,'crampon1923','On fit cinquante agrafes d''airain pour assembler la tente, afin qu''elle format un seul tout.'),
('ex',36,19,'crampon1923','On fit pour la tente une couverture en peaux de béliers teintes en rouge, et une couverture en peaux de veaux marins, par dessus.'),
('ex',36,20,'crampon1923','On fit aussi les planches pour la Demeure, des planches de bois d''acacia, posées debout.'),
('ex',36,21,'crampon1923','La longueur d''une planche était de dix coudées, et la largeur d''une planche était d''une coudée et demie.'),
('ex',36,22,'crampon1923','Il y avait à chaque planche deux tenons, joints l''un à l''autre: on fit de même pour toutes les planches de la Demeure.'),
('ex',36,23,'crampon1923','On fit les planches pour la Demeure: vingt planches pour la face du midi, à droite.'),
('ex',36,24,'crampon1923','On mit sous les vingt planches quarante socles d''argent, deux socles sous chaque planche pour ses deux tenons.'),
('ex',36,25,'crampon1923','Pour le second côté de la Demeure, le côté du nord, on fit vingt planches,'),
('ex',36,26,'crampon1923','ainsi que leurs quarante socles d''argent, deux socles sous chaque planche.'),
('ex',36,27,'crampon1923','On fit six planches pour le fond de la Demeure, du côté de l''occident.'),
('ex',36,28,'crampon1923','On fit deux planches pour les angles de la Demeure, dans le fond;'),
('ex',36,29,'crampon1923','elles étaient doubles depuis le bas, formant ensemble un seul tout jusqu''à leur sommet, jusqu''au premier anneau: ainsi fit-on pour toutes les deux, aux deux angles.'),
('ex',36,30,'crampon1923','Il y avait ainsi huit planches, avec leurs socles d''argent, seize socles, deux socles sous chaque planche.'),
('ex',36,31,'crampon1923','On fit des traverses de bois d''acacia, cinq pour les planches de l''un des côtés de la Demeure,'),
('ex',36,32,'crampon1923','cinq traverses pour les planches du second côté de la Demeure, et cinq traverses pour les planches du côté de la Demeure qui en forme le fond, vers l''occident.'),
('ex',36,33,'crampon1923','La traverse du milieu s''étendait, le long des planches, d''une extrémité à l''autre.'),
('ex',36,34,'crampon1923','On revêtit d''or les planches, et l''on fit d''or leurs anneaux qui recevaient les traverses, et l''on revêtit d''or les traverses.'),
('ex',36,35,'crampon1923','On fit le voile de pourpre violette, de pourpre écarlate, de cramoisi, et de lin retors; on y représenta des chérubins figurés: ouvrage d''un habile tisseur.'),
('ex',36,36,'crampon1923','On fit pour lui quatre colonnes d''acacia, revêtues d''or, avec des crochets d''or; et l''on fondit pour elles quatre socles d''argent.'),
('ex',36,37,'crampon1923','On fit pour l''entrée de la tente un rideau en pourpre violette, pourpre écarlate, cramoisi et lin retors, ouvrage d''un dessin varié.'),
('ex',36,38,'crampon1923','On fit pour ce rideau cinq colonnes et leurs crochets et l''on revêtit d''or leurs chapiteaux et leurs tringles; leurs cinq socles étaient d''airain.'),
('ex',37,1,'crampon1923','Béseléel fit l''arche de bois d''acacia; sa longueur était de deux coudées et demie, sa largeur d''une coudée et demie, et sa hauteur d''une coudée et demie.'),
('ex',37,2,'crampon1923','Il la revêtit d''or pur, en dedans et en dehors, et il y fit une guirlande d''or tout autour.'),
('ex',37,3,'crampon1923','Il fondit pour elle quatre anneaux d''or, qu''il mit à ses quatre pieds, deux anneaux d''un côté et deux anneaux de l''autre.'),
('ex',37,4,'crampon1923','Il fit des barres de bois d''acacia et les revêtit d''or.'),
('ex',37,5,'crampon1923','Il passa les barres dans les anneaux sur les côtés de l''arche, pour la porter.'),
('ex',37,6,'crampon1923','Il fit un propitiatoire d''or pur; sa longueur était de deux coudées et demie, sa largeur d''une coudée et demie.'),
('ex',37,7,'crampon1923','Il fit deux chérubins d''or; il les fit d''or battu, aux deux extrémités du propitiatoire,'),
('ex',37,8,'crampon1923','un chérubin à l''une des extrémités et un chérubin à l''autre extrémité; il fit les chérubins sortant du propitiatoire à ses deux extrémités.'),
('ex',37,9,'crampon1923','Les chérubins avaient leurs ailes déployées vers le haut, couvrant de leurs ailes le propitiatoire, et se faisant face l''un à l''autre; les faces des chérubins étaient tournées vers le propitiatoire.'),
('ex',37,10,'crampon1923','Il fit la table de bois d''acacia; sa longueur était de deux coudées, sa largeur d''une coudée, et sa hauteur d''une coudée et demie.'),
('ex',37,11,'crampon1923','Il la revêtit d''or pur, et y mit une guirlande d''or tout autour.'),
('ex',37,12,'crampon1923','Il lui fit à l''entour un châssis d''une palme, et il fit une guirlande d''or au châssis tout autour.'),
('ex',37,13,'crampon1923','Il fondit pour la table quatre anneaux d''or, et il mit les anneaux aux quatre coins, qui sont à ses quatre pieds.'),
('ex',37,14,'crampon1923','Les anneaux étaient près du châssis pour recevoir les barres qui doivent porter la table.'),
('ex',37,15,'crampon1923','Il fit les barres de bois d''acacia et les revêtit d''or; elles servaient à porter la table.'),
('ex',37,16,'crampon1923','Il fit les ustensiles qu''on devait mettre sur la table, ses plats, ses cassolettes, ses coupes et ses tasses pour servir aux libations; il les fit d''or pur.'),
('ex',37,17,'crampon1923','Il fit le chandelier d''or pur; il fit d''or battu le chandelier, avec son pied et sa tige; ses calices, ses boutons et ses fleurs étaient d''une même pièce.'),
('ex',37,18,'crampon1923','Six branches sortaient de ses côtés; trois branches du chandelier de l''un de ses côtés, et trois branches du chandelier du second de ses côtés.'),
('ex',37,19,'crampon1923','Il y avait sur la première branche trois calices en fleurs d''amandier, bouton et fleur, et sur la seconde branche trois calices en fleurs d''amandiers, bouton et fleur; il en était de même pour les six branches partant du chandelier.'),
('ex',37,20,'crampon1923','A la tige du chandelier, il y avait quatre calices, en fleurs d''amandier, avec leurs boutons et leurs fleurs.'),
('ex',37,21,'crampon1923','Il y avait un bouton sous les deux premières branches partant de la tige du chandelier, un bouton sous les deux branches suivantes partant de la tige du chandelier, et un bouton sous les deux dernières branches partant de la tige du chandelier, selon les six branches sortant du chandelier.'),
('ex',37,22,'crampon1923','Ces boutons et ces branches étaient d''une même pièce avec le chandelier; le tout était une masse d''or battu, d''or pur.'),
('ex',37,23,'crampon1923','Il fit ses lampes au nombre de sept, ses mouchettes et ses vases à cendre, en or pur.'),
('ex',37,24,'crampon1923','On employa un talent d''or pur pour faire le chandelier avec tous ses ustensiles.'),
('ex',37,25,'crampon1923','Il fit l''autel des parfums de bois d''acacia; sa longueur était d''une coudée, et sa largeur d''une coudée; il était carré, et sa hauteur était de deux coudées; ses cornes faisaient corps avec lui.'),
('ex',37,26,'crampon1923','Il le revêtit d''or pur, le dessus, les côtés tout autour et les cornes, et il y fit une guirlande d''or tout autour.'),
('ex',37,27,'crampon1923','Il fit pour lui deux anneaux d''or, au-dessous de sa guirlande, sur ses deux arêtes; il les fit aux deux côtés, pour recevoir les barres qui servaient à le porter.'),
('ex',37,28,'crampon1923','Il fit les barres de bois d''acacia et les revêtit d''or.'),
('ex',37,29,'crampon1923','Il fit l''huile pour l''onction sainte, et le parfum pour l''encensement, composé selon l''art du parfumeur.'),
('ex',38,1,'crampon1923','Il fit l''autel des holocaustes en bois d''acacia; sa longueur était de cinq coudées, et sa largeur de cinq coudées; il était carré, et sa hauteur était de trois coudées.'),
('ex',38,2,'crampon1923','A ses quatre coins, il fit des cornes qui sortaient de l''autel, et il le revêtit d''airain.'),
('ex',38,3,'crampon1923','Il fit tous les ustensiles de l''autel, les vases à cendre, les pelles, les bassins, les fourchettes et les brasiers; il fit d''airain tous ces ustensiles.'),
('ex',38,4,'crampon1923','Il fit à l''autel une grille d''airain en forme de treillis; il la plaça sous la corniche de l''autel, par en bas, jusqu''à moitié de la hauteur.'),
('ex',38,5,'crampon1923','Il fondit quatre anneaux, qu''il mit aux quatre coins de la grille d''airain, pour recevoir les barres.'),
('ex',38,6,'crampon1923','Il fit les barres de bois d''acacia et les revêtit d''airain.'),
('ex',38,7,'crampon1923','Il passa les barres dans les anneaux, aux côtés de l''autel, pour qu''elles servent à le transporter. Il le fit creux, en planches.'),
('ex',38,8,'crampon1923','Il fit la cuve d''airain et sa base d''airain, avec les miroirs des femmes qui s''assemblaient à l''entrée de la tente de réunion.'),
('ex',38,9,'crampon1923','Il fit le parvis. Du côté du midi, à droite, les rideaux du parvis, en lin retors, avaient une longueur de cent coudées,'),
('ex',38,10,'crampon1923','avec vingt colonnes et leurs vingt socles d''airain; les crochets des colonnes et leurs tringles étaient d''argent.'),
('ex',38,11,'crampon1923','Du côté du nord, les rideaux avaient cent coudées avec vingt colonnes et leurs vingt socles d''airain; les crochets des colonnes et leurs tringles étaient d''argent.'),
('ex',38,12,'crampon1923','Du côté de l''occident, les rideaux avaient cinquante coudées, avec dix colonnes et leurs dix socles.'),
('ex',38,13,'crampon1923','Du côté de l''orient, sur le devant, il y avait cinquante coudées:'),
('ex',38,14,'crampon1923','et il y avait quinze coudées de rideaux pour un côté de la porte, avec trois colonnes et leurs trois socles,'),
('ex',38,15,'crampon1923','et pour le deuxième côté — d''un côté de la porte du parvis comme de l''autre, — quinze coudées de rideaux avec trois colonnes et leurs trois socles.'),
('ex',38,16,'crampon1923','Tous les rideaux formant l''enceinte du parvis étaient de lin retors.'),
('ex',38,17,'crampon1923','Les socles pour les colonnes étaient d''airain, les crochets des colonnes et leurs tringles étaient d''argent, et leurs chapiteaux étaient revêtus d''argent. Toutes les colonnes du parvis étaient reliées par des tringles d''argent.'),
('ex',38,18,'crampon1923','Le rideau de la porte du parvis était un ouvrage de dessin varié, en pourpre violette, pourpre écarlate, cramoisi, et lin retors; sa longueur était de vingt coudées, et sa hauteur de cinq coudées, comme la largeur des rideaux du parvis;'),
('ex',38,19,'crampon1923','ses quatre colonnes et leurs quatre socles étaient d''airain, les crochets et leurs tringles d''argent, et leurs chapiteaux revêtus d''argent.'),
('ex',38,20,'crampon1923','Tous les pieux pour la Demeure et pour l''enceinte du parvis étaient d''airain.'),
('ex',38,21,'crampon1923','Voici le compte des choses qui ont été employées pour la Demeure, la Demeure du témoignage, compte dressé par le soin des Lévites sur l''ordre de Moïse et sous la direction d''Ithamar, fils du grand prêtre Aaron.'),
('ex',38,22,'crampon1923','Béseléel, fils d''Uri, fils de Hur, de la tribu de Juda, fit tout ce que Yahweh avait ordonné à Moïse;'),
('ex',38,23,'crampon1923','il eut pour aide Ooliab, fils Achisamech, de la tribu de Dan, habile à sculpter, à inventer, à tisser en dessin varié la pourpre violette, la pourpre écarlate, le cramoisi, et le fin lin.'),
('ex',38,24,'crampon1923','Total de l''or employé à l''ouvrage, pour tout l''ouvrage du sanctuaire, or qui était le produit des offrandes: vingt-neuf talents et sept cent trente sicles, selon le sicle du sanctuaire.'),
('ex',38,25,'crampon1923','L''argent de ceux de l''assemblée qui furent recensés s''élevait à cent talents et mille sept cent soixante-quinze sicles, selon le sicle du sanctuaire.'),
('ex',38,26,'crampon1923','C''était un béka par tête, la moitié d''un sicle, selon le sicle du sanctuaire, pour chaque homme compris dans le recensement, depuis l''âge de vingt ans et au-dessus, soit pour six cent trois mille cinq cent cinquante hommes.'),
('ex',38,27,'crampon1923','Les cent talents d''argent servirent à fondre les socles du sanctuaire et les socles du voile, cent socles pour les cent talents, un talent par socle.'),
('ex',38,28,'crampon1923','Et avec les mille sept cent soixante-quinze sicles, on fit les crochets pour les colonnes, on revêtit les chapiteaux et on les joignit par des tringles.'),
('ex',38,29,'crampon1923','L''airain des offrandes montait à soixante-dix talents et deux mille quatre cent sicles.'),
('ex',38,30,'crampon1923','On en fit les socles de l''entrée de la tente de réunion, l''autel d''airain avec sa grille d''airain et tous les ustensiles de l''autel,'),
('ex',38,31,'crampon1923','les socles de l''enceinte du parvis et les socles de la porte du parvis, et tous les pieux de la Demeure et tous les pieux de l''enceinte du parvis.'),
('ex',39,1,'crampon1923','Avec la pourpre violette, la pourpre écarlate et le cramoisi, on fit les vêtements de cérémonie peur le service dans le sanctuaire, et on fit les vêtements sacrés pour Aaron, comme Yahweh l''avait ordonné à Moïse.'),
('ex',39,2,'crampon1923','On fit l''éphod d''or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors.'),
('ex',39,3,'crampon1923','On étendit l''or en lames et on les coupa en fils, que l''on entrelaça dans la pourpre violette, la pourpre écarlate, le cramoisi et le fin lin; ouvrage de dessin varié.'),
('ex',39,4,'crampon1923','On fit des épaulettes pour le joindre, et ainsi il était joint à ses deux extrémités.'),
('ex',39,5,'crampon1923','La ceinture pour attacher l''éphod en passant dessus faisait corps avec lui et était du même travail; elle était d''or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors, comme Yahweh l''avait ordonné à Moïse.'),
('ex',39,6,'crampon1923','On fit les pierres d''onyx enchâssées dans des chatons d''or, sur lesquelles on grava les noms des fils d''Israël, comme on grave les cachets.'),
('ex',39,7,'crampon1923','On les plaça sur les épaulettes de l''éphod comme pierres de souvenir pour les enfants d''Israël, comme Yahweh l''avait ordonné à Moïse.'),
('ex',39,8,'crampon1923','On fit le pectoral, artistement travaillé, du même travail que l''éphod, d''or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors.'),
('ex',39,9,'crampon1923','Il était carré; on fit le pectoral double; sa longueur était d''un empan et sa largeur d''un empan; il était double.'),
('ex',39,10,'crampon1923','On le garnit de quatre rangées de pierres: une rangée de sardoine, de topaze, d''émeraude: première rangée;'),
('ex',39,11,'crampon1923','deuxième rangée: une escarboucle, un saphir, un diamant;'),
('ex',39,12,'crampon1923','troisième rangée: une opale, une agate, une améthyste;'),
('ex',39,13,'crampon1923','quatrième rangée: une chrysolithe, un onyx, un jaspe. Ces pierres étaient entourées de rosettes d''or dans leurs garnitures.'),
('ex',39,14,'crampon1923','Les pierres étaient selon les noms des fils d''Israël, douze selon leurs noms; elles étaient gravées comme des cachets, chacune avec son nom, pour les douze tribus. —'),
('ex',39,15,'crampon1923','On fit pour le pectoral des chaînettes d''or pur, tressées en forme de cordons.'),
('ex',39,16,'crampon1923','On fit deux chatons d''or et deux anneaux d''or, et on mit les deux anneaux aux deux extrémités du pectoral.'),
('ex',39,17,'crampon1923','On passa les deux cordons d''or dans les deux anneaux, aux extrémités du pectoral,'),
('ex',39,18,'crampon1923','et l''on attacha les deux bouts des deux cordons aux deux chatons, et on les plaça sur les épaulettes de l''éphod, par devant.'),
('ex',39,19,'crampon1923','On fit encore deux anneaux d''or, que l''on mit aux deux extrémités inférieures du pectoral, sur le bord intérieur appliqué contre l''éphod.'),
('ex',39,20,'crampon1923','On fit deux autres anneaux d''or, que l''un mit au bas des deux épaulettes de l''éphod sur le devant, près de l''attache, au-dessus de la ceinture de l''éphod.'),
('ex',39,21,'crampon1923','On attacha le pectoral par ses anneaux aux anneaux de l''éphod avec un ruban de pourpre violette, afin que le pectoral fût au-dessus de la ceinture de l''éphod; et le pectoral ne pouvait se séparer de l''éphod, comme Yahweh l''a ordonné à Moïse.'),
('ex',39,22,'crampon1923','On fit la robe de l''éphod, œuvre du tisseur, tout entière en pourpre violette.'),
('ex',39,23,'crampon1923','Il y avait, au milieu de la robe de l''éphod, une ouverture semblable à celle d''une cotte d''arme, et cette ouverture avait un rebord tissé tout autour, afin que la robe ne se déchirât pas.'),
('ex',39,24,'crampon1923','On mit au bord inférieur de la robe des grenades de pourpre violette, de pourpre écarlate, de cramoisi, de lin retors;'),
('ex',39,25,'crampon1923','on fit des clochettes d''or pur, et l''on mit ces clochettes au milieu des grenades, sur le bord inférieur de la robe tout autour, au milieu des grenades:'),
('ex',39,26,'crampon1923','une clochette et une grenade, une clochette et une grenade, sur le bord de la robe tout autour, pour le service, comme Yahweh l''avait ordonné à Moïse.'),
('ex',39,27,'crampon1923','On fit les tuniques de lin, œuvre du tisseur, pour Aaron et pour ses fils;'),
('ex',39,28,'crampon1923','la tiare de lin, et les mitres de lin servant de parure; les caleçons blancs de lin retors;'),
('ex',39,29,'crampon1923','la ceinture de lin retors, en pourpre violette, en pourpre écarlate et en cramoisi, damassée, comme Yahweh l''avait ordonné à Moïse.'),
('ex',39,30,'crampon1923','On fit d''or pur la lame, diadème sacré, et l''on y grava, comme on grave sur un cachet: Sainteté à Yahweh.'),
('ex',39,31,'crampon1923','On l''attacha avec un ruban de pourpre violette pour la placer sur la tiare, en haut, comme Yahweh l''avait ordonné à Moïse.'),
('ex',39,32,'crampon1923','Ainsi fut achevé tout l''ouvrage de la Demeure, de la tente de réunion; et les enfants d''Israël exécutèrent tout selon ce que Yahweh avait ordonné à Moïse; ils firent ainsi.'),
('ex',39,33,'crampon1923','On présenta la Demeure à Moïse, la tente et tous ses ustensiles, ses agrafes, ses planches, ses traverses, ses colonnes et ses socles;'),
('ex',39,34,'crampon1923','la couverture de peaux de béliers teintes en rouge, la couverture de peaux de veaux marins et le voile de séparation;'),
('ex',39,35,'crampon1923','l''arche du témoignage avec ses barres et le propitiatoire;'),
('ex',39,36,'crampon1923','la table avec tous ses ustensiles et les pains de proposition;'),
('ex',39,37,'crampon1923','le chandelier d''or pur, ses lampes, les lampes à y ranger, tous ses ustensiles et l''huile pour le luminaire;'),
('ex',39,38,'crampon1923','l''autel d''or, l''huile d''onction et le parfum pour l''encens, ainsi que le rideau pour l''entrée de la tente;'),
('ex',39,39,'crampon1923','l''autel d''airain, sa grille d''airain, ses barres et tous ses ustensiles; la cuve avec sa base; les rideaux du parvis, ses colonnes, ses socles,'),
('ex',39,40,'crampon1923','la tenture de la porte du parvis, ses cordages et ses pieux, et tous les ustensiles pour le service de la Demeure, pour la tente de réunion;'),
('ex',39,41,'crampon1923','les vêtements de cérémonie pour le service du sanctuaire, les vêtements sacrés pour le grand prêtre Aaron, et les vêtements de ses fils pour les fonctions du sacerdoce.'),
('ex',39,42,'crampon1923','Les enfants d''Israël avaient fait tout cet ouvrage conformément à tout ce que Yahweh avait ordonné à Moïse.'),
('ex',39,43,'crampon1923','Moïse examina tout l''ouvrage, et voici, ils l''avaient exécuté; ils l''avaient fait comme Yahweh l''avait ordonné. Et Moïse les bénit.'),
('ex',40,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('ex',40,2,'crampon1923','" Le premier jour du premier mois, tu dresseras la Demeure, la tente de réunion.'),
('ex',40,3,'crampon1923','Tu y placeras l''arche du témoignage, et tu couvriras l''arche avec le voile.'),
('ex',40,4,'crampon1923','Tu apporteras la table et tu y disposeras ce qui doit la garnir. Tu apporteras le chandelier et tu poseras dessus ses lampes.'),
('ex',40,5,'crampon1923','Tu placeras l''autel d''or pour le parfum devant l''arche du témoignage, et tu mettras le voile à l''entrée de la Demeure.'),
('ex',40,6,'crampon1923','Tu placeras l''autel des holocaustes devant l''entrée de la Demeure, de la tente de réunion.'),
('ex',40,7,'crampon1923','Tu placeras la cuve entre la tente de réunion et l''autel, et tu y mettras de l''eau.'),
('ex',40,8,'crampon1923','Tu dresseras le parvis à l''entour, et tu mettras la tenture à la porte du parvis.'),
('ex',40,9,'crampon1923','" Tu prendras l''huile d''onction, tu en oindras la Demeure et tout ce qu''elle renferme; tu la consacreras avec tous ses ustensiles, et elle sera sainte.'),
('ex',40,10,'crampon1923','Tu oindras l''autel des holocaustes et tous ses ustensiles; tu consacreras l''autel, et l''autel sera très saint.'),
('ex',40,11,'crampon1923','Tu oindras la cuve avec sa base, et tu la consacreras.'),
('ex',40,12,'crampon1923','" Tu feras avancer Aaron et ses fils près de l''entrée de la tente de réunion, et tu les laveras avec de l''eau.'),
('ex',40,13,'crampon1923','Puis tu revêtiras Aaron des vêtements sacrés, tu l''oindras et tu le consacreras, et il sera prêtre à mon service.'),
('ex',40,14,'crampon1923','Tu feras approcher ses fils et, les ayant revêtus des tuniques,'),
('ex',40,15,'crampon1923','tu les oindras comme tu auras oint leur père, et ils seront prêtres à mon service. Cette onction leur conférera le sacerdoce à perpétuité parmi leurs descendants. "'),
('ex',40,16,'crampon1923','Moïse fit tout ce que Yahweh lui avait ordonné; il fit ainsi.'),
('ex',40,17,'crampon1923','Le premier jour du premier mois de la seconde année, la Demeure fut dressée.'),
('ex',40,18,'crampon1923','Moïse dressa la Demeure; il en posa les socles, il en plaça les planches et les traverses, en dressa les colonnes.'),
('ex',40,19,'crampon1923','Il étendit la tente sur la Demeure, et mit par-dessus la couverture de la tente, comme Yahweh l''avait ordonné à Moïse.'),
('ex',40,20,'crampon1923','Il prit le témoignage et le plaça dans l''arche; il mit les barres à l''arche et posa le propitiatoire au-dessus de l''arche.'),
('ex',40,21,'crampon1923','Il porta l''arche dans la Demeure; et, ayant mis le voile de séparation, il en couvrit l''arche du témoignage, comme Yahweh l''avait ordonné à Moïse.'),
('ex',40,22,'crampon1923','Il plaça la table dans la tente de réunion, au côté septentrional de la Demeure, en dehors du voile,'),
('ex',40,23,'crampon1923','et il y disposa les pains devant Yahweh, comme Yahweh l''avait ordonné à Moïse.'),
('ex',40,24,'crampon1923','Il plaça le chandelier dans la tente de réunion, vis-à-vis de la table, au côté méridional de la Demeure,'),
('ex',40,25,'crampon1923','et il y posa les lampes devant Yahweh, comme Yahweh l''avait ordonné à Moïse.'),
('ex',40,26,'crampon1923','Il plaça l''autel d''or dans la tente de réunion, devant le voile,'),
('ex',40,27,'crampon1923','et il y fit brûler l''encens, comme Yahweh l''avait ordonné à Moïse.'),
('ex',40,28,'crampon1923','Il plaça le rideau à l''entrée de la Demeure.'),
('ex',40,29,'crampon1923','Il plaça l''autel des holocaustes à l''entrée de la Demeure, de la tente de réunion, et il y offrit l''holocauste et l''oblation, comme Yahweh l''avait ordonné à Moïse.'),
('ex',40,30,'crampon1923','Il plaça la cuve entre la tente de réunion et l''autel, et il y mit de l''eau pour les ablutions;'),
('ex',40,31,'crampon1923','Moïse, Aaron et ses fils s''y lavèrent les mains et les pieds.'),
('ex',40,32,'crampon1923','Lorsqu''ils entraient dans la tente de réunion et qu''ils s''approchaient de l''autel, ils se lavaient, comme Yahweh l''avait ordonné à Moïse.'),
('ex',40,33,'crampon1923','Il dressa le parvis autour de la Demeure et de l''autel, et il mit la tenture à la porte du parvis. Ce fut ainsi que Moïse acheva cette œuvre.'),
('ex',40,34,'crampon1923','Alors la nuée couvrit la tente de réunion, et la gloire de Yahweh remplit la Demeure.'),
('ex',40,35,'crampon1923','Et Moïse ne pouvait plus entrer dans la tente de réunion, parce que la nuée restait dessus, et que la gloire de Yahweh remplissait la Demeure.'),
('ex',40,36,'crampon1923','Tant que durèrent leurs marches, les enfants d''Israël partaient lorsque la nuée s''élevait de dessus la Demeure;'),
('ex',40,37,'crampon1923','et si la nuée ne s''élevait pas, ils ne partaient pas, jusqu''au jour où elle s''élevait.'),
('ex',40,38,'crampon1923','Car la nuée de Yahweh reposait pendant le jour sur la Demeure, et, pendant la nuit, il y avait du feu dans la nuée, aux yeux de toute la maison d''Israël, tant que durèrent leurs marches.'),
('lv',1,1,'crampon1923','YAHWEH appela Moïse, et lui parla de la tente de réunion, en disant:'),
('lv',1,2,'crampon1923','" Parle aux enfants d''Israël et dis-leur: Lorsque quelqu''un d''entre vous fera à Yahweh une offrande, ce sera du bétail que vous offrirez, du gros ou du menu bétail.'),
('lv',1,3,'crampon1923','Si son offrande est un holocauste de gros bétail, il offrira un mâle sans défaut; il l''offrira à l''entrée de la tente de réunion, pour être agréé devant Yahweh.'),
('lv',1,4,'crampon1923','Il posera sa main sur la tête de l''holocauste, et il sera accepté en sa faveur pour faire expiation pour lui.'),
('lv',1,5,'crampon1923','Il égorgera le jeune taureau devant Yahweh, et les prêtres, fils d''Aaron, offriront le sang et le répandront tout autour sur l''autel qui est à l''entrée de la tente de réunion.'),
('lv',1,6,'crampon1923','On dépouillera l''holocauste et on le découpera en ses morceaux.'),
('lv',1,7,'crampon1923','Les fils du prêtre Aaron mettront du feu sur l''autel et disposeront du bois sur le feu;'),
('lv',1,8,'crampon1923','puis les prêtres, fils d''Aaron, arrangeront les morceaux, avec la tête et la fressure, sur le bois placé sur le feu de l''autel.'),
('lv',1,9,'crampon1923','On lavera avec de l''eau les entrailles et les jambes, et le prêtre fera fumer le tout sur l''autel. C''est un holocauste, un sacrifice par le feu, d''une agréable odeur à Yahweh.'),
('lv',1,10,'crampon1923','Si son offrande est de menu bétail, un holocauste d''agneaux ou de chèvres, il offrira un mâle sans défaut.'),
('lv',1,11,'crampon1923','Il l''égorgera au côté septentrional de l''autel, devant Yahweh; et les prêtres, fils d''Aaron, en répandront le sang tout autour sur l''autel.'),
('lv',1,12,'crampon1923','On le découpera en ses morceaux, avec sa tête et sa fressure; puis le prêtre les arrangera sur le bois placé sur le feu de l''autel.'),
('lv',1,13,'crampon1923','Il lavera dans l''eau les entrailles et les jambes, et le prêtre offrira le tout et le fera fumer sur l''autel. C''est un holocauste, un sacrifice par le feu, d''une agréable odeur à Yahweh.'),
('lv',1,14,'crampon1923','Si son offrande à Yahweh est un holocauste d''oiseaux, il offrira des tourterelles ou de jeunes pigeons.'),
('lv',1,15,'crampon1923','Le prêtre apportera l''oiseau à l''autel; il lui brisera la tête avec l''ongle et la fera fumer sur l''autel, et son sang sera exprimé contre la paroi de l''autel.'),
('lv',1,16,'crampon1923','Il ôtera le jabot avec ses impuretés et le jettera près de l''autel, vers l''Orient, au lieu où l''on met les cendres.'),
('lv',1,17,'crampon1923','Puis il fendra l''oiseau aux ailes, sans les séparer, et le prêtre le fera fumer sur l''autel, sur le bois placé sur le feu. C''est un holocauste, un sacrifice par le feu, d''une agréable odeur à Yahweh.'),
('lv',2,1,'crampon1923','Lorsque quelqu''un présentera comme offrande à Yahweh une oblation, son offrande sera de fleur de farine; il versera de l''huile dessus et y ajoutera de l''encens.'),
('lv',2,2,'crampon1923','Il l''apportera aux prêtres, fils d''Aaron; et le prêtre prendra une poignée de la fleur de farine arrosée d''huile, avec tout l''encens, et il fera fumer cela sur l''autel en souvenir. C''est un sacrifice fait par le feu, d''une agréable odeur à Yahweh.'),
('lv',2,3,'crampon1923','Ce qui restera de l''oblation sera pour Aaron et ses fils; c''est une chose très sainte entre les sacrifices faits par le feu à Yahweh.'),
('lv',2,4,'crampon1923','Quand tu offriras une oblation de ce qui est cuit au four, ce sera des gâteaux de fleur de farine, sans levain, pétris à l''huile, et des galettes sans levain arrosées d''huile.'),
('lv',2,5,'crampon1923','Si tu offres en oblation un gâteau cuit à la poêle, il sera de fleur de farine pétrie à l''huile, sans levain.'),
('lv',2,6,'crampon1923','Tu le rompras en morceaux et tu verseras de l''huile dessus: c''est une oblation.'),
('lv',2,7,'crampon1923','Si tu offres en oblation un gâteau cuit dans la casserole, il sera fait de fleur de farine avec de l''huile.'),
('lv',2,8,'crampon1923','Tu apporteras à Yahweh l''oblation ainsi préparée, et elle sera présentée au prêtre, qui l''apportera à l''autel.'),
('lv',2,9,'crampon1923','Le prêtre en prélèvera ce qui doit être offert en souvenir, et le fera fumer sur l''autel: c''est un sacrifice fait par le feu, d''une agréable odeur à Yahweh.'),
('lv',2,10,'crampon1923','Ce qui restera de l''oblation sera pour Aaron et pour ses fils; c''est une chose très sainte entre les sacrifices faits par le feu à Yahweh.'),
('lv',2,11,'crampon1923','Toute oblation que vous présenterez à Yahweh doit être préparée sans levain, car vous ne ferez fumer rien qui contienne du levain ou du miel en sacrifice fait par le feu à Yahweh.'),
('lv',2,12,'crampon1923','Vous pourrez les présenter à Yahweh en offrandes de prémices; mais il n''en sera pas placé sur l''autel comme offrandes d''agréable odeur.'),
('lv',2,13,'crampon1923','Tout ce que tu présenteras en oblation sera salé; tu ne laisseras point le sel de l''alliance de ton Dieu manquer à ton oblation; sur toutes tes offrandes tu offriras du sel.'),
('lv',2,14,'crampon1923','Si tu fais à Yahweh une oblation de prémices, tu présenteras des épis rôtis au feu, du grain nouveau broyé, comme oblation de tes prémices.'),
('lv',2,15,'crampon1923','Tu verseras de l''huile dessus, et tu y ajouteras de l''encens; c''est une oblation.'),
('lv',2,16,'crampon1923','Le prêtre fera fumer en souvenir une partie du grain broyé et de l''huile, avec tout l''encens. C''est un sacrifice fait par le feu à Yahweh.'),
('lv',3,1,'crampon1923','Lorsqu''un homme offrira un sacrifice pacifique, s''il offre du gros bétail, mâle ou femelle, il l''offrira sans défaut devant Yahweh.'),
('lv',3,2,'crampon1923','Il posera sa main sur la tête de la victime et il l''égorgera à l''entrée de la tente de réunion, et les prêtres, fils d''Aaron, répandront le sang sur les parois de l''autel tout autour.'),
('lv',3,3,'crampon1923','De ce sacrifice pacifique, il offrira en sacrifice par le feu à Yahweh: la graisse qui enveloppe les entrailles et toute la graisse qui est attachée aux entrailles;'),
('lv',3,4,'crampon1923','les deux rognons avec la graisse qui les recouvre et qui tient à la région lombaire; la taie du foie qu''il détachera près des rognons.'),
('lv',3,5,'crampon1923','Les fils d''Aaron feront fumer cela sur l''autel, par-dessus l''holocauste placé sur le bois qui est sur le feu. C''est un sacrifice fait par le feu, d''une agréable odeur à Yahweh.'),
('lv',3,6,'crampon1923','S''il offre du menu bétail, mâle ou femelle, en sacrifice pacifique à Yahweh, il l''offrira sans défaut.'),
('lv',3,7,'crampon1923','S''il offre en sacrifice un agneau, il le présentera devant Yahweh.'),
('lv',3,8,'crampon1923','Il posera sa main sur la tête de la victime et il l''égorgera devant la tente de réunion, et les fils d''Aaron en répandront le sang sur les parois de l''autel tout autour.'),
('lv',3,9,'crampon1923','De ce sacrifice pacifique, il offrira en sacrifice par le feu à Yahweh: sa graisse, la queue entière, coupée près de l''échine; la graisse qui enveloppe les entrailles et toute la graisse qui est attachée aux entrailles;'),
('lv',3,10,'crampon1923','les deux rognons, avec la graisse qui les recouvre et qui tient à la région lombaire; la taie du foie qu''il détachera près des rognons.'),
('lv',3,11,'crampon1923','Le prêtre fera fumer cela sur l''autel: c''est l''aliment d''un sacrifice fait par le feu à Yahweh.'),
('lv',3,12,'crampon1923','Si son offrande est une chèvre, il la présentera devant Yahweh.'),
('lv',3,13,'crampon1923','Il posera sa main sur la tête de la victime, et il l''égorgera devant la tente de réunion, et les fils d''Aaron en répandront le sang sur les parois de l''autel tout autour.'),
('lv',3,14,'crampon1923','De la victime, il offrira en sacrifice par le feu à Yahweh: la graisse qui enveloppe les entrailles et toute la graisse qui est attachée aux entrailles;'),
('lv',3,15,'crampon1923','les deux rognons, avec la graisse qui les recouvre et qui tient à la région lombaire; la taie du foie qu''il détachera près des rognons.'),
('lv',3,16,'crampon1923','Le prêtre fera fumer cela sur l''autel: c''est l''aliment d''un sacrifice fait par le feu d''une agréable odeur. Toute graisse appartient à Yahweh.'),
('lv',3,17,'crampon1923','C''est ici une loi perpétuelle pour vos descendants, en quelque lieu que vous habitiez: vous ne mangerez ni graisse, ni sang. "'),
('lv',4,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',4,2,'crampon1923','" Parle aux enfants d''Israël et dis-leur: Lorsqu''un homme aura péché par erreur contre l''un des commandements de Yahweh relatifs aux choses qui ne doivent point se faire, et qu''il aura fait l''une de ces choses;'),
('lv',4,3,'crampon1923','Si c''est le prêtre ayant reçu l''onction qui a péché, rendant par là le peuple coupable, il offrira à Yahweh pour le péché qu''il a commis un jeune taureau sans défaut, en sacrifice d''expiation.'),
('lv',4,4,'crampon1923','Il amènera le taureau à l''entrée de la tente de réunion, devant Yahweh, et il posera sa main sur la tête du taureau, et il l''égorgera devant Yahweh.'),
('lv',4,5,'crampon1923','Le prêtre ayant reçu l''onction prendra du sang du taureau et l''apportera dans la tente de réunion;'),
('lv',4,6,'crampon1923','il trempera son doigt dans le sang, il en fera sept fois l''aspersion devant Yahweh, en face du voile du sanctuaire.'),
('lv',4,7,'crampon1923','Le prêtre mettra du sang sur les cornes de l''autel des parfums odoriférants, qui est devant Yahweh dans la tente de réunion, et il répandra tout le reste du sang du taureau au pied de l''autel des holocaustes, qui est à l''entrée de la tente de réunion.'),
('lv',4,8,'crampon1923','Il enlèvera ensuite toute la graisse du taureau immolé pour le péché, la graisse qui enveloppe les entrailles et toute la graisse qui est attachée aux entrailles;'),
('lv',4,9,'crampon1923','les deux rognons, avec la graisse qui les recouvre et qui tient à la région lombaire; la taie du foie qu''il détachera près des rognons.'),
('lv',4,10,'crampon1923','Il enlèvera ces parties comme on les enlève du taureau dans le sacrifice pacifique, et il les fera fumer sur l''autel des holocaustes.'),
('lv',4,11,'crampon1923','Mais la peau du taureau, toute sa chair, avec sa tête, ses jambes, ses entrailles et ses excréments,'),
('lv',4,12,'crampon1923','le taureau entier, il l''emportera hors du camp, dans un lieu pur, où l''on jette les cendres, et il le brûlera au feu sur du bois; c''est sur le tas de cendres qu''il sera brûlé.'),
('lv',4,13,'crampon1923','Si toute l''assemblée d''Israël a péché par erreur, sans que la chose ait apparu à ses yeux, et qu''ils aient fait quelqu''une de toutes les choses que Yahweh a défendues de faire, se rendant ainsi coupables,'),
('lv',4,14,'crampon1923','quand le péché commis par eux sera reconnu, l''assemblée offrira un jeune taureau en sacrifice d''expiation, et on l''amènera devant la tente de réunion.'),
('lv',4,15,'crampon1923','Les anciens de l''assemblée d''Israël poseront leurs mains sur la tête du taureau devant Yahweh, et on égorgera le taureau devant Yahweh.'),
('lv',4,16,'crampon1923','Le prêtre ayant reçu l''onction apportera du sang du taureau dans la tente de réunion;'),
('lv',4,17,'crampon1923','il trempera son doigt dans le sang, il en fera sept fois l''aspersion devant Yahweh, en face du voile.'),
('lv',4,18,'crampon1923','Il mettra du sang sur les cornes de l''autel qui est devant Yahweh dans la tente de réunion, et il répandra tout le reste du sang au pied de l''autel des holocaustes, qui est à l''entrée de la tente de réunion.'),
('lv',4,19,'crampon1923','Il enlèvera ensuite toute la graisse du taureau, et il la fera fumer sur l''autel.'),
('lv',4,20,'crampon1923','Il fera de ce taureau comme du taureau immolé pour le péché du prêtre ayant reçu l''onction; il fera de même. C''est ainsi que le prêtre fera pour eux l''expiation, et il leur sera pardonné.'),
('lv',4,21,'crampon1923','Il emportera le taureau hors du camp et le brûlera comme le premier taureau. Tel est le sacrifice pour le péché de l''assemblée d''Israël.'),
('lv',4,22,'crampon1923','Si c''est un chef qui a péché, en faisant par erreur une de toutes les choses que Yahweh, son Dieu, a défendu de faire, se rendant ainsi coupable,'),
('lv',4,23,'crampon1923','quand le péché commis par lui sera venu à sa connaissance, il amènera pour son offrande un bouc mâle sans défaut.'),
('lv',4,24,'crampon1923','Il posera sa main sur la tête du bouc, et il l''égorgera dans le lieu où l''on égorge les holocaustes devant Yahweh; c''est un sacrifice pour le péché.'),
('lv',4,25,'crampon1923','Le prêtre prendra avec son doigt du sang de la victime pour le péché, il en mettra sur les cornes de l''autel des holocaustes, et il répandra le reste du sang au pied de cet autel.'),
('lv',4,26,'crampon1923','Puis il en brûlera toute la graisse sur l''autel, comme on brûle la graisse des sacrifices pacifiques. C''est ainsi que le prêtre fera pour lui l''expiation de son péché, et il lui sera pardonné.'),
('lv',4,27,'crampon1923','Si quelqu''un du peuple du pays a péché par erreur, en faisant une des choses que Yahweh a défendu de faire, se rendant ainsi coupable,'),
('lv',4,28,'crampon1923','quand le péché commis par lui sera venu à sa connaissance, il amènera pour son offrande une chèvre velue, une femelle sans défaut, pour le péché qu''il a commis.'),
('lv',4,29,'crampon1923','Il posera sa main sur la tête de la victime pour le péché et il l''égorgera dans le lieu où l''on offre les holocaustes.'),
('lv',4,30,'crampon1923','Le prêtre prendra avec son doigt du sang de la victime, il en mettra sur les cornes de l''autel des holocaustes, et il répandra tout le reste du sang au pied de l''autel.'),
('lv',4,31,'crampon1923','Il enlèvera toute la graisse, comme on enlève la graisse de dessus le sacrifice pacifique, et le prêtre la fera fumer sur l''autel en agréable odeur à Yahweh. C''est ainsi que le prêtre fera l''expiation pour cet homme, et il lui sera pardonné.'),
('lv',4,32,'crampon1923','Si c''est un agneau qu''il amène en sacrifice pour le péché, il amènera une femelle sans défaut.'),
('lv',4,33,'crampon1923','Il posera sa main sur la tête de la victime pour le péché et l''égorgera en sacrifice d''expiation dans le lieu où l''on immole l''holocauste.'),
('lv',4,34,'crampon1923','Le prêtre prendra avec son doigt du sang de la victime, il en mettra sur les cornes de l''autel des holocaustes, et il répandra tout le reste du sang au pied de l''autel.'),
('lv',4,35,'crampon1923','Il enlèvera toute la graisse, comme on enlève la graisse de l''agneau dans le sacrifice pacifique, et le prêtre la fera fumer sur l''autel, sur les sacrifices faits par le feu à Yahweh. C''est ainsi que le prêtre fera l''expiation pour cet homme, pour le péché qu''il a commis, et il lui sera pardonné.'),
('lv',5,1,'crampon1923','Si quelqu''un pèche en ce que, après avoir entendu l''adjuration du juge, en sa qualité de témoin, il ne déclare pas ce qu''il a vu, ou ce qu''il sait, il portera son iniquité.'),
('lv',5,2,'crampon1923','Si quelqu''un, sans s''en apercevoir, touche une chose impure, soit le cadavre d''une bête sauvage impure, soit le cadavre d''un animal domestique impur, soit le cadavre d''un reptile impur, et qu''il se trouve ainsi lui-même impur, il aura contracté une faute;'),
('lv',5,3,'crampon1923','de même si, sans y prendre garde, il touche une impureté humaine quelconque par laquelle on puisse être souillé, et qu''il s''en aperçoive plus tard, il aura contracté une faute.'),
('lv',5,4,'crampon1923','Si quelqu''un, parlant à la légère, jure de faire du mal ou du bien, quoi que ce soit qu''il affirme ainsi par un serment inconsidéré, et que, ne l''ayant pas remarqué d''abord, il s''en aperçoive plus tard, il aura en l''une de ces choses contracté une faute.'),
('lv',5,5,'crampon1923','Celui donc qui se sera rendu coupable dans l''une de ces trois choses, confessera ce en quoi il a péché.'),
('lv',5,6,'crampon1923','Il amènera à Yahweh, comme expiation, pour le péché qu''il a commis, une femelle de menu bétail, brebis ou chèvre, en sacrifice pour le péché, et le prêtre fera pour lui l''expiation de son péché.'),
('lv',5,7,'crampon1923','S''il n''a pas le moyen de se procurer une brebis ou une chèvre, il offrira à Yahweh, comme expiation pour son péché, deux tourterelles ou deux jeunes pigeons, l''un comme sacrifice pour le péché, l''autre comme holocauste.'),
('lv',5,8,'crampon1923','Il les apportera au prêtre, qui sacrifiera en premier lieu la victime pour le péché. Le prêtre lui brisera la tête près de la nuque, sans la détacher;'),
('lv',5,9,'crampon1923','il fera l''aspersion du sang de la victime pour le péché contre la paroi de l''autel et le reste du sang sera exprimé au pied de l''autel; c''est un sacrifice pour le péché.'),
('lv',5,10,'crampon1923','Il fera de l''autre oiseau un holocauste, d''après les rites de ce sacrifice. C''est ainsi que le prêtre fera pour cet homme l''expiation du péché qu''il a commis, et il lui sera pardonné.'),
('lv',5,11,'crampon1923','S''il n''a pas de quoi se procurer deux tourterelles ou deux jeunes pigeons, il apportera en offrande pour son péché un dixième d''épha de fleur de farine comme sacrifice pour le péché; il ne mettra point d''huile dessus, et il n''y ajoutera point d''encens, car c''est un sacrifice pour le péché.'),
('lv',5,12,'crampon1923','Il l''apportera au prêtre, et le prêtre en prendra une poignée en souvenir et la fera fumer sur l''autel, sur les sacrifices faits par le feu à Yahweh; c''est un sacrifice pour le péché.'),
('lv',5,13,'crampon1923','C''est ainsi que le prêtre fera l''expiation pour cet homme, pour le péché qu''il a commis à l''égard de l''une de ces trois choses, et il lui sera pardonné. Ce qui restera appartiendra au prêtre, comme dans l''oblation. "'),
('lv',5,14,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',5,15,'crampon1923','" Si quelqu''un commet une infidélité et pèche par erreur en retenant quelque chose des saintes offrandes de Yahweh il amènera à Yahweh en sacrifice de réparation, un bélier sans défaut, pris du troupeau, estimé par toi en sicles d''argent, selon le sicle du sanctuaire; ce sera un sacrifice de réparation.'),
('lv',5,16,'crampon1923','Et ce dont il a fait tort au sanctuaire, il le restituera, avec un cinquième en plus, et il le donnera au prêtre. Et le prêtre fera pour lui l''expiation avec le bélier offert en sacrifice de réparation, et il lui sera pardonné.'),
('lv',5,17,'crampon1923','Si quelqu''un pèche en faisant sans le savoir une de toutes les choses que Yahweh a défendu de faire, il sera coupable et portera son iniquité.'),
('lv',5,18,'crampon1923','Il amènera au prêtre, en sacrifice de réparation, un bélier sans défaut, pris du troupeau d''après ton estimation. Et le prêtre fera pour lui l''expiation pour le péché qu''il a commis par erreur, et qu''il n''a pas connu, et il lui sera pardonné.'),
('lv',5,19,'crampon1923','C''est un sacrifice de réparation; cet homme était certainement coupable devant Yahweh. "'),
('lv',5,20,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',5,21,'crampon1923','" Si quelqu''un pèche et commet une infidélité envers Yahweh, en mentant à son prochain au sujet d''un dépôt, d''un gage mis entre ses mains, d''une chose volée, ou en faisant violence à son prochain;'),
('lv',5,22,'crampon1923','en mentant à propos d''un objet perdu qu''il a trouvé, en faisant un faux serment au sujet de l''une des choses dans lesquelles l''homme peut pécher:'),
('lv',5,23,'crampon1923','quand il aura péché ainsi et se sera rendu coupable, il restituera la chose volée ou ravie par violence, le dépôt qui lui avait été confié, l''objet perdu qu''il a trouvé,'),
('lv',5,24,'crampon1923','ou tout objet au sujet duquel il a fait un faux serment. Il le restituera en son entier, avec un cinquième de la valeur en sus, et le remettra à son propriétaire, le jour même où il offrira son sacrifice de réparation.'),
('lv',5,25,'crampon1923','Il amènera au prêtre pour être offert à Yahweh en sacrifice de réparation un bélier sans défaut, pris du troupeau d''après ton estimation,'),
('lv',5,26,'crampon1923','Et le prêtre fera pour lui l''expiation devant Yahweh, et il lui sera pardonné, de quelque faute qu''il se soit rendu coupable. "'),
('lv',6,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',6,2,'crampon1923','" Donne cet ordre à Aaron et à ses fils, et dis-leur: Voici la loi de l''holocauste. L''holocauste brûlera sur le foyer de l''autel toute la nuit jusqu''au matin, et le feu de l''autel y sera tenu allumé.'),
('lv',6,3,'crampon1923','Chaque matin, le prêtre, ayant revêtu sa tunique de lin et mis des caleçons de lin sur sa chair, enlèvera la cendre laissée par le feu qui aura consumé l''holocauste sur l''autel, et la déposera à côté de l''autel;'),
('lv',6,4,'crampon1923','puis il quittera ses vêtements et en mettra d''autres pour porter la cendre hors du camp, en un lieu pur.'),
('lv',6,5,'crampon1923','Le feu sur l''autel y sera entretenu sans qu''il s''éteigne; le prêtre y allumera du bois chaque matin, arrangera dessus l''holocauste, et y fera fumer la graisse des sacrifices pacifiques.'),
('lv',6,6,'crampon1923','Un feu perpétuel doit brûler sur l''autel sans s''éteindre.'),
('lv',6,7,'crampon1923','Voici la loi de l''oblation: les fils d''Aaron la présenteront devant Yahweh, devant l''autel.'),
('lv',6,8,'crampon1923','Le prêtre en prélèvera une poignée de fleur de farine avec son huile, et tout l''encens qui est sur l''oblation, et il fera fumer cela sur l''autel, en agréable odeur, comme souvenir à Yahweh.'),
('lv',6,9,'crampon1923','Ce qui restera de l''oblation, Aaron et ses fils le mangeront; ils le mangeront sans levain, en lieu saint, dans le parvis de la tente de réunion.'),
('lv',6,10,'crampon1923','On ne le cuira pas avec du levain. C''est la part que je leur ai assignée de mes offrandes consumées par le feu. C''est une chose très sainte, comme le sacrifice pour le péché et comme le sacrifice de réparation.'),
('lv',6,11,'crampon1923','Tout mâle des enfants d''Aaron en mangera. C''est une loi perpétuelle pour vos descendants sur les offrandes faites par le feu à Yahweh. Quiconque y touchera sera saint. "'),
('lv',6,12,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',6,13,'crampon1923','" Voici l''offrande qu''Aaron et ses fils feront à Yahweh le jour où il recevra l''onction: un dixième d''épha de fleur de farine, comme oblation perpétuelle, moitié le matin et moitié le soir.'),
('lv',6,14,'crampon1923','Elle sera préparée dans la poêle avec de l''huile; tu l''apporteras quand elle sera frite, et tu l''offriras en morceaux, comme offrande divisée, d''agréable odeur à Yahweh.'),
('lv',6,15,'crampon1923','Le prêtre ayant reçu l''onction, qui lui succédera d''entre ses fils, fera aussi cette oblation: c''est une loi perpétuelle devant Yahweh; elle montera tout entière en fumée.'),
('lv',6,16,'crampon1923','Toute offrande de prêtre sera consumée tout entière; on ne la mangera pas. "'),
('lv',6,17,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',6,18,'crampon1923','" Parle à Aaron et à ses fils, et dis-leur: Voici la loi du sacrifice pour le péché: c''est dans le lieu où l''on égorge l''holocauste que sera égorgée la victime pour le péché devant Yahweh: c''est une chose très sainte.'),
('lv',6,19,'crampon1923','Le prêtre qui offrira la victime pour le péché la mangera; elle sera mangée en lieu saint, dans le parvis de la tente de réunion.'),
('lv',6,20,'crampon1923','Quiconque en touchera la chair sera saint. S''il en rejaillit du sang sur un vêtement, la place où le sang aura rejailli, tu la laveras en lieu saint.'),
('lv',6,21,'crampon1923','Le vase de terre dans lequel elle aura cuit sera brisé; si elle a cuit dans un vase d''airain, il sera nettoyé et rincé dans l''eau.'),
('lv',6,22,'crampon1923','Tout mâle parmi les prêtres en mangera: c''est une chose très sainte.'),
('lv',6,23,'crampon1923','Mais on ne mangera aucune victime pour le péché dont on doit porter le sang dans la tente de réunion pour faire l''expiation dans le sanctuaire: elle sera brûlée au feu.'),
('lv',7,1,'crampon1923','Voici la loi du sacrifice de réparation; c''est une chose très sainte.'),
('lv',7,2,'crampon1923','C''est dans le lieu où l''on égorge l''holocauste que sera égorgée la victime de réparation. On en répandra le sang sur l''autel tout autour.'),
('lv',7,3,'crampon1923','On en offrira toute la graisse, la queue, la graisse qui enveloppe les entrailles,'),
('lv',7,4,'crampon1923','les deux rognons avec la graisse qui les recouvre et qui tient à la région lombaire, et la taie du foie, qu''on détachera près des rognons.'),
('lv',7,5,'crampon1923','Le prêtre les fera fumer sur l''autel en sacrifice par le feu à Yahweh. C''est un sacrifice de réparation.'),
('lv',7,6,'crampon1923','Tout mâle parmi les prêtres en mangera la chair; il la mangera en lieu saint: c''est une chose très sainte.'),
('lv',7,7,'crampon1923','Il en est du sacrifice de réparation comme du sacrifice pour le péché; la loi est la même pour les deux: la victime appartiendra au prêtre qui fera l''expiation.'),
('lv',7,8,'crampon1923','Le prêtre qui offrira l''holocauste de quelqu''un aura pour lui la peau de l''holocauste qu''il a offert.'),
('lv',7,9,'crampon1923','Toute oblation cuite au four, et celle qui est préparée dans la casserole ou à la poêle appartiendra au prêtre qui l''aura offerte.'),
('lv',7,10,'crampon1923','Toute oblation pétrie à l''huile ou sèche sera pour tous les fils d''Aaron, qui en auront une part égale.'),
('lv',7,11,'crampon1923','Voici la loi du sacrifice pacifique qu''on offrira à Yahweh.'),
('lv',7,12,'crampon1923','Si on l''offre par reconnaissance, on offrira, avec la victime de reconnaissance, des gâteaux sans levain pétris à l''huile, des galettes sans levain arrosées d''huile, de la farine frite en gâteaux pétris à l''huile.'),
('lv',7,13,'crampon1923','On ajoutera des gâteaux levés à l''offrande qu''on présentera avec la victime de reconnaissance de son sacrifice pacifique.'),
('lv',7,14,'crampon1923','On présentera une pièce de chacune de ces offrandes prélevées pour Yahweh; elle sera pour le prêtre qui aura fait l''aspersion du sang de la victime pacifique.'),
('lv',7,15,'crampon1923','La chair de la victime de reconnaissance du sacrifice pacifique sera mangée le jour où on l''aura offerte; on n''en laissera rien jusqu''au matin.'),
('lv',7,16,'crampon1923','Si la victime est offerte par suite d''un vœu ou comme offrande volontaire, la victime sera mangée le jour où on l''aura offerte, et ce qui en restera sera mangé le lendemain.'),
('lv',7,17,'crampon1923','Ce qui resterait encore de la chair de la victime le troisième jour sera consumé par le feu.'),
('lv',7,18,'crampon1923','Si un homme mange de la chair de son sacrifice pacifique le troisième jour, ce sacrifice ne sera point agréé; il n''en sera pas tenu compte à celui qui l''a offert; ce sera une abomination, et quiconque en aura mangé portera son iniquité.'),
('lv',7,19,'crampon1923','La chair qui a touché quelque chose d''impur ne se mangera pas; elle sera consumée par le feu. Quant à la chair du sacrifice pacifique, tout homme pur pourra en manger.'),
('lv',7,20,'crampon1923','Mais celui qui, se trouvant en état d''impureté, aura mangé de la chair de la victime pacifique appartenant à Yahweh, celui-là sera retranché de son peuple.'),
('lv',7,21,'crampon1923','Et celui qui touchera quelque chose d''impur, souillure d''homme ou animal impur, ou toute autre abomination impure, et qui mangera de la chair de la victime pacifique appartenant à Yahweh, celui-là sera retranché de son peuple. "'),
('lv',7,22,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',7,23,'crampon1923','" Parle aux enfants d''Israël et dis-leur: Vous ne mangerez point de graisse de bœuf, de brebis, ni de chèvre.'),
('lv',7,24,'crampon1923','La graisse d''un animal mort ou déchiré par une bête féroce pourra servir à un usage quelconque, mais vous n''en mangerez en aucune manière.'),
('lv',7,25,'crampon1923','Car quiconque mangera de la graisse des animaux que l''on offre à Yahweh en sacrifices faits par le feu, sera retranché de son peuple.'),
('lv',7,26,'crampon1923','Vous ne mangerez point de sang ni d''oiseau, ni de quadrupède, dans tous les lieux que vous habiterez.'),
('lv',7,27,'crampon1923','Celui qui mangera d''un sang quelconque, celui-là sera retranché de son peuple. "'),
('lv',7,28,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',7,29,'crampon1923','" Parle aux enfants d''Israël et dis-leur: Celui qui offrira à Yahweh sa victime pacifique apportera à Yahweh son offrande prélevée sur son sacrifice pacifique.'),
('lv',7,30,'crampon1923','Il apportera dans ses mains ce qui doit être offert par le feu à Yahweh: il apportera la graisse avec la poitrine, la poitrine pour la balancer devant Yahweh.'),
('lv',7,31,'crampon1923','Le prêtre fera fumer la graisse sur l''autel, et la poitrine sera pour Aaron et pour ses fils.'),
('lv',7,32,'crampon1923','Vous donnerez aussi au prêtre la cuisse droite comme offrande prélevée de vos victimes pacifiques.'),
('lv',7,33,'crampon1923','Celui des fils d''Aaron qui offrira le sang et la graisse des victimes pacifiques aura la cuisse droite pour sa part.'),
('lv',7,34,'crampon1923','Car j''ai pris sur les sacrifices pacifiques des enfants d''Israël la poitrine à balancer et l''épaule prélevée, et je les donne au prêtre Aaron et à ses fils comme une redevance perpétuelle imposée aux enfants d''Israël.'),
('lv',7,35,'crampon1923','C''est là le droit de l''onction d''Aaron et le droit de l''onction de ses fils sur les sacrifices faits par le feu à Yahweh, à partir du jour où on les présentera pour être prêtres au service de Yahweh.'),
('lv',7,36,'crampon1923','C''est ce que Yahweh a ordonné aux enfants d''Israël de leur donner depuis le jour de leur onction; ce sera une redevance perpétuelle parmi leurs descendants. "'),
('lv',7,37,'crampon1923','Telle est la loi de l''holocauste, de l''oblation, du sacrifice pour le péché, du sacrifice de réparation, de l''installation et du sacrifice pacifique.'),
('lv',7,38,'crampon1923','Yahweh la prescrivit à Moïse sur la montagne de Sinaï, le jour où il ordonna aux enfants d''Israël de présenter leurs offrandes à Yahweh dans le désert de Sinaï.'),
('lv',8,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',8,2,'crampon1923','" Prends Aaron et ses fils avec lui, les vêtements, l''huile d''onction, le taureau pour le sacrifice pour le péché, les deux béliers et la corbeille de pains sans levain,'),
('lv',8,3,'crampon1923','et convoque toute l''assemblée à l''entrée de la tente de réunion. "'),
('lv',8,4,'crampon1923','Moïse fit ce que Yahweh lui avait ordonné; et l''assemblée s''étant réunie à l''entrée de la tente de réunion,'),
('lv',8,5,'crampon1923','Moïse dit à l''assemblée: " Voici ce que Yahweh a ordonné de faire. "'),
('lv',8,6,'crampon1923','Moïse fit approcher Aaron et ses fils, et il les lava avec de l''eau.'),
('lv',8,7,'crampon1923','Il mit à Aaron la tunique, le ceignit de la ceinture, le revêtit de la robe, et il plaça sur lui l''éphod,'),
('lv',8,8,'crampon1923','qu''il serra avec la ceinture de l''éphod et il le lui attacha. Il lui mit le pectoral et il joignit au pectoral l''Urim et le Thummim;'),
('lv',8,9,'crampon1923','et, ayant posé la tiare sur sa tête, il plaça sur le devant de la tiare la lame d''or, diadème sacré, comme Yahweh l''avait ordonné à Moïse.'),
('lv',8,10,'crampon1923','Et Moïse prit l''huile d''onction, il oignit la Demeure et toutes les choses qui étaient dedans, et il les consacra.'),
('lv',8,11,'crampon1923','Il en aspergea sept fois l''autel, et il oignit l''autel avec tous ses ustensiles, ainsi que le bassin avec sa base, pour les consacrer.'),
('lv',8,12,'crampon1923','Il versa de l''huile d''onction sur la tête d''Aaron, et l''oignit pour le consacrer.'),
('lv',8,13,'crampon1923','Moïse fit aussi approcher les fils d''Aaron; il les revêtit de tuniques, les ceignit de ceintures et leur attacha des mitres, comme Yahweh l''avait ordonné à Moïse.'),
('lv',8,14,'crampon1923','Il fit approcher le taureau du sacrifice pour le péché, et Aaron et ses fils posèrent leurs mains sur la tête du taureau du sacrifice pour le péché.'),
('lv',8,15,'crampon1923','Moïse l''égorgea, prit du sang, en mit avec son doigt sur les cornes de l''autel tout autour, et purifia l''autel; il répandit le reste du sang au pied de l''autel, et le consacra en faisant sur lui l''expiation.'),
('lv',8,16,'crampon1923','Il prit ensuite toute la graisse qui enveloppe les entrailles, la taie du foie et les deux rognons avec leur graisse, et il les fit fumer sur l''autel.'),
('lv',8,17,'crampon1923','Mais le taureau, sa peau, sa chair et ses excréments, il les brûla hors du camp, comme Yahweh l''avait ordonné à Moïse.'),
('lv',8,18,'crampon1923','Il fit approcher le bélier de l''holocauste, et Aaron et ses fils posèrent leurs mains sur la tête du bélier.'),
('lv',8,19,'crampon1923','On l''égorgea et Moïse répandit le sang sur l''autel tout autour.'),
('lv',8,20,'crampon1923','Puis on coupa le bélier en morceaux, et Moïse fit fumer la tête, les morceaux et la graisse.'),
('lv',8,21,'crampon1923','On lava dans l''eau les entrailles et les jambes, et Moïse fit fumer tout le bélier sur l''autel: c''était un holocauste d''agréable odeur, un sacrifice fait par le feu à Yahweh, comme Yahweh l''avait ordonné à Moïse.'),
('lv',8,22,'crampon1923','Il fit approcher l''autre bélier, le bélier d''installation. Aaron et ses fils ayant posé leurs mains sur la tête du bélier,'),
('lv',8,23,'crampon1923','Moïse égorgea le bélier, prit de son sang, et en mit sur le lobe de l''oreille droite d''Aaron, sur le pouce de sa main droite et sur le gros orteil de son pied droit.'),
('lv',8,24,'crampon1923','Il fit approcher les fils d''Aaron, mit du sang sur le lobe de leur oreille droite, sur le pouce de leur main droite et sur le gros orteil de leur pied droit; puis il répandit le reste du sang sur l''autel tout autour.'),
('lv',8,25,'crampon1923','Il prit ensuite la graisse, la queue, toute la graisse qui couvre les entrailles, la taie du foie, les deux rognons avec leur graisse, et la cuisse droite;'),
('lv',8,26,'crampon1923','il prit aussi, de la corbeille de pains sans levain placée devant Yahweh, un gâteau sans levain, un gâteau de pain pétri à l''huile et une galette, et il les posa sur les graisses et sur la cuisse droite;'),
('lv',8,27,'crampon1923','et ayant mis toutes ces choses sur les mains d''Aaron et sur les mains de ses fils, il les balança en offrande devant Yahweh.'),
('lv',8,28,'crampon1923','Puis Moïse les ôta de dessus leurs mains, et les fit fumer sur l''autel, par-dessus l''holocauste; car c''était un sacrifice d''installation, d''agréable odeur, sacrifice fait par le feu à Yahweh.'),
('lv',8,29,'crampon1923','Moïse prit la poitrine du bélier d''installation et la balança en offrande devant Yahweh: ce fut la portion de Moïse, comme Yahweh l''avait ordonné à Moïse.'),
('lv',8,30,'crampon1923','Moïse prit de l''huile d''onction et du sang qui était sur l''autel; il en fit l''aspersion sur Aaron et sur ses vêtements, sur les fils d''Aaron et sur leurs vêtements, et il consacra ainsi Aaron et ses vêtements, ses fils et leurs vêtements avec lui.'),
('lv',8,31,'crampon1923','Moïse dit à Aaron et à ses fils: " Faites cuire la chair à l''entrée de la tente de réunion; c''est là que vous la mangerez, avec le pain qui est dans la corbeille d''installation, comme je l''ai ordonné en disant: Aaron et ses fils la mangeront.'),
('lv',8,32,'crampon1923','Et ce qui restera de la chair et du pain, vous le brûlerez dans le feu.'),
('lv',8,33,'crampon1923','Pendant sept jours vous ne sortirez point de l''entrée de la tente de réunion, jusqu''à ce que soient accomplis les jours de votre installation; car votre installation durera sept jours.'),
('lv',8,34,'crampon1923','Ce qui s''est fait aujourd''hui, Yahweh a ordonné de le faire durant sept jours afin de faire l''expiation pour vous.'),
('lv',8,35,'crampon1923','Vous resterez sept jours, jour et nuit, à l''entrée de la tente de réunion, et vous observerez les ordres de Yahweh, afin que vous ne mouriez pas; car c''est là ce qui m''a été ordonné. "'),
('lv',8,36,'crampon1923','Aaron et ses fils firent toutes les choses que Yahweh avait commandées par Moïse.'),
('lv',9,1,'crampon1923','Le huitième jour, Moïse appela Aaron et ses fils, et les anciens d''Israël.'),
('lv',9,2,'crampon1923','Il dit à Aaron: " Prends un jeune veau pour le sacrifice pour le péché et un bélier pour l''holocauste, tous deux sans défaut, et offre-les devant Yahweh.'),
('lv',9,3,'crampon1923','Tu parleras aux enfants d''Israël, en disant: Prenez un bouc pour le sacrifice pour le péché; un veau et un agneau âgés d''un an et sans défaut pour l''holocauste;'),
('lv',9,4,'crampon1923','un bœuf et un bélier pour le sacrifice pacifique, afin de les immoler devant Yahweh; et une oblation pétrie à l''huile. Car aujourd''hui Yahweh vous apparaîtra. "'),
('lv',9,5,'crampon1923','Ils amenèrent devant la tente de réunion ce que Moïse avait commandé, et toute l''assemblée s''approcha et se tint devant Yahweh.'),
('lv',9,6,'crampon1923','Alors Moïse dit: " Faites ce que Yahweh vous ordonne, et la gloire de Yahweh vous apparaîtra. "'),
('lv',9,7,'crampon1923','Moïse dit à Aaron: " Approche-toi de l''autel; offre ton sacrifice pour le péché et ton holocauste, et fais l''expiation pour toi et pour le peuple; présente aussi l''offrande du peuple et fais l''expiation pour lui, comme Yahweh l''a ordonné. "'),
('lv',9,8,'crampon1923','Aaron s''approcha de l''autel et égorgea le veau du sacrifice pour le péché offert pour lui.'),
('lv',9,9,'crampon1923','Les fils d''Aaron lui ayant présenté le sang, il y trempa son doigt, en mit sur les cornes de l''autel et répandit le sang au pied de l''autel.'),
('lv',9,10,'crampon1923','Il fit fumer sur l''autel la graisse, les rognons et la taie du foie de la victime pour le péché, comme Yahweh l''avait ordonné à Moïse;'),
('lv',9,11,'crampon1923','mais la chair et la peau, il les brûla par le feu hors du camp.'),
('lv',9,12,'crampon1923','Il égorgea l''holocauste, et les fils d''Aaron lui ayant présenté le sang, il le répandit sur l''autel, tout autour.'),
('lv',9,13,'crampon1923','Ils lui présentèrent l''holocauste coupé en morceaux, avec la tête, et il les fit fumer sur l''autel.'),
('lv',9,14,'crampon1923','Il lava les entrailles et les jambes, et les fit fumer sur l''autel par-dessus l''holocauste.'),
('lv',9,15,'crampon1923','Il présenta ensuite l''offrande du peuple. Il prit le bouc du sacrifice pour le péché offert pour le peuple, et l''ayant égorgé, il l''offrit en expiation, comme il avait fait pour la première victime.'),
('lv',9,16,'crampon1923','il offrit de même l''holocauste et le sacrifia suivant le rite.'),
('lv',9,17,'crampon1923','Il présenta l''oblation, en prit une poignée et la consuma sur l''autel, en sus de l''holocauste du matin.'),
('lv',9,18,'crampon1923','Enfin il égorgea le taureau et le bélier en sacrifice pacifique pour le peuple. Les fils d''Aaron lui présentèrent le sang, qu''il répandit sur l''autel tout autour;'),
('lv',9,19,'crampon1923','ainsi que les parties grasses du taureau et du bélier, la queue, la graisse qui enveloppe les entrailles, les rognons et la taie du foie;'),
('lv',9,20,'crampon1923','et ils placèrent les graisses sur les poitrines, et il fit fumer les graisses sur l''autel.'),
('lv',9,21,'crampon1923','Puis Aaron balança devant Yahweh les poitrines et la cuisse droite en offrande balancée, comme Moïse l''avait ordonné.'),
('lv',9,22,'crampon1923','Alors Aaron, élevant ses mains vers le peuple, le bénit; et il descendit, après avoir offert le sacrifice pour le péché, l''holocauste et le sacrifice pacifique.'),
('lv',9,23,'crampon1923','Moïse et Aaron entrèrent dans la tente de réunion; lorsqu''ils en sortirent, ils bénirent le peuple. Et la gloire de Yahweh apparut à tout le peuple,'),
('lv',9,24,'crampon1923','et le feu, sortant de devant Yahweh, dévora sur l''autel l''holocauste et les graisses. Et tout le peuple le vit; et ils poussèrent des cris de joie, et ils tombèrent sur leur face.'),
('lv',10,1,'crampon1923','Les fils d''Aaron, Nadab et Abiu, prirent chacun leur encensoir, y mirent du feu et, ayant posé du parfum dessus, ils apportèrent devant Yahweh un feu étranger, ce qu''il ne leur avait point commandé.'),
('lv',10,2,'crampon1923','Alors un feu sortit de devant Yahweh et les dévora: ils moururent devant Yahweh.'),
('lv',10,3,'crampon1923','Et Moïse dit à Aaron: " C''est ce que Yahweh a déclaré, lorsqu''il a dit: Je serai sanctifié en ceux qui m''approchent, et je serai glorifié en présence de tout le peuple. " Aaron se tut.'),
('lv',10,4,'crampon1923','Et Moïse appela Misaël et Elisaphon, fils d''Oziel, oncle d''Aaron, et il leur dit: " Approchez-vous, emportez vos frères loin du sanctuaire, hors du camp. "'),
('lv',10,5,'crampon1923','Ils s''approchèrent et les emportèrent revêtus de leurs tuniques hors du camp, comme Moïse l''avait ordonné.'),
('lv',10,6,'crampon1923','Moïse dit à Aaron, à Eléazar et à Ithamar: " Vous ne laisserez point flotter en désordre les cheveux de votre tête et vous ne déchirerez point vos vêtements, de peur que vous ne mouriez, et que Yahweh ne s''irrite contre toute l''assemblée. Que vos frères, toute la maison d''Israël, pleurent sur l''embrasement que Yahweh a allumé.'),
('lv',10,7,'crampon1923','Pour vous, vous ne sortirez point de l''entrée de la tente de réunion, de peur que vous ne mouriez; car l''huile de l''onction de Yahweh est sur vous. " Ils firent ce que Moïse avait dit.'),
('lv',10,8,'crampon1923','Yahweh parla à Aaron, en disant:'),
('lv',10,9,'crampon1923','" Tu ne boiras ni vin, ni boisson enivrante, toi et tes fils avec toi, lorsque vous entrerez dans la tente de réunion, afin que vous ne mouriez pas: c''est une loi perpétuelle parmi vos descendants,'),
('lv',10,10,'crampon1923','et afin que vous sachiez discerner ce qui est saint de ce qui est profane, ce qui est pur de ce qui est impur,'),
('lv',10,11,'crampon1923','et afin que vous puissiez enseigner aux enfants d''Israël toutes les lois que Yahweh leur a données par Moïse.'),
('lv',10,12,'crampon1923','Moïse dit à Aaron, à Eléazar et à Ithamar, les deux fils qui restaient à Aaron: " Prenez l''oblation qui reste des sacrifices faits par le feu à Yahweh, et mangez-la sans levain près de l''autel, car c''est une chose très sainte.'),
('lv',10,13,'crampon1923','Vous la mangerez dans un lieu saint: c''est ton droit et le droit de tes fils sur les offrandes faites par le feu à Yahweh; c''est là ce qui m''a été ordonné.'),
('lv',10,14,'crampon1923','Vous mangerez aussi en lieu pur, toi, tes fils et tes filles avec toi, la poitrine qui aura été balancée et la cuisse qui aura été prélevée; car ces morceaux vous sont donnés comme ton droit et le droit de tes fils sur les sacrifices pacifiques des enfants d''Israël.'),
('lv',10,15,'crampon1923','Ils apporteront, outre les graisses destinées à être consumées par le feu, la cuisse que l''on prélève et la poitrine que l''on balance, pour qu''elles soient balancées devant Yahweh; elles seront pour toi et pour tes fils avec toi par une loi perpétuelle, comme Yahweh l''a ordonné. "'),
('lv',10,16,'crampon1923','Moïse s''enquit du bouc immolé pour le péché, et voici, il avait été brûlé. Alors, il s''irrita contre Eléazar et Ithamar, les fils qui restaient à Aaron, et il leur dit:'),
('lv',10,17,'crampon1923','" Pourquoi n''avez-vous pas mangé la victime pour le péché dans le lieu saint? Car c''est une chose très sainte, et Yahweh vous l''a donnée, afin que vous portiez l''iniquité de l''assemblée, afin que vous fassiez pour elle l''expiation devant Yahweh.'),
('lv',10,18,'crampon1923','Voici, le sang de la victime n''a pas été porté dans l''intérieur du sanctuaire; vous deviez la manger dans un lieu saint, comme je l''ai commandé. "'),
('lv',10,19,'crampon1923','Aaron dit à Moïse: " Voici, ils ont offert aujourd''hui leur sacrifice pour le péché et leur holocauste devant Yahweh; mais, après ce qui m''est arrivé, si j''avais mangé aujourd''hui la victime pour le péché, cela eût-il été agréable aux yeux de Yahweh? "'),
('lv',10,20,'crampon1923','Moïse, ayant entendu ces paroles, il les eut pour agréables.'),
('lv',11,1,'crampon1923','Yahweh parla à Moïse et à Aaron, en leur disant:'),
('lv',11,2,'crampon1923','" Parlez aux enfants d''Israël, et dites: Voici les animaux que vous mangerez parmi toutes les bêtes qui sont sur la terre:')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('lv',11,3,'crampon1923','Tout animal qui a la corne divisée et le pied fourchu, et qui rumine, vous le mangerez.'),
('lv',11,4,'crampon1923','Mais vous ne mangerez pas de ceux qui ruminent seulement, ou qui ont seulement la corne divisée. Tel est le chameau, qui rumine, mais dont la corne n''est pas divisée: il sera impur pour vous.'),
('lv',11,5,'crampon1923','Telle la gerboise, qui rumine, mais qui n''a pas la corné divisée: elle sera impure pour vous.'),
('lv',11,6,'crampon1923','Tel le lièvre, qui rumine, mais qui n''a pas la corne divisée: il sera impur pour vous.'),
('lv',11,7,'crampon1923','Tel le porc, qui a la corne divisée et le pied fourchu, mais qui ne rumine pas: il sera impur pour vous.'),
('lv',11,8,'crampon1923','Vous ne mangerez pas de leur chair, et vous ne toucherez pas à leurs corps morts: ils seront impurs pour vous.'),
('lv',11,9,'crampon1923','Voici les animaux que vous mangerez parmi tous ceux qui sont dans les eaux: Tout ce qui a nageoires et écailles, dans les eaux, soit dans la mer, soit dans les rivières, vous le mangerez.'),
('lv',11,10,'crampon1923','Mais vous aurez en abomination tout ce qui n''a pas nageoires et écailles, dans les mers et dans les rivières, parmi tous les animaux qui se meuvent dans les eaux et parmi tous les êtres vivants qui s''y trouvent.'),
('lv',11,11,'crampon1923','Ils seront pour vous une abomination; vous ne mangerez pas de leur chair, et vous tiendrez pour abominables leurs cadavres.'),
('lv',11,12,'crampon1923','Tout ce qui, dans les eaux, n''a pas de nageoires et d''écailles, vous l''aurez en abomination.'),
('lv',11,13,'crampon1923','Voici, parmi les oiseaux, ceux que vous aurez en abomination; on ne les mangera pas, c''est chose abominable: l''aigle, l''orfraie et le vautour:'),
('lv',11,14,'crampon1923','le milan et toute espèce de faucons;'),
('lv',11,15,'crampon1923','toute espèce de corbeaux;'),
('lv',11,16,'crampon1923','l''autruche, le chat-huant, la mouette et toute espèce d''éperviers;'),
('lv',11,17,'crampon1923','le hibou, le cormoran et la chouette;'),
('lv',11,18,'crampon1923','le cygne, le pélican et le gypaète;'),
('lv',11,19,'crampon1923','la cigogne, toute espèce de hérons; la huppe et la chauve-souris.'),
('lv',11,20,'crampon1923','Tout insecte ailé qui marche sur quatre pattes, vous l''aurez en abomination.'),
('lv',11,21,'crampon1923','Mais, parmi tous les insectes ailés qui marchent sur quatre pattes, vous mangerez ceux qui ont des jambes au-dessus de leurs pattes, pour sauter sur la terre.'),
('lv',11,22,'crampon1923','Voici ceux d''entre eux que vous mangerez: toute espèce de sauterelles, toute espèce de solam, toute espèce de hargol, toute espèce de hagab.'),
('lv',11,23,'crampon1923','Toute autre bête ailée ayant quatre pattes, vous l''aurez en abomination.'),
('lv',11,24,'crampon1923','Ceux-ci aussi vous rendront impurs: quiconque touchera leur corps mort sera impur jusqu''au soir,'),
('lv',11,25,'crampon1923','et quiconque emportera quelque partie de leur corps mort lavera ses vêtements et sera impur jusqu''au soir.'),
('lv',11,26,'crampon1923','Tout animal qui a la corne divisée, mais qui n''a pas le pied fourchu et qui ne rumine pas, sera impur pour vous; quiconque le touchera se rendra impur.'),
('lv',11,27,'crampon1923','Et parmi les animaux à quatre pieds, tout ce qui marche sur la plante des pieds vous sera impur: quiconque touchera leur corps mort sera impur jusqu''au soir;'),
('lv',11,28,'crampon1923','et quiconque portera leur corps mort lavera ses vêtements et sera impur jusqu''au soir. Ces animaux seront impurs pour vous.'),
('lv',11,29,'crampon1923','Voici, parmi les petites bêtes qui rampent sur la terre, celles qui seront impures pour vous: la belette, la souris et toute espèce de lézards;'),
('lv',11,30,'crampon1923','la musaraigne, le caméléon, la salamandre, le lézard vert et la taupe.'),
('lv',11,31,'crampon1923','Tels sont ceux qui seront impurs pour vous parmi les reptiles: quiconque les touchera morts sera impur jusqu''au soir.'),
('lv',11,32,'crampon1923','Tout objet sur lequel il en tombera de morts sera souillé: ustensile de bois, vêtement, peau, sac, tout objet dont on fait usage; on le mettra dans l''eau, et il restera souillé jusqu''au soir; après quoi, il sera pur.'),
('lv',11,33,'crampon1923','S''il en tombe quelque chose dans le milieu de tout vase de terre, tout ce qui sera dans le milieu du vase sera souillé, et vous briserez le vase.'),
('lv',11,34,'crampon1923','Tout aliment servant à la nourriture et préparé avec de l''eau, sera souillé; toute boisson dont on fait usage, quel que soit le vase qui la contienne, sera souillée.'),
('lv',11,35,'crampon1923','Tout objet sur lequel tombera quelque chose de leur corps mort sera souillé; le four et le vase avec son couvercle seront détruits; ils seront souillés et vous les tiendrez pour souillés.'),
('lv',11,36,'crampon1923','Mais les sources et les citernes, où se forment les amas d''eau, resteront pures; toutefois celui qui touchera le corps mort sera impur.'),
('lv',11,37,'crampon1923','S''il tombe quelque chose de leur corps mort sur une semence qui doit être semée, la semence restera pure;'),
('lv',11,38,'crampon1923','mais si l''on a mis de l''eau sur la semence, et qu''il y tombe quelque chose de leur corps mort, vous la tiendrez pour souillée.'),
('lv',11,39,'crampon1923','S''il meurt un des animaux qui vous servent de nourriture, celui qui touchera son cadavre sera impur jusqu''au soir.'),
('lv',11,40,'crampon1923','Celui qui mangera de son corps mort lavera ses vêtements et sera impur jusqu''au soir; celui qui portera son corps mort, lavera ses vêtements et sera impur jusqu''au soir.'),
('lv',11,41,'crampon1923','Vous aurez en abomination tout reptile qui rampe sur la terre: on n''en mangera point.'),
('lv',11,42,'crampon1923','Vous ne mangerez d''aucun animal qui rampe sur la terre, soit de ceux qui se traînent sur le ventre, soit de ceux qui marchent sur quatre pieds ou sur un grand nombre de pieds; car vous les aurez en abomination.'),
('lv',11,43,'crampon1923','Ne vous rendez point abominables par tous ces reptiles qui rampent; ne vous rendez point impurs par eux; vous seriez souillés par eux.'),
('lv',11,44,'crampon1923','Car je suis Yahweh, votre Dieu; vous vous sanctifierez et vous serez saints, car je suis saint; et vous ne vous souillerez point par tous ces reptiles, qui rampent sur la terre.'),
('lv',11,45,'crampon1923','Car je suis Yahweh, qui vous ai fait monter du pays d''Egypte, pour être votre Dieu. Vous serez saints, car je suis saint. "'),
('lv',11,46,'crampon1923','Telle est la loi touchant les quadrupèdes, les oiseaux, tous les êtres vivants qui se meuvent dans les eaux, et tous les êtres qui rampent sur la terre,'),
('lv',11,47,'crampon1923','afin que vous distinguiez entre ce qui est impur et ce qui est pur, entre l''animal qui se mange et celui qui ne se mange pas.'),
('lv',12,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',12,2,'crampon1923','" Parle aux enfants d''Israël, et dis-leur: Quand une femme enfantera et mettra au monde un garçon, elle sera impure pendant sept jours; elle sera impure comme aux jours de son indisposition menstruelle.'),
('lv',12,3,'crampon1923','Le huitième jour, l''enfant sera circoncis;'),
('lv',12,4,'crampon1923','mais elle restera encore trente-trois jours dans le sang de sa purification; elle ne touchera aucune chose sainte et elle n''ira point au sanctuaire, jusqu''à ce que les jours de sa purification soient accomplis.'),
('lv',12,5,'crampon1923','Si elle met au monde une fille, elle sera impure pendant deux semaines, comme à son indisposition menstruelle, et elle restera soixante-six jours dans le sang de sa purification.'),
('lv',12,6,'crampon1923','Lorsque les jours de sa purification seront accomplis, pour un fils ou une fille, elle présentera au prêtre, à l''entrée de la tente de réunion, un agneau d''un an en holocauste, et un jeune pigeon ou une tourterelle en sacrifice pour le péché.'),
('lv',12,7,'crampon1923','Le prêtre les offrira devant Yahweh, et fera pour elle l''expiation, et elle sera pure du flux de son sang. Telle est la loi pour la femme qui met au monde soit un fils soit une fille.'),
('lv',12,8,'crampon1923','Si elle n''a pas de quoi se procurer un agneau, qu''elle prenne deux tourterelles ou deux jeunes pigeons, l''un pour l''holocauste, l''autre pour le sacrifice pour le péché; et le prêtre fera pour elle l''expiation, et elle sera pure. "'),
('lv',13,1,'crampon1923','Yahweh parla à Moïse et à Aaron en disant:'),
('lv',13,2,'crampon1923','" Quand un homme aura sur la peau de sa chair une tumeur, une dartre ou une tache blanche, et qu''il viendra ainsi sur la peau de sa chair une plaie de lèpre, on l''amènera à Aaron, le prêtre, ou à l''un de ses fils qui sont prêtres.'),
('lv',13,3,'crampon1923','Le prêtre examinera la plaie qui est sur la peau de la chair: si le poil de la plaie est devenu blanc et que la plaie paraisse plus profonde que la peau de la chair, c''est une plaie de lèpre: le prêtre, ayant examiné cet homme, le déclarera impur.'),
('lv',13,4,'crampon1923','S''il y a sur la peau de sa chair une tache blanche qui ne paraisse pas plus profonde que la peau, et que le poil ne soit pas devenu blanc, le prêtre séquestrera pendant sept jours celui qui a la plaie.'),
('lv',13,5,'crampon1923','Le septième jour le prêtre l''examinera: si la plaie lui paraît n''avoir pas fait de progrès, ne s''étant pas étendue sur la peau, le prêtre le séquestrera une seconde fois pendant sept jours.'),
('lv',13,6,'crampon1923','Le prêtre l''examinera une seconde fois le septième jour: si la plaie est devenue terne et ne s''est pas étendue sur la peau, le prêtre déclarera cet homme pur: c''est une dartre; il lavera ses vêtements, et il sera pur.'),
('lv',13,7,'crampon1923','Mais si la dartre s''est étendue sur la peau, après qu''il s''est montré au prêtre pour être déclaré pur, il se montrera une seconde fois au prêtre.'),
('lv',13,8,'crampon1923','Le prêtre l''examinera et, si la dartre s''est étendue sur la peau, le prêtre le déclarera impur: c''est la lèpre.'),
('lv',13,9,'crampon1923','Lorsqu''il y aura sur un homme une plaie de lèpre, on l''amènera au prêtre.'),
('lv',13,10,'crampon1923','Le prêtre l''examinera. Et voici, il y a sur la peau une tumeur blanche, et cette tumeur a fait blanchir le poil, et il y a trace de chair vive dans la tumeur;'),
('lv',13,11,'crampon1923','c''est une lèpre invétérée dans la peau de sa chair: le prêtre le déclarera impur; il ne l''enfermera pas, car cet homme est impur.'),
('lv',13,12,'crampon1923','Mais si la lèpre s''est épanouie sur la peau et couvre toute la peau de celui qui a la plaie, depuis la tête jusqu''aux pieds, selon tout ce que voient les yeux du prêtre,'),
('lv',13,13,'crampon1923','le prêtre l''examinera, et si la lèpre couvre tout le corps, il déclarera pur celui qui a la plaie: il est devenu tout entier blanc; il est pur.'),
('lv',13,14,'crampon1923','Mais le jour où l''on apercevra en lui de la chair vive, il sera impur;'),
('lv',13,15,'crampon1923','quand le prêtre aura vu la chair vive, il le déclarera impur; la chair vive est impure, c''est la lèpre.'),
('lv',13,16,'crampon1923','Si la chair vive change et devient blanche, il ira vers le prêtre.'),
('lv',13,17,'crampon1923','Le prêtre l''examinera, et si la plaie est devenue blanche, le prêtre déclarera pur celui qui a la plaie: il est pur.'),
('lv',13,18,'crampon1923','Lorsqu''un homme aura eu sur son corps, sur sa peau, un ulcère, et que, cet ulcère étant guéri,'),
('lv',13,19,'crampon1923','il y aura, à la place de l''ulcère, une tumeur blanche ou une tache d''un blanc rougeâtre, cet homme se montrera au prêtre.'),
('lv',13,20,'crampon1923','Le prêtre l''examinera. Si la tache paraît plus enfoncée que la peau, et que le poil y soit devenu blanc, le prêtre le déclarera impur: c''est une plaie de lèpre qui a fait éruption dans l''ulcère.'),
('lv',13,21,'crampon1923','Mais si le prêtre voit qu''il n''y a pas de poil blanc dans la tache, que celle-ci n''est pas plus enfoncée que la peau et qu''elle est devenue pâle, il séquestrera cet homme pendant sept jours.'),
('lv',13,22,'crampon1923','Si, durant ce temps, la tache s''est étendue sur la peau, le prêtre le déclarera impur: c''est une plaie de lèpre.'),
('lv',13,23,'crampon1923','Si au contraire la tache est restée à sa place, sans s''étendre, c''est la cicatrice de l''ulcère: le prêtre le déclarera pur.'),
('lv',13,24,'crampon1923','Lorsqu''un homme aura eu sur le corps, sur la peau, une brûlure faite par le feu, s''il se forme sur la trace de la brûlure une tache blanche ou d''un blanc rougeâtre,'),
('lv',13,25,'crampon1923','le prêtre l''examinera. Si le poil est devenu blanc dans la tache et qu''elle paraisse plus profonde que la peau, c''est la lèpre, elle a fait éruption dans la brûlure; le prêtre déclarera cet homme impur; c''est une plaie de lèpre.'),
('lv',13,26,'crampon1923','Mais si le prêtre voit qu''il n''y a pas de poil blanc dans la tache, qu''elle n''est pas plus enfoncée que la peau et qu''elle est devenue pâle, il séquestrera cet homme pendant sept jours.'),
('lv',13,27,'crampon1923','Le prêtre l''examinera le septième jour. Si la tache s''est étendue sur la peau, le prêtre le déclarera impur: c''est une plaie de lèpre.'),
('lv',13,28,'crampon1923','Mais si la tache est restée à la même place, sans s''étendre sur la peau, et qu''elle soit devenue pâle, c''est la tumeur de la brûlure; le prêtre le déclarera pur, car c''est la cicatrice de la brûlure.'),
('lv',13,29,'crampon1923','Lorsqu''un homme ou une femme aura une plaie à la tête ou au menton, le prêtre examinera la plaie.'),
('lv',13,30,'crampon1923','Si elle paraît plus profonde que la peau, et qu''il y ait du poil jaunâtre et grêle, le prêtre déclarera cet homme impur: c''est le nétheq, c''est la lèpre de la tête ou du menton.'),
('lv',13,31,'crampon1923','Si le prêtre voit que la plaie du nétheq ne paraît pas plus profonde que la peau, sans pourtant qu''il y ait poil noir, le prêtre séquestrera pendant sept jours celui qui a la plaie du nétheq.'),
('lv',13,32,'crampon1923','Le septième jour, le prêtre examinera la plaie. Si le nétheq ne s''est pas étendu, qu''il ne s''y trouve aucun poil jaunâtre et que le nétheq ne paraisse pas plus profond que la peau,'),
('lv',13,33,'crampon1923','celui qui a le nétheq se rasera, mais il ne rasera pas l''endroit de la plaie, et le prêtre le séquestrera une deuxième fois pendant sept jours.'),
('lv',13,34,'crampon1923','Le septième jour, le prêtre examinera le nétheq: si le nétheq ne s''est pas étendu sur la peau et qu''il ne paraisse pas plus profond que la peau, le prêtre déclarera cet homme pur: il lavera ses vêtements, et il sera pur.'),
('lv',13,35,'crampon1923','Si, cependant, après qu''il a été déclaré pur, le nétheq s''étend sur la peau,'),
('lv',13,36,'crampon1923','le prêtre l''examinera; et si le nétheq s''est étendu sur la peau, le prêtre n''aura pas à rechercher s''il y a du poil jaunâtre: l''homme est impur.'),
('lv',13,37,'crampon1923','Mais si le nétheq lui paraît n''avoir pas fait de progrès, et qu''il y ait poussé des poils noirs, le nétheq est guéri: l''homme est pur, et le prêtre le déclarera pur.'),
('lv',13,38,'crampon1923','Lorsqu''un homme ou une femme aura sur la peau de sa chair des taches blanches,'),
('lv',13,39,'crampon1923','le prêtre l''examinera. S''il y a sur la peau de sa chair des taches d''un blanc pâle, c''est un exanthème qui a poussé sur la peau: il est pur.'),
('lv',13,40,'crampon1923','Lorsqu''un homme a perdu ses cheveux sur la tête, il est chauve, mais il est pur.'),
('lv',13,41,'crampon1923','Si ses cheveux sont tombés du côté de la face, il a le front chauve, mais il est pur.'),
('lv',13,42,'crampon1923','Mais si, dans la partie chauve de devant ou de derrière, il se trouve une plaie d''un blanc rougeâtre, c''est la lèpre qui a fait éruption dans la partie chauve de derrière ou de devant.'),
('lv',13,43,'crampon1923','Le prêtre l''examinera. Si la plaie est une tumeur d''un blanc rougeâtre dans la partie chauve de derrière ou de devant, ayant l''aspect d''une lèpre de la peau de la chair,'),
('lv',13,44,'crampon1923','c''est un homme lépreux, il est impur: le prêtre le déclarera impur: c''est à la tête qu''est sa plaie de lèpre.'),
('lv',13,45,'crampon1923','Le lépreux, atteint de la plaie, portera ses vêtements déchirés et laissera flotter ses cheveux, il se couvrira la barbe et criera: Impur! impur!'),
('lv',13,46,'crampon1923','Aussi longtemps que durera sa plaie, il sera impur. Il est impur; il habitera seul; sa demeure sera hors du camp.'),
('lv',13,47,'crampon1923','Lorsque, sur un vêtement, il y aura une plaie de lèpre, sur un vêtement de lin ou sur un vêtement de laine,'),
('lv',13,48,'crampon1923','au fil de lin ou de laine destiné à la chaîne ou à la trame, à une peau ou à quelque ouvrage fait de peau,'),
('lv',13,49,'crampon1923','si la plaie est verdâtre ou rougeâtre sur le vêtement, sur la peau, sur le fil destiné à la chaîne ou à la trame, sur tout objet fait de peau, c''est une plaie de lèpre; on la montrera au prêtre.'),
('lv',13,50,'crampon1923','Le prêtre, après avoir considéré la plaie, enfermera pendant sept jours l''objet qui a la plaie.'),
('lv',13,51,'crampon1923','Le septième jour, il examinera la plaie: si la plaie s''est étendue sur le vêtement, sur le fil destiné à la chaîne ou à la trame, sur la peau ou sur un ouvrage quelconque qui est fait de peau, c''est une plaie de lèpre maligne; l''objet est impur.'),
('lv',13,52,'crampon1923','Il brûlera le vêtement, le fil de lin ou de laine destiné à la chaîne ou à la trame, l''objet quelconque de peau sur lequel se trouve la plaie, car c''est une lèpre maligne: l''objet sera brûlé au feu.'),
('lv',13,53,'crampon1923','Mais si le prêtre voit que la plaie ne s''est pas étendue sur le vêtement, sur le fil destiné à la chaîne ou à la trame, sur tout objet fait de peau,'),
('lv',13,54,'crampon1923','il fera laver l''objet qui a la plaie, et il l''enfermera une seconde fois pendant sept jours.'),
('lv',13,55,'crampon1923','Le prêtre examinera la plaie, sept jours après qu''elle aura été lavée. Si elle n''a pas changé d''aspect et ne s''est pas étendue, l''objet est impur: tu le consumeras par le feu; la lèpre en a rongé l''endroit ou l''envers.'),
('lv',13,56,'crampon1923','Mais si le prêtre voit que la plaie, sept jours après avoir été lavée, est devenue pâle, il l''arrachera du vêtement, de la peau, ou du fil destiné à la chaîne ou à la trame.'),
('lv',13,57,'crampon1923','Si elle reparaît ensuite sur le vêtement, sur le fil destiné à la chaîne ou à la trame, ou sur tout objet fait de peau, c''est une éruption de lèpre; tu consumeras par le feu l''objet atteint par la plaie.'),
('lv',13,58,'crampon1923','Mais le vêtement, le fil pour la chaîne ou la trame, tout objet fait de peau que tu auras lavé et d''où la plaie aura disparu, sera lavé une seconde fois et il sera pur.'),
('lv',13,59,'crampon1923','Telle est la loi sur la plaie de la lèpre qui attaque les vêtements de laine ou de lin, le fil pour la chaîne ou pour la trame, tout objet fait de peau, pour déclarer ces choses pures ou impures. "'),
('lv',14,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',14,2,'crampon1923','" Voici quelle sera la loi concernant le lépreux, pour le jour de sa purification. On l''amènera au prêtre,'),
('lv',14,3,'crampon1923','et le prêtre, étant sorti du camp, l''examinera. Si le lépreux est guéri de la plaie de lèpre,'),
('lv',14,4,'crampon1923','le prêtre ordonnera que l''on prenne pour celui qui doit être purifié deux oiseaux vivants et purs, du bois de cèdre, du cramoisi et de l''hysope.'),
('lv',14,5,'crampon1923','Le prêtre fera égorger l''un des oiseaux au-dessus d''un vase de terre, sur de l''eau vive.'),
('lv',14,6,'crampon1923','Puis, ayant pris l''oiseau vivant, le bois de cèdre, le cramoisi et l''hysope, il les trempera, ainsi que l''oiseau vivant, dans le sang de l''oiseau égorgé sur l''eau vive.'),
('lv',14,7,'crampon1923','Il en aspergera sept fois celui qui doit être purifié de la lèpre, il le déclarera pur et lâchera dans les champs l''oiseau vivant.'),
('lv',14,8,'crampon1923','Celui qui se purifie lavera ses vêtements, rasera tout son poil et se baignera dans l''eau; et il sera pur. Ensuite il pourra entrer dans le camp, mais il restera sept jours hors de sa tente.'),
('lv',14,9,'crampon1923','Le septième jour, il rasera tout son poil, ses cheveux, sa barbe, ses sourcils, il rasera tout son poil; il lavera ses vêtements et baignera son corps dans l''eau, et il sera pur.'),
('lv',14,10,'crampon1923','Le huitième jour, il prendra deux agneaux sans défaut et une brebis d''un an sans défaut, trois dixièmes d''épha de fleur de farine pétrie à l''huile, en oblation, et un log d''huile.'),
('lv',14,11,'crampon1923','Le prêtre qui fait la purification présentera l''homme qui se purifie et toutes ces choses devant Yahweh, à l''entrée de la tente de réunion.'),
('lv',14,12,'crampon1923','Le prêtre prendra l''un des agneaux, et l''offrira en sacrifice de réparation, ainsi que le log d''huile; il les balancera en offrande balancée devant Yahweh.'),
('lv',14,13,'crampon1923','Il immolera l''agneau dans le lieu où l''on immole les victimes pour le péché et l''holocauste, savoir, dans le lieu saint; car dans le sacrifice de réparation, comme dans le sacrifice pour le péché, la victime appartient au prêtre: c''est une chose très sainte.'),
('lv',14,14,'crampon1923','Le prêtre, ayant pris du sang du sacrifice de réparation, en mettra sur le lobe de l''oreille droite de celui qui se purifie, sur le pouce de sa main droite et sur le gros orteil de son pied droit.'),
('lv',14,15,'crampon1923','Le prêtre prendra le log d''huile, et il en versera dans le creux de sa main gauche.'),
('lv',14,16,'crampon1923','Le prêtre trempera le doigt de sa main droite dans l''huile qui est dans le creux de sa main gauche, et fera avec le doigt sept fois l''aspersion de l''huile devant Yahweh.'),
('lv',14,17,'crampon1923','Puis, de l''huile qui lui reste dans la main, le prêtre en mettra sur le lobe de l''oreille droite de celui qui se purifie, sur le pouce de sa main droite et sur le gros orteil de son pied droit, par-dessus le sang de la victime de réparation.'),
('lv',14,18,'crampon1923','Ce qui lui reste d''huile dans la main, le prêtre le mettra sur la tête de celui qui se purifie; et le prêtre fera pour lui l''expiation devant Yahweh.'),
('lv',14,19,'crampon1923','Ensuite le prêtre offrira le sacrifice pour le péché, et il fera l''expiation pour celui qui se purifie de sa souillure. Enfin, ayant égorgé l''holocauste,'),
('lv',14,20,'crampon1923','le prêtre offrira sur l''autel l''holocauste avec l''oblation; et il fera l''expiation pour cet homme, et il sera pur.'),
('lv',14,21,'crampon1923','S''il est pauvre et que ses moyens soient limités, il prendra un seul agneau qui sera offert en sacrifice de réparation, en offrande balancée, pour faire l''expiation pour lui. Il prendra un seul dixième d''épha de fleur de farine pétrie à l''huile pour l''oblation, et un log d''huile;'),
('lv',14,22,'crampon1923','ainsi que deux tourterelles ou deux jeunes pigeons, selon ses moyens, l''un pour le sacrifice pour le péché, l''autre pour l''holocauste.'),
('lv',14,23,'crampon1923','Le huitième jour, il les apportera au prêtre pour sa purification, à l''entrée de la tente de réunion, devant Yahweh.'),
('lv',14,24,'crampon1923','Le prêtre prendra l''agneau pour le sacrifice de réparation, et le log d''huile, et les balancera devant Yahweh.'),
('lv',14,25,'crampon1923','Et, après avoir immolé l''agneau du sacrifice de réparation, le prêtre prendra du sang du sacrifice de réparation et en mettra sur le lobe de l''oreille droite de celui qui se purifie, sur le pouce de sa main droite et sur le gros orteil de son pied droit.'),
('lv',14,26,'crampon1923','Le prêtre versera ensuite de l''huile dans le creux de sa main gauche.'),
('lv',14,27,'crampon1923','Le prêtre fera avec le doigt de sa main droite l''aspersion de l''huile qui est dans sa main gauche, sept fois devant Yahweh.'),
('lv',14,28,'crampon1923','Le prêtre mettra de l''huile qui est dans sa main sur le lobe de l''oreille droite de celui qui se purifie, sur le pouce de sa main droite et sur le gros orteil de son pied droit, à la place où il a mis du sang de la victime de réparation.'),
('lv',14,29,'crampon1923','Ce qui lui restera d''huile dans la main, le prêtre le mettra sur la tête de celui qui se purifie, afin de faire pour lui l''expiation devant Yahweh.'),
('lv',14,30,'crampon1923','Puis il offrira l''une des tourterelles ou l''un des jeunes pigeons qu''il aura pu se procurer,'),
('lv',14,31,'crampon1923','l''un en sacrifice pour le péché, l''autre en holocauste, avec oblation; le prêtre fera ainsi, pour celui qui se purifie, l''expiation devant Yahweh.'),
('lv',14,32,'crampon1923','Telle est la loi pour la purification de celui qui a une plaie de lèpre et dont les moyens sont limités. "'),
('lv',14,33,'crampon1923','Yahweh parla à Moïse et à Aaron, en disant:'),
('lv',14,34,'crampon1923','" Lorsque vous serez entrés dans le pays de Chanaan, dont je vous donne la possession, si je mets la plaie de lèpre sur une maison du pays que vous posséderez,'),
('lv',14,35,'crampon1923','le propriétaire de la maison ira le déclarer au prêtre, et dira: J''aperçois comme une plaie de lèpre à ma maison.'),
('lv',14,36,'crampon1923','Le prêtre, avant d''y entrer pour examiner la plaie, fera vider la maison, afin que tout ce qui s''y trouve ne devienne pas impur; après quoi, le prêtre entrera pour examiner la maison.'),
('lv',14,37,'crampon1923','Le prêtre examinera la plaie. Si la plaie qui est aux murs de la maison présente des cavités verdâtres ou rougeâtres, paraissant enfoncées dans le mur,'),
('lv',14,38,'crampon1923','le prêtre sortira de la maison jusqu''à la porte de la maison, et il fera fermer la maison pour sept jours.'),
('lv',14,39,'crampon1923','Le prêtre y retournera le septième jour. S''il voit que la plaie s''est étendue sur les murs de la maison,'),
('lv',14,40,'crampon1923','il ordonnera qu''on enlève les pierres atteintes de la plaie, et qu''on les jette hors de la ville, dans un lieu impur.'),
('lv',14,41,'crampon1923','Il fera racler toute la maison à l''intérieur, et l''on versera hors de la ville, dans un lieu impur, la poussière qu''on aura raclée.'),
('lv',14,42,'crampon1923','On prendra d''autres pierres que l''on mettra à la place des premières, et on prendra d''autre mortier pour recrépir la maison.'),
('lv',14,43,'crampon1923','Si la plaie fait de nouveau éruption dans la maison, après qu''on aura enlevé les pierres, raclé et recrépi la maison,'),
('lv',14,44,'crampon1923','le prêtre y retournera et l''examinera. Si la plaie s''est étendue dans la maison, c''est une lèpre maligne dans la maison: elle est impure.'),
('lv',14,45,'crampon1923','On démolira la maison, les pierres, le bois et tout le mortier de la maison, et l''on transportera ces choses hors de la ville, dans un lieu impur.'),
('lv',14,46,'crampon1923','Celui qui sera entré dans la maison pendant tout le temps qu''elle a été déclarée close, sera impur jusqu''au soir.'),
('lv',14,47,'crampon1923','Celui qui aura couché dans la maison lavera ses vêtements. Celui qui aura mangé dans la maison lavera aussi ses vêtements.'),
('lv',14,48,'crampon1923','Mais si le prêtre, étant retourné dans la maison, voit que la plaie ne s''est pas étendue après que la maison a été recrépie, il déclarera la maison pure, car la plaie est guérie.'),
('lv',14,49,'crampon1923','Il prendra, pour purifier la maison, deux oiseaux, du bois de cèdre, du cramoisi et de l''hysope;'),
('lv',14,50,'crampon1923','puis il immolera l''un des oiseaux sur un vase de terre, sur de l''eau vive.'),
('lv',14,51,'crampon1923','Et ayant pris le bois de cèdre, l''hysope, le cramoisi et l''oiseau vivant, il les trempera dans le sang de l''oiseau immolé et dans l''eau vive, et il en aspergera sept fois la maison.'),
('lv',14,52,'crampon1923','Il purifiera la maison avec le sang de l''oiseau, avec l''eau vive, avec l''oiseau vivant, avec le bois de cèdre, l''hysope et le cramoisi.'),
('lv',14,53,'crampon1923','Et il lâchera l''oiseau vivant hors de la ville, dans les champs. C''est ainsi qu''il fera l''expiation pour la maison, et elle sera pure.'),
('lv',14,54,'crampon1923','Telle est la loi pour toute plaie de lèpre et pour le nétheq,'),
('lv',14,55,'crampon1923','pour la lèpre des vêtements et des maisons,'),
('lv',14,56,'crampon1923','pour les tumeurs, les dartres et les taches;'),
('lv',14,57,'crampon1923','elle fait connaître quand une chose est impure et quand une chose est pure. Telle est la loi concernant la lèpre. "'),
('lv',15,1,'crampon1923','Yahweh parla à Moïse et à Aaron, en disant:'),
('lv',15,2,'crampon1923','" Parlez aux enfants d''Israël, et dites-leur: Tout homme qui a une gonorrhée est impur par là.'),
('lv',15,3,'crampon1923','Et telle est la souillure provenant de son flux: soit que sa chair laisse couler son flux ou que sa chair retienne son flux, il y a souillure.'),
('lv',15,4,'crampon1923','Tout lit sur lequel couchera celui qui a un flux sera impur; tout objet sur lequel il s''assiéra, sera impur.'),
('lv',15,5,'crampon1923','Celui qui touchera son lit lavera ses vêtements, se baignera dans l''eau et sera impur jusqu''au soir.'),
('lv',15,6,'crampon1923','Celui qui s''assiéra sur l''objet où se sera assis l''homme qui a un flux, lavera ses vêtements, se baignera dans l''eau et sera impur jusqu''au soir.'),
('lv',15,7,'crampon1923','Celui qui touchera la chair de celui qui a un flux lavera ses vêtements, se baignera dans l''eau et sera impur jusqu''au soir.'),
('lv',15,8,'crampon1923','Si celui qui a un flux crache sur un homme pur, cet homme lavera ses vêtements, se baignera dans l''eau et sera impur jusqu''au soir.'),
('lv',15,9,'crampon1923','Toute selle sur laquelle sera monté celui qui a un flux sera impure.'),
('lv',15,10,'crampon1923','Celui qui touchera une chose qui a été sous lui sera impur jusqu''au soir, et celui qui la portera lavera ses vêtements, se baignera dans l''eau et sera impur jusqu''au soir.'),
('lv',15,11,'crampon1923','Celui qu''aura touché celui qui a un flux et qui n''aura pas lavé ses mains dans l''eau, lavera ses vêtements, se baignera dans l''eau et sera impur jusqu''au soir.'),
('lv',15,12,'crampon1923','Tout vase de terre qu''aura touché celui qui a un flux sera brisé, et tout vase de bois sera lavé dans l''eau.'),
('lv',15,13,'crampon1923','Lorsque celui qui a un flux sera purifié de son flux, il comptera sept jours pour sa purification; il lavera alors ses vêtements, baignera son corps dans de l''eau vive, et il sera pur.'),
('lv',15,14,'crampon1923','Le huitième jour, ayant pris deux tourterelles ou deux jeunes pigeons, il viendra devant Yahweh, à l''entrée de la tente de réunion, et il les donnera au prêtre.'),
('lv',15,15,'crampon1923','Le prêtre les offrira, l''un en sacrifice pour le péché, l''autre en holocauste, et le prêtre fera pour lui l''expiation devant Yahweh, à cause de son flux.'),
('lv',15,16,'crampon1923','L''homme qui aura un épanchement séminal baignera tout son corps dans l''eau, et sera impur jusqu''au soir.'),
('lv',15,17,'crampon1923','Tout vêtement et toute peau qui seront atteints par l''épanchement séminal seront lavés dans l''eau et seront impurs jusqu''au soir.'),
('lv',15,18,'crampon1923','Si une femme a couché avec un homme et a eu commerce avec lui, elle se baignera dans l''eau ainsi que lui, et ils seront impurs jusqu''au soir.'),
('lv',15,19,'crampon1923','Quand une femme aura un flux, un flux de sang dans sa chair, elle sera sept jours dans son impureté. Quiconque la touchera sera impur jusqu''au soir.'),
('lv',15,20,'crampon1923','Tout meuble sur lequel elle se couchera pendant son impureté sera impur, et tout objet sur lequel elle s''assiéra sera impur.'),
('lv',15,21,'crampon1923','Quiconque touchera son lit lavera ses vêtements, se baignera dans l''eau et sera impur jusqu''au soir.'),
('lv',15,22,'crampon1923','Quiconque touchera un objet sur lequel elle se sera assise, lavera ses vêtements, se baignera dans l''eau et sera impur jusqu''au soir.'),
('lv',15,23,'crampon1923','S''il y a une chose sur le lit ou sur le siège sur lequel elle s''est assise, celui qui la touchera sera impur jusqu''au soir.'),
('lv',15,24,'crampon1923','Si un homme couche avec elle et que l''impureté de cette femme vienne sur lui, il sera impur pendant sept jours, et tout lit sur lequel il couchera sera impur.'),
('lv',15,25,'crampon1923','Quand une femme aura un flux de sang pendant plusieurs jours en dehors du temps accoutumé, ou si son flux se prolonge au-delà du temps de son impureté, elle sera impure tout le temps de ce flux, comme au temps de son impureté menstruelle.'),
('lv',15,26,'crampon1923','Tout lit sur lequel elle couchera tout le temps de ce flux, sera pour elle comme le lit de son impureté menstruelle, et tout objet sur lequel elle s''assiéra, sera impur comme au temps de son impureté menstruelle.'),
('lv',15,27,'crampon1923','Quiconque les touchera sera impur; il lavera ses vêtements, se baignera dans l''eau et sera impur jusqu''au soir.'),
('lv',15,28,'crampon1923','Lorsqu''elle sera purifiée de son flux, elle comptera sept jours, après lesquels elle sera pure.'),
('lv',15,29,'crampon1923','Le huitième jour, elle prendra deux tourterelles ou deux jeunes pigeons, et les apportera au prêtre, à l''entrée de la tente de réunion.'),
('lv',15,30,'crampon1923','Le prêtre les offrira, l''un en sacrifice pour le péché, l''autre en holocauste, et le prêtre fera pour elle l''expiation devant Yahweh, à cause du flux qui la rendait impure.'),
('lv',15,31,'crampon1923','Vous apprendrez aux enfants d''Israël à se purifier de leurs impuretés, de peur qu''ils ne meurent à cause de leur impureté, en souillant ma Demeure qui est au milieu d''eux.'),
('lv',15,32,'crampon1923','Telle est la loi concernant l''homme qui a une gonorrhée ou qui est souillé par un épanchement séminal,'),
('lv',15,33,'crampon1923','et concernant la femme qui a son flux menstruel, et toute personne ayant un flux, soit homme, soit femme, et pour l''homme qui couche avec une femme impure. "'),
('lv',16,1,'crampon1923','Yahweh parla à Moïse, après la mort des deux fils d''Aaron, qui furent frappés lorsqu''ils s''approchèrent de la face de Yahweh.'),
('lv',16,2,'crampon1923','Yahweh dit à Moïse: " Parle à ton frère Aaron, afin qu''il n''entre pas en tout temps dans le sanctuaire, au-dedans du voile, devant le propitiatoire qui est sur l''arche, de peur qu''il ne meure; car j''apparais dans la nuée sur le propitiatoire.'),
('lv',16,3,'crampon1923','Voici le rite suivant lequel Aaron entrera dans le sanctuaire. Il prendra un jeune taureau pour le sacrifice pour le péché et un bélier pour l''holocauste.'),
('lv',16,4,'crampon1923','Il se revêtira de la sainte tunique de lin et mettra sur sa chair des caleçons de lin; il se ceindra d''une ceinture de lin et se couvrira la tête d''une tiare de lin: ce sont les vêtements sacrés qu''il revêtira, après avoir baigné son corps dans l''eau.'),
('lv',16,5,'crampon1923','Il recevra de l''assemblée des enfants d''Israël deux boucs pour le sacrifice pour le péché, et un bélier pour l''holocauste.'),
('lv',16,6,'crampon1923','Aaron offrira son taureau pour le péché, et il fera l''expiation pour lui et pour sa maison.'),
('lv',16,7,'crampon1923','Puis il prendra les deux boucs et, les placera devant Yahweh, à l''entrée de la tente de réunion.'),
('lv',16,8,'crampon1923','Aaron jettera le sort sur les deux boucs, un sort pour Yahweh et un sort pour Azazel.'),
('lv',16,9,'crampon1923','Aaron fera approcher le bouc sur lequel sera tombé le sort pour Yahweh et l''offrira en sacrifice pour le péché.'),
('lv',16,10,'crampon1923','Et le bouc sur lequel sera tombé le sort pour Azazel, il le placera vivant devant Yahweh, afin de faire l''expiation sur lui et de le lâcher dans le désert pour Azazel.'),
('lv',16,11,'crampon1923','Aaron offrira donc le taureau du sacrifice pour le péché qui est pour lui, et il fera l''expiation pour lui et pour sa maison. Après avoir égorgé son taureau pour le péché,'),
('lv',16,12,'crampon1923','il prendra un encensoir plein de charbons ardents de dessus l''autel, de devant Yahweh, et deux poignées de parfum odoriférant en poudre; et ayant porté ces choses au-delà du voile,'),
('lv',16,13,'crampon1923','il mettra le parfum sur le feu devant Yahweh, afin que la nuée du parfum couvre le propitiatoire qui est sur le témoignage, et qu''il ne meure pas.'),
('lv',16,14,'crampon1923','Il prendra du sang du taureau, et en fera aspersion avec son doigt sur la face orientale du propitiatoire, et il fera avec son doigt sept fois aspersion du sang devant le propitiatoire.'),
('lv',16,15,'crampon1923','Il égorgera le bouc du sacrifice pour le péché qui est pour le peuple, et il en portera le sang au delà du voile et, faisant de ce sang comme il a fait du sang du taureau, il en fera l''aspersion une fois sur le propitiatoire et sept fois devant le propitiatoire.'),
('lv',16,16,'crampon1923','C''est ainsi qu''il fera l''expiation pour le sanctuaire à cause des souillures des enfants d''Israël et de toutes leurs transgressions, selon qu''ils ont péché. Il fera de même pour la tente de réunion, qui demeure avec eux au milieu de leurs souillures.'),
('lv',16,17,'crampon1923','Qu''il n''y ait personne dans la tente de réunion lorsqu''il entrera pour faire l''expiation dans le sanctuaire, jusqu''à ce qu''il en sorte. Il fera l''expiation pour lui, pour sa maison et pour toute l''assemblée d''Israël.'),
('lv',16,18,'crampon1923','Il ira en sortant vers l''autel qui est devant Yahweh, et fera l''expiation pour l''autel: ayant pris du sang du taureau et du sang du bouc, il en mettra sur les cornes de l''autel tout autour.'),
('lv',16,19,'crampon1923','Il fera sur l''autel, avec son doigt, sept fois aspersion du sang; il le purifiera et le sanctifiera des souillures des enfants d''Israël.'),
('lv',16,20,'crampon1923','Lorsqu''il aura achevé de faire l''expiation pour le sanctuaire, pour la tente de réunion et pour l''autel, il présentera le bouc vivant.'),
('lv',16,21,'crampon1923','Ayant posé ses deux mains sur la tête du bouc vivant, Aaron confessera sur lui toutes les iniquités des enfants d''Israël et toutes leurs transgressions, selon qu''ils ont péché; il les mettra sur la tête du bouc et il l''enverra ensuite au désert par un homme tout prêt.'),
('lv',16,22,'crampon1923','Le bouc emportera sur lui toutes leurs iniquités dans une terre inhabitée, et l''homme lâchera le bouc dans le désert.'),
('lv',16,23,'crampon1923','Alors Aaron entrera dans la tente de réunion; il quittera les vêtements de lin qu''il avait revêtus pour entrer dans le sanctuaire et, les ayant déposés là,'),
('lv',16,24,'crampon1923','il baignera son corps dans l''eau en un lieu saint et reprendra ses vêtements.'),
('lv',16,25,'crampon1923','Il sortira ensuite, offrira son holocauste et celui du peuple, fera l''expiation pour lui et pour le peuple, et fera fumer sur l''autel la graisse du sacrifice pour le péché.'),
('lv',16,26,'crampon1923','Celui qui aura lâché le bouc pour Azazel lavera ses vêtements et baignera son corps dans l''eau; après quoi, il rentrera dans le camp.'),
('lv',16,27,'crampon1923','On emportera hors du camp le taureau pour le péché et le bouc pour le péché, dont le sang aura été porté dans le sanctuaire pour faire l''expiation, et l''on consumera par le feu leur peau, leur chair et leurs excréments.'),
('lv',16,28,'crampon1923','Celui qui les aura brûlés lavera ses vêtements et baignera son corps dans l''eau; après quoi, il rentrera dans le camp.'),
('lv',16,29,'crampon1923','Ceci sera pour vous une loi perpétuelle: au septième mois, le dixième jour du mois, vous affligerez vos âmes et ne ferez aucun ouvrage, ni l''indigène, ni l''étranger qui séjourne au milieu de vous.'),
('lv',16,30,'crampon1923','Car en ce jour on fera l''expiation pour vous, afin de vous purifier; vous serez purs de tous vos péchés devant Yahweh.'),
('lv',16,31,'crampon1923','Ce sera pour vous un sabbat, un jour de repos, et vous affligerez vos âmes. C''est une loi perpétuelle.'),
('lv',16,32,'crampon1923','L''expiation sera faite, dans l''avenir, par le grand prêtre qui aura reçu l''onction et qui aura été installé pour remplir les fonctions sacerdotales à la place de son père. Il revêtira des vêtements de lin, des vêtements sacrés.'),
('lv',16,33,'crampon1923','Il fera l''expiation pour le sanctuaire de sainteté, il fera l''expiation pour la tente de réunion et pour l''autel des holocaustes; il fera l''expiation pour les prêtres et pour tout le peuple de l''assemblée.'),
('lv',16,34,'crampon1923','Ce sera pour vous une loi perpétuelle: l''expiation se fera une fois chaque année pour les enfants d''Israël, à cause de leurs péchés. " On fit ce que Yahweh avait ordonné à Moïse.'),
('lv',17,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',17,2,'crampon1923','" Parle à Aaron et à ses fils, et à tous les enfants d''Israël, et tu leur diras: Voici ce que Yahweh a ordonné.'),
('lv',17,3,'crampon1923','Tout homme de la maison d''Israël qui, dans le camp ou hors du camp, égorge un bœuf, une brebis ou une chèvre,'),
('lv',17,4,'crampon1923','sans l''amener à l''entrée de la tente de réunion pour le présenter en offrande à Yahweh devant la Demeure de Yahweh, le sang sera imputé à cet homme; il a répandu le sang, cet homme sera retranché du milieu de son peuple.'),
('lv',17,5,'crampon1923','C''est afin que les enfants d''Israël, au lieu d''immoler leurs victimes dans la campagne, les amènent au prêtre devant Yahweh, à l''entrée de la tente de réunion, et qu''ils les offrent à Yahweh en sacrifice pacifique.'),
('lv',17,6,'crampon1923','Le prêtre répandra le sang sur l''autel de Yahweh, à l''entrée de la tente de réunion, et il fera fumer la graisse en odeur agréable à Yahweh.'),
('lv',17,7,'crampon1923','Ils n''offriront plus leurs sacrifices aux satyres, avec lesquels ils se prostituent. Ce sera pour eux une loi perpétuelle de génération en génération.'),
('lv',17,8,'crampon1923','Tu leur diras encore: Tout homme de la maison d''Israël ou d''entre les étrangers séjournant au milieu d''eux qui offrira un holocauste ou un autre sacrifice,'),
('lv',17,9,'crampon1923','et n''amènera pas la victime à l''entrée de la tente de réunion pour l''offrir en sacrifice à Yahweh, cet homme sera retranché du milieu de son peuple.'),
('lv',17,10,'crampon1923','Tout homme de la maison d''Israël ou d''entre les étrangers séjournant au milieu d''eux qui mangera le sang d''un animal quelconque, je tournerai ma face contre celui qui mange le sang, et je le retrancherai du milieu de son peuple;'),
('lv',17,11,'crampon1923','car l''âme de la chair est dans le sang, et je vous l''ai donné en vue de l''autel pour qu''il servit d''expiation pour vos âmes; car c''est par l''âme que le sang fait expiation.'),
('lv',17,12,'crampon1923','C''est pourquoi j''ai dit aux enfants d''Israël: Personne d''entre vous ne mangera du sang, et l''étranger qui séjourne au milieu de vous ne mangera pas du sang.'),
('lv',17,13,'crampon1923','Tout homme d''entre les enfants d''Israël ou d''entre les étrangers séjournant au milieu d''eux qui prend à la chasse un animal ou un oiseau qui se mange, il en versera le sang et le couvrira de terre;'),
('lv',17,14,'crampon1923','car l''âme de toute chair, c''est son sang il en est son âme. C''est pourquoi j''ai dit aux enfants d''Israël: Vous ne mangerez le sang d''aucune chair; car l''âme de toute chair, c''est son sang: quiconque en mangera sera retranché.'),
('lv',17,15,'crampon1923','Toute personne, née dans le pays ou étrangère, qui mangera d''une bête morte ou déchirée, lavera ses vêtements, se baignera dans l''eau, et sera impure jusqu''au soir; puis elle sera pure.'),
('lv',17,16,'crampon1923','Si elle ne lave pas ses vêtements et son corps, elle portera son iniquité. "'),
('lv',18,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',18,2,'crampon1923','" Parle aux enfants d''Israël, et dis-leur: Je suis Yahweh, votre Dieu.'),
('lv',18,3,'crampon1923','Vous ne ferez point ce qui se fait dans le pays d''Egypte où vous avez habité, et vous ne ferez point ce qui se fait dans le pays de Chanaan où je vous conduis: vous ne suivrez pas leurs lois.'),
('lv',18,4,'crampon1923','Vous pratiquerez mes ordonnances et vous observerez mes lois: vous les suivrez. Je suis Yahweh votre Dieu.'),
('lv',18,5,'crampon1923','Vous observerez mes Lois et mes ordonnances; l''homme qui les mettra en pratique vivra par elles. Je suis Yahweh.'),
('lv',18,6,'crampon1923','Aucun de vous ne s''approchera d''une femme qui est sa proche parente, pour découvrir sa nudité: je suis Yahweh.'),
('lv',18,7,'crampon1923','Tu ne découvriras pas la nudité de ton père et la nudité de ta mère. C''est ta mère, tu ne découvriras pas sa nudité.'),
('lv',18,8,'crampon1923','Tu ne découvriras pas la nudité de la femme de ton père: c''est la nudité de ton père.'),
('lv',18,9,'crampon1923','Tu ne découvriras pas la nudité de ta sœur, fille de ton père ou fille de ta mère, née dans la maison ou née hors de la maison; tu ne découvriras pas leur nudité.'),
('lv',18,10,'crampon1923','Tu ne découvriras pas la nudité de la fille de ton fils ou de la fille de ta fille: car c''est ta nudité.'),
('lv',18,11,'crampon1923','Tu ne découvriras pas la nudité de la fille de la femme de ton père, née de ton père: c''est ta sœur.'),
('lv',18,12,'crampon1923','Tu ne découvriras pas la nudité de la sœur de ton père: c''est la chair de ton père.'),
('lv',18,13,'crampon1923','Tu ne découvriras pas la nudité de la sœur de ta mère: c''est la chair de ta mère.'),
('lv',18,14,'crampon1923','Tu ne découvriras pas la nudité du frère de ton père, en t''approchant de sa femme: c''est ta tante.'),
('lv',18,15,'crampon1923','Tu ne découvriras pas la nudité de ta belle-fille: c''est la femme de ton fils, tu ne découvriras pas sa nudité.'),
('lv',18,16,'crampon1923','Tu ne découvriras pas la nudité de la femme de ton frère: c''est la nudité de ton frère.'),
('lv',18,17,'crampon1923','Tu ne découvriras pas la nudité d''une femme et de sa fille: tu ne prendras pas la fille de son fils ni la fille de sa fille, pour découvrir leur nudité: elles sont proches parentes, c''est un crime.'),
('lv',18,18,'crampon1923','Tu ne prendras pas la sœur de ta femme, pour en faire une rivale, en découvrant sa nudité avec celle de ta femme, de son vivant.'),
('lv',18,19,'crampon1923','Tu ne t''approcheras pas d''une femme pendant son impureté menstruelle, pour découvrir sa nudité.'),
('lv',18,20,'crampon1923','Tu n''auras pas commerce avec la femme de ton prochain, pour te souiller avec elle.'),
('lv',18,21,'crampon1923','Tu ne donneras aucun de tes enfants pour le faire passer par le feu en l''honneur de Moloch, et tu ne profaneras pas le nom de ton Dieu. Je suis Yahweh.'),
('lv',18,22,'crampon1923','Tu ne coucheras pas avec un homme comme on fait avec une femme: c''est une abomination.'),
('lv',18,23,'crampon1923','Tu ne coucheras pas avec une bête, pour te souiller avec elle. La femme ne se tiendra pas devant une bête pour se prostituer à elle: c''est une honte.'),
('lv',18,24,'crampon1923','Ne vous souillez par aucune de ces choses, car c''est par elles que se sont souillées les nations que je vais chasser devant vous.'),
('lv',18,25,'crampon1923','Le pays a été souillé; je punirai ses iniquités, et le pays vomira ses habitants.'),
('lv',18,26,'crampon1923','Mais vous, vous observerez mes lois et mes ordonnances, et vous ne commettrez aucune de ces abominations, ni l''indigène, ni l''étranger qui séjourne au milieu de vous.'),
('lv',18,27,'crampon1923','Car toutes ces abominations, les hommes du pays, qui y ont été avant vous, les ont commises, et le pays en a été souillé.'),
('lv',18,28,'crampon1923','Et le pays ne vous vomira pas pour l''avoir souillé, comme il a vomi les nations qui y étaient avant vous.'),
('lv',18,29,'crampon1923','Car tous ceux qui commettront quelqu''une de ces abominations seront retranchés du milieu de leur peuple.'),
('lv',18,30,'crampon1923','Vous observerez mes commandements, afin de ne pratiquer aucun des usages abominables qui se pratiquaient avant vous, et vous ne vous souillerez point par eux. Je suis Yahweh, votre Dieu. "'),
('lv',19,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',19,2,'crampon1923','" Parle à toute l''assemblée d''Israël, et dis-leur: Soyez saints, car je suis saint, moi Yahweh, votre Dieu.'),
('lv',19,3,'crampon1923','Que chacun de vous craigne sa mère et son père, et observe mes sabbats. Je suis Yahweh, votre Dieu.'),
('lv',19,4,'crampon1923','Ne vous tournez point vers les idoles, et ne vous faites point de dieux de fonte. Je suis Yahweh, votre Dieu.'),
('lv',19,5,'crampon1923','Quand vous offrirez à Yahweh un sacrifice pacifique, vous l''offrirez de manière à vous concilier sa faveur.'),
('lv',19,6,'crampon1923','La victime sera mangée le jour où vous l''immolerez, ou le lendemain; ce qui restera jusqu''au troisième jour sera consumé par le feu.'),
('lv',19,7,'crampon1923','Si quelqu''un en mange le troisième jour, c''est une abomination: le sacrifice ne sera point agréé.'),
('lv',19,8,'crampon1923','Celui qui en mangera portera son iniquité, car il profane ce qui est consacré à Yahweh: cet homme sera retranché de son peuple.'),
('lv',19,9,'crampon1923','Quand vous ferez la moisson de votre pays, tu ne moissonneras pas jusqu''à la limite extrême de ton champ, et tu ne ramasseras pas ce qu''il y a à glaner de ta moisson.'),
('lv',19,10,'crampon1923','Tu ne cueilleras pas non plus les grappes restées dans ta vigne, et tu ne ramasseras pas les fruits tombés dans ton verger; tu laisseras cela au pauvre et à l''étranger. Je suis Yahweh, votre Dieu.'),
('lv',19,11,'crampon1923','Vous ne déroberez point, et vous n''userez ni de tromperie ni de mensonge les uns envers les autres.'),
('lv',19,12,'crampon1923','Vous ne jurerez point par mon nom, en mentant, car tu profanerais le nom de ton Dieu. Je suis Yahweh.'),
('lv',19,13,'crampon1923','Tu n''opprimeras point ton prochain, et tu ne le dépouilleras pas. Le salaire du mercenaire ne restera pas chez toi jusqu''au lendemain.'),
('lv',19,14,'crampon1923','Tu ne proféreras point de malédiction contre un sourd, et tu ne mettras pas devant un aveugle quelque chose qui puisse le faire tomber; car tu auras la crainte de ton Dieu. Je suis Yahweh.'),
('lv',19,15,'crampon1923','Vous ne commettrez pas d''injustice dans le jugement: tu n''auras pas de faveur pour le pauvre, et tu n''auras pas de complaisance pour le puissant; mais tu jugeras ton prochain selon la justice.'),
('lv',19,16,'crampon1923','Tu n''iras pas semant la diffamation parmi ton peuple. Tu ne te tiendras pas comme témoin contre le sang de ton prochain. Je suis Yahweh.'),
('lv',19,17,'crampon1923','Tu ne haïras point ton frère dans ton cœur, mais tu reprendras ton prochain, afin de ne pas te charger d''un péché à cause de lui.'),
('lv',19,18,'crampon1923','Tu ne te vengeras point, et tu ne garderas point de rancune contre les enfants de ton peuple. Tu aimeras ton prochain comme toi-même. Je suis Yahweh.'),
('lv',19,19,'crampon1923','Vous observerez mes lois. Tu n''accoupleras point des bestiaux de deux espèces différentes; tu n''ensemenceras pas ton champ de deux espèces de semences; et tu ne porteras point un vêtement tissu de deux espèces de fils.'),
('lv',19,20,'crampon1923','Si un homme couche et a commerce avec une femme qui soit une esclave fiancée à un autre homme et qui n''a pas été rachetée ou affranchie, ils seront châtiés tous deux, mais non punis de mort, parce que l''esclave n''était pas affranchie.'),
('lv',19,21,'crampon1923','Pour sa faute, l''homme amènera à Yahweh, à l''entrée de la tente de réunion, un bélier en sacrifice de réparation.'),
('lv',19,22,'crampon1923','Le prêtre fera pour lui l''expiation devant Yahweh avec le bélier du sacrifice de réparation, pour le péché qu''il a commis, et le péché qu''il a commis lui sera pardonné.'),
('lv',19,23,'crampon1923','Quand vous serez entrés dans le pays et que vous aurez planté toutes sortes d''arbres fruitiers, vous en regarderez les fruits comme incirconcis: pendant trois ans, ils seront incirconcis pour vous: on n''en mangera point.'),
('lv',19,24,'crampon1923','La quatrième année, tous leurs fruits seront consacrés en louange à Yahweh.'),
('lv',19,25,'crampon1923','La cinquième année, vous en mangerez les fruits, et ainsi l''arbre vous continuera son rapport. Je suis Yahweh, votre Dieu.'),
('lv',19,26,'crampon1923','Vous ne mangerez rien avec du sang. Vous ne pratiquerez ni la divination ni la magie.'),
('lv',19,27,'crampon1923','Vous ne tondrez point en rond les coins de votre chevelure, et tu ne raseras point les coins de ta barbe.'),
('lv',19,28,'crampon1923','Vous ne ferez point d''incisions dans votre chair pour un mort, et vous n''imprimerez point de figures sur vous. Je suis Yahweh.'),
('lv',19,29,'crampon1923','Ne profane pas ta fille en la prostituant, de peur que le pays ne se livre à la prostitution et ne se remplisse de crimes.'),
('lv',19,30,'crampon1923','Vous observerez mes sabbats et vous révérerez mon sanctuaire. Je suis Yahweh.'),
('lv',19,31,'crampon1923','Ne vous adressez point à ceux qui évoquent les esprits, ni aux devins; ne les consultez point, pour ne pas être souillés par eux. Je suis Yahweh, votre Dieu.'),
('lv',19,32,'crampon1923','Tu te lèveras devant une tête blanchie, et tu honoreras la personne du vieillard. Tu craindras ton Dieu. Je suis Yahweh.'),
('lv',19,33,'crampon1923','Si un étranger vient séjourner avec vous dans votre pays, vous ne l''opprimerez point.'),
('lv',19,34,'crampon1923','Vous traiterez l''étranger en séjour parmi vous comme un indigène du milieu de vous; tu l''aimeras comme toi-même, car vous avez été étrangers dans le pays d''Egypte. Je suis Yahweh, votre Dieu.'),
('lv',19,35,'crampon1923','Vous ne commettrez point d''injustice, soit dans les jugements, soit dans les mesures de longueur, soit dans les poids, soit dans les mesures de capacité.'),
('lv',19,36,'crampon1923','Vous aurez des balances justes, des poids justes, un épha juste et un hin juste. Je suis Yahweh, votre Dieu, qui vous ai fait sortir du pays d''Egypte.'),
('lv',19,37,'crampon1923','Vous observerez toutes mes lois et toutes mes ordonnances, et vous les mettrez en pratique. Je suis Yahweh. "'),
('lv',20,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',20,2,'crampon1923','" Tu diras aux enfants d''Israël: Quiconque d''entre les enfants d''Israël ou d''entre les étrangers qui séjournent en Israël donne à Moloch l''un de ses enfants, sera puni de mort: le peuple du pays le lapidera.'),
('lv',20,3,'crampon1923','Et moi, je tournerai ma face contre cet homme, et je le retrancherai du milieu de son peuple, parce qu''il aura livré un de ses enfants à Moloch, pour souiller mon sanctuaire et profaner mon saint nom.'),
('lv',20,4,'crampon1923','Si le peuple du pays ferme les yeux sur cet homme quand il donnera de ses enfants à Moloch, et ne le fait pas mourir,'),
('lv',20,5,'crampon1923','moi, je tournerai ma face contre cet homme et contre sa famille, et je le retrancherai du milieu de son peuple, avec tous ceux qui se prostituent comme lui en se prostituant à Moloch.'),
('lv',20,6,'crampon1923','Si quelqu''un s''adresse à ceux qui évoquent les esprits et aux devins, pour se prostituer après eux, je tournerai ma face contre cet homme et je le retrancherai du milieu de son peuple.'),
('lv',20,7,'crampon1923','Vous vous sanctifierez et vous serez saints, car je suis Yahweh, votre Dieu.'),
('lv',20,8,'crampon1923','Vous observerez mes lois et vous les mettrez en pratique. Je suis Yahweh, qui vous sanctifie.'),
('lv',20,9,'crampon1923','Quiconque maudit son père ou sa mère sera puni de mort; il a maudit son père ou sa mère: son sang est sur lui.'),
('lv',20,10,'crampon1923','Si un homme commet adultère avec une femme mariée, et s''il commet adultère avec la femme de son prochain, ils seront tous deux punis de mort, l''homme et la femme adultères.'),
('lv',20,11,'crampon1923','Si un homme couche avec la femme de son père, et découvre ainsi la nudité de son père, ils seront tous deux punis de mort: leur sang est sur eux.'),
('lv',20,12,'crampon1923','Si un homme couche avec sa belle-fille, ils seront tous deux punis de mort; ils ont fait une chose honteuse: leur sang est sur eux.'),
('lv',20,13,'crampon1923','Si un homme couche avec un homme comme on fait avec une femme, ils ont fait tous deux une chose abominable, ils seront punis de mort: leur sang est sur eux.'),
('lv',20,14,'crampon1923','Si un homme prend pour femmes la fille et la mère, c''est un crime; on les livrera au feu, lui et elles, afin que ce crime n''existe pas parmi vous.'),
('lv',20,15,'crampon1923','L''homme qui aura commerce avec une bête sera puni de mort, et vous tuerez la bête.'),
('lv',20,16,'crampon1923','Si une femme s''approche d''une bête pour se prostituer à elle, tu tueras la femme et la bête; elles seront mises à mort: leur sang est sur elles.'),
('lv',20,17,'crampon1923','Si un homme prend sa sœur, fille de son père ou fille de sa mère, s''il voit sa nudité et qu''elle voie la sienne, c''est une infamie; ils seront retranchés sous les yeux des enfants de leur peuple. Il a découvert la nudité de sa sœur, il portera son iniquité.'),
('lv',20,18,'crampon1923','Si un homme couche avec une femme qui a son indisposition menstruelle, et découvre sa nudité, il a découvert son flux, et elle a découvert le flux de son sang; ils seront retranchés tous deux du milieu de leur peuple.'),
('lv',20,19,'crampon1923','Tu ne découvriras point la nudité de la sœur de ta mère, ni de la sœur de ton père, car c''est découvrir sa propre chair: ils porteront leur iniquité.'),
('lv',20,20,'crampon1923','Si un homme couche avec sa tante, il découvre la nudité de son oncle; ils porteront leur péché: ils mourront sans enfants.'),
('lv',20,21,'crampon1923','Si un homme prend la femme de son frère, c''est une impureté; il a découvert la nudité de son frère: ils seront sans enfants.'),
('lv',20,22,'crampon1923','Vous observerez toutes mes lois et toutes mes ordonnances et vous les mettrez en pratique, afin que le pays où je vous mène pour y habiter ne vous vomisse pas.'),
('lv',20,23,'crampon1923','Vous ne suivrez pas les usages des nations que je vais chasser de devant vous; car elles ont fait toutes ces choses, et je les ai en dégoût.'),
('lv',20,24,'crampon1923','Je vous ai dit: C''est vous qui posséderez leur terre; je vous la donnerai pour la posséder; c''est un pays où coulent le lait et le miel. Je suis Yahweh, votre Dieu, qui vous ai séparés des autres peuples.'),
('lv',20,25,'crampon1923','Vous distinguerez entre les animaux purs et impurs, entre les oiseaux purs et impurs, et vous ne vous rendrez pas abominables par des animaux, par des oiseaux et par tout ce qui se meut sur la terre, que je vous ai appris à distinguer comme impurs.'),
('lv',20,26,'crampon1923','Vous serez saints pour moi, car je suis saint, moi Yahweh, et je vous ai séparés des autres peuples, afin que vous soyez à moi.'),
('lv',20,27,'crampon1923','Tout homme ou femme qui évoque les esprits ou s''adonne à la divination sera mis à mort; on les lapidera: leur sang est sur eux. "'),
('lv',21,1,'crampon1923','Yahweh dit à Moïse: Parle aux prêtres, fils d''Aaron, et dis-leur: Nul ne se rendra impur au milieu de son peuple pour un mort,'),
('lv',21,2,'crampon1923','excepté pour son parent du même rang, pour sa mère, pour son père, pour son fils, pour sa fille, pour son frère,'),
('lv',21,3,'crampon1923','et pour sa sœur vierge, qui vit auprès de lui, n''étant pas encore mariée; pour elle il se rendra impur.'),
('lv',21,4,'crampon1923','Chef de maison parmi son peuple, il ne se souillera pas et ne profanera pas sa dignité.'),
('lv',21,5,'crampon1923','Les prêtres ne se raseront pas la tête, ils n''enlèveront pas les côtés de leur barbe, et ils ne feront pas d''incisions dans leur chair.'),
('lv',21,6,'crampon1923','Ils seront saints pour leur Dieu, et ils ne profaneront pas le nom de leur Dieu, car ils offrent à Yahweh des sacrifices consumés par le feu, le pain de leur Dieu: ils seront saints.'),
('lv',21,7,'crampon1923','Ils ne prendront point une femme prostituée ou déshonorée; ils ne prendront point une femme répudiée par son mari, car le prêtre est saint pour son Dieu.'),
('lv',21,8,'crampon1923','Tu le tiendras pour saint, car il offre le pain de ton Dieu; il sera saint pour toi, car je suis saint, moi Yahweh, qui vous sanctifie.'),
('lv',21,9,'crampon1923','Si la fille d''un prêtre se déshonore en se prostituant, elle déshonore son père: elle sera brûlée au feu.'),
('lv',21,10,'crampon1923','Le grand prêtre qui est au-dessus de ses frères, sur la tête duquel a été répandue l''huile d''onction, et qui a été installé pour revêtir les vêtements sacrés, ne découvrira pas sa tête et ne déchirera pas ses vêtements.'),
('lv',21,11,'crampon1923','Il n''approchera d''aucun mort; il ne se rendra impur ni pour son père, ni pour sa mère.'),
('lv',21,12,'crampon1923','Il ne sortira pas du sanctuaire, et ne profanera pas le sanctuaire de son Dieu, car l''huile d''onction de son Dieu est un diadème sur lui. Je suis Yahweh.'),
('lv',21,13,'crampon1923','Il prendra pour femme une vierge.'),
('lv',21,14,'crampon1923','Il ne prendra ni une veuve, ni une femme répudiée, ni une femme déshonorée ou prostituée; mais il prendra pour femme une vierge du milieu de son peuple.'),
('lv',21,15,'crampon1923','Il ne déshonorera pas sa postérité au milieu de son peuple; car je suis Yahweh, qui le sanctifie. "'),
('lv',21,16,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',21,17,'crampon1923','" Parle à Aaron, et dis-lui: Nul homme de ta race, dans toutes les générations, qui aura une difformité corporelle, n''approchera pour offrir le pain de ton Dieu.'),
('lv',21,18,'crampon1923','Car nul homme qui a une difformité corporelle n''approchera: un homme aveugle ou boiteux, ou qui aura une mutilation ou une excroissance;'),
('lv',21,19,'crampon1923','ou un homme qui aura une fracture au pied ou à la main;'),
('lv',21,20,'crampon1923','qui sera bossu ou nain, ou qui aura une tache à l''œil, la gale, une dartre ou les testicules écrasés.'),
('lv',21,21,'crampon1923','Nul homme de la race du prêtre Aaron qui aura une difformité corporelle, ne s''approchera pour offrir à Yahweh les sacrifices faits par le feu; il a une difformité corporelle: qu''il ne s''approche point pour offrir le pain de son Dieu.'),
('lv',21,22,'crampon1923','Il pourra manger le pain de son Dieu, des choses très saintes et des choses saintes.'),
('lv',21,23,'crampon1923','Mais il n''ira point vers le voile et ne s''approchera point de l''autel, car il a une difformité corporelle; il ne profanera point mes sanctuaires, car je suis Yahweh; qui les sanctifie. "'),
('lv',21,24,'crampon1923','Ainsi parla Moïse à Aaron et à ses fils, et à tous les enfants d''Israël.'),
('lv',22,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',22,2,'crampon1923','" Parle à Aaron et à ses fils, afin qu''ils s''abstiennent des choses saintes que me consacrent les enfants d''Israël, et qu''ils ne profanent pas mon saint nom. Je suis Yahweh.'),
('lv',22,3,'crampon1923','Dis-leur: Tout homme de votre race qui, dans toutes vos générations, ayant sur lui quelque impureté, s''approchera des choses saintes que les enfants d''Israël consacrent à Yahweh, sera retranché de devant moi. Je suis Yahweh.'),
('lv',22,4,'crampon1923','Tout homme de la race d''Aaron qui aura la lèpre ou une gonorrhée, ne mangera pas des choses saintes, jusqu''à ce qu''il soit pur. Il en sera de même de celui qui aura touché une personne souillée par le contact d''un cadavre, de celui qui aura eu un épanchement séminal,'),
('lv',22,5,'crampon1923','de celui qui aura touché soit un animal rampant qui l''ait rendu impur, soit un homme impur qui lui ait communiqué sa souillure quelle qu''elle soit.'),
('lv',22,6,'crampon1923','Celui qui touchera ces choses sera impur jusqu''au soir et il ne mangera pas des choses saintes; mais il baignera son corps dans l''eau'),
('lv',22,7,'crampon1923','et, après le coucher du soleil, il sera pur; il pourra manger alors des choses saintes, car c''est sa nourriture.'),
('lv',22,8,'crampon1923','Il ne mangera pas d''une bête morte ou déchirée, de manière à être souillé par elle; je suis Yahweh.'),
('lv',22,9,'crampon1923','Ils observeront mes commandements, de peur qu''ils ne se chargent d''un péché à ce sujet, et qu''ils ne meurent pour avoir profané les choses saintes. Je suis Yahweh, qui les sanctifie.'),
('lv',22,10,'crampon1923','Aucun étranger ne mangera des choses saintes; celui qui demeure chez un prêtre et le mercenaire ne mangeront point des choses saintes.'),
('lv',22,11,'crampon1923','Mais un esclave acquis par le prêtre à prix d''argent pourra en manger; il en est de même de celui qui est né dans sa maison: ils mangeront de sa nourriture.'),
('lv',22,12,'crampon1923','La fille d''un prêtre, mariée à un étranger, ne mangera pas de ce qui a été prélevé sur les choses saintes.'),
('lv',22,13,'crampon1923','Mais si la fille d''un prêtre, devenue veuve ou répudiée, sans avoir d''enfants, retourne dans la maison de son père, comme elle y était dans sa jeunesse, elle pourra manger de la nourriture de son père; mais aucun étranger n''en mangera.'),
('lv',22,14,'crampon1923','Si un homme mange par erreur d''une chose sainte, il restituera au prêtre la valeur de la chose sainte, en y ajoutant un cinquième.'),
('lv',22,15,'crampon1923','Les prêtres ne profaneront point les choses saintes des enfants d''Israël, ce qu''ils ont prélevé pour Yahweh,'),
('lv',22,16,'crampon1923','et ne leur feront pas porter le poids de la faute qu''ils commettraient en mangeant leurs choses saintes; car je suis Yahweh, qui les sanctifie. "'),
('lv',22,17,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',22,18,'crampon1923','" Parle à Aaron et à ses fils, ainsi qu''à tous les enfants d''Israël; et dis-leur: Qui que ce soit de la maison d''Israël ou des étrangers en Israël qui présente son offrande, soit pour l''accomplissement d''un vœu, soit comme don volontaire, s''il l''offre à Yahweh en holocauste,'),
('lv',22,19,'crampon1923','pour que vous soyez agréés, que la victime soit un mâle sans défaut, d''entre les bœufs, les brebis ou les chèvres.'),
('lv',22,20,'crampon1923','Vous n''en offrirez aucune qui ait un défaut, car elle ne serait pas agréée.'),
('lv',22,21,'crampon1923','Quand un homme offre à Yahweh du gros ou du menu bétail en sacrifice pacifique, soit pour s''acquitter d''un vœu, soit comme offrande volontaire, la victime, pour être agréée, devra être parfaite; il n''y aura en elle aucun défaut.'),
('lv',22,22,'crampon1923','Un animal aveugle, estropié ou mutilé, ayant un ulcère, la gale ou une dartre, vous ne l''offrirez pas à Yahweh; vous n''en ferez point sur l''autel un sacrifice par le feu à Yahweh.'),
('lv',22,23,'crampon1923','Tu pourras immoler comme offrande volontaire un bœuf ou une brebis ayant un membre trop long ou trop court; mais, pour l''accomplissement d''un vœu, cette victime ne serait pas agréée.'),
('lv',22,24,'crampon1923','Vous n''offrirez point à Yahweh un animal qui ait les testicules froissés, écrasés, arrachés ou coupés; vous ne ferez pas cela dans votre pays.'),
('lv',22,25,'crampon1923','Même de la main d''un étranger, vous n''accepterez aucune de ces victimes pour l''offrir comme aliment de votre Dieu; car elles sont corrompues, il y a en elles un défaut: elles ne seraient pas agréées pour vous. "'),
('lv',22,26,'crampon1923','Yahweh dit à Moïse:'),
('lv',22,27,'crampon1923','" Un bœuf, un agneau ou une chèvre, quand il naîtra, restera sept jours sous sa mère; à partir du huitième jour et les jours suivants, il sera agréé pour être offert en sacrifice fait par le feu à Yahweh.'),
('lv',22,28,'crampon1923','Bœuf ou agneau, vous n''immolerez pas l''animal et son petit le même jour.'),
('lv',22,29,'crampon1923','Quand vous offrirez à Yahweh un sacrifice d''actions de grâces, vous l''offrirez de manière qu''il soit agréé;'),
('lv',22,30,'crampon1923','pour cela, la victime sera mangée le même jour; vous n''en laisserez rien jusqu''au matin. Je suis Yahweh.'),
('lv',22,31,'crampon1923','Vous observerez mes commandements et les mettrez en pratique: je suis Yahweh.'),
('lv',22,32,'crampon1923','Vous ne profanerez pas mon saint nom, et je serai sanctifié au milieu des enfants d''Israël. Je suis Yahweh, qui vous sanctifie,'),
('lv',22,33,'crampon1923','celui qui vous a fait sortir du pays d''Egypte, pour être votre Dieu. Je suis Yahweh. "'),
('lv',23,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',23,2,'crampon1923','" Parle aux enfants d''Israël, et dis-leur: Voici les solennités de Yahweh que vous publierez pour être de saintes assemblées; ce sont mes solennités.'),
('lv',23,3,'crampon1923','On travaillera durant six jours; mais le septième jour est un sabbat, un repos complet: il y aura une sainte assemblée. Vous ne ferez aucun ouvrage. C''est un repos consacré à Yahweh, dans tous les lieux que vous habiterez.'),
('lv',23,4,'crampon1923','Voici les fêtes de Yahweh, les saintes assemblées que vous publierez en leur temps.'),
('lv',23,5,'crampon1923','Au premier mois, le quatorzième jour du mois, entre les deux soirs, c''est la Pâque de Yahweh.'),
('lv',23,6,'crampon1923','Et le quinzième jour de ce mois, c''est la fête des pains sans levain en l''honneur de Yahweh: pendant sept jours, vous mangerez des pains sans levain.'),
('lv',23,7,'crampon1923','Le premier jour vous aurez une sainte assemblée: vous ne ferez aucune œuvre servile.'),
('lv',23,8,'crampon1923','Vous offrirez à Yahweh, pendant sept jours, des sacrifices faits par le feu. Le septième jour, il y aura une sainte assemblée: vous ne ferez aucune œuvre servile. "'),
('lv',23,9,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',23,10,'crampon1923','" Parle aux enfants d''Israël, et dis-leur: Quand vous serez entrés dans le pays que je vous donne, et que vous y ferez la moisson, vous apporterez au prêtre une gerbe, prémices de votre moisson.'),
('lv',23,11,'crampon1923','Il balancera cette gerbe devant Yahweh, pour qu''il vous soit favorable; le prêtre la balancera le lendemain du sabbat.'),
('lv',23,12,'crampon1923','Le jour où vous balancerez la gerbe, vous sacrifierez en holocauste à Yahweh un agneau d''un an, sans défaut;'),
('lv',23,13,'crampon1923','l''oblation qui l''accompagnera sera de deux dixièmes de fleur de farine pétrie à l''huile, comme offrande faite par le feu, d''une agréable odeur à Yahweh; la libation sera de vin, le quart d''un hin.'),
('lv',23,14,'crampon1923','Vous ne mangerez ni pain, ni épis grillés, ni épis frais, jusqu''à ce jour même, jusqu''à ce que vous apportiez l''offrande de votre Dieu. C''est une loi perpétuelle pour vos descendants, dans tous les lieux que vous habiterez.'),
('lv',23,15,'crampon1923','A partir du lendemain du sabbat, du jour où vous aurez apporté la gerbe pour être balancée, vous compterez sept semaines entières.'),
('lv',23,16,'crampon1923','Vous compterez cinquante jours jusqu''au lendemain du septième sabbat, et vous offrirez à Yahweh une oblation nouvelle.'),
('lv',23,17,'crampon1923','Vous apporterez de vos demeures deux pains pour offrande balancée; ils seront faits avec deux dixièmes d''épha de fleur de farine, et cuits avec du levain: ce sont les prémices de Yahweh.'),
('lv',23,18,'crampon1923','Avec ces pains, vous offrirez en holocauste à Yahweh sept agneaux d''un an, sans défaut, un jeune taureau et deux béliers, en y joignant l''oblation et la libation ordinaires: ce sera un sacrifice fait par le feu, d''une agréable odeur à Yahweh.'),
('lv',23,19,'crampon1923','Vous immolerez aussi un bouc en sacrifice pour le péché, et deux agneaux d''un an en sacrifice pacifique.'),
('lv',23,20,'crampon1923','Le prêtre balancera les victimes avec les pains des prémices en offrande balancée devant Yahweh, avec les deux agneaux; ils seront consacrés à Yahweh et appartiendront au prêtre.'),
('lv',23,21,'crampon1923','Ce jour-là même, vous publierez la fête, et vous aurez une sainte assemblée: vous ne ferez aucune œuvre servile. C''est une loi perpétuelle pour vos descendants, dans tous les lieux où vous habiterez.'),
('lv',23,22,'crampon1923','Quand vous ferez la moisson dans votre pays, tu ne moissonneras pas jusqu''à la limite extrême de ton champ, et tu ne ramasseras pas de ta moisson ce qui reste à glaner; tu laisseras cela pour le pauvre et pour l''étranger. Je suis Yahweh, votre Dieu. "'),
('lv',23,23,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',23,24,'crampon1923','" Parle aux enfants d''Israël et dis-leur: Au septième mois, le premier jour du mois, vous aurez un repos solennel, un rappel à son de cor, une sainte assemblée.'),
('lv',23,25,'crampon1923','Vous ne ferez aucune œuvre servile, et vous offrirez à Yahweh des sacrifices faits par le feu. "'),
('lv',23,26,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',23,27,'crampon1923','" Le dixième jour de ce septième mois est le jour des Expiations: vous aurez une sainte assemblée, vous affligerez vos âmes, et vous offrirez à Yahweh des sacrifices faits par le feu.'),
('lv',23,28,'crampon1923','Vous ne ferez ce jour-là aucun travail, car c''est un jour d''expiation, où doit être faite l''expiation pour vous devant Yahweh, votre Dieu.'),
('lv',23,29,'crampon1923','Toute personne qui ne s''affligera pas ce jour-là sera retranchée de son peuple;'),
('lv',23,30,'crampon1923','et toute personne qui fera ce jour-là un ouvrage quelconque, je la ferai périr du milieu de son peuple.'),
('lv',23,31,'crampon1923','Vous ne ferez aucun travail. C''est une loi perpétuelle pour vos descendants, dans tous les lieux où vous demeurerez.'),
('lv',23,32,'crampon1923','Ce sera pour vous un sabbat, un repos absolu, et vous affligerez vos âmes; le neuvième jour du mois, au soir, du soir jusqu''au soir suivant, vous observerez votre sabbat. "'),
('lv',23,33,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',23,34,'crampon1923','" Parle aux enfants d''Israël, et dis-leur: Au quinzième jour de ce septième mois, c''est la fête des Tabernacles, pendant sept jours, en l''honneur de Yahweh.'),
('lv',23,35,'crampon1923','Le premier jour, il y aura une sainte assemblée; vous ne ferez aucune œuvre servile.'),
('lv',23,36,'crampon1923','Pendant sept jours, vous offrirez à Yahweh des sacrifices faits par le feu. Le huitième jour, vous aurez une sainte assemblée, et vous offrirez à Yahweh des sacrifices faits par le feu; c''est une fête de clôture: vous ne ferez aucune œuvre servile.'),
('lv',23,37,'crampon1923','Telles sont les fêtes de Yahweh que vous publierez pour y tenir de saintes assemblées, pour offrir à Yahweh des sacrifices faits par le feu, des holocaustes, des oblations, des victimes et des libations, chacun d''eux à son jour:'),
('lv',23,38,'crampon1923','indépendamment des sabbats de Yahweh, indépendamment de vos dons, indépendamment de tous vos vœux et indépendamment de toutes vos offrandes volontaires que vous présenterez à Yahweh.'),
('lv',23,39,'crampon1923','Le quinzième jour du septième mois, quand vous aurez récolté les produits du pays, vous célébrerez la fête de Yahweh pendant sept jours; le premier jour sera un repos solennel, et le huitième jour un repos solennel.'),
('lv',23,40,'crampon1923','Vous prendrez, le premier jour, du fruit de beaux arbres, des branches de palmiers, des rameaux d''arbres touffus et des saules de rivière; et vous vous réjouirez devant Yahweh, votre Dieu, pendant sept jours.'),
('lv',23,41,'crampon1923','Vous célébrerez cette fête en l''honneur de Yahweh sept jours chaque année. C''est une loi perpétuelle pour vos descendants; vous la célébrerez le septième mois.'),
('lv',23,42,'crampon1923','Vous demeurerez pendant sept jours sous des huttes de feuillage: tous les indigènes en Israël demeureront dans des huttes;'),
('lv',23,43,'crampon1923','afin que vos descendants sachent que j''ai fait habiter sous des huttes les enfants d''Israël, lorsque je les ai fait sortir du pays d''Egypte. Je suis Yahweh, votre Dieu. "'),
('lv',23,44,'crampon1923','Moïse fit ainsi connaître aux enfants d''Israël les fêtes de Yahweh. "'),
('lv',24,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',24,2,'crampon1923','" Ordonne aux enfants d''Israël de t''apporter pour le chandelier de l''huile pure d''olives concassées, pour entretenir les lampes continuellement.'),
('lv',24,3,'crampon1923','En dehors du voile qui est devant le témoignage, dans la tente de réunion, Aaron la préparera pour brûler continuellement du soir au matin en présence de Yahweh. C''est une loi perpétuelle pour vos descendants.'),
('lv',24,4,'crampon1923','Il arrangera les lampes sur le chandelier d''or pur, pour qu''elles brûlent constamment devant Yahweh.'),
('lv',24,5,'crampon1923','" Tu prendras de la fleur de farine, et tu en cuiras douze gâteaux; chaque gâteau sera de deux dixièmes d''épha.'),
('lv',24,6,'crampon1923','Tu les placeras en deux piles, six par pile, sur la table d''or pur devant Yahweh.'),
('lv',24,7,'crampon1923','Tu mettras de l''encens pur sur chaque pile, et il servira, pour le pain, de mémorial offert par le feu à Yahweh.'),
('lv',24,8,'crampon1923','Chaque jour de sabbat, on disposera ces pains devant Yahweh constamment, de la part des enfants d''Israël: c''est une alliance perpétuelle.'),
('lv',24,9,'crampon1923','Ils appartiendront à Aaron et à ses fils, qui les mangeront en lieu saint; car c''est pour eux une chose très sainte parmi les offrandes faites par le feu à Yahweh. C''est une loi perpétuelle. "'),
('lv',24,10,'crampon1923','Le fils d''une femme israélite, mais qui était fils d''un Egyptien, vint au milieu des enfants d''Israël, et il y eut une querelle dans le camp entre le fils de la femme israélite et un homme d''Israël.'),
('lv',24,11,'crampon1923','Le fils de la femme israélite blasphéma le Nom sacré et le maudit, et sa mère s''appelait Salumith, fille de Dabri, de la tribu de Dan.'),
('lv',24,12,'crampon1923','On le mit sous garde, pour que Moïse leur déclarât de la part de Yahweh, ce qu''il y avait à faire.'),
('lv',24,13,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',24,14,'crampon1923','" Fais sortir du camp le blasphémateur; que tous ceux qui l''ont entendu posent leurs mains sur sa tête, et que toute l''assemblée le lapide.'),
('lv',24,15,'crampon1923','Tu parleras aux enfants d''Israël, en disant: Tout homme qui maudit son Dieu portera son péché;'),
('lv',24,16,'crampon1923','et celui qui blasphémera le nom de Yahweh sera puni de mort: toute l''assemblée le lapidera. Etranger ou indigène, s''il blasphème le Nom sacré, il mourra.'),
('lv',24,17,'crampon1923','Celui qui frappe un homme mortellement sera mis à mort.'),
('lv',24,18,'crampon1923','Celui qui frappe mortellement une tête de bétail en donnera une autre: vie pour vie.'),
('lv',24,19,'crampon1923','Si quelqu''un fait une blessure à son prochain, on lui fera comme il a fait:'),
('lv',24,20,'crampon1923','fracture pour fracture, œil pour œil, dent pour dent; on lui fera la même blessure qu''il a faite à son prochain.'),
('lv',24,21,'crampon1923','Celui qui aura tué une pièce de bétail en rendra une autre; mais celui qui aura tué un homme sera mis à mort.'),
('lv',24,22,'crampon1923','La même loi régnera parmi vous, pour l''étranger comme pour l''indigène; car je suis Yahweh, votre Dieu. "'),
('lv',24,23,'crampon1923','Moïse ayant ainsi parlé aux enfants d''Israël, ils firent sortir du camp le blasphémateur, et le lapidèrent. Les enfants d''Israël firent selon que Yahweh avait ordonné à Moïse.'),
('lv',25,1,'crampon1923','Yahweh parla à Moïse sur la montagne de Sinaï, en disant:'),
('lv',25,2,'crampon1923','" Parle aux enfants d''Israël, et dis-leur: Quand vous serez entrés dans le pays que je vous donne, la terre se reposera: ce sera un sabbat en l''honneur de Yahweh.'),
('lv',25,3,'crampon1923','Pendant six ans tu ensemenceras ton champ, pendant six ans tu tailleras ta vigne, et tu en recueilleras le produit.'),
('lv',25,4,'crampon1923','Mais la septième année sera un sabbat, un solennel repos pour la terre, un sabbat en l''honneur de Yahweh: tu n''ensemenceras point ton champ et tu ne tailleras point ta vigne.'),
('lv',25,5,'crampon1923','Tu ne moissonneras pas ce qui poussera de soi-même, des grains tombés de ta dernière moisson, et tu ne recueilleras point les raisins de ta vigne non taillée: ce sera une année de repos pour la terre.'),
('lv',25,6,'crampon1923','Ce que produira la terre pendant son sabbat vous servira de nourriture, à toi, à ton serviteur et à ta servante, à ton mercenaire et à l''étranger qui demeurent avec toi;'),
('lv',25,7,'crampon1923','à ton bétail aussi et aux animaux qui sont dans ton pays, tout son produit servira de nourriture.'),
('lv',25,8,'crampon1923','Tu compteras sept sabbats d''années, sept fois sept ans; la durée de ces sept sabbats d''années te fera une période de quarante-neuf ans.'),
('lv',25,9,'crampon1923','Le dixième jour du septième mois, tu feras retentir le son éclatant de la trompette; le jour des Expiations, vous ferez passer la trompette dans tout votre pays.'),
('lv',25,10,'crampon1923','Et vous sanctifierez la cinquantième année, et vous publierez la liberté dans le pays pour tous ses habitants. Ce sera pour vous un jubilé, et chacun de vous retournera dans sa propriété et chacun de vous retournera dans sa famille.'),
('lv',25,11,'crampon1923','La cinquantième année sera pour vous un jubilé; vous ne sèmerez point, vous ne moissonnerez point ce que la terre produira d''elle-même, et vous ne vendangerez point la vigne non taillée.'),
('lv',25,12,'crampon1923','Car c''est un jubilé; il sera sacré pour vous. Vous mangerez le produit tiré de vos champs.'),
('lv',25,13,'crampon1923','Dans cette année de jubilé, chacun de vous retournera dans sa propriété.'),
('lv',25,14,'crampon1923','Si vous faites une vente à votre prochain, ou si vous achetez de votre prochain, qu''aucun de vous ne porte préjudice à son frère.'),
('lv',25,15,'crampon1923','Tu achèteras à ton prochain d''après le nombre des années écoulées depuis le dernier jubilé, et il te vendra d''après le nombre des années de récolte.'),
('lv',25,16,'crampon1923','Plus il restera d''années, plus tu élèveras le prix, et moins il y aura d''années, plus tu abaisseras le prix; car c''est le nombre des récoltes qu''il te vend.'),
('lv',25,17,'crampon1923','Qu''aucun de vous ne porte préjudice à son frère; crains ton Dieu, car je suis Yahweh, votre Dieu.'),
('lv',25,18,'crampon1923','Vous mettrez mes lois en pratique, vous observerez mes ordonnances et les mettrez en pratique, et vous habiterez en sécurité dans le pays.'),
('lv',25,19,'crampon1923','La terre donnera ses fruits, vous mangerez à satiété et vous y habiterez en sécurité.'),
('lv',25,20,'crampon1923','Si vous dites: Que mangerons-nous la septième année, puisque nous ne sèmerons point et ne recueillerons point nos produits?'),
('lv',25,21,'crampon1923','Je vous enverrai ma bénédiction la sixième année, et elle produira des fruits pour trois ans.'),
('lv',25,22,'crampon1923','Vous sèmerez la huitième année, et vous mangerez de l''ancienne récolte; jusqu''à la neuvième année, jusqu''à ce que vienne sa récolte, vous mangerez l''ancienne.'),
('lv',25,23,'crampon1923','Les terres ne se vendront point à perpétuité, car le pays est à moi, et vous êtes chez moi comme des étrangers et des gens en séjour.'),
('lv',25,24,'crampon1923','Dans tout le pays que vous posséderez, vous accorderez un droit de rachat pour les terres.'),
('lv',25,25,'crampon1923','Si ton frère est devenu pauvre et vend une portion de sa propriété, son représentant, son parent le plus proche viendra et rachètera ce qu''a vendu son frère.'),
('lv',25,26,'crampon1923','Si un homme n''a personne qui le représente, et que lui-même se procure de quoi faire le rachat,'),
('lv',25,27,'crampon1923','il comptera les années écoulées depuis la vente, rendra le surplus à l''acquéreur, et retournera dans sa propriété.'),
('lv',25,28,'crampon1923','S''il ne trouve pas de quoi lui faire cette restitution, le bien vendu restera entre les mains de l''acquéreur jusqu''à l''année du jubilé; au jubilé, il sera libéré, et le vendeur rentrera dans sa propriété.'),
('lv',25,29,'crampon1923','Si un homme vend une maison d''habitation dans une ville entourée de murs, il aura le droit de rachat jusqu''au terme de l''année de la vente; son droit de rachat durera une année pleine.'),
('lv',25,30,'crampon1923','Que si la maison qui est située dans une ville murée n''est pas rachetée avant l''expiration d''une année complète, elle appartiendra à perpétuité à l''acquéreur et à ses descendants; elle ne sortira pas de leur possession au jubilé.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('lv',25,31,'crampon1923','Mais les maisons des villages non entourés de murs seront considérées comme allant avec le fonds de terre; on pourra les racheter, et elles seront libérées au jubilé.'),
('lv',25,32,'crampon1923','Quant aux villes des Lévites et aux maisons des villes qu''ils posséderont, les Lévites auront un droit perpétuel de rachat.'),
('lv',25,33,'crampon1923','Si quelqu''un achète des Lévites une maison, la maison vendue dans la ville qui leur a été donnée sera libérée au jubilé, car les maisons des villes des Lévites sont leur propriété au milieu des enfants d''Israël.'),
('lv',25,34,'crampon1923','Les champs de la banlieue des villes des Lévites ne seront point vendus, car c''est leur possession à perpétuité.'),
('lv',25,35,'crampon1923','Si ton frère devient pauvre et que sa main s''affaiblisse près de toi, tu le soutiendras, fût-il étranger ou hôte, afin qu''il vive auprès de toi.'),
('lv',25,36,'crampon1923','Ne tire de lui ni intérêt ni profit, mais crains ton Dieu et que ton frère vive avec toi.'),
('lv',25,37,'crampon1923','Tu ne lui prêteras point ton argent à intérêt, et tu ne lui donneras point de tes vivres pour en tirer profit.'),
('lv',25,38,'crampon1923','Je suis Yahweh, ton Dieu, qui vous ai fait sortir du pays d''Egypte, pour vous donner le pays de Chanaan, pour être votre Dieu.'),
('lv',25,39,'crampon1923','Si ton frère devient pauvre près de toi et qu''il se vende à toi, tu n''exigeras pas de lui le travail d''un esclave.'),
('lv',25,40,'crampon1923','Il sera chez toi comme un mercenaire, comme un hôte; il te servira jusqu''à l''année du jubilé.'),
('lv',25,41,'crampon1923','Il sortira alors de chez toi, lui et ses enfants avec lui, et il retournera dans sa famille, et rentrera dans la propriété de ses pères.'),
('lv',25,42,'crampon1923','Car ils sont mes serviteurs, que j''ai fait sortir du pays d''Egypte: ils ne seront point vendus comme on vend des esclaves.'),
('lv',25,43,'crampon1923','Tu ne domineras point sur lui avec dureté, mais tu craindras ton Dieu.'),
('lv',25,44,'crampon1923','Tes esclaves et tes servantes qui t''appartiendront, tu les prendras des nations qui t''entourent; c''est d''elles que vous achèterez serviteurs et servantes.'),
('lv',25,45,'crampon1923','Vous pourrez aussi en acheter parmi les enfants des étrangers qui séjournent chez vous, et parmi leurs familles qui vivent avec vous, qu''ils auront engendrés dans votre pays; et ils seront votre propriété.'),
('lv',25,46,'crampon1923','Vous les laisserez en héritage à vos enfants après vous, pour les posséder comme une propriété; ils seront perpétuellement vos esclaves. Mais à l''égard de vos frères, les enfants d''Israël, nul d''entre vous ne dominera sur son frère avec dureté.'),
('lv',25,47,'crampon1923','Si un étranger ou un hôte s''est enrichi près de toi, et que ton frère, devenu pauvre près de lui, se soit vendu à l''étranger, à l''hôte qui est près de toi ou au rejeton d''une famille étrangère,'),
('lv',25,48,'crampon1923','il y aura pour lui, après qu''il se sera vendu, le droit de rachat; un de ses frères pourra le racheter;'),
('lv',25,49,'crampon1923','ou son oncle, ou le fils de son oncle pourra le racheter; ou l''un de ses proches parents pourra le racheter; ou bien, s''il acquiert des richesses, il se rachètera lui-même.'),
('lv',25,50,'crampon1923','Il comptera, avec celui qui l''a acheté, depuis l''année où il s''est vendu à lui jusqu''à l''année du jubilé, et le prix de vente se comptera d''après le nombre des années, en évaluant les journées de son travail comme celles d''un mercenaire.'),
('lv',25,51,'crampon1923','S''il y a encore beaucoup d''années, il paiera son rachat à raison du nombre de ces années, en tenant compte du prix auquel il avait été acheté;'),
('lv',25,52,'crampon1923','s''il reste peu d''années jusqu''à celle du jubilé, il en fera le compte, et il paiera son rachat à raison de ces années.'),
('lv',25,53,'crampon1923','Il sera chez lui comme un mercenaire de l''année, et son maître ne le traitera point avec dureté sous tes yeux.'),
('lv',25,54,'crampon1923','S''il n''est racheté d''aucune de ces manières, il sortira libre l''année du jubilé, lui et ses enfants avec lui.'),
('lv',25,55,'crampon1923','Car c''est de moi que les enfants d''Israël sont serviteurs; ils sont mes serviteurs, que j''ai fait sortir du pays d''Egypte. Je suis Yahweh, votre Dieu. "'),
('lv',26,1,'crampon1923','" Vous ne ferez point d''idoles, vous ne vous dresserez ni image taillée ni stèle sacrée, et vous ne placerez dans votre pays aucune pierre ornée de figures, pour vous prosterner près d''elle; car je suis Yahweh, votre Dieu.'),
('lv',26,2,'crampon1923','Vous observerez mes sabbats, et vous révérerez mon sanctuaire. Je suis Yahweh. "'),
('lv',26,3,'crampon1923','" Si vous suivez mes lois, si vous gardez mes commandements et les mettez en pratique,'),
('lv',26,4,'crampon1923','j''enverrai vos pluies en leur saison; la terre donnera ses produits, et les arbres des champs donneront leurs fruits.'),
('lv',26,5,'crampon1923','Le battage du blé se prolongera chez vous jusqu''à la vendange, et la vendange atteindra les semailles; vous mangerez votre pain à satiété, et vous habiterez en sécurité dans votre pays.'),
('lv',26,6,'crampon1923','Je mettrai la paix dans le pays; vous dormirez sans que personne vous effraie. Je ferai disparaître du pays les bêtes féroces, et l''épée ne passera point à travers votre pays.'),
('lv',26,7,'crampon1923','Vous poursuivrez vos ennemis, et ils tomberont devant vous par l''épée.'),
('lv',26,8,'crampon1923','Cinq d''entre vous en poursuivront cent, et cent d''entre vous en poursuivront dix mille, et vos ennemis tomberont devant vous par l''épée.'),
('lv',26,9,'crampon1923','Je me tournerai vers vous, je vous rendrai féconds et je vous multiplierai, et j''établirai mon alliance avec vous.'),
('lv',26,10,'crampon1923','Vous mangerez des récoltes anciennes, très anciennes, et vous rejetterez l''ancienne pour faire place à la nouvelle.'),
('lv',26,11,'crampon1923','J''établirai ma demeure au milieu de vous, et mon âme ne vous prendra point en dégoût.'),
('lv',26,12,'crampon1923','Je marcherai au milieu de vous, je serai votre Dieu, et vous serez mon peuple.'),
('lv',26,13,'crampon1923','Je suis Yahweh, votre Dieu, qui vous ai fait sortir du pays d''Egypte, pour que vous n''y fussiez plus esclaves; j''ai brisé les barres de votre joug et je vous ai fait marcher tête levée.'),
('lv',26,14,'crampon1923','Mais si vous ne n''écoutez pas et ne mettez pas en pratique tous ces commandements,'),
('lv',26,15,'crampon1923','si vous méprisez mes lois, et si votre âme a en dégoût mes ordonnances, pour ne pas pratiquer tous mes commandements et pour violer mon alliance,'),
('lv',26,16,'crampon1923','voici à mon tour ce que je vous ferai: J''enverrai sur vous la terreur, la consomption et la fièvre, qui font languir les yeux et défaillir l''âme. Vous sèmerez en vain votre semence; vos ennemis la mangeront.'),
('lv',26,17,'crampon1923','Je tournerai ma face contre vous, et vous serez battus par vos ennemis; ceux qui vous haïssent domineront sur vous, et vous fuirez sans que personne vous poursuive.'),
('lv',26,18,'crampon1923','Si, après cela, vous ne m''écoutez pas, je vous châtierai sept fois plus pour vos péchés.'),
('lv',26,19,'crampon1923','Je briserai l''orgueil de votre force; je rendrai votre ciel comme de fer, et votre terre comme d''airain.'),
('lv',26,20,'crampon1923','Votre force se dépensera inutilement: votre terre ne donnera pas ses produits, et les arbres de la terre ne donneront pas leurs fruits.'),
('lv',26,21,'crampon1923','Si vous marchez encore contre moi et ne voulez pas m''écouter, je vous frapperai sept fois plus selon vos péchés.'),
('lv',26,22,'crampon1923','Je lâcherai contre vous les animaux sauvages, qui vous raviront vos enfants, déchireront votre bétail et vous réduiront à un petit nombre; et vos chemins deviendront déserts.'),
('lv',26,23,'crampon1923','Si avec ces châtiments vous ne vous laissez pas corriger par moi et si vous marchez toujours contre moi,'),
('lv',26,24,'crampon1923','à mon tour je marcherai contre vous, et je vous frapperai, moi aussi, sept fois plus pour vos péchés.'),
('lv',26,25,'crampon1923','Je ferai venir contre vous l''épée vengeresse de mon alliance; vous vous rassemblerez dans vos villes, et j''enverrai la peste au milieu de vous, et vous serez livrés aux mains de l''ennemi,'),
('lv',26,26,'crampon1923','lorsque je vous retirerai le pain, votre soutien, que dix femmes cuiront votre pain dans un seul four et rendront votre pain au poids, et que vous mangerez sans être rassasiés.'),
('lv',26,27,'crampon1923','Si, après cela, vous ne m''écoutez pas et marchez encore contre moi,'),
('lv',26,28,'crampon1923','je marcherai contre vous avec fureur et je vous châtierai, moi aussi, sept fois plus pour vos péchés.'),
('lv',26,29,'crampon1923','Vous mangerez la chair de vos fils, et vous mangerez la chair de vos filles.'),
('lv',26,30,'crampon1923','Je détruirai vos hauts lieux, j''abattrai vos stèles consacrées au soleil, je placerai vos cadavres sur les cadavres de vos infâmes idoles, et mon âme vous rejettera avec horreur.'),
('lv',26,31,'crampon1923','Je réduirai vos villes en déserts, je ravagerai vos sanctuaires, et je ne respirerai plus l''odeur agréable de vos parfums.'),
('lv',26,32,'crampon1923','Je dévasterai le pays, et vos ennemis qui l''habiteront en seront stupéfaits.'),
('lv',26,33,'crampon1923','Et vous, je vous disperserai parmi les nations et je tirerai l''épée derrière vous; votre pays sera dévasté, et vos villes seront désertes.'),
('lv',26,34,'crampon1923','Alors la terre jouira de ses sabbats, tout le temps que durera sa solitude et que vous serez dans le pays de vos ennemis. Alors la terre se reposera et jouira de ses sabbats.'),
('lv',26,35,'crampon1923','Tout le temps qu''elle sera dévastée, elle aura le repos qu''elle n''avait pas eu dans vos sabbats, lorsque vous l''habitiez.'),
('lv',26,36,'crampon1923','Ceux d''entre vous qui survivront, je leur mettrai au cœur l''épouvante, dans les pays de leurs ennemis: le bruit d''une feuille agitée les mettra en fuite; ils fuiront comme on fait devant l''épée, et ils tomberont sans qu''on les poursuive.'),
('lv',26,37,'crampon1923','Ils trébucheront les uns contre les autres comme devant l''épée, sans qu''on les poursuive; vous ne tiendrez point en présence de vos ennemis.'),
('lv',26,38,'crampon1923','Vous périrez parmi les nations, et le pays de vos ennemis vous dévorera.'),
('lv',26,39,'crampon1923','Ceux d''entre vous qui survivront, se consumeront à cause de leurs iniquités, dans le pays de leurs ennemis; ils seront aussi consumés à cause des iniquités de leurs pères, lesquelles sont encore avec eux.'),
('lv',26,40,'crampon1923','Ils confesseront leur iniquité et l''iniquité de leurs pères, dans les transgressions qu''ils ont commises contre moi, reconnaissant que c''est parce qu''ils ont marché contre moi'),
('lv',26,41,'crampon1923','que moi aussi j''ai marché contre eux et les ai fait venir dans le pays de leurs ennemis. Si alors leur cœur incirconcis s''humilie, et qu''ils acceptent le châtiment de leurs fautes, je me souviendrai de mon alliance avec Jacob,'),
('lv',26,42,'crampon1923','je me souviendrai aussi de mon alliance avec Isaac et aussi de mon alliance avec Abraham, et je me souviendrai du pays.'),
('lv',26,43,'crampon1923','Et le pays sera abandonné par eux et il jouira de ses sabbats, pendant qu''il sera dévasté loin d''eux, et ils accepteront le châtiment de leurs fautes, parce qu''ils ont méprisé mes ordonnances et que leur âme a eu mes lois en dégoût.'),
('lv',26,44,'crampon1923','Mais même ainsi, lorsqu''ils seront dans le pays de leurs ennemis, je ne les rejetterai pas et je ne les aurai point en dégoût jusqu''à les exterminer et à rompre mon alliance avec eux; car je suis Yahweh, leur Dieu.'),
('lv',26,45,'crampon1923','Je me souviendrai en leur faveur de l''alliance conclue avec leurs ancêtres, que j''ai fait sortir du pays d''Egypte, aux yeux des nations, pour être leur Dieu. Je suis Yahweh. "'),
('lv',26,46,'crampon1923','Tels sont les statuts, les ordonnances et les lois que Yahweh établit entre lui et les enfants d''Israël, sur la montagne de Sinaï, par le ministère de Moïse.'),
('lv',27,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('lv',27,2,'crampon1923','" Parle aux enfants d''Israël, et dis-leur: Si quelqu''un fait un vœu, les personnes seront à Yahweh selon ton estimation.'),
('lv',27,3,'crampon1923','Si l''objet de ton estimation est un homme de vingt à soixante ans, ton estimation sera de cinquante sicles d''argent, selon le sicle du sanctuaire;'),
('lv',27,4,'crampon1923','si c''est une femme, ton estimation sera de trente sicles.'),
('lv',27,5,'crampon1923','De cinq ans à vingt ans, ton estimation sera de vingt sicles pour un garçon, et de dix sicles pour une fille.'),
('lv',27,6,'crampon1923','D''un mois à cinq ans, ton estimation sera de cinq sicles d''argent pour un garçon, et pour une fille ton estimation sera de trois sicles d''argent.'),
('lv',27,7,'crampon1923','De soixante ans et au-dessus, ton estimation sera de quinze sicles pour un homme, et de dix sicles pour une femme.'),
('lv',27,8,'crampon1923','Si celui qui a fait le vœu est trop pauvre pour payer la valeur de ton estimation, on le présentera au prêtre, qui fera son estimation; le prêtre fera l''estimation d''après les ressources de celui qui a fait le vœu.'),
('lv',27,9,'crampon1923','Si l''on voue un des animaux dont on fait offrande à Yahweh, tout ce qu''on en donne ainsi à Yahweh sera chose sainte.'),
('lv',27,10,'crampon1923','On ne le changera point, on ne mettra pas un mauvais à la place d''un bon, ni un bon à la place d''un mauvais; si l''on remplace un animal par un autre, ils seront l''un et l''autre chose sainte.'),
('lv',27,11,'crampon1923','Si c''est quelque animal impur dont on ne peut faire offrande à Yahweh, on présentera l''animal au prêtre,'),
('lv',27,12,'crampon1923','et le prêtre en fera l''estimation selon qu''il sera bon ou mauvais, et l''on s''en rapportera à l''estimation de prêtre.'),
('lv',27,13,'crampon1923','Si on veut le racheter, on ajoutera un cinquième à ton estimation.'),
('lv',27,14,'crampon1923','Si quelqu''un sanctifie sa maison en la consacrant à Yahweh, le prêtre en fera l''estimation selon qu''elle est bonne ou mauvaise, et l''on s''en tiendra à l''estimation du prêtre.'),
('lv',27,15,'crampon1923','Si celui qui a sanctifié sa maison veut la racheter, il ajoutera un cinquième au prix de ton estimation, et elle sera à lui.'),
('lv',27,16,'crampon1923','Si quelqu''un consacre à Yahweh une partie du champ qui est sa propriété, ton estimation se fera d''après la quantité de grain nécessaire pour l''ensemencer, à raison de cinquante sicles d''argent pour un chomer de semence d''orge.'),
('lv',27,17,'crampon1923','Si c''est dès l''année du jubilé qu''il consacre son champ, on s''en tiendra à ton estimation;'),
('lv',27,18,'crampon1923','mais si c''est après le jubilé qu''il consacre son champ, le prêtre en évaluera le prix à raison du nombre d''années qui restent jusqu''au jubilé, et il sera fait une réduction sur ton estimation.'),
('lv',27,19,'crampon1923','Si celui qui a consacré son champ veut le racheter, il ajoutera un cinquième au prix de ton estimation, et le champ lui restera.'),
('lv',27,20,'crampon1923','S''il ne rachète pas le champ, ou qu''il le vende à un autre homme, ce champ ne pourra plus être racheté;'),
('lv',27,21,'crampon1923','et quand il sera libéré au jubilé, le champ sera consacré à Yahweh, comme un champ qui a été voué: il deviendra la propriété du prêtre.'),
('lv',27,22,'crampon1923','Si quelqu''un consacre à Yahweh un champ acheté par lui et ne faisant pas partie de son patrimoine,'),
('lv',27,23,'crampon1923','le prêtre en évaluera le prix d''après ton estimation jusqu''à l''année du jubilé, et cet homme paiera le jour même le prix fixé, comme chose consacrée à Yahweh.'),
('lv',27,24,'crampon1923','L''année du jubilé, le champ retournera à celui de qui on l''avait acheté et du patrimoine duquel il faisait partie.'),
('lv',27,25,'crampon1923','Toutes tes estimations seront faites au sicle du sanctuaire: le sicle est de vingt guéras.'),
('lv',27,26,'crampon1923','Nul, toutefois, ne pourra consacrer le premier-né de son bétail, lequel, comme premier-né, appartient déjà à Yahweh: bœuf ou brebis, il appartient à Yahweh.'),
('lv',27,27,'crampon1923','S''il s''agit d''un animal impur, on le rachètera au prix de ton estimation, en y ajoutant un cinquième; s''il n''est pas racheté, il sera vendu d''après ton estimation.'),
('lv',27,28,'crampon1923','Rien de ce qu''un homme aura voué par anathème à Yahweh, dans tout ce qui lui appartient, que ce soit un homme, un animal ou un champ de son patrimoine, ne pourra ni se vendre, ni se racheter; tout ce qui est voué par anathème est chose très sainte, appartenant à Yahweh.'),
('lv',27,29,'crampon1923','Aucune personne vouée par anathème ne pourra être rachetée: elle sera mise à mort.'),
('lv',27,30,'crampon1923','Toute dîme de la terre, prélevée soit sur les semences de la terre, soit sur les fruits des arbres, appartient à Yahweh: c''est une chose consacrée à Yahweh.'),
('lv',27,31,'crampon1923','Si quelqu''un veut racheter quelque chose de sa dîme, il y ajoutera un cinquième.'),
('lv',27,32,'crampon1923','Quant aux dîmes de gros et de menu bétail, de tout ce qui passe sous la houlette, le dixième animal sera consacré à Yahweh.'),
('lv',27,33,'crampon1923','On ne fera pas un choix entre ce qui est bon ou mauvais, et l''on ne fera pas d''échange; et si l''on fait un échange, l''animal remplacé et celui qui le remplace seront tous deux chose sainte et ne pourront être rachetés. "'),
('lv',27,34,'crampon1923','Tels sont les commandements que Yahweh donna à Moïse pour les enfants d''Israël, sur la montagne de Sinaï.'),
('nb',1,1,'crampon1923','Yahweh parla à Moïse au désert de Sinaï, dans la tente de réunion, le premier jour du second mois, la deuxième année après leur sortie du pays d’Égypte, en disant:'),
('nb',1,2,'crampon1923','« Faites le compte de toute l’assemblée des enfants d’Israël, selon leurs familles, selon leurs maisons patriarcales, en comptant par tête le nom de tous les mâles'),
('nb',1,3,'crampon1923','depuis l’âge de vingt ans et au-dessus, tous les hommes aptes à porter les armes en Israël; vous en ferez le dénombrement selon leurs troupes, toi et Aaron.'),
('nb',1,4,'crampon1923','Il y aura avec vous un homme de chaque tribu, chef de sa maison patriarcale.'),
('nb',1,5,'crampon1923','Voici les noms de ceux qui se tiendront avec vous: Pour Ruben: Elisur, fils de Sédéur;'),
('nb',1,6,'crampon1923','pour Siméon: Salamiel, fils de Surisaddaï;'),
('nb',1,7,'crampon1923','pour Juda: Nahasson, fils d’Aminadab;'),
('nb',1,8,'crampon1923','pour Issachar: Nathanaël, fils de Suar;'),
('nb',1,9,'crampon1923','pour Zabulon: Eliab, fils de Hélon;'),
('nb',1,10,'crampon1923','pour les fils de Joseph, pour Ephraïm: Elisama, fils d’Ammiud; pour Manassé: Gamaliel, fils de Phadassur;'),
('nb',1,11,'crampon1923','pour Benjamin: Abidan, fils de Gédéon;'),
('nb',1,12,'crampon1923','pour Dan: Ahiéser, fils d’Ammisaddaï;'),
('nb',1,13,'crampon1923','pour Aser: Phégiel, fils d’Ochran;'),
('nb',1,14,'crampon1923','pour Gad: Eliasaph, fils de Duel;'),
('nb',1,15,'crampon1923','pour Nephtali: Ahira, fils d’Enan. »'),
('nb',1,16,'crampon1923','Tels sont ceux qui furent appelés de l’assemblée; ils étaient princes des tribus de leurs pères, chefs des milliers d’Israël.'),
('nb',1,17,'crampon1923','Moïse et Aaron, ayant pris ces hommes qui avaient été désignés par leurs noms,'),
('nb',1,18,'crampon1923','convoquèrent toute l’assemblée pour le premier jour du deuxième mois. Et ils furent enregistrés selon leurs familles, selon leurs maisons patriarcales, en comptant par tête les noms, depuis l’âge de vingt et au-dessus.'),
('nb',1,19,'crampon1923','Comme Yahweh l’avait ordonné à Moïse, celui-ci en fit le dénombrement dans le désert de Sinaï.'),
('nb',1,20,'crampon1923','Fils de Ruben, premier-né d’Israël, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms par tête, tous les mâles depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter des armes:'),
('nb',1,21,'crampon1923','les recensés de la tribu de Ruben furent quarante-six mille cinq cents.'),
('nb',1,22,'crampon1923','Fils de Siméon, leurs descendants selon leurs familles, selon leurs maisons patriarcales, leurs recensés en comptant les noms par tête, tous les mâles depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,23,'crampon1923','les recensés de la tribu de Siméon furent cinquante-neuf mille trois cents.'),
('nb',1,24,'crampon1923','Fils de Gad, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,25,'crampon1923','les recensés de la tribu de Gad furent quarante-cinq mille six cent cinquante.'),
('nb',1,26,'crampon1923','Fils de Juda, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,27,'crampon1923','les recensés de la tribu de Juda furent soixante-quatorze mille six cents.'),
('nb',1,28,'crampon1923','Fils d’Issachar, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,29,'crampon1923','les recensés de la tribu d’Issachar furent cinquante-quatre mille quatre cents.'),
('nb',1,30,'crampon1923','Fils de Zabulon, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,31,'crampon1923','les recensés de la tribu de Zabulon furent cinquante-sept mille quatre cents.'),
('nb',1,32,'crampon1923','Fils de Joseph, — fils d’Ephraïm, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,33,'crampon1923','les recensés de la tribu d’Ephraïm furent quarante mille cinq cents.'),
('nb',1,34,'crampon1923','— Fils de Manassé, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,35,'crampon1923','les recensés de la tribu de Manassé furent trente-deux mille deux cents.'),
('nb',1,36,'crampon1923','Fils de Benjamin, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,37,'crampon1923','les recensés de la tribu de Benjamin furent trente-cinq mille quatre cents.'),
('nb',1,38,'crampon1923','Fils de Dan, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,39,'crampon1923','les recensés de la tribu de Dan furent soixante-deux mille sept cents.'),
('nb',1,40,'crampon1923','Fils d’Aser, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,41,'crampon1923','les recensés de la tribu d’Aser furent quarante et un mille cinq cents.'),
('nb',1,42,'crampon1923','Fils de Nephtali, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l’âge de vingt ans et au-dessus, tous les hommes en état de porter les armes:'),
('nb',1,43,'crampon1923','les recensés de la tribu de Nephtali furent cinquante-trois mille quatre cents.'),
('nb',1,44,'crampon1923','Tels sont ceux qui furent recensés, que recensèrent Moïse et Aaron, avec les princes d’Israël, au nombre de douze: un homme pour chacune de leurs maisons patriarcales.'),
('nb',1,45,'crampon1923','Tous les enfants d’Israël dont on fit le recensement, selon leurs maisons patriarcales, depuis l’âge de vingt ans et au-dessus, tous les hommes d’Israël en état de porter les armes,'),
('nb',1,46,'crampon1923','tous les recensés furent six cent trois mille cinq cent cinquante.'),
('nb',1,47,'crampon1923','Les Lévites, selon leur tribu patriarcale, ne furent pas recensés avec eux.'),
('nb',1,48,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',1,49,'crampon1923','« Tu ne feras pas le recensement de la tribu de Lévi, et tu n’en réuniras pas le compte avec celui des enfants d’Israël.'),
('nb',1,50,'crampon1923','Remets à leur soin la demeure du témoignage, tous ses ustensiles et tout ce qui lui appartient. Ils porteront la Demeure et tous ses ustensiles, ils en feront le service, et ils camperont autour de la Demeure.'),
('nb',1,51,'crampon1923','Quand la Demeure partira, les Lévites la démonteront; quand la Demeure campera, les Lévites la dresseront; et l’étranger qui s’en approchera sera puni de mort.'),
('nb',1,52,'crampon1923','Les enfants d’Israël camperont chacun dans son camp, chacun près de sa bannière, selon leurs troupes.'),
('nb',1,53,'crampon1923','Mais les Lévites camperont autour de la Demeure du témoignage, afin que ma colère n’éclate point sur l’assemblée des enfants d’Israël; et les Lévites auront la garde de la Demeure du témoignage. »'),
('nb',1,54,'crampon1923','Les enfants d’Israël agirent selon tout ce que Yahweh avait ordonné à Moïse; ils firent ainsi.'),
('nb',2,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',2,2,'crampon1923','« Les enfants d’Israël camperont chacun près de sa bannière, sous les enseignes de leurs maisons patriarcales; ils camperont vis-à-vis de la tente de réunion, tout autour.'),
('nb',2,3,'crampon1923','A l’avant, vers l’orient, campera la bannière du camp de Juda, avec ses troupes; le prince des fils de Juda est Nahasson, fils d’Aminadab,'),
('nb',2,4,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de soixante-quatorze mille six cents hommes.'),
('nb',2,5,'crampon1923','A ses côtés campera la tribu d’Issachar; le prince des fils d’Issachar est Nathanaël, fils de Suar,'),
('nb',2,6,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de cinquante-quatre mille quatre cents hommes.'),
('nb',2,7,'crampon1923','Puis la tribu de Zabulon; le prince des fils de Zabulon est Eliab, fils de Hélon,'),
('nb',2,8,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de cinquante-sept mille quatre cents hommes.'),
('nb',2,9,'crampon1923','Total pour le camp de Juda, d’après les hommes recensés: cent quatre-vingt-six mille quatre cents hommes, selon leurs troupes. Ils se mettront en marche les premiers.'),
('nb',2,10,'crampon1923','Au midi, la bannière du camp de Ruben, avec ses troupes; le prince des fils de Ruben est Elisur, fils de Sédéur,'),
('nb',2,11,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de quarante-six mille cinq cents hommes.'),
('nb',2,12,'crampon1923','A ses côtés campera la tribu de Siméon; le prince des fils de Siméon est Salamiel, fils de Surisaddaï,'),
('nb',2,13,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de cinquante-neuf mille trois cents hommes.'),
('nb',2,14,'crampon1923','Puis la tribu de Gad; le chef des fils de Gad est Eliasaph, fils de Duel,'),
('nb',2,15,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de quarante-cinq mille six cent cinquante hommes.'),
('nb',2,16,'crampon1923','Total pour le camp de Ruben, d’après les hommes recensés: cent cinquante et un mille quatre cent cinquante hommes, selon leurs troupes. Ils se mettront en marche les seconds.'),
('nb',2,17,'crampon1923','Ensuite s’avancera la tente de réunion, le camp des Lévites au milieu des autres camps. Ils suivront dans la marche l’ordre de leur campement, chacun à son rang, selon sa bannière.'),
('nb',2,18,'crampon1923','A l’occident, la bannière d’Ephraïm, avec ses troupes; le prince des fils d’Ephraïm est Elisama, fils d’Ammiud,'),
('nb',2,19,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de quarante mille cinq cents hommes.'),
('nb',2,20,'crampon1923','A ses côtés campera la tribu de Manassé; le prince des fils de Manassé est Gamaliel, fils de Phadassur,'),
('nb',2,21,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de trente-deux mille deux cents hommes.'),
('nb',2,22,'crampon1923','Puis la tribu de Benjamin; le prince des fils de Benjamin est Abidan, fils de Gédéon,'),
('nb',2,23,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de trente-cinq mille quatre cents hommes.'),
('nb',2,24,'crampon1923','Total pour le camp d’Ephraïm, d’après les hommes recensés: cent huit mille et cent hommes, selon leurs troupes. Ils se mettront en marche les troisièmes.'),
('nb',2,25,'crampon1923','Au nord, la bannière du camp de Dan, avec ses troupes; le prince des fils de Dan est Ahiéser, fils d’Ammisaddaï,'),
('nb',2,26,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de soixante-deux mille sept cents hommes.'),
('nb',2,27,'crampon1923','A ses côtés campera la tribu d’Aser; le prince des fils d’Aser est Phégiel, fils d’Ochran,'),
('nb',2,28,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de quarante-et-un mille cinq cents hommes.'),
('nb',2,29,'crampon1923','Puis la tribu de Nephtali; le prince des fils de Nephtali est Ahira, fils d’Enan,'),
('nb',2,30,'crampon1923','et son corps d’armée, d’après les hommes recensés, est de cinquante-trois mille quatre cents hommes.'),
('nb',2,31,'crampon1923','Total pour le camp de Dan, d’après les hommes recensés: cent cinquante-sept mille six cents hommes. Ils se mettront en marche les derniers, selon leurs bannières. »'),
('nb',2,32,'crampon1923','Tels furent les enfants d’Israël inscrits au recensement selon leurs maisons patriarcales. Total pour tous les hommes recensés, répartis en divers camps, selon leurs troupes d’armée: six cent trois mille cinq cent cinquante hommes.'),
('nb',2,33,'crampon1923','Les Lévites ne furent pas compris dans le recensement avec les enfants d’Israël, suivant que Yahweh l’avait ordonné à Moïse.'),
('nb',2,34,'crampon1923','Et les enfants d’Israël agirent selon tout ce que Yahweh avait ordonné à Moïse. C’est ainsi qu’ils campaient, selon leurs bannières, et ainsi qu’ils se mettaient en marche, chacun selon sa famille, selon sa maison patriarcale.'),
('nb',3,1,'crampon1923','Voici la postérité d’Aaron et de Moïse, au temps où Yahweh parla à Moïse sur la montagne de Sinaï'),
('nb',3,2,'crampon1923','Voici les noms des fils d’Aaron: Nadab, le premier-né, Abiu, Eléazar et Ithamar.'),
('nb',3,3,'crampon1923','Tels sont les noms des fils d’Aaron, des prêtres ayant reçu l’onction, installés pour exercer le sacerdoce.'),
('nb',3,4,'crampon1923','Nadab et Abiu moururent devant Yahweh, lorsqu’ils apportèrent devant Yahweh du feu étranger, dans le désert de Sinaï; ils n’avaient point de fils. Eléazar et Ithamar exercèrent le sacerdoce en présence d’Aaron, leur père.'),
('nb',3,5,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',3,6,'crampon1923','« Fais approcher la tribu de Lévi, et tu la placeras devant Aaron le prêtre, pour qu’elle soit à son service.'),
('nb',3,7,'crampon1923','Ils auront la charge de tout ce qui est commis à sa charge et à la charge de toute l’assemblée, devant la tente de réunion, faisant ainsi le service de la Demeure.'),
('nb',3,8,'crampon1923','Ils seront chargés de tous les ustensiles de la tente de réunion, et de ce qui est commis à la charge des enfants d’Israël: ils feront ainsi le service de la Demeure.'),
('nb',3,9,'crampon1923','Tu donneras les Lévites à Aaron et à ses fils; ils lui seront entièrement donnés, d’entre les enfants d’Israël.'),
('nb',3,10,'crampon1923','Tu établiras Aaron et ses fils pour accomplir les fonctions de leur sacerdoce; l’étranger qui approchera du sanctuaire sera puni de mort. »'),
('nb',3,11,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',3,12,'crampon1923','« Voici, j’ai pris les Lévites du milieu des enfants d’Israël, à la place de tout premier-né qui ouvre le sein de sa mère parmi les enfants d’Israël, et les Lévites sont à moi.'),
('nb',3,13,'crampon1923','Car tout premier-né est à moi; le jour où j’ai frappé tous les premiers nés dans le pays d’Egypte, je me suis consacré tout premier-né en Israël, tant des hommes que des animaux: ils sont à moi. Je suis Yahweh. »'),
('nb',3,14,'crampon1923','Yahweh parla à Moïse dans le désert de Sinaï, en disant:'),
('nb',3,15,'crampon1923','« Fais le recensement des enfants de Lévi selon leurs maisons patriarcales, selon leurs familles. Tu feras le recensement de tous les mâles, depuis l’âge d’un mois et au-dessus. »'),
('nb',3,16,'crampon1923','Moïse fit leur recensement sur l’ordre de Yahweh, selon qu’il lui avait été commandé.'),
('nb',3,17,'crampon1923','Voici les fils de Lévi, d’après leurs noms: Gerson, Caath et Mérari. —'),
('nb',3,18,'crampon1923','Voici les noms des fils de Gerson, selon leurs familles: Lebni et Séméi.'),
('nb',3,19,'crampon1923','Fils de Caath, selon leurs familles: Amram, Jésaar, Hébron et Oziel.'),
('nb',3,20,'crampon1923','Fils de Mérari, selon leurs familles: Moholi et Musi. — Ce sont là les familles de Lévi selon leurs maisons patriarcales.'),
('nb',3,21,'crampon1923','De Gerson viennent la famille de Lebni et la famille de Séméi; ce sont les familles de Gersonites.'),
('nb',3,22,'crampon1923','Leurs recensés, en comptant tous les mâles depuis l’âge d’un mois et au-dessus, leurs recensés furent sept mille cinq cents.'),
('nb',3,23,'crampon1923','Les familles des Gersonites campaient derrière la Demeure, à l’occident.'),
('nb',3,24,'crampon1923','Le prince de la maison patriarcale des Gersonites était Eliasaph, fils de Laël.'),
('nb',3,25,'crampon1923','En ce qui concerne la tente de réunion, les fils de Gerson avaient la charge de la Demeure et de la tente, de sa couverture, du rideau qui est à l’entrée de la tente de réunion,'),
('nb',3,26,'crampon1923','des tentures du parvis et du rideau de l’entrée du parvis, tout autour de la Demeure et de l’autel, et de ses cordages pour tout son service.'),
('nb',3,27,'crampon1923','De Caath viennent la famille des Amramites, la famille des Jésaarites, la famille des Hébronites et la famille des Oziélites; ce sont là les familles des Caathites.'),
('nb',3,28,'crampon1923','En comptant tous les mâles depuis l’âge d’un mois et au-dessus, on en trouva huit mille six cents, chargés de la garde du sanctuaire.'),
('nb',3,29,'crampon1923','Les familles des fils de Caath campaient au côté méridional de la Demeure.'),
('nb',3,30,'crampon1923','Le prince de la maison patriarcale des familles des Caathites était Elisaphan, fils d’Oziel.'),
('nb',3,31,'crampon1923','On confia à leur garde l’arche, la table de proposition, le chandelier, les autels, les ustensiles du sanctuaire avec lesquels on fait le service, le voile et tout ce qui se rapporte à son service.'),
('nb',3,32,'crampon1923','Le prince des princes des Lévites était Eléazar, fils du prêtre Aaron; il avait la surveillance de ceux qui étaient chargés de la garde du sanctuaire.'),
('nb',3,33,'crampon1923','De Mérari viennent la famille des Moholites et la famille des Musites: ce sont là les familles des Mérarites.'),
('nb',3,34,'crampon1923','Leurs recensés, en comptant tous les mâles depuis l’âge d’un mois et au-dessus, furent six mille deux cents.'),
('nb',3,35,'crampon1923','Le prince de la maison patriarcale des familles de Mérari était Suriel, fils d’Abihaiel. Ils campaient au côté septentrional de la Demeure.'),
('nb',3,36,'crampon1923','Les fils de Mérari eurent le soin et la garde des ais de la Demeure, de ses traverses, de ses colonnes et de leurs socles, de tous ses ustensiles et de tout son service,'),
('nb',3,37,'crampon1923','des colonnes du parvis tout autour, de leurs socles, de leurs pieux et de leurs cordages.'),
('nb',3,38,'crampon1923','En face de la Demeure, à l’orient, devant la tente de réunion, au levant, campaient Moïse, Aaron et ses fils; ils avaient la garde du sanctuaire, pour ce qui était remis à la garde des enfants d’Israël; l’étranger qui s’en approcherait devait être puni de mort.'),
('nb',3,39,'crampon1923','Total des Lévites recensés dont Moïse fit le recensement sur l’ordre de Yahweh selon leurs familles, de tous les mâles depuis l’âge d’un mois et au-dessus: vingt-deux mille.'),
('nb',3,40,'crampon1923','Yahweh dit à Moïse: « Fais le recensement de tous les premiers-nés mâles parmi les enfants d’Israël, depuis l’âge d’un mois et au-dessus, et fais le compte de leurs noms.'),
('nb',3,41,'crampon1923','Tu prendras les Lévites pour moi, — je suis Yahweh, — à la place de tous les premiers-nés des enfants d’Israël, et le bétail des Lévites à la place de tous les premiers-nés du bétail des enfants d’Israël. »'),
('nb',3,42,'crampon1923','Moïse fit le recensement de tous les premiers-nés parmi les enfants d’Israël, selon l’ordre que Yahweh lui avait donné.'),
('nb',3,43,'crampon1923','Tous les premiers-nés mâles, comptés par leurs noms, depuis l’âge d’un mois et au-dessus, dont on fit le recensement, furent vingt-deux mille deux cent soixante-treize.'),
('nb',3,44,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',3,45,'crampon1923','« Prends les Lévites à la place de tous les premiers-nés des enfants d’Israël, et le bétail des Lévites à la place de leur bétail; et les Lévites seront à moi. Je suis Yahweh.'),
('nb',3,46,'crampon1923','Pour le rachat des deux cent soixante-treize d’entre les premiers-nés des enfants d’Israël qui dépassent le nombre des Lévites,'),
('nb',3,47,'crampon1923','tu prendras cinq sicles par tête; tu les prendras selon le sicle du sanctuaire, qui est de vingt guéras.'),
('nb',3,48,'crampon1923','Tu donneras l’argent à Aaron et à ses fils pour le rachat de ceux qui dépassent le nombre des Lévites. »'),
('nb',3,49,'crampon1923','Moïse prit l’argent pour le rachat de ceux qui dépassaient le nombre des premiers-nés rachetés par les Lévites;'),
('nb',3,50,'crampon1923','il prit l’argent des premiers-nés des enfants d’Israël, mille trois cent soixante-cinq sicles, selon le sicle du sanctuaire.'),
('nb',3,51,'crampon1923','Et Moïse donna l’argent du rachat à Aaron et à ses fils, sur l’ordre de Yahweh, selon que Yahweh l’avait ordonné à Moïse.'),
('nb',4,1,'crampon1923','Yahweh parla à Moïse et à Aaron, en disant:'),
('nb',4,2,'crampon1923','« Compte les fils de Caath parmi les enfants de Lévi, selon leurs familles, selon leurs maisons patriarcales,'),
('nb',4,3,'crampon1923','depuis l’âge de trente ans et au-dessus jusqu’à l’âge de cinquante ans, tous ceux qui ont à faire le service, à remplir quelque fonction dans la tente de réunion.'),
('nb',4,4,'crampon1923','Voici quel sera le service des fils de Caath dans la tente de réunion: il portera sur les objets très saints.'),
('nb',4,5,'crampon1923','Quand on lèvera le camp, Aaron et ses fils viendront descendre le voile et ils en couvriront l’arche du témoignage;'),
('nb',4,6,'crampon1923','ils mettront dessus une couverture de peau de veau marin, et ils étendront par-dessus un drap tout entier de pourpre violette; puis ils placeront les barres de l’arche.'),
('nb',4,7,'crampon1923','Ils étendront un drap de pourpre violette sur la table des pains de proposition, et ils mettront dessus les plats, les calices, les patères et les coupes pour les libations; le pain perpétuel sera sur elle;'),
('nb',4,8,'crampon1923','ils étendront par-dessus un drap de cramoisi, qu’ils envelopperont d’une couverture de peau de veau de marin, et ils placeront les barres de la table.'),
('nb',4,9,'crampon1923','Ils prendront un drap de pourpre violette et ils en couvriront le chandelier, ainsi que ses lampes, ses mouchettes, ses vases à cendre et tous ses vases à huile, nécessaires pour son service;'),
('nb',4,10,'crampon1923','puis, l’ayant mis, avec tous ses ustensiles, dans une couverture de peau de veau de marin, ils le placeront sur le brancard.'),
('nb',4,11,'crampon1923','Ils étendront un drap de pourpre violette sur l’autel d’or, et, après l’avoir enveloppé d’une couverture de peau de veau de marin, ils y mettront les barres.'),
('nb',4,12,'crampon1923','Ils prendront tous les ustensiles en usage pour le service dans le sanctuaire, et les ayant mis dans un drap de pourpre violette, ils les envelopperont d’une couverture de peau de veau de marin, et les placeront sur le brancard.'),
('nb',4,13,'crampon1923','Ils ôteront les cendres de l’autel et ils étendront par-dessus un drap de pourpre écarlate;'),
('nb',4,14,'crampon1923','ils mettront dessus tous les ustensiles nécessaires à son service, les brasiers, les fourchettes, les pelles, les bassins, tous les ustensiles de l’autel et, ayant étendu sur le tout une couverture de peau de veau de marin, ils y mettront les barres.'),
('nb',4,15,'crampon1923','Quand Aaron et ses fils auront achevé de couvrir le sanctuaire et tous les ustensiles du sanctuaire, et qu’on lèvera le camp, les fils de Caath viendront les emporter, mais ils ne toucheront point les choses saintes, de peur qu’ils ne meurent. — Voilà ce qu’auront à porter les fils de Caath dans la tente de réunion.'),
('nb',4,16,'crampon1923','Eléazar, fils d’Aaron, le prêtre, aura sous sa surveillance l’huile du chandelier, le parfum odoriférant, l’oblation perpétuelle et l’huile d’onction; il aura la surveillance de toute la Demeure et de tout ce qu''elle contient, du sanctuaire et de tous ses ustensiles. »'),
('nb',4,17,'crampon1923','Yahweh parla à Moïse et à Aaron, en disant:'),
('nb',4,18,'crampon1923','« Prenez garde de faire retrancher la tribu des familles des Caathites du milieu des Lévites.'),
('nb',4,19,'crampon1923','Agissez ainsi à leur égard, afin qu’ils vivent et ne meurent point, quand ils s’approcheront des objets très saints. Aaron et ses fils viendront, et ils assigneront à chacun d’eux son service et ce qu’il a à porter;'),
('nb',4,20,'crampon1923','et les Lévites n’entreront point pour voir un seul instant les choses saintes, de peur qu’ils ne meurent. »'),
('nb',4,21,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',4,22,'crampon1923','« Compte aussi les fils de Gerson d''après leurs maisons patriarcales, d’après leurs familles;'),
('nb',4,23,'crampon1923','tu feras leur recensement, depuis l’âge de trente ans et au-dessus jusqu’à l’âge de cinquante ans, de tous ceux qui ont à faire le service, à remplir quelque fonction dans la tente de réunion.'),
('nb',4,24,'crampon1923','Voici le service des familles des Gersonites, ce qu’ils auront à faire et à porter.'),
('nb',4,25,'crampon1923','Ils porteront les tentures de la Demeure et la tente de réunion, sa couverture et la couverture de peau de veau de marin qui se met par-dessus, le rideau qui est à l’entrée de la tente de réunion,'),
('nb',4,26,'crampon1923','les tentures du parvis et le rideau de l’entrée de la porte du parvis, tout autour de la Demeure et de l’autel, leurs cordages et tous les ustensiles à leur usage; et ils feront tout le service qui s’y rapporte.'),
('nb',4,27,'crampon1923','Tout le service des fils des Gersonites sera sous les ordres d’Aaron et de ses fils, pour tout ce qu’ils auront à porter et pour tout ce qu’ils auront à faire; vous remettrez à leur garde toutes les choses qu’ils ont à porter.'),
('nb',4,28,'crampon1923','Tel est le service des familles des fils des Gersonites à l’égard de la tente de réunion; ils exerceront leur charge sous la direction d’Ithamar, fils d’Aaron, le prêtre.'),
('nb',4,29,'crampon1923','Tu feras le recensement des fils de Mérari selon leurs familles, selon leurs maisons patriarcales;'),
('nb',4,30,'crampon1923','tu les recenseras, depuis l’âge de trente ans et au-dessus jusqu’à l’âge de cinquante ans, tous ceux qui ont à faire le service, à remplir quelque fonction dans la tente de réunion;'),
('nb',4,31,'crampon1923','Voici ce qui sera remis à leur charge, ce qu’ils auront à porter selon tout leur service dans la tente de réunion: les ais de la Demeure, ses traverses, ses colonnes, ses socles;'),
('nb',4,32,'crampon1923','les colonnes du parvis qui l’entoure, leurs socles, leurs pieux, leurs cordages, tous leurs ustensiles et tout ce qui se rapporte à leur service. Vous ferez l’inventaire par leurs noms des objets qui leur ont été confiés pour les porter;'),
('nb',4,33,'crampon1923','Tel est le service des familles des fils de Mérari, tout leur service à l’égard de la tente de réunion, sous la direction d’Ithamar, fils d’Aaron, le prêtre ».'),
('nb',4,34,'crampon1923','Moïse, Aaron et les princes de l’assemblée firent le recensement des fils des Caathites selon leurs familles et selon leurs maisons patriarcales,'),
('nb',4,35,'crampon1923','depuis l’âge de trente et au-dessus jusqu’à l’âge de cinquante ans, tous ceux qui avaient à faire le service, à remplir quelque fonction dans la tente de réunion.'),
('nb',4,36,'crampon1923','Les recensés, selon leurs familles, furent deux mille sept cent cinquante.'),
('nb',4,37,'crampon1923','Ce furent là les recensés des familles des Caathites, tous ceux qui remplissaient un service dans la tente de réunion. Moïse et Aaron en firent le recensement selon l’ordre de Yahweh par l’organe de Moïse.'),
('nb',4,38,'crampon1923','Les recensés des fils de Gerson selon leurs familles et selon leurs maisons patriarcales,'),
('nb',4,39,'crampon1923','depuis l’âge de trente ans et au-dessus jusqu’à l’âge de cinquante ans, tous ceux qui avaient à faire le service, à remplir quelque fonction dans la tente de réunion,'),
('nb',4,40,'crampon1923','les recensés selon leurs familles, selon leurs maisons patriarcales, furent deux mille six cent trente.'),
('nb',4,41,'crampon1923','Ce furent là les recensés des familles des fils de Gerson, tous ceux qui remplissaient un service dans la tente de réunion. Moïse et Aaron en firent le recensement sur l’ordre de Yahweh.'),
('nb',4,42,'crampon1923','Les recensés des fils de Mérari selon leurs familles, selon leurs maisons patriarcales,'),
('nb',4,43,'crampon1923','depuis l’âge de trente ans et au-dessus jusqu’à l’âge de cinquante ans, tous ceux qui avaient à faire le service, à remplir quelque fonction dans la tente de réunion,'),
('nb',4,44,'crampon1923','les recensés, selon leurs familles, furent trois mille deux cents.'),
('nb',4,45,'crampon1923','Ce furent là les recensés des familles des fils de Mérari. Moïse et Aaron en firent le recensement sur l’ordre de Yahweh par l’organe de Moïse.'),
('nb',4,46,'crampon1923','Tous les recensés des Lévites, dont Moïse, Aaron et les princes d’Israël firent le recensement, selon leurs familles et selon leurs maisons patriarcales,'),
('nb',4,47,'crampon1923','depuis l’âge de trente ans et au-dessus jusqu’à l’âge de cinquante ans, tous ceux qui avaient à remplir quelque fonction, dans le service et le transport, à l’égard de la tente de réunion,'),
('nb',4,48,'crampon1923','tous les recensés furent huit mille cinq cent quatre-vingts.'),
('nb',4,49,'crampon1923','On en fit le recensement selon l’ordre de Yahweh par l’organe de Moïse, en assignant à chacun le service qu’il devait faire et ce qu’il devait porter; c’est ainsi qu’ils furent recensés, comme Yahweh l’avait ordonné à Moïse.'),
('nb',5,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',5,2,'crampon1923','« Ordonne aux enfants d’Israël de faire sortir du camp quiconque à la lèpre et quiconque a une gonorrhée, et quiconque est souillé par un cadavre.'),
('nb',5,3,'crampon1923','Hommes ou femmes, vous les ferez sortir du camp, afin qu’ils ne souillent pas leur camp, au milieu duquel j’habite. »'),
('nb',5,4,'crampon1923','Les enfants d’Israël firent ainsi, et ils les firent sortir hors du camp; comme Yahweh l’avait ordonné à Moïse, ainsi firent les enfants d’Israël.'),
('nb',5,5,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',5,6,'crampon1923','« Dis aux enfants d’Israël: Si quelqu’un, homme ou femme, commet quelqu’un de tous les péchés qui cause un préjudice au prochain, en se rendant infidèle envers Yahweh, et qu’il se soit rendu coupable,'),
('nb',5,7,'crampon1923','il confessera son péché et il restituera en son entier l’objet mal acquis, en y ajoutant un cinquième; il le remettra à celui envers qui il s’est rendu coupable.'),
('nb',5,8,'crampon1923','Si celui-ci n’a pas de représentant à qui puisse être rendu l’objet du délit, cet objet revient à Yahweh, au prêtre, outre le bélier expiatoire avec lequel on fera l’expiation pour le coupable ».'),
('nb',5,9,'crampon1923','« Toute offrande prélevée sur les choses saintes que les enfants d’Israël présentent au prêtre, appartiendra à celui-ci;'),
('nb',5,10,'crampon1923','les choses que tout homme aura consacré seront à lui; ce que chacun donne au prêtre lui appartiendra ».'),
('nb',5,11,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',5,12,'crampon1923','« Parle aux enfants d’Israël, et dis-leur: Si une femme mariée se détourne et devient infidèle à son mari,'),
('nb',5,13,'crampon1923','un autre homme ayant eu commerce avec elle, et que la chose soit cachée aux yeux de son mari, cette femme s’étant souillée en secret, sans qu’il y ait eu de témoin contre elle, et sans qu’elle ait été prise sur le fait:'),
('nb',5,14,'crampon1923','— si le mari est saisi d’un esprit de jalousie et qu’il soit jaloux de sa femme qui s’est souillée, ou bien s’il est saisi d’un esprit de jalousie et qu’il soit jaloux de sa femme qui ne s’est pas souillée:'),
('nb',5,15,'crampon1923','cet homme amènera sa femme au prêtre et il apportera une offrande à cause d’elle, un dixième d’épha de farine d’orge; il n’y versera pas d’huile et n’y mettra pas d’encens, car c’est une oblation de jalousie, une oblation de souvenir, qui rappelle une prévarication.'),
('nb',5,16,'crampon1923','Le prêtre la fera approcher de l’autel et se tenir debout devant Yahweh.'),
('nb',5,17,'crampon1923','Le prêtre prendra de l’eau sainte dans un vase de terre et, ayant pris de la poussière sur le sol de la Demeure, il la mettra dans l’eau.'),
('nb',5,18,'crampon1923','Le prêtre fera tenir la femme debout devant Yahweh, il dénouera la chevelure de la tête de la femme et lui posera sur les mains l’oblation de souvenir; c’est une oblation de jalousie. Le prêtre aura dans la main les eaux amères qui apportent la malédiction.'),
('nb',5,19,'crampon1923','Le prêtre adjurera la femme et lui dira: Si aucun homme n’a couché avec toi, et si tu ne t’es pas détournée pour te souiller, étant sous la puissance de ton mari, sois préservée de l’effet de ces eaux amères qui apportent la malédiction.'),
('nb',5,20,'crampon1923','Mais si, étant sous la puissance de ton mari, tu t’es détournée et t’es souillée, et si un autre homme que ton mari a couché avec toi:'),
('nb',5,21,'crampon1923','— le prêtre adjurera la femme par le serment d’imprécation, et lui dira: — Que Yahweh fasse de toi une malédiction et une exécration au milieu de ton peuple, en faisant maigrir tes flancs et enfler ton ventre,'),
('nb',5,22,'crampon1923','et que ces eaux qui apportent la malédiction entrent dans tes entrailles pour te faire enfler le ventre et maigrir les flancs! Et la femme dira: Amen! Amen!'),
('nb',5,23,'crampon1923','Le prêtre écrira ces imprécations sur un rouleau, et il les effacera ensuite dans les eaux amères.'),
('nb',5,24,'crampon1923','Puis il fera boire à la femme les eaux amères qui apportent la malédiction, et les eaux qui apportent la malédiction entreront en elle pour lui être amères.'),
('nb',5,25,'crampon1923','Le prêtre, ayant pris des mains de la femme l’oblation de jalousie, la balancera devant Yahweh, et l’approchera de l’autel;'),
('nb',5,26,'crampon1923','il prendra une poignée de cette oblation comme mémorial, et il la fera fumer sur l’autel; et après cela, il fera boire les eaux à la femme.'),
('nb',5,27,'crampon1923','Quand il lui fera boire les eaux, il arrivera, si elle s’est souillée et a été infidèle à son mari, que les eaux qui apportent la malédiction entreront en elle pour lui être amères: son ventre s’enflera, ses flancs maigriront, et cette femme sera une malédiction au milieu de son peuple.'),
('nb',5,28,'crampon1923','Mais si la femme ne s’est pas souillée et qu’elle soit pure, elle sera préservée, et elle aura des enfants.'),
('nb',5,29,'crampon1923','Telle est la loi sur la jalousie, quand une femme, étant sous la puissance de son mari, se détourne et se souille,'),
('nb',5,30,'crampon1923','ou quand l’esprit de jalousie s’empare d’un mari et qu’il devient jaloux de sa femme: il fera tenir sa femme debout devant Yahweh, et le prêtre lui appliquera cette loi dans son entier.'),
('nb',5,31,'crampon1923','Le mari sera exempt de faute; mais la femme portera son iniquité ».'),
('nb',6,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',6,2,'crampon1923','« Parle aux enfants d’Israël, et dis-leur: Lorsqu’un homme ou une femme se sépare par un vœu, un vœu de nazaréen, pour se séparer en l’honneur de Yahweh,'),
('nb',6,3,'crampon1923','il s’abstiendra de vin et boisson enivrante; il ne boira ni vinaigre fait avec du vin, ni vinaigre fait avec une boisson enivrante; il ne boira d’aucun jus de raisin; il ne mangera ni raisins frais, ni raisins secs.'),
('nb',6,4,'crampon1923','Pendant tout le temps de son nazaréat, il ne mangera d’aucun produit de la vigne, depuis les pépins jusqu’à la peau du raisin.'),
('nb',6,5,'crampon1923','Pendant tout le temps du vœu de son nazaréat, le rasoir ne passera point sur sa tête; jusqu’à l’accomplissement des jours pour la durée desquels il se sépare en l’honneur de Yahweh, il sera saint, laissant croître librement ses cheveux.'),
('nb',6,6,'crampon1923','Tout le temps pendant lequel il se sépare en l’honneur de Yahweh, il ne s’approchera d’aucun corps mort;'),
('nb',6,7,'crampon1923','il ne se souillera ni pour son père, ni pour sa mère, ni pour son frère ou sa sœur, à leur mort, car il porte sur sa tête la consécration à son Dieu.'),
('nb',6,8,'crampon1923','Tout le temps de son nazaréat, il est consacré à Yahweh.'),
('nb',6,9,'crampon1923','Si quelqu’un meurt subitement près de lui, et que sa tête consacrée soit ainsi souillée, il se rasera la tête le jour de sa purification; il la rasera le septième jour.'),
('nb',6,10,'crampon1923','Et le huitième jour, il apportera au prêtre deux tourterelles ou deux jeunes pigeons, à l’entrée de la tente de réunion.'),
('nb',6,11,'crampon1923','Le prêtre offrira l’un en sacrifice pour le péché, et l’autre en holocauste, et il fera pour lui l’expiation pour son péché à l’occasion du mort. Ce jour-là, le nazaréen consacrera sa tête.'),
('nb',6,12,'crampon1923','Il consacrera de nouveau à Yahweh les jours de son nazaréat, et il offrira un agneau d’un an en sacrifice de réparation; les jours précédents sont nuls, parce que son nazaréat a été souillé.'),
('nb',6,13,'crampon1923','Voici la loi du nazaréen. Le jour où il aura accompli le temps de son nazaréat, on le fera venir à l’entrée de la tente de réunion.'),
('nb',6,14,'crampon1923','Il présentera son offrande à Yahweh: un agneau d’un an, sans défaut, pour l’holocauste; une brebis d’un an, sans défaut, pour le sacrifice pour le péché; un bélier sans défaut pour le sacrifice pacifique;'),
('nb',6,15,'crampon1923','ainsi qu’une corbeille de pains sans levain, de gâteaux de fleur de farine pétris à l’huile, et de galettes sans levain arrosées d’huile, avec l’oblation et les libations ordinaires.'),
('nb',6,16,'crampon1923','Le prêtre les présentera devant Yahweh, et il offrira son sacrifice pour le péché et son holocauste.'),
('nb',6,17,'crampon1923','Puis il offrira le bélier en sacrifice pacifique à Yahweh, avec la corbeille de pains sans levain; le prêtre fera son oblation et sa libation.'),
('nb',6,18,'crampon1923','Le nazaréen rasera, à l’entrée de la tente de réunion, sa tête consacrée; et prenant les cheveux de sa tête consacrée, il les mettra sur le feu qui est sous la victime du sacrifice pacifique.'),
('nb',6,19,'crampon1923','Le prêtre prendra l’épaule du bélier quand elle sera cuite, un gâteau sans levain de la corbeille et une galette sans levain; et, les ayant posés sur les mains du nazaréen, après que celui-ci aura rasé sa tête consacrée,'),
('nb',6,20,'crampon1923','le prêtre les balancera devant Yahweh: c’est une chose sainte qui appartient au prêtre, outre la poitrine balancée et la cuisse prélevée. Après cela le nazaréen pourra boire du vin.'),
('nb',6,21,'crampon1923','Telle est la loi du nazaréen qui a fait un vœu, telle est son offrande à Yahweh pour son nazaréat, outre ce que ses moyens lui permettront de faire. Selon le vœu qu’il aura fait, ainsi il agira d’après la loi de son nazaréat. »'),
('nb',6,22,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',6,23,'crampon1923','« Parle à Aaron et à ses fils en disant: Vous bénirez ainsi les enfants d’Israël, vous leur direz:'),
('nb',6,24,'crampon1923','Que Yahweh te bénisse et te garde!'),
('nb',6,25,'crampon1923','Que Yahweh fasse luire sa face sur toi, et qu’il t’accorde sa grâce!'),
('nb',6,26,'crampon1923','Que Yahweh lève sa face vers toi, et qu’il te donne la paix! —'),
('nb',6,27,'crampon1923','C’est ainsi qu’ils mettront mon nom sur les enfants d’Israël, et je les bénirai. » III– DERNIERS ÉVÉNEMENTS DU SÉJOUR AU SINAÏ'),
('nb',7,1,'crampon1923','Le jour où Moïse acheva de dresser la Demeure, de l’oindre et de la sanctifier avec tous ses ustensiles, ainsi que l’autel avec tous ses ustensiles; lorsqu’il les eut oints et sanctifiés,'),
('nb',7,2,'crampon1923','les princes d’Israël, chefs de leurs maisons patriarcales, présentèrent leurs offrandes: c’étaient les princes des tribus, ceux qui avaient présidé au dénombrement.'),
('nb',7,3,'crampon1923','Ils amenèrent leur offrande devant Yahweh: six chars couverts et douze bœufs, soit un char pour deux princes et un bœuf pour chaque prince, et ils les présentèrent devant la Demeure.'),
('nb',7,4,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',7,5,'crampon1923','« Reçois d’eux ces choses, et qu’elles soient employées pour le service de la tente de réunion; tu les donneras aux Lévites, à chacun selon les besoins de son service. »'),
('nb',7,6,'crampon1923','Moïse, ayant pris les chars et les bœufs, les remit aux Lévites.'),
('nb',7,7,'crampon1923','Il donna deux chars et quatre bœufs aux fils de Gerson, selon les besoins de leur service;'),
('nb',7,8,'crampon1923','il donna quatre chars et huit bœufs aux fils de Mérari, selon les besoins de leur service, sous la surveillance d’Ithamar, fils d’Aaron, le prêtre.'),
('nb',7,9,'crampon1923','Mais il n’en donna pas aux fils de Caath, parce que, ayant le service des objets sacrés, ils devaient les porter sur leurs épaules.'),
('nb',7,10,'crampon1923','Les princes présentèrent leur offrande pour la dédicace de l’autel, le jour où on l’oignit; les princes présentèrent leur offrande devant l’autel.'),
('nb',7,11,'crampon1923','Et Yahweh dit à Moïse: « Que chaque jour un prince vienne présenter son offrande pour la dédicace de l’autel. »'),
('nb',7,12,'crampon1923','Celui qui présenta son offrande le premier jour fut Nahasson, fils d’Aminadab, de la tribu de Juda.'),
('nb',7,13,'crampon1923','Il offrit: un plat d’argent du poids de cent trente sicles, une coupe d’argent de soixante-dix sicles, selon le sicle du sanctuaire, l’un et l’autre pleins de fleur de farine pétrie à l’huile, pour l’oblation;'),
('nb',7,14,'crampon1923','un godet d’or de dix sicles, plein de parfum;'),
('nb',7,15,'crampon1923','un jeune taureau, un bélier et un agneau d’un an pour l’holocauste;'),
('nb',7,16,'crampon1923','un bouc pour le sacrifice pour le péché,'),
('nb',7,17,'crampon1923','et, pour le sacrifice pacifique, deux bœufs, cinq béliers, cinq boucs et cinq agneaux d’un an. Telle fut l’offrande de Nahasson, fils d’Aminadab.'),
('nb',7,18,'crampon1923','Le second jour, Nathanaël, fils de Suar, prince de la tribu d’Issachar, présenta son offrande.'),
('nb',7,19,'crampon1923','Il offrit: un plat d’argent du poids de cent trente sicles, une coupe d’argent de soixante-dix sicles, selon le sicle du sanctuaire, l’un et l’autre pleins de fleur de farine pétrie à l’huile, pour l’oblation;'),
